function createRoleDefaultPermissions(roleName, isFullAccess = false) {
  const perms = {};
  const modules = [
    'dashboard', 'bulk-assign', 'inbox', 'enquiries', 'followups', 'catalog', 'orders',
    'customers', 'dnd', 'staff', 'analytics', 'audit', 'settings', 'backup', 'masking', 'packing-slip-config'
  ];
  const adminOnlyMods = ['settings', 'backup', 'staff', 'audit', 'masking', 'bulk-assign'];
  modules.forEach(m => {
    const isAdmMod = adminOnlyMods.includes(m);
    perms[m] = {
      view: isFullAccess || !isAdmMod,
      create: isFullAccess,
      edit: isFullAccess,
      delete: isFullAccess
    };
  });
  if (perms.audit) { perms.audit.create = false; perms.audit.edit = false; perms.audit.delete = false; }
  return perms;
}
window.createRoleDefaultPermissions = createRoleDefaultPermissions;

function initRolePermissionsState() {
  if (typeof CRM_STATE === 'undefined' || !CRM_STATE) return;
  if (!CRM_STATE.rolePermissions) {
    CRM_STATE.rolePermissions = {};
    try {
      const stored = localStorage.getItem('CRM_ROLE_PERMISSIONS');
      if (stored) {
        CRM_STATE.rolePermissions = JSON.parse(stored) || {};
      }
    } catch (e) {
      CRM_STATE.rolePermissions = {};
    }
  }

  // Ensure Super Admin always exists with full access
  if (!CRM_STATE.rolePermissions['Super Admin']) {
    CRM_STATE.rolePermissions['Super Admin'] = JSON.parse(JSON.stringify(DEFAULT_ROLE_PERMISSIONS['Super Admin']));
  }

  // Strictly purge ALL legacy hardcoded demo roles from memory and persistent storage
  LEGACY_HARDCODED_DEMO_ROLES.forEach(legacyRole => {
    if (CRM_STATE.rolePermissions[legacyRole]) {
      delete CRM_STATE.rolePermissions[legacyRole];
    }
  });
  try {
    localStorage.setItem('CRM_ROLE_PERMISSIONS', JSON.stringify(CRM_STATE.rolePermissions));
  } catch (e) { }

  // Ensure any role held by staff (that is not a legacy demo role) is present in rolePermissions
  (CRM_STATE.staffList || []).forEach(st => {
    if (st && st.role && !LEGACY_HARDCODED_DEMO_ROLES.includes(st.role) && !CRM_STATE.rolePermissions[st.role]) {
      CRM_STATE.rolePermissions[st.role] = createRoleDefaultPermissions(st.role, false);
    }
  });

  // Sanitize permissions across all configured roles
  Object.keys(CRM_STATE.rolePermissions).forEach(r => {
    if (!CRM_STATE.rolePermissions[r].masking || typeof CRM_STATE.rolePermissions[r].masking !== 'object') {
      const isAdmRole = (r === 'Super Admin' || r === 'Admin Manager' || r === 'admin');
      CRM_STATE.rolePermissions[r].masking = { view: isAdmRole, create: isAdmRole, edit: isAdmRole, delete: isAdmRole };
    }
    if (!CRM_STATE.rolePermissions[r]['bulk-assign'] || typeof CRM_STATE.rolePermissions[r]['bulk-assign'] !== 'object') {
      const isAdmRole = (r === 'Super Admin' || r === 'Admin Manager' || r === 'admin');
      CRM_STATE.rolePermissions[r]['bulk-assign'] = { view: isAdmRole, create: isAdmRole, edit: isAdmRole, delete: isAdmRole };
    }
    if (CRM_STATE.rolePermissions[r]?.audit) {
      CRM_STATE.rolePermissions[r].audit.create = false;
      CRM_STATE.rolePermissions[r].audit.edit = false;
      CRM_STATE.rolePermissions[r].audit.delete = false;
    }
  });
}
window.initRolePermissionsState = initRolePermissionsState;

function getUserAssignedRoleName(user) {
  if (!user) user = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER) ? CURRENT_USER : (typeof window !== 'undefined' && window.CURRENT_USER ? window.CURRENT_USER : null);
  if (!user) return 'Super Admin';

  if (user.role === 'admin' || user.id === 'admin' || user.role === 'Super Admin' || (user.title && user.title.includes('Admin Manager'))) {
    return 'Super Admin';
  }

  initRolePermissionsState();

  if (user.role && CRM_STATE?.rolePermissions && CRM_STATE.rolePermissions[user.role]) {
    return user.role;
  }
  if (user.title && CRM_STATE?.rolePermissions && CRM_STATE.rolePermissions[user.title]) {
    return user.title;
  }
  if (user.role_name && CRM_STATE?.rolePermissions && CRM_STATE.rolePermissions[user.role_name]) {
    return user.role_name;
  }
  const staffId = user.staff_id || user.staffId || user.id || user.role;
  const staffObj = (CRM_STATE?.staffList || []).find(s => s.id === staffId || s.username === user.username);
  if (staffObj && staffObj.role && CRM_STATE?.rolePermissions && CRM_STATE.rolePermissions[staffObj.role]) {
    return staffObj.role;
  }
  if (staffObj && staffObj.role) {
    return staffObj.role;
  }

  return user.title || user.role || 'Sales Specialist (Baby Collection)';
}
window.getUserAssignedRoleName = getUserAssignedRoleName;

function canUserPerformAction(moduleName, action) {
  const user = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER) ? CURRENT_USER : ((typeof window !== 'undefined' && window.CURRENT_USER) ? window.CURRENT_USER : ((typeof CRM_AUTH_SESSION !== 'undefined' && CRM_AUTH_SESSION) ? CRM_AUTH_SESSION : null));
  if (!user) return true;

  // Audit Logs is strictly view-only across all roles (no manual create, edit, or delete actions)
  if (moduleName === 'audit' && action !== 'view') {
    return false;
  }

  const isSuperAdmin = user.role === 'admin' || user.id === 'admin' || user.role === 'Super Admin' || user.name === 'Super Admin' || (user.title && user.title.includes('Admin'));
  if (isSuperAdmin) {
    return true;
  }

  // 1. Check individual staff action permissions configured by Admin during staff onboarding / editing
  const staffId = user.staff_id || user.staffId || user.id || user.username;
  const staffObj = (CRM_STATE?.staffList || []).find(s => s.id === staffId || s.username === user.username || s.name === user.name);
  const staffPerms = (staffObj && staffObj.permissions) ? staffObj.permissions : (user.permissions ? user.permissions : null);

  // If Admin explicitly set this action permission to false for this staff member, strictly DENY!
  // E.g. If staff was assigned View only, then create/edit/delete are false across all modules!
  if (staffPerms && typeof staffPerms === 'object' && typeof staffPerms[action] === 'boolean') {
    if (!staffPerms[action]) {
      return false;
    }
  }

  // 2. Resolve Role Permissions Matrix for this module and action
  initRolePermissionsState();
  const roleName = getUserAssignedRoleName(user);

  if (roleName === 'Admin Manager' || roleName === 'admin') {
    const adminPerms = (CRM_STATE?.rolePermissions && CRM_STATE.rolePermissions['Admin Manager']) || DEFAULT_ROLE_PERMISSIONS['Admin Manager'];
    if (adminPerms && adminPerms[moduleName] && adminPerms[moduleName][action] !== undefined) {
      return Boolean(adminPerms[moduleName][action]);
    }
    return true;
  }

  const rolePerms = (CRM_STATE?.rolePermissions && CRM_STATE.rolePermissions[roleName]) || DEFAULT_ROLE_PERMISSIONS[roleName];

  // For enquiries, autoreply & broadcast: WhatsApp Inbox sub-modules — inherit from inbox permissions
  if (moduleName === 'autoreply' || moduleName === 'broadcast' || moduleName === 'enquiries') {
    if (rolePerms && rolePerms[moduleName] && rolePerms[moduleName][action] !== undefined) {
      return Boolean(rolePerms[moduleName][action]);
    }
    const inboxPerm = (rolePerms && rolePerms.inbox) ? rolePerms.inbox[action] : undefined;
    if (inboxPerm !== undefined) {
      return Boolean(inboxPerm);
    }
    return canUserPerformAction('inbox', action);
  }

  // Check specific module in role permissions matrix
  if (rolePerms && rolePerms[moduleName] && rolePerms[moduleName][action] !== undefined) {
    return Boolean(rolePerms[moduleName][action]);
  }

  // For audit (System Audit Trail & Security Logs): strictly view-only tamper-proof log
  if (moduleName === 'audit') {
    if (action === 'view') {
      return Boolean(rolePerms?.audit ? rolePerms.audit.view : false);
    }
    return false;
  }

  // Fallback for modules:
  if (staffPerms && typeof staffPerms === 'object' && staffPerms[action] === true) {
    if (moduleName === 'settings' && action !== 'view') return false;
    return true;
  }

  return false;
}
window.canUserPerformAction = canUserPerformAction;

