// Global App State (Safely Initialized Immediately)
var CRM_STATE = window.CRM_STATE || JSON.parse(JSON.stringify(INITIAL_CRM_DATA));
window.CRM_STATE = CRM_STATE;
var CURRENT_USER = window.CURRENT_USER || null; // Currently logged in user profile
var CRM_AUTH_SESSION = window.CRM_AUTH_SESSION || null; // Normalized Auth Session reference

// Standardized session retrieval helper across Admin & Staff operations
function getCurrentUser() {
  let user = null;
  if (typeof CURRENT_USER !== 'undefined' && CURRENT_USER) {
    user = CURRENT_USER;
  } else if (typeof window !== 'undefined' && window.CURRENT_USER) {
    user = window.CURRENT_USER;
  } else if (typeof CRM_AUTH_SESSION !== 'undefined' && CRM_AUTH_SESSION) {
    user = CRM_AUTH_SESSION;
  } else if (typeof window !== 'undefined' && window.CRM_AUTH_SESSION) {
    user = window.CRM_AUTH_SESSION;
  } else {
    try {
      const sessionStr = localStorage.getItem('GRM_CRM_SESSION') || sessionStorage.getItem('GRM_CRM_SESSION');
      if (sessionStr) {
        user = JSON.parse(sessionStr);
        CURRENT_USER = user;
      }
    } catch (e) { }
  }

  if (!user) {
    if (typeof ACTIVE_ROLE !== 'undefined' && ACTIVE_ROLE && ACTIVE_ROLE !== 'admin') {
      const staff = (CRM_STATE?.staffList || []).find(s => s.id === ACTIVE_ROLE);
      if (staff) user = { ...staff };
      else user = { name: 'Sales Specialist', role: ACTIVE_ROLE, id: ACTIVE_ROLE, staffId: ACTIVE_ROLE };
    } else {
      user = { id: 'admin', staffId: 'admin', username: 'admin', role: 'admin', name: 'Super Admin' };
    }
  }

  if (!user.id) user.id = user.staffId || user.role || user.username || 'admin';
  if (!user.staffId) user.staffId = user.id;
  if (!user.name) user.name = (user.role === 'admin' || user.id === 'admin') ? 'Super Admin' : 'Staff Specialist';

  CURRENT_USER = user;
  window.CURRENT_USER = user;
  window.CRM_AUTH_SESSION = user;
  CRM_AUTH_SESSION = user;
  return user;
}

// Global Authenticated Fetch Interceptor for api.php
(function() {
  if (typeof window === 'undefined' || typeof window.fetch !== 'function') return;
  const _origFetch = window.fetch;
  window.fetch = function(resource, init) {
    init = init || {};
    const url = typeof resource === 'string' ? resource : (resource && resource.url ? resource.url : '');
    if (url.includes('api.php') || url.includes('auth.php')) {
      init.credentials = init.credentials || 'same-origin';
      init.headers = init.headers || {};
      const curUser = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER) ? CURRENT_USER : (typeof getCurrentUser === 'function' ? getCurrentUser() : null);
      if (curUser && curUser.id) {
        if (typeof Headers !== 'undefined' && init.headers instanceof Headers) {
          if (!init.headers.has('X-User-Id')) init.headers.append('X-User-Id', curUser.id);
        } else if (typeof init.headers === 'object') {
          if (!init.headers['X-User-Id']) init.headers['X-User-Id'] = curUser.id;
        }
      }
    }
    return _origFetch.call(this, resource, init).then(res => {
      if (res.status === 401 && (url.includes('api.php?action=get_state') || url.includes('api.php?action=get_all'))) {
        console.warn('[CRM Auth Guard] Session expired or invalid, redirecting to login.');
        if (typeof window !== 'undefined' && window.location && !window.location.pathname.endsWith('login.html')) {
          localStorage.removeItem('GRM_CRM_SESSION');
          sessionStorage.removeItem('GRM_CRM_SESSION');
          window.location.href = 'login.html';
        }
      }
      return res;
    });
  };
})();

function getPersistedActiveView() {
  try {
    const validViews = ['inbox', 'bulk-assign', 'enquiries', 'dashboard', 'catalog', 'orders', 'followups', 'customers', 'dnd', 'staff', 'audit', 'analytics', 'settings', 'backup', 'masking', 'packing-slip-config'];
    const rawHash = (typeof window !== 'undefined' && window.location && window.location.hash) ? window.location.hash.replace('#', '').trim().toLowerCase() : '';
    const mainHash = rawHash.split('/')[0];
    if (mainHash && validViews.includes(mainHash)) {
      return mainHash;
    }
    const stored = (typeof localStorage !== 'undefined') ? localStorage.getItem('GRM_CRM_ACTIVE_VIEW') : null;
    if (stored && validViews.includes(stored)) {
      return stored;
    }
  } catch (e) {
    console.error('Error getting persisted view:', e);
  }
  return 'inbox';
}

var ACTIVE_VIEW = window.ACTIVE_VIEW || getPersistedActiveView();
var ACTIVE_ROLE = window.ACTIVE_ROLE || 'admin'; // 'admin', 'staff_01', 'staff_02', 'staff_03', etc.
