function sendCallWhatsAppPing() {
  if (!ACTIVE_CALL_CUSTOMER_ID) return;
  const customer = CRM_STATE.customers.find(c => c.id === ACTIVE_CALL_CUSTOMER_ID);
  if (!customer) return;

  const brand = getBrandName();
  const staff = getCurrentUser();
  const pingText = `📞 *${brand}* • Voice Call Alert\n━━━━━━━━━━━━━━━━━━━━\nHello ${customer.name ? customer.name.split(' ')[0] : 'there'}! 👋 Our sales specialist (${staff ? staff.name.split(' ')[0] : 'Sales Desk'}) is trying to reach you regarding your garment inquiry. Please accept our call or reply with a convenient time!`;

  const newMsg = {
    id: Date.now(),
    sender: 'staff',
    text: pingText,
    time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    status: 'DELIVERED'
  };

  if (!CRM_STATE.conversations[customer.id]) {
    CRM_STATE.conversations[customer.id] = [];
  }
  CRM_STATE.conversations[customer.id].push(newMsg);
  saveCRMState();
  if (ACTIVE_CUSTOMER_ID === customer.id) renderChatMessages();

  dispatchWhatsAppOutbound(customer.whatsapp || customer.phone, pingText, newMsg);
  showToast('WhatsApp Ping Sent', `Call alert message delivered to ${customer.name}`, 'send', 'emerald');
}

function insertCallOutcomeNote(noteText) {
  const notesArea = document.getElementById('call-outcome-notes');
  if (notesArea) {
    if (notesArea.value) notesArea.value += '\n• ' + noteText;
    else notesArea.value = '• ' + noteText;
    notesArea.focus();
  }
}

function endBrandMaskedCall(saveOutcome = false) {
  if (CALL_ACTIVE_INTERVAL) {
    clearInterval(CALL_ACTIVE_INTERVAL);
    CALL_ACTIVE_INTERVAL = null;
  }

  stopSoftphoneRingTone();

  // Stop WebRTC audio streams and visualizer
  if (WEBRTC_ANIM_FRAME) {
    cancelAnimationFrame(WEBRTC_ANIM_FRAME);
    WEBRTC_ANIM_FRAME = null;
  }
  if (WEBRTC_AUDIO_STREAM) {
    WEBRTC_AUDIO_STREAM.getTracks().forEach(t => t.stop());
    WEBRTC_AUDIO_STREAM = null;
  }
  if (WEBRTC_AUDIO_CTX && WEBRTC_AUDIO_CTX.state !== 'closed') {
    WEBRTC_AUDIO_CTX.close().catch(() => { });
    WEBRTC_AUDIO_CTX = null;
  }

  // Terminate Staff WebRTC session & finalize dual-stream audio recording
  if (window.CRM_STAFF_VOICE) {
    window.CRM_STAFF_VOICE.endCall(CALL_ACTIVE_SECONDS);
  }

  const custId = ACTIVE_CALL_CUSTOMER_ID || ACTIVE_CUSTOMER_ID;
  const customer = CRM_STATE.customers.find(c => c.id === custId);
  const notesArea = document.getElementById('call-outcome-notes');
  const notesText = notesArea ? notesArea.value.trim() : '';

  const mins = String(Math.floor(CALL_ACTIVE_SECONDS / 60)).padStart(2, '0');
  const secs = String(CALL_ACTIVE_SECONDS % 60).padStart(2, '0');
  const durationStr = `${mins}:${secs}`;
  const brand = getBrandName();

  const activeCallId = (typeof ACTIVE_CURRENT_CALL_SESSION_ID !== 'undefined' && ACTIVE_CURRENT_CALL_SESSION_ID)
    ? ACTIVE_CURRENT_CALL_SESSION_ID
    : ((typeof ACTIVE_INCOMING_CALL !== 'undefined' && ACTIVE_INCOMING_CALL && ACTIVE_INCOMING_CALL.call_id) ? ACTIVE_INCOMING_CALL.call_id : null);
  const staffUser = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
  const finalDuration = Math.max(1, CALL_ACTIVE_SECONDS || 0);

  // Finalize active call session in MariaDB call_sessions and Call Masking Control Hub
  if (activeCallId) {
    try {
      fetch('api.php?action=end_call', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          call_id: activeCallId,
          duration_seconds: finalDuration,
          outcome: 'COMPLETED',
          outcome_notes: notesText || (`Call completed normally (${durationStr})`)
        })
      }).then(() => {
        if (ACTIVE_VIEW === 'masking' && typeof loadMaskingSettingsAndSessions === 'function') {
          loadMaskingSettingsAndSessions();
        }
      }).catch(() => { });
    } catch (e) { }
  }

  if (customer) {
    const callLogText = `📞 [In-CRM Voice Call via ${brand}] Duration: ${durationStr}${notesText ? (' — Outcome: ' + notesText) : ''}`;
    const newMsg = {
      id: Date.now(),
      sender: 'staff',
      text: callLogText,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      status: 'DELIVERED',
      isCallLog: true
    };

    if (!CRM_STATE.conversations[customer.id]) {
      CRM_STATE.conversations[customer.id] = [];
    }
    CRM_STATE.conversations[customer.id].push(newMsg);

    // Update query
    const query = CRM_STATE.queries.find(q => q.customerId === customer.id);
    if (query) {
      query.lastMessage = `Staff: "${callLogText}"`;
      query.status = (query.status === 'NEW') ? 'IN_PROGRESS' : query.status;
    }

    saveCRMState();
    if (ACTIVE_CUSTOMER_ID === customer.id) renderChatMessages();
    renderInboxConversationList();

    logAudit('BRAND_MASKED_CALL_ENDED', 'CALLING', `In-CRM Call ended with ${customer.name} (Duration: ${durationStr}). Notes: "${notesText || 'No notes'}"`);

    // Only log a new session if this was NOT already an active call session
    if (!activeCallId) {
      try {
        const rawCustomerPhone = customer.whatsapp || customer.phone || '';
        fetch('api.php?action=log_call_session', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            id: 'CALL-' + Math.floor(1000 + Math.random() * 9000),
            provider_call_id: 'WEBRTC-' + Math.random().toString(36).substring(2, 8).toUpperCase(),
            customer_id: customer.id,
            customer_name: customer.name || 'Customer',
            customer_phone: rawCustomerPhone,
            masked_phone: formatDisplayPhone(rawCustomerPhone, customer.id),
            virtual_number: (CRM_STATE?.maskingSettings?.virtual_company_number || '+91 8000 123 456'),
            assigned_staff_id: staffUser?.id || 'staff_01',
            assigned_staff_name: staffUser?.name || 'Super Admin',
            status: 'COMPLETED',
            started_at: new Date(Date.now() - (finalDuration * 1000)).toISOString().slice(0, 19).replace('T', ' '),
            ended_at: new Date().toISOString().slice(0, 19).replace('T', ' '),
            duration_seconds: finalDuration,
            outcome: 'COMPLETED',
            outcome_notes: notesText || 'Call completed normally'
          })
        }).then(() => {
          if (ACTIVE_VIEW === 'masking' && typeof loadMaskingSettingsAndSessions === 'function') {
            loadMaskingSettingsAndSessions();
          }
        }).catch(() => { });
      } catch (e) { }
    }
  }

  closeModal('modal-brand-call');
  showToast('Call Finished', `In-CRM call logged (${durationStr}). Timeline updated.`, 'call_end', 'blue');
  ACTIVE_CALL_CUSTOMER_ID = null;
  ACTIVE_CURRENT_CALL_SESSION_ID = null;
  ACTIVE_INCOMING_CALL = null;
  CALL_ACTIVE_SECONDS = 0;
  CALL_IS_ON_HOLD = false;
}

function toggleGlobalPhoneMasking() {
  if (!CRM_STATE.settings) CRM_STATE.settings = {};
  CRM_STATE.settings.maskCustomerNumbers = !(CRM_STATE.settings.maskCustomerNumbers ?? false);
  saveCRMState();
  updateMaskingUI();
  renderCurrentView();
  showToast(
    CRM_STATE.settings.maskCustomerNumbers ? 'Privacy Mode Active' : 'Masking Disabled',
    CRM_STATE.settings.maskCustomerNumbers ? 'Customer phone numbers are now masked.' : 'Full customer phone numbers are now visible.',
    CRM_STATE.settings.maskCustomerNumbers ? 'lock' : 'lock_open',
    CRM_STATE.settings.maskCustomerNumbers ? 'amber' : 'blue'
  );
}

function toggleRevealPhone(customerId) {
  if (REVEALED_CUSTOMERS.has(customerId)) {
    REVEALED_CUSTOMERS.delete(customerId);
  } else {
    REVEALED_CUSTOMERS.add(customerId);
  }
  renderChatHeader();
  renderCustomer360Panel();
  renderInboxConversationList();
}

function updateMaskingUI() {
  const isMasked = CRM_STATE?.settings?.maskCustomerNumbers ?? true;
  const btn = document.getElementById('btn-mask-toggle');
  const icon = document.getElementById('mask-icon');
  const label = document.getElementById('mask-status-label');

  if (btn) {
    if (isMasked) {
      btn.className = 'flex items-center gap-1.5 px-3 py-1.5 bg-amber-50 hover:bg-amber-100 text-amber-900 border border-amber-300 rounded-lg text-xs font-semibold transition shadow-sm';
    } else {
      btn.className = 'flex items-center gap-1.5 px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 border border-slate-300 rounded-lg text-xs font-semibold transition shadow-sm';
    }
  }
  if (icon) icon.innerText = isMasked ? 'lock' : 'lock_open';
  if (label) label.innerText = isMasked ? 'ON' : 'OFF';

  // Also synchronize Inbox Settings Submodule controls
  const sBtn = document.getElementById('inbox-settings-mask-btn');
  const sIcon = document.getElementById('inbox-settings-mask-icon');
  const sStatus = document.getElementById('inbox-settings-mask-status');
  const sPill = document.getElementById('inbox-settings-mask-pill');
  const sPreview = document.getElementById('inbox-settings-mask-preview');
  const sActionBtn = document.getElementById('inbox-settings-mask-btn-text');

  if (sBtn) {
    sBtn.className = isMasked
      ? 'flex items-center gap-1.5 px-3 py-2 bg-amber-50 hover:bg-amber-100 text-amber-900 border border-amber-300 rounded-xl text-xs font-bold transition shadow-2xs whitespace-nowrap cursor-pointer active:scale-95'
      : 'flex items-center gap-1.5 px-3 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 border border-slate-300 rounded-xl text-xs font-bold transition shadow-2xs whitespace-nowrap cursor-pointer active:scale-95';
  }
  if (sIcon) sIcon.innerText = isMasked ? 'lock' : 'lock_open';
  if (sStatus) sStatus.innerText = isMasked ? 'ON' : 'OFF';
  if (sPill) {
    sPill.innerText = isMasked ? 'MASKING ACTIVE' : 'MASKING OFF';
    sPill.className = isMasked
      ? 'text-[10px] font-extrabold px-2 py-0.5 bg-amber-100 text-amber-800 rounded-full border border-amber-200'
      : 'text-[10px] font-extrabold px-2 py-0.5 bg-slate-100 text-slate-600 rounded-full border border-slate-200';
  }
  if (sPreview) sPreview.innerText = isMasked ? '+91 86*** **593' : '+91 86680 07593';
  if (sActionBtn) sActionBtn.innerText = isMasked ? 'Disable Number Masking' : 'Enable Number Masking';
}

function renderCurrentView() {
  if (ACTIVE_VIEW === 'inbox') renderInbox();
  else if (ACTIVE_VIEW === 'bulk-assign') renderBulkAssignModule();
  else if (ACTIVE_VIEW === 'enquiries') renderEnquiriesTable();
  else if (ACTIVE_VIEW === 'customers') renderCustomersTable();
  else if (ACTIVE_VIEW === 'dnd') renderDndModule();
  else if (ACTIVE_VIEW === 'orders') renderOrdersTable();
  else if (ACTIVE_VIEW === 'dashboard') renderDashboard();
}


// Initialize Realtime WebSocket (Socket.IO) Connection
// Dynamic Bridge URL Resolver (supports local and Render deployment)
function getBridgeBaseUrl() {
  if (typeof window !== 'undefined' && window.BRIDGE_URL && !window.BRIDGE_URL.includes('trycloudflare.com')) {
    return window.BRIDGE_URL.replace(/\/+$/, '');
  }
  const stored = (typeof localStorage !== 'undefined') ? localStorage.getItem('GRM_BRIDGE_URL') : null;
  if (stored && !stored.includes('trycloudflare.com')) {
    return stored.replace(/\/+$/, '');
  } else if (stored && stored.includes('trycloudflare.com')) {
    try { localStorage.removeItem('GRM_BRIDGE_URL'); } catch (e) { }
  }
  if (typeof CRM_STATE !== 'undefined' && CRM_STATE?.settings?.bridgeUrl && !CRM_STATE.settings.bridgeUrl.includes('trycloudflare.com')) {
    return CRM_STATE.settings.bridgeUrl.replace(/\/+$/, '');
  }
  const isLocal = typeof window !== 'undefined' && (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1');
  return isLocal ? 'http://localhost:3000' : 'https://mediumturquoise-dugong-987946.hostingersite.com';
}
window.getBridgeBaseUrl = getBridgeBaseUrl;

function initSocketIO() {
  if (typeof io === 'undefined') {
    console.warn('Socket.IO client library not loaded, using fallback sync');
    return;
  }

  try {
    const bridgeUrl = getBridgeBaseUrl();
    // On remote hosting, skip localhost:3000 if not configured to prevent mixed content warnings
    if ((bridgeUrl === 'http://localhost:3000') && window.location.hostname !== 'localhost' && window.location.hostname !== '127.0.0.1') {
      console.log('ℹ️ [Bridge]: Set localStorage.setItem("GRM_BRIDGE_URL", "https://your-bridge.onrender.com") to connect Render WebSocket');
      return;
    }
    SOCKET_IO = io(bridgeUrl, {
      transports: ['websocket', 'polling'],
      reconnection: true,
      reconnectionAttempts: Infinity,
      reconnectionDelay: 1500
    });

    SOCKET_IO.on('connect', () => {
      console.log('⚡ Socket.IO Connected to Bridge (ID: ' + SOCKET_IO.id + ')');
      // Toast silenced on connect/refresh to prevent intrusive notification slider

      // 1. Fetch latest rules
      fetch(`${getBridgeBaseUrl()}/api/autoreply/rules`)
        .then(r => r.json())
        .then(data => {
          if (data && Array.isArray(data.rules) && data.rules.length > 0) {
            CRM_STATE.autoReplyRules = data.rules;
            saveCRMState();
            if (typeof renderAutoReplyRulesList === 'function') renderAutoReplyRulesList();
            if (typeof renderInboxPresetTemplatesBar === 'function') renderInboxPresetTemplatesBar();
            if (typeof updateRulesCountBadge === 'function') updateRulesCountBadge();
          }
        }).catch(() => { });

      // 2. Fetch live Auto-Reply master status from Bridge
      fetch(`${getBridgeBaseUrl()}/api/autoreply/status`)
        .then(r => r.json())
        .then(data => {
          if (data && typeof data.enabled === 'boolean') {
            if (!CRM_STATE.autoReplySettings) CRM_STATE.autoReplySettings = {};
            CRM_STATE.autoReplySettings.enabled = data.enabled;
            saveCRMState();
            updateAutoReplyUI();
            console.log('⚡ [Auto-Reply Sync] Live Status from Bridge on connect:', data.enabled ? 'ON' : 'OFF');
          }
        }).catch(() => { });
    });

    // Real-time Inbound Message from WhatsApp (Pushed instantly)
    // Real-time Active Call Broadcast (e.g. from WhatsApp Inbox or softphone)
    SOCKET_IO.on('call:active', (data) => {
      console.log('📞 [Socket.IO Call Active]:', data);
      if (ACTIVE_VIEW === 'masking' && typeof loadMaskingSettingsAndSessions === 'function') {
        loadMaskingSettingsAndSessions();
      }
    });

    // Real-time Telephony Inbound Call Simultaneous Broadcast
    SOCKET_IO.on('call:incoming', (data) => {
      console.log('🔔 [Socket.IO Call Incoming]:', data);
      if (typeof handleSocketIncomingCall === 'function') handleSocketIncomingCall(data);
    });

    // Real-time Atomic Call Claimed by Staff Member
    SOCKET_IO.on('call:claimed', (data) => {
      console.log('🔒 [Socket.IO Call Claimed]:', data);
      if (typeof handleSocketCallClaimed === 'function') handleSocketCallClaimed(data);
    });

    // Real-time Call Released / Reassigned
    SOCKET_IO.on('call:released', (data) => {
      console.log('🔄 [Socket.IO Call Released/Reassigned]:', data);
      if (typeof handleSocketCallReleased === 'function') handleSocketCallReleased(data);
    });

    // Real-time Call Ended / Completed
    SOCKET_IO.on('call:ended', (data) => {
      console.log('🏁 [Socket.IO Call Ended]:', data);
      if (typeof handleSocketCallEnded === 'function') handleSocketCallEnded(data);
    });

    // Real-time Call Pickup Notification (Native WhatsApp Call)
    SOCKET_IO.on('call:pickup_link_sent', (data) => {
      console.log('📤 [Socket.IO Call Connected]:', data);
      const statusLabel = document.getElementById('call-status-label');
      if (statusLabel) statusLabel.innerText = '● Connected • Active Call';
      const streamStatus = document.getElementById('call-audio-stream-status');
      if (streamStatus) streamStatus.innerText = '● WhatsApp Call Connected on Official Line';
    });

    // Real-time Bulk Price Request Approval / Rejection Update from Admin Link or WhatsApp
    SOCKET_IO.on('bulk_request:updated', (data) => {
      console.log('⚡ [Socket.IO Bulk Request Updated]:', data);
      if (typeof checkActiveCustomerBulkRequests === 'function') {
        checkActiveCustomerBulkRequests();
      }
      if (typeof updateHeaderBulkRequestsBadge === 'function') {
        updateHeaderBulkRequestsBadge();
      }
      const hubModal = document.getElementById('modal-bulk-requests-hub');
      if (hubModal && !hubModal.classList.contains('hidden') && typeof loadBulkRequestsHubList === 'function') {
        loadBulkRequestsHubList();
      }
      if (data && data.status === 'APPROVED') {
        if (typeof showToast === 'function') {
          showToast('✅ Bulk Price Request Approved!', `Admin approved ${data.request?.request_code || 'bulk price request'}! Special price ₹${parseFloat(data.request?.requested_price || 0).toFixed(2)}/pc is now active.`, 'check_circle', 'emerald');
        }
      } else if (data && data.status === 'REJECTED') {
        if (typeof showToast === 'function') {
          showToast('❌ Bulk Price Request Rejected', `${data.request?.request_code || 'Bulk request'} was rejected by Admin. Reason: ${data.reason || data.request?.rejection_reason || 'Price declined'}`, 'cancel', 'rose');
        }
      } else if (data && data.status === 'PENDING') {
        if (typeof showToast === 'function') {
          showToast('🔔 New Bulk Price Request', `New bulk price request ${data.request?.request_code || ''} received! Pending Admin decision.`, 'price_change', 'amber');
        }
      }
    });

    SOCKET_IO.on('notification:new', (notif) => {
      console.log('⚡ [Socket.IO New In-App Notification]:', notif);
      if (notif && notif.title && typeof showToast === 'function') {
        const type = notif.type || 'INFO';
        const color = (type.includes('APPROV') || type === 'SUCCESS') ? 'emerald' : ((type.includes('REJECT') || type === 'ERROR') ? 'rose' : 'amber');
        const icon = (type.includes('APPROV') || type === 'SUCCESS') ? 'check_circle' : ((type.includes('REJECT') || type === 'ERROR') ? 'cancel' : 'notifications');
        showToast(notif.title, notif.message || '', icon, color);
        
      }
    });

    SOCKET_IO.on('whatsapp:inbound', (payload) => {
      console.log('⚡ [Socket.IO Inbound Message Received]:', payload);
      ingestInboundMessage(payload);
      // Double-guard: Forward from browser directly to CRM API to guarantee 100% database persistence across page refreshes
      try {
        fetch('api.php?action=receive_message', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        }).catch(err => console.warn('[Inbound Sync] API persist check:', err));
      } catch (e) {}
    });

    // Real-time Auto-Reply Rules Sync from Bridge
    SOCKET_IO.on('autoreply:rules_updated', (data) => {
      if (data && Array.isArray(data.rules)) {
        console.log('⚡ [Socket.IO Rules Sync Received]:', data.rules.length, 'rules');
        CRM_STATE.autoReplyRules = data.rules;
        saveCRMState();
        if (typeof renderAutoReplyRulesList === 'function') renderAutoReplyRulesList();
        if (typeof renderInboxPresetTemplatesBar === 'function') renderInboxPresetTemplatesBar();
        if (typeof updateRulesCountBadge === 'function') updateRulesCountBadge();
      }
    });

    // Real-time Auto-Reply Master Toggle Sync from Bridge
    SOCKET_IO.on('autoreply:updated', (data) => {
      if (data && typeof data.enabled === 'boolean') {
        console.log('⚡ [Socket.IO Auto-Reply Updated]:', data.enabled ? 'ON' : 'OFF');
        if (!CRM_STATE.autoReplySettings) CRM_STATE.autoReplySettings = {};
        CRM_STATE.autoReplySettings.enabled = data.enabled;
        saveCRMState();
        updateAutoReplyUI();
      }
    });

    SOCKET_IO.on('autoreply:status', (data) => {
      if (data && typeof data.enabled === 'boolean') {
        if (!CRM_STATE.autoReplySettings) CRM_STATE.autoReplySettings = {};
        CRM_STATE.autoReplySettings.enabled = data.enabled;
        saveCRMState();
        updateAutoReplyUI();
      }
    });

    // Real-time Bridge Status Changes
    SOCKET_IO.on('bridge:accounts', (data) => {
      if (data && Array.isArray(data.accounts)) {
        applyUpdatedAccountsDelta(data.accounts, false);
      }
    });

    SOCKET_IO.on('bridge:status', (statusData) => {
      updateQRBridgeUI(statusData);
    });

    // Real-time Outbound Delivery Ack & Instant Broadcast Ingestion
    SOCKET_IO.on('whatsapp:sent_ack', (ack) => {
      console.log('⚡ [Socket.IO Outbound Ack]:', ack);
    });

    SOCKET_IO.on('whatsapp:outbound', (outboundPayload) => {
      if (outboundPayload) {
        ingestInboundMessage(outboundPayload, true);
      }
    });

    SOCKET_IO.on('disconnect', () => {
      console.warn('Socket.IO Disconnected from Bridge');
    });

  } catch (e) {
    console.error('Socket.IO Connection Error:', e);
  }
}

// =========================================================================
// REAL-TIME INBOUND MESSAGE INGESTION & DISPATCH ENGINE
// =========================================================================
function ingestInboundMessage(payload, suppressChime = false) {
  if (!payload || !CRM_STATE) return;

  const phoneNorm = normalizeWhatsAppPhone(payload.sender_phone || payload.sender_jid || '');
  let cleanPhone = phoneNorm.formattedPhone || '+91 98765 43210';
  let normalizedDigits = phoneNorm.cleanDigits;

  // Privacy LID Resolution
  const lidCandidate = payload.lid || ((payload.sender_jid && payload.sender_jid.includes('@lid')) ? payload.sender_jid.split('@')[0].split(':')[0].replace(/[^0-9]/g, '') : (normalizedDigits.length >= 14 ? normalizedDigits : null));
  if (lidCandidate) {
    const sharedLidMap = (CRM_STATE && CRM_STATE.lidMappings) || window.LID_MAPPINGS || {};
    if (sharedLidMap[lidCandidate]) {
      const mapped = String(sharedLidMap[lidCandidate]).replace(/[^0-9]/g, '');
      if (mapped.length >= 10) {
        normalizedDigits = mapped;
        cleanPhone = mapped.length === 10 ? ('+91 ' + mapped.slice(0, 5) + ' ' + mapped.slice(5)) : (mapped.length === 12 && mapped.startsWith('91') ? ('+91 ' + mapped.slice(2, 7) + ' ' + mapped.slice(7)) : ('+' + mapped));
      }
    }
  }

  // Guard against internal WhatsApp Business line labels becoming customer names
  const rawSenderName = payload.sender_name || '';
  const isLineLabel = /whatsapp business|primary line|primary whatsapp|line \d|account_\d|awaiting link/i.test(rawSenderName);
  const cleanSenderName = (!isLineLabel && rawSenderName && !rawSenderName.startsWith('WhatsApp Customer') && !rawSenderName.includes('Admin')) ? rawSenderName : null;
  const senderName = cleanSenderName || `Customer (${cleanPhone.slice(-4)})`;

  const messageText = payload.message_text || payload.text || 'Message';
  const timeStr = payload.received_at || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  const msgType = payload.type || 'text';
  const mediaUrl = payload.media_url || null;
  const duration = payload.duration || null;
  const msgTimestamp = payload.timestamp_epoch ? (payload.timestamp_epoch * 1000) : Date.now();

  const isOutboundMsg = Boolean(
    payload.is_outbound || 
    payload.direction === 'outbound' || 
    payload.sender === 'staff' || 
    payload.source === 'CRM_OUTBOUND' || 
    payload.source === 'WHATSAPP_PHONE_DIRECT' ||
    payload.source === 'AUTOREPLY_BOT' || 
    payload.source === 'STAFF_OUTBOUND'
  );

  // 1. Safe Unicode Avatar Extraction (Supports emojis & math bold script characters)
  const nameChars = Array.from(senderName || 'WA');
  const safeAvatar = (nameChars.slice(0, 2).join('')).toUpperCase() || 'WA';

  // 2. Match or Create Customer in CRM_STATE (ID match first, then phone match)
  const payloadAccountId = payload.account_id || 'account_1';
  const payloadBusinessNum = payload.received_on_number || CRM_STATE?.whatsappAccount?.phoneNumber || '+91 86680 07593';

  let customer = null;
  if (payload.customer_id) {
    customer = (CRM_STATE.customers || []).find(c => c && String(c.id) === String(payload.customer_id));
  }
  if (!customer && normalizedDigits) {
    const digits10 = normalizedDigits.slice(-10);
    customer = (CRM_STATE.customers || []).find(c => {
      const cPhoneDigits = (c.phone || c.whatsapp || '').replace(/[^0-9]/g, '');
      const phoneMatch = (cPhoneDigits.length >= 7 && (cPhoneDigits === normalizedDigits || cPhoneDigits.slice(-10) === digits10)) ||
        (c.id && c.id.replace(/[^0-9]/g, '').endsWith(digits10)) ||
        (c.jid && payload.sender_jid && (c.jid === payload.sender_jid || (c.jid.includes('@') && payload.sender_jid.includes('@') && c.jid.split('@')[0].split(':')[0] === payload.sender_jid.split('@')[0].split(':')[0])));
      return phoneMatch;
    });
  }

  if (!customer) {
    const newCustId = 'cust_' + (normalizedDigits.slice(-10) || Date.now().toString().slice(-6));
    // Look up if customer exists in another line to inherit friendly contact name
    const existingOther = CRM_STATE.customers.find(c => {
      const cPhoneDigits = (c.phone || c.whatsapp || '').replace(/[^0-9]/g, '');
      return (cPhoneDigits.length > 5 && (cPhoneDigits === normalizedDigits || normalizedDigits.endsWith(cPhoneDigits) || cPhoneDigits.endsWith(normalizedDigits))) ||
        (cPhoneDigits.length >= 10 && normalizedDigits.length >= 10 && cPhoneDigits.slice(-10) === normalizedDigits.slice(-10));
    });
    const finalName = cleanSenderName || (existingOther && existingOther.name && !/whatsapp business|primary line|primary whatsapp|line \d|account_\d/i.test(existingOther.name) && !existingOther.name.startsWith('WhatsApp Customer') ? existingOther.name : `Customer (${cleanPhone.slice(-4)})`);

    const lineTag = payloadAccountId === 'account_2' ? 'Line 2 Lead' : 'Line 1 Lead';
    customer = {
      id: newCustId,
      code: `CUST-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`,
      name: finalName,
      phone: cleanPhone,
      whatsapp: cleanPhone,
      jid: payload.sender_jid || '',
      accountId: payloadAccountId,
      businessNumber: payloadBusinessNum,
      address: '',
      city: 'Direct Inbound',
      customerType: 'Live WhatsApp Lead',
      tags: ['Live WhatsApp', lineTag],
      totalOrders: 0,
      totalSpend: 0,
      avatar: safeAvatar
    };
    CRM_STATE.customers.unshift(customer);
  } else {
    customer.accountId = payloadAccountId;
    if (payloadBusinessNum && payloadBusinessNum !== 'Primary') customer.businessNumber = payloadBusinessNum;

    // Self-healing: heal customer phone and name if corrupted with trailing 0 or line slot label
    customer.phone = cleanPhone;
    customer.whatsapp = cleanPhone;
    if (/whatsapp business|primary line|primary whatsapp|line \d|account_\d/i.test(customer.name)) {
      customer.name = cleanSenderName || `Customer (${cleanPhone.slice(-4)})`;
      customer.avatar = safeAvatar;
    } else if (!isOutboundMsg && cleanSenderName && (customer.name.startsWith('Customer') || customer.name.startsWith('WhatsApp Customer'))) {
      customer.name = cleanSenderName;
      customer.avatar = safeAvatar;
    }

    if (payload.sender_jid && !customer.jid) {
      customer.jid = payload.sender_jid;
    }
    const currentLineTag = payloadAccountId === 'account_2' ? 'Line 2 Lead' : 'Line 1 Lead';
    if (Array.isArray(customer.tags) && !customer.tags.includes(currentLineTag)) {
      customer.tags.push(currentLineTag);
    }
  }

  // 3. Add message to customer's conversation stream
  if (!CRM_STATE.conversations) {
    CRM_STATE.conversations = {};
  }
  if (!CRM_STATE.conversations[customer.id]) {
    CRM_STATE.conversations[customer.id] = [];
  }
  if (payload.customer_id && payload.customer_id !== customer.id && !CRM_STATE.conversations[payload.customer_id]) {
    CRM_STATE.conversations[payload.customer_id] = CRM_STATE.conversations[customer.id];
  }

  const isBotMsg = Boolean(payload.source === 'AUTOREPLY_BOT' || payload.is_bot || payload.sender === 'bot');
  const msgSender = isBotMsg ? 'bot' : (isOutboundMsg ? 'staff' : (payload.sender || 'customer'));

  // Deduplicate against existing messages
  const existingMsgs = CRM_STATE.conversations[customer.id];
  const payloadUid = String(payload.message_uid || payload.id || '');
  let matchingMessage = null;

  if (payloadUid) {
    matchingMessage = existingMsgs.find(m =>
      String(m.message_uid || m.id || '') === payloadUid
    );
  }

  if (!matchingMessage && isOutboundMsg) {
    matchingMessage = existingMsgs.find(m =>
      m.sender === 'staff' &&
      String(m.text || '') === String(messageText) &&
      Math.abs(msgTimestamp - Number(m.timestamp || 0)) < 120000
    );
  }

  if (!matchingMessage && !isOutboundMsg) {
    const isDuplicate = existingMsgs.some(m =>
      (payload.id && String(m.id) === String(payload.id)) ||
      (m.sender === msgSender && m.text === messageText && (m.time === timeStr || Math.abs(msgTimestamp - (m.timestamp || 0)) < 15000)) ||
      (mediaUrl && m.media_url && String(m.media_url).slice(-30) === String(mediaUrl).slice(-30))
    );
    if (isDuplicate) matchingMessage = true;
  }

  if (matchingMessage && matchingMessage !== true) {
    matchingMessage.id = payloadUid || matchingMessage.id;
    matchingMessage.message_uid = payloadUid || matchingMessage.message_uid;
    matchingMessage.status = payload.status || 'DELIVERED';
    matchingMessage.timestamp = matchingMessage.timestamp || msgTimestamp;
    if (mediaUrl && !matchingMessage.media_url) matchingMessage.media_url = mediaUrl;
  } else if (!matchingMessage) {
    const newMsg = {
      id: payload.id || msgTimestamp,
      sender: msgSender,
      isBot: isBotMsg,
      rule_name: payload.rule_name || null,
      rule_id: payload.rule_id || null,
      text: messageText,
      time: timeStr,
      status: 'DELIVERED',
      type: msgType,
      media_url: mediaUrl,
      duration: duration,
      timestamp: msgTimestamp
    };
    CRM_STATE.conversations[customer.id].push(newMsg);

    // Dynamic Bot Automation & Chosen Products Activity Tracker
    syncCustomerAutomationHistory(customer);

    // Trigger simulated auto-reply if message is from customer simulator / test mode
    if (!isOutboundMsg && (payload.source === 'SIMULATOR' || payload.source === 'TEST') && CRM_STATE?.autoReplySettings?.enabled !== false) {
      triggerClientSideAutoReplyIfMatched(customer, messageText);
    }
  }

  // 4. Match or Create Lead / Query Card
  let query = CRM_STATE.queries.find(q => q.customerId === customer.id);
  if (!query && customer.phone) {
    const custDigits = customer.phone.replace(/[^0-9]/g, '');
    query = CRM_STATE.queries.find(q => {
      const qCust = CRM_STATE.customers.find(c => c.id === q.customerId);
      const qDigits = (qCust?.phone || qCust?.whatsapp || '').replace(/[^0-9]/g, '');
      return (custDigits.length >= 10 && qDigits.length >= 10 && custDigits.slice(-10) === qDigits.slice(-10));
    });
  }
  if (query) {
    if (!query.accountId) query.accountId = payloadAccountId;
    if (!query.businessNumber) query.businessNumber = payloadBusinessNum;
    if (payload.assigned_to && payload.assigned_to !== 'UNASSIGNED') {
      query.assignedTo = payload.assigned_to;
      customer.assignedTo = payload.assigned_to;
    } else if (customer.assignedTo && customer.assignedTo !== 'UNASSIGNED') {
      query.assignedTo = customer.assignedTo;
    }
    if (!isDuplicate && !isOutboundMsg) {
      query.unreadCount = (query.unreadCount || 0) + 1;
    }
    query.lastMessage = isBotMsg ? `Bot: "${messageText.slice(0, 35)}..."` : (isOutboundMsg ? `Staff: "${messageText.slice(0, 35)}..."` : `Customer: "${messageText}"`);
    if (!isOutboundMsg) {
      query.status = (query.status === 'CLOSED' || query.status === 'RESOLVED') ? 'NEW' : query.status;
    }
    query.createdAt = timeStr;
    query.lastTimeEpoch = msgTimestamp;

    // Move query to top of queries array
    CRM_STATE.queries = [query, ...CRM_STATE.queries.filter(q => q.id !== query.id)];
  } else {
    const initAssigned = (payload.assigned_to && payload.assigned_to !== 'UNASSIGNED') ? payload.assigned_to : (customer.assignedTo || 'UNASSIGNED');
    query = {
      id: `Q-${new Date().getFullYear()}-${Math.floor(100000 + Math.random() * 900000)}`,
      customerId: customer.id,
      accountId: payloadAccountId,
      businessNumber: payloadBusinessNum,
      assignedTo: initAssigned,
      status: (initAssigned !== 'UNASSIGNED') ? 'ASSIGNED' : 'NEW',
      priority: payload.priority || 'HIGH',
      queryText: messageText,
      productSku: null,
      createdAt: timeStr,
      unreadCount: isOutboundMsg ? 0 : 1,
      lastMessage: isBotMsg ? `Bot: "${messageText.slice(0, 35)}..."` : (isOutboundMsg ? `Staff: "${messageText.slice(0, 35)}..."` : `Customer: "${messageText}"`),
      lastTimeEpoch: msgTimestamp
    };
    CRM_STATE.queries.unshift(query);
  }

  // Update customer latest activity timestamp for instant queue time alignment
  customer.lastMessage = messageText;
  customer.last_message = messageText;
  customer.lastMessageAt = timeStr;
  customer.last_message_at = new Date(msgTimestamp).toISOString().slice(0, 19).replace('T', ' ');
  customer.lastTimeEpoch = msgTimestamp;

  // 5. Update last poll epoch
  if (payload.timestamp_epoch) {
    LAST_POLL_EPOCH = Math.max(LAST_POLL_EPOCH, payload.timestamp_epoch);
  }

  // 6. Ensure ACTIVE_CUSTOMER_ID is valid
  if (!ACTIVE_CUSTOMER_ID || !CRM_STATE.customers.some(c => c.id === ACTIVE_CUSTOMER_ID)) {
    ACTIVE_CUSTOMER_ID = customer.id;
  }

  // 7. Save state & refresh UI
  saveCRMState();

  // Re-render Views instantly in-place (Zero Page Refresh)
  if (ACTIVE_VIEW === 'inbox') {
    renderInbox();
    const stream = document.getElementById('chat-messages-stream');
    if (stream) stream.scrollTop = stream.scrollHeight;
  } else if (ACTIVE_VIEW === 'enquiries') {
    if (typeof renderEnquiriesTable === 'function') renderEnquiriesTable();
  } else if (ACTIVE_VIEW === 'dashboard') {
    if (typeof renderDashboard === 'function') renderDashboard();
  }
  updateBadgeCounters();

  // 8. Audio chime & Live notification (if not suppressing initial batch)
  if (!suppressChime && !isDuplicate) {
    if (typeof playChime === 'function') playChime('inbound');
    showToast(
      'New WhatsApp Message Received',
      `${customer.name}: "${messageText.length > 50 ? messageText.slice(0, 50) + '...' : messageText}"`,
      'chat',
      'emerald'
    );
    
  }

  // 9. Automated Stock Category Instant Auto-Responder Engine
  // For live WhatsApp messages, bridge/server.js handles actual WhatsApp dispatch via Baileys and emits the real bot reply.
  // Frontend only simulates for offline TEST or SIMULATOR mode to prevent phantom "Sent Auto" bubbles.
  if (!suppressChime && !isDuplicate && payload.source !== 'STAFF_OUTBOUND' && payload.source !== 'AUTOREPLY_BOT') {
    if (payload.source === 'SIMULATOR' || payload.source === 'TEST') {
      handleAutomatedInboundResponse(customer, messageText, payload);
    }
  }
}

// Background & Immediate REST incoming call polling loop
let LAST_PROCESSED_RINGING_CALL_ID = null;
if (!window.DISMISSED_CALL_IDS) {
  try {
    const saved = sessionStorage.getItem('GRM_DISMISSED_CALL_IDS');
    window.DISMISSED_CALL_IDS = new Set(saved ? JSON.parse(saved) : []);
  } catch (e) {
    window.DISMISSED_CALL_IDS = new Set();
  }
}

function syncIncomingCallsNow() {
  fetch('api.php?action=get_incoming_calls')
    .then(r => r.json())
    .then(res => {
      if (res && res.status === 'success' && Array.isArray(res.incoming_calls)) {
        const ringingCall = res.incoming_calls.find(c => c.status === 'RINGING');
        if (ringingCall) {
          const callId = ringingCall.call_id || ringingCall.id;
          if (!callId) return;

          // Check call age safely (handling epoch and UTC strings)
          let ageSec = 0;
          if (ringingCall.epoch && res.server_time) {
            ageSec = Math.max(0, res.server_time - ringingCall.epoch);
          } else if (ringingCall.timestamp) {
            ageSec = Math.floor((Date.now() - Number(ringingCall.timestamp)) / 1000);
          } else if (ringingCall.started_at) {
            const sStr = ringingCall.started_at.includes('Z') || ringingCall.started_at.includes('+')
              ? ringingCall.started_at
              : ringingCall.started_at.replace(' ', 'T') + 'Z';
            const parsed = Date.parse(sStr);
            if (!isNaN(parsed)) ageSec = Math.floor((Date.now() - parsed) / 1000);
          }
          if (ageSec > 50) return;

          // Never pop up a call already dismissed or claimed in this session
          if (window.DISMISSED_CALL_IDS && window.DISMISSED_CALL_IDS.has(callId)) return;

          const modalEl = document.getElementById('modal-incoming-call-alert');
          const currentModalId = document.getElementById('incoming-call-id')?.value;
          const isModalVisible = modalEl && !modalEl.classList.contains('hidden');

          if (currentModalId === callId && isModalVisible) return;

          if (callId !== LAST_PROCESSED_RINGING_CALL_ID) {
            LAST_PROCESSED_RINGING_CALL_ID = callId;
            ringingCall.call_id = callId;
            if (typeof handleSocketIncomingCall === 'function') {
              handleSocketIncomingCall(ringingCall);
            }
          }
        }
      }
    })
    .catch(() => { });
}

// Background & Immediate REST message polling loop
function applyUpdatedCustomersDelta(updatedCustomers) {
  if (!Array.isArray(updatedCustomers) || updatedCustomers.length === 0) return false;
  let hasCustUpdates = false;
  updatedCustomers.forEach(uc => {
    if (!uc || !uc.id) return;
    const existing = (CRM_STATE.customers || []).find(c => c && (c.id === uc.id || String(c.id) === String(uc.id)));
    if (existing) {
      if (uc.name !== undefined && uc.name) existing.name = uc.name;
      if (uc.phone !== undefined && uc.phone) existing.phone = uc.phone;
      if (uc.whatsapp !== undefined && uc.whatsapp) existing.whatsapp = uc.whatsapp;
      if (uc.alt_phone !== undefined || uc.altPhone !== undefined) {
        existing.altPhone = uc.alt_phone || uc.altPhone || '';
        existing.alt_phone = uc.alt_phone || uc.altPhone || '';
      }
      if (uc.address !== undefined) existing.address = uc.address;
      if (uc.alt_address !== undefined || uc.altAddress !== undefined) {
        existing.altAddress = uc.alt_address || uc.altAddress || '';
        existing.alt_address = uc.alt_address || uc.altAddress || '';
      }
      if (uc.notes !== undefined && uc.notes !== null) existing.notes = uc.notes;
      if (uc.gender !== undefined) existing.gender = uc.gender;
      if (uc.age !== undefined) existing.age = uc.age;
      if (uc.email !== undefined) existing.email = uc.email;
      if (uc.tags !== undefined) existing.tags = Array.isArray(uc.tags) ? uc.tags : (typeof uc.tags === 'string' ? (JSON.parse(uc.tags || '[]') || []) : []);
      if (uc.customer_type || uc.customerType) existing.customerType = uc.customer_type || uc.customerType;
      if (existing.name) {
        const nameChars = Array.from(existing.name || 'WA');
        existing.avatar = (nameChars.slice(0, 2).join('')).toUpperCase();
      }
      hasCustUpdates = true;

      // Realtime Customer 360 live update for active chat customer across all browsers
      if (typeof ACTIVE_CUSTOMER_ID !== 'undefined' && String(ACTIVE_CUSTOMER_ID) === String(existing.id)) {
        if (!window.CUSTOMER_EDIT_MODES || !window.CUSTOMER_EDIT_MODES.has(existing.id)) {
          if (typeof renderCustomer360Panel === 'function') renderCustomer360Panel();
          if (typeof renderChatHeader === 'function') renderChatHeader();
        }
      }
    } else {
      CRM_STATE.customers.push({
        id: uc.id,
        code: uc.code || ('CUST-' + Date.now().toString().slice(-4)),
        name: uc.name || 'Customer',
        phone: uc.phone || '',
        whatsapp: uc.whatsapp || uc.phone || '',
        altPhone: uc.alt_phone || uc.altPhone || '',
        alt_phone: uc.alt_phone || uc.altPhone || '',
        address: uc.address || '',
        altAddress: uc.alt_address || uc.altAddress || '',
        alt_address: uc.alt_address || uc.altAddress || '',
        notes: uc.notes || '',
        gender: uc.gender || '',
        age: uc.age || '',
        email: uc.email || '',
        customerType: uc.customer_type || uc.customerType || 'Live WhatsApp Lead',
        avatar: (uc.name ? uc.name.slice(0, 2) : 'CU').toUpperCase()
      });
      hasCustUpdates = true;
    }
  });
  return hasCustUpdates;
}
window.applyUpdatedCustomersDelta = applyUpdatedCustomersDelta;

// Multi-Tab & Cross-Browser Real-Time WhatsApp Account Sync Bus
var CRM_WHATSAPP_CHANNEL = (typeof BroadcastChannel !== 'undefined') ? new BroadcastChannel('crm_whatsapp_sync_bus') : null;
if (CRM_WHATSAPP_CHANNEL) {
  CRM_WHATSAPP_CHANNEL.onmessage = function (ev) {
    if (ev && ev.data) {
      if (ev.data.accounts) {
        applyUpdatedAccountsDelta(ev.data.accounts, false);
      }
      if (ev.data.action === 'bulk_assigned') {
        handleRemoteBulkAssignment(ev.data);
      }
    }
  };
}

// Window Storage Event Listener for cross-window / cross-tab broadcast synchronization
if (typeof window !== 'undefined') {
  window.addEventListener('storage', function (e) {
    if (e.key === 'GRM_LAST_BULK_ASSIGN' && e.newValue) {
      try {
        const parsed = JSON.parse(e.newValue);
        if (parsed && parsed.action === 'bulk_assigned') {
          handleRemoteBulkAssignment(parsed);
        }
      } catch (err) { }
    }
  });
}

function handleRemoteBulkAssignment(data) {
  if (!data || !CRM_STATE) return;
  const staffId = String(data.staff_id || '').toLowerCase();
  const staffName = data.staff_name || 'Staff Member';
  const targetCustIds = new Set((data.customer_ids || []).map(String));
  const targetQueryIds = new Set((data.query_ids || []).map(String));
  const candidates = Array.isArray(data.candidates) ? data.candidates : [];

  // 1. Update existing in-memory customer models
  (CRM_STATE.customers || []).forEach(c => {
    if (targetCustIds.has(String(c.id))) {
      c.assignedTo = data.staff_id;
      c.assigned_to = data.staff_id;
    }
  });

  // 2. Update existing in-memory query models
  (CRM_STATE.queries || []).forEach(q => {
    if (targetQueryIds.has(String(q.id)) || targetCustIds.has(String(q.customerId || q.customer_id))) {
      q.assignedTo = data.staff_id;
      q.assigned_to = data.staff_id;
      q.status = 'ASSIGNED';
    }
  });

  // 3. Inject or update candidate leads in CRM_STATE
  candidates.forEach(cand => {
    const cId = String(cand.customerId || cand.customer_id || '');
    const clean10 = String(cand.customerPhone || '').replace(/\D/g, '').slice(-10);

    let cust = (CRM_STATE.customers || []).find(c => String(c.id) === cId);
    if (!cust && clean10) {
      cust = (CRM_STATE.customers || []).find(c => {
        const d = String(c.phone || c.whatsapp || '').replace(/\D/g, '').slice(-10);
        return d === clean10;
      });
    }

    if (cust) {
      cust.assignedTo = data.staff_id;
      cust.assigned_to = data.staff_id;
    } else if (cId || clean10) {
      const newCust = {
        id: cId || ('cust_' + clean10),
        name: cand.customerName || 'Customer',
        phone: cand.customerPhone || '',
        whatsapp: cand.customerPhone || '',
        assignedTo: data.staff_id,
        assigned_to: data.staff_id,
        accountId: cand.accountId || 'account_1',
        createdAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        lastMessage: 'Customer WhatsApp Enquiry'
      };
      if (!Array.isArray(CRM_STATE.customers)) CRM_STATE.customers = [];
      CRM_STATE.customers.unshift(newCust);
    }

    let qry = (CRM_STATE.queries || []).find(q => {
      if (!q) return false;
      if (String(q.id) === String(cand.queryId || cand.id)) return true;
      if (cId && String(q.customerId || q.customer_id) === cId) return true;
      if (clean10) {
        const qp = String(q.customerPhone || q.customer_phone || '').replace(/\D/g, '').slice(-10);
        if (qp === clean10) return true;
      }
      return false;
    });

    if (qry) {
      qry.assignedTo = data.staff_id;
      qry.assigned_to = data.staff_id;
      qry.status = 'ASSIGNED';
    } else {
      const newQ = {
        id: cand.queryId || (clean10 ? ('Q-' + clean10) : ('Q-' + (cId || Date.now()))),
        customerId: cId || (clean10 ? ('cust_' + clean10) : ('cust_' + Date.now())),
        customer_id: cId || (clean10 ? ('cust_' + clean10) : ('cust_' + Date.now())),
        customerName: cand.customerName || 'Customer',
        customerPhone: cand.customerPhone || '',
        assignedTo: data.staff_id,
        assigned_to: data.staff_id,
        accountId: cand.accountId || 'account_1',
        status: 'ASSIGNED',
        priority: 'NORMAL',
        queryText: 'WhatsApp Customer Enquiry',
        lastMessage: 'WhatsApp Customer Enquiry',
        createdAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      };
      if (!Array.isArray(CRM_STATE.queries)) CRM_STATE.queries = [];
      CRM_STATE.queries.unshift(newQ);
    }
  });

  saveCRMState();

  // Check if current user is this staff member
  const currentUser = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER) ? CURRENT_USER : ((typeof CRM_AUTH_SESSION !== 'undefined') ? CRM_AUTH_SESSION : null);
  const isTargetStaff = currentUser && (
    String(currentUser.id).toLowerCase() === staffId ||
    String(currentUser.staffId || '').toLowerCase() === staffId ||
    String(currentUser.staff_id || '').toLowerCase() === staffId ||
    String(currentUser.username || '').toLowerCase() === staffId ||
    String(currentUser.name || '').toLowerCase() === staffName.toLowerCase()
  );

  if (isTargetStaff) {
    if (typeof playChime === 'function') playChime('inbound');
    if (typeof showToast === 'function') {
      showToast(
        'New Leads Assigned',
        `${data.assigned_count || candidates.length} customer inquiries dynamically added to your queue!`,
        'assignment_ind',
        'emerald'
      );
    }
  }

  if (typeof renderInboxConversationList === 'function') renderInboxConversationList();
  if (typeof renderInbox === 'function') renderInbox();
  if (typeof updateBadgeCounters === 'function') updateBadgeCounters();
  if (typeof updateBulkAssignBadgeCounters === 'function') updateBulkAssignBadgeCounters();
}
window.handleRemoteBulkAssignment = handleRemoteBulkAssignment;

function broadcastWhatsAppSyncEvent(data) {
  if (CRM_WHATSAPP_CHANNEL) {
    try {
      CRM_WHATSAPP_CHANNEL.postMessage(data);
    } catch (e) { }
  }
}
window.broadcastWhatsAppSyncEvent = broadcastWhatsAppSyncEvent;

function isPhantomWhatsAppAccount(acc) {
  if (!acc) return true;
  const id = String(acc.id || acc.account_slot || '');
  const label = String(acc.label || acc.name || acc.display_name || '');
  if (id === 'account_3' || id === 'account_4' || id === 'account_5' || id.startsWith('account_1795')) {
    return true;
  }
  if (label.includes('Customer Support') || label.includes('Wholesale & Bulk') || label.includes('VIP Fast-Track')) {
    return true;
  }
  return false;
}
window.isPhantomWhatsAppAccount = isPhantomWhatsAppAccount;

function applyUpdatedAccountsDelta(accounts, shouldBroadcast = true, isExplicitLogout = false) {
  if (!Array.isArray(accounts) || accounts.length === 0) return;
  // Strictly filter out phantom accounts (Lines 3, 4, 5 and account_1795...)
  accounts = accounts.filter(a => !isPhantomWhatsAppAccount(a));

  MULTI_ACCOUNTS_STATE = accounts;
  if (!Array.isArray(CRM_STATE.whatsappLines)) {
    CRM_STATE.whatsappLines = [];
  }
  // Purge any previously stored phantom lines
  CRM_STATE.whatsappLines = CRM_STATE.whatsappLines.filter(a => !isPhantomWhatsAppAccount(a));

  accounts.forEach(acc => {
    let existing = CRM_STATE.whatsappLines.find(l => l.id === acc.id);
    if (existing) {
      const incomingRawPhone = acc.phone || acc.connected_number || '';
      const hasIncomingRealPhone = incomingRawPhone && 
                                   incomingRawPhone !== 'Awaiting Link' && 
                                   incomingRawPhone !== 'Scan QR Code' &&
                                   !incomingRawPhone.includes('Awaiting');

      const existingPhone = (existing.connected_number && existing.connected_number !== 'Awaiting Link' && existing.connected_number !== 'Scan QR Code')
        ? existing.connected_number
        : (CRM_STATE?.whatsappAccount?.phoneNumber && CRM_STATE.whatsappAccount.phoneNumber !== 'Awaiting Link' && CRM_STATE.whatsappAccount.phoneNumber !== 'Scan QR Code' ? CRM_STATE.whatsappAccount.phoneNumber : '');

      // If bridge returns SCAN_QR with a QR image, immediately accept SCAN_QR so user can scan!
      if (acc.status === 'SCAN_QR') {
        existing.status = 'SCAN_QR';
        existing.qr_image = acc.qr_image || existing.qr_image || null;
        existing.connected_number = 'Scan QR Code';
      } else if (acc.status === 'DISCONNECTED' || isExplicitLogout) {
        existing.status = 'DISCONNECTED';
        existing.qr_image = null;
        existing.connected_number = 'Awaiting Link';
      } else if (acc.status === 'CONNECTED') {
        existing.status = 'CONNECTED';
        existing.connected_number = hasIncomingRealPhone ? incomingRawPhone : (existingPhone || acc.connected_number);
        existing.qr_image = null;
      } else {
        existing.status = (acc.status || 'DISCONNECTED').toUpperCase();
        existing.qr_image = acc.qr_image || null;
      }
      existing.label = acc.label || acc.name || existing.label;
    } else {
      if (!Array.isArray(CRM_STATE.deletedSlots) || !CRM_STATE.deletedSlots.includes(acc.id)) {
        CRM_STATE.whatsappLines.push({
          id: acc.id,
          label: acc.label || acc.name || `WhatsApp Line (${acc.id})`,
          status: (acc.status || 'DISCONNECTED').toUpperCase(),
          connected_number: acc.phone || acc.connected_number || 'Awaiting Link',
          qr_image: acc.qr_image || null,
          brand_name: acc.label || acc.name || acc.id
        });
      }
    }
  });

  const primary = accounts.find(a => a.id === 'account_1') || accounts[0];
  const deltaStaffPhones = (CRM_STATE?.staffList || []).map(s => (s.phone || s.mobile || '').replace(/\D/g, '')).filter(p => p.length >= 7);
  const isStaffNumber = ph => deltaStaffPhones.some(sp => sp && String(ph).replace(/\D/g, '').endsWith(sp));

  if (CRM_STATE.whatsappAccount) {
    const primaryPhone = primary?.phone || primary?.connected_number;
    if (primary && primary.status === 'CONNECTED' && primaryPhone && !isStaffNumber(primaryPhone) && primaryPhone !== 'Awaiting Link') {
      CRM_STATE.whatsappAccount.phoneNumber = primaryPhone;
      CRM_STATE.whatsappAccount.status = 'CONNECTED';
    } else {
      const currentSavedPhone = CRM_STATE.whatsappAccount.phoneNumber;
      const hasRealSavedPhone = currentSavedPhone && currentSavedPhone !== 'Awaiting Link' && currentSavedPhone !== 'Scan QR Code' && !isStaffNumber(currentSavedPhone);
      if (hasRealSavedPhone) {
        CRM_STATE.whatsappAccount.phoneNumber = currentSavedPhone;
        if (CRM_STATE.whatsappAccount.status === 'CONNECTED' && !isExplicitLogout) {
          // Retain CONNECTED: Never demote an authenticated account to DISCONNECTED on network hiccup!
        } else {
          CRM_STATE.whatsappAccount.status = (primary?.status || 'DISCONNECTED').toUpperCase();
        }
      } else {
        CRM_STATE.whatsappAccount.status = (primary?.status || 'DISCONNECTED').toUpperCase();
      }
    }
  }

  saveCRMState();
  if (typeof renderMultiAccountsHub === 'function') renderMultiAccountsHub();
  if (typeof renderQuickLineSwitcher === 'function') renderQuickLineSwitcher();
  if (typeof renderPhoneSwitcherDropdown === 'function') renderPhoneSwitcherDropdown();
  if (typeof updateConfiguredPhoneDisplays === 'function') updateConfiguredPhoneDisplays();

  if (shouldBroadcast && typeof getAvailableWhatsAppAccounts === 'function') {
    broadcastWhatsAppSyncEvent({ action: 'sync_delta', accounts: getAvailableWhatsAppAccounts() });
  }
}
window.applyUpdatedAccountsDelta = applyUpdatedAccountsDelta;

function syncInboundMessagesNow(isInitial = false) {
  const since = isInitial ? 0 : LAST_POLL_EPOCH;
  return fetch(`api.php?action=get_inbound_messages&since=${since}`)
    .then(r => r.json())
    .then(res => {
      if (res && res.status === 'success') {
        let hasMsgUpdates = false;
        if (res.messages && res.messages.length > 0) {
          res.messages.forEach(msg => ingestInboundMessage(msg, isInitial));
          hasMsgUpdates = true;
          if (res.server_time) {
            LAST_POLL_EPOCH = Math.max(LAST_POLL_EPOCH, res.server_time);
          }
        }
        let hasAssignmentUpdates = false;
        if (Array.isArray(res.assignments) && res.assignments.length > 0) {
          res.assignments.forEach(asgn => {
            let q = (CRM_STATE.queries || []).find(qry => qry && (qry.id === asgn.query_id || qry.customerId === asgn.customer_id || qry.customer_id === asgn.customer_id));
            if (q) {
              if (q.assignedTo !== asgn.assigned_to) {
                q.assignedTo = asgn.assigned_to;
                hasAssignmentUpdates = true;
              }
              if (asgn.status && q.status !== asgn.status) {
                q.status = asgn.status;
                hasAssignmentUpdates = true;
              }
            }
            let c = (CRM_STATE.customers || []).find(cust => cust && (cust.id === asgn.customer_id || (asgn.phone && (cust.phone === asgn.phone || cust.whatsapp === asgn.phone))));
            if (c && c.assignedTo !== asgn.assigned_to) {
              c.assignedTo = asgn.assigned_to;
              hasAssignmentUpdates = true;
            }
          });
        }
        let hasCustUpdates = false;
        if (Array.isArray(res.updated_customers) && res.updated_customers.length > 0) {
          hasCustUpdates = applyUpdatedCustomersDelta(res.updated_customers);
        }
        if (hasAssignmentUpdates || hasMsgUpdates || hasCustUpdates) {
          saveCRMState();
          if (ACTIVE_VIEW === 'inbox') {
            renderInbox();
          }
          updateBadgeCounters();
        }
      }
    })
    .catch(() => { });
}

// =========================================================================
// PHASE 4: SERVER-SENT EVENTS (SSE) REAL-TIME PUSH PIPELINE
// Replaces 2.5s short-polling with persistent HTTP stream (< 50ms latency)
// Server CPU drops to ~0% when idle; inbound WhatsApp messages arrive instantly
// =========================================================================
window.CRM_SSE_INSTANCE = null;
window.IS_SSE_STREAM_ACTIVE = false;

function initSSEStream() {
  if (typeof EventSource === 'undefined') {
    console.warn('⚠️ [SSE]: Browser does not support EventSource; continuing with delta polling');
    return false;
  }

  // Close previous connection if active or stale
  if (window.CRM_SSE_INSTANCE) {
    try {
      window.CRM_SSE_INSTANCE.close();
    } catch (e) { }
    window.CRM_SSE_INSTANCE = null;
  }

  const sseUrl = `sse.php?since=${LAST_POLL_EPOCH || 0}`;
  try {
    const es = new EventSource(sseUrl);
    window.CRM_SSE_INSTANCE = es;

    es.onopen = function () {
      window.IS_SSE_STREAM_ACTIVE = true;
      console.log('⚡ [SSE Stream Active]: Real-time event pipeline connected (0% idle CPU, <50ms push)');
    };

    es.onmessage = function (event) {
      if (!event || !event.data) return;
      try {
        const res = JSON.parse(event.data);
        if (res && res.status === 'success') {
          let hasMsgUpdates = false;
          if (Array.isArray(res.messages) && res.messages.length > 0) {
            res.messages.forEach(msg => ingestInboundMessage(msg, false));
            hasMsgUpdates = true;
            if (res.server_time) {
              LAST_POLL_EPOCH = Math.max(LAST_POLL_EPOCH, res.server_time);
            }
          }

          let hasAssignmentUpdates = false;
          if (Array.isArray(res.assignments) && res.assignments.length > 0) {
            const currentUser = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER) ? CURRENT_USER : ((typeof CRM_AUTH_SESSION !== 'undefined') ? CRM_AUTH_SESSION : null);
            let targetStaffNotified = false;

            res.assignments.forEach(asgn => {
              const staffId = asgn.assigned_to;
              const qId = asgn.query_id;
              const cId = asgn.customer_id;
              const cPhone = asgn.phone || asgn.customer_phone || '';
              const clean10 = cPhone ? String(cPhone).replace(/\D/g, '').slice(-10) : '';

              let q = (CRM_STATE.queries || []).find(qry => qry && (qry.id === qId || qry.customerId === cId || qry.customer_id === cId || (clean10 && String(qry.customerPhone || qry.customer_phone || '').includes(clean10))));
              if (q) {
                if (q.assignedTo !== staffId || q.assigned_to !== staffId) {
                  q.assignedTo = staffId;
                  q.assigned_to = staffId;
                  hasAssignmentUpdates = true;
                }
                if (asgn.status && q.status !== asgn.status) {
                  q.status = asgn.status;
                  hasAssignmentUpdates = true;
                }
              } else if (qId || cId || clean10) {
                const newQ = {
                  id: qId || ('Q-' + (clean10 || cId)),
                  customerId: cId || ('cust_' + clean10),
                  customer_id: cId || ('cust_' + clean10),
                  customerName: asgn.name || asgn.customer_name || 'Customer',
                  customerPhone: cPhone,
                  assignedTo: staffId,
                  assigned_to: staffId,
                  accountId: asgn.account_id || 'account_1',
                  status: asgn.status || 'ASSIGNED',
                  priority: 'NORMAL',
                  queryText: 'WhatsApp Customer Enquiry',
                  lastMessage: 'WhatsApp Customer Enquiry',
                  createdAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
                };
                if (!Array.isArray(CRM_STATE.queries)) CRM_STATE.queries = [];
                CRM_STATE.queries.unshift(newQ);
                hasAssignmentUpdates = true;
              }

              let c = (CRM_STATE.customers || []).find(cust => cust && (cust.id === cId || (clean10 && String(cust.phone || cust.whatsapp || '').includes(clean10))));
              if (c) {
                if (c.assignedTo !== staffId || c.assigned_to !== staffId) {
                  c.assignedTo = staffId;
                  c.assigned_to = staffId;
                  hasAssignmentUpdates = true;
                }
              } else if (cId || clean10) {
                const newC = {
                  id: cId || ('cust_' + clean10),
                  name: asgn.name || asgn.customer_name || 'Customer',
                  phone: cPhone,
                  whatsapp: cPhone,
                  assignedTo: staffId,
                  assigned_to: staffId,
                  accountId: asgn.account_id || 'account_1',
                  createdAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                  lastMessage: 'WhatsApp Customer Enquiry'
                };
                if (!Array.isArray(CRM_STATE.customers)) CRM_STATE.customers = [];
                CRM_STATE.customers.unshift(newC);
                hasAssignmentUpdates = true;
              }

              // Check if notification is for current logged-in staff member
              if (!targetStaffNotified && currentUser && staffId) {
                const isTargetStaff = (
                  String(currentUser.id).toLowerCase() === String(staffId).toLowerCase() ||
                  String(currentUser.staffId || '').toLowerCase() === String(staffId).toLowerCase() ||
                  String(currentUser.staff_id || '').toLowerCase() === String(staffId).toLowerCase() ||
                  String(currentUser.username || '').toLowerCase() === String(staffId).toLowerCase()
                );
                if (isTargetStaff) {
                  targetStaffNotified = true;
                  if (typeof playChime === 'function') playChime('inbound');
                  if (typeof showToast === 'function') {
                    showToast('New Lead Received', `WhatsApp inquiry for ${asgn.name || asgn.customer_name || 'Customer'} assigned to you!`, 'assignment_ind', 'emerald');
                  }
                }
              }
            });
          }

          if (Array.isArray(res.incoming_calls) && res.incoming_calls.length > 0) {
            const ringingCall = res.incoming_calls.find(c => c.status === 'RINGING');
            if (ringingCall) {
              const callId = ringingCall.call_id || ringingCall.id;
              if (callId && (!window.DISMISSED_CALL_IDS || !window.DISMISSED_CALL_IDS.has(callId))) {
                if (callId !== LAST_PROCESSED_RINGING_CALL_ID) {
                  LAST_PROCESSED_RINGING_CALL_ID = callId;
                  ringingCall.call_id = callId;
                  if (typeof handleSocketIncomingCall === 'function') {
                    handleSocketIncomingCall(ringingCall);
                  }
                }
              }
            }
          }

          let hasCustUpdates = false;
          if (Array.isArray(res.updated_customers) && res.updated_customers.length > 0) {
            hasCustUpdates = applyUpdatedCustomersDelta(res.updated_customers);
          }

          if (Array.isArray(res.whatsapp_accounts) && res.whatsapp_accounts.length > 0) {
            applyUpdatedAccountsDelta(res.whatsapp_accounts, false);
          }

          if (hasAssignmentUpdates || hasMsgUpdates || hasCustUpdates) {
            saveCRMState();
            if (ACTIVE_VIEW === 'inbox') {
              renderInbox();
            }
            updateBadgeCounters();
          }
        }
      } catch (err) {
        console.warn('⚠️ [SSE Parse Error]:', err);
      }
    };

    es.onerror = function () {
      window.IS_SSE_STREAM_ACTIVE = false;
      // Note: native EventSource handles reconnect attempts automatically
    };

    return true;
  } catch (e) {
    window.IS_SSE_STREAM_ACTIVE = false;
    console.warn('⚠️ [SSE Init Failed]:', e);
    return false;
  }
}

function startRealtimeMessageSync() {
  // 1. Initial immediate sync
  syncInboundMessagesNow(true);

  // 2. Initialize persistent Server-Sent Events stream
  initSSEStream();

  // 3. Dynamic background heartbeat & graceful fallback loop:
  // When SSE is active: Short-polling is relaxed to 30 seconds (92% reduction in server hits).
  // When SSE is reconnecting / inactive: Polling runs every 10 seconds.
  let pollTicker = 0;
  setInterval(() => {
    if (typeof document !== 'undefined' && document.hidden) return;
    pollTicker++;

    // Ensure SSE stream is kept open if browser closed it
    if (!window.IS_SSE_STREAM_ACTIVE && (!window.CRM_SSE_INSTANCE || window.CRM_SSE_INSTANCE.readyState === (typeof EventSource !== 'undefined' ? EventSource.CLOSED : 2))) {
      initSSEStream();
    }

    // 12 ticks of 2.5s = 30s when SSE is active; 4 ticks = 10s fallback
    const intervalRequirement = window.IS_SSE_STREAM_ACTIVE ? 12 : 4;
    if (pollTicker % intervalRequirement === 0) {
      syncInboundMessagesNow(false);
      syncIncomingCallsNow();
    }
  }, 2500);

  // 4. Tab visibility re-sync: when user switches back to this tab, immediately catch up
  if (typeof document !== 'undefined' && typeof document.addEventListener === 'function') {
    document.addEventListener('visibilitychange', () => {
      if (!document.hidden) {
        syncInboundMessagesNow(false);
        if (!window.IS_SSE_STREAM_ACTIVE) {
          initSSEStream();
        }
      }
    });
  }
}

// Inbound Simulator Modal Controllers
function openInboundSimulatorModal() {
  openModal('modal-inbound-simulator');
}

function handleInboundSimulationSubmit(event) {
  event.preventDefault();
  const name = document.getElementById('sim-customer-name')?.value || 'New Customer';
  const phone = document.getElementById('sim-customer-phone')?.value || '+91 98401 23456';
  const text = document.getElementById('sim-message-text')?.value || 'Hello from WhatsApp';
  const type = document.getElementById('sim-message-type')?.value || 'text';
  const priority = document.getElementById('sim-message-priority')?.value || 'HIGH';
  const slot = document.getElementById('sim-account-slot')?.value || 'account_1';

  const simulatedPayload = {
    sender_name: name,
    sender_phone: phone,
    sender_jid: phone.replace(/[^0-9]/g, '') + '@s.whatsapp.net',
    message_text: text,
    type: type,
    media_url: null,
    duration: type === 'audio' ? 8 : null,
    account_id: slot,
    received_on_number: (CRM_STATE?.whatsappAccount?.phoneNumber && !isStaffMobile(CRM_STATE.whatsappAccount.phoneNumber)) ? CRM_STATE.whatsappAccount.phoneNumber : '',
    priority: priority,
    assigned_to: 'UNASSIGNED',
    source: 'INBOUND_SIMULATOR',
    timestamp_epoch: Math.floor(Date.now() / 1000),
    received_at: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
  };

  // Ingest locally
  ingestInboundMessage(simulatedPayload, false);

  // Also post to backend api.php
  fetch('api.php?action=receive_message', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(simulatedPayload)
  }).catch(() => { });

  closeModal('modal-inbound-simulator');
}

// Automated Deduplication Engine: Guarantees 1 Customer = 1 Card & 1 Unified Thread
function cleanupAndDeduplicateCRMState() {
  if (!CRM_STATE || !CRM_STATE.customers) return;

  // 1. Filter out mock system test customers & resolve WhatsApp LIDs to real phone numbers
  CRM_STATE.customers = CRM_STATE.customers.filter(c =>
    c &&
    c.name !== 'System' &&
    c.name !== 'GRM Linked WhatsApp Device' &&
    !c.name.startsWith('WhatsApp Linked')
  );

  CRM_STATE.customers.forEach(cust => {
    const raw = cust.phone || cust.whatsapp || '';
    if (raw.includes('156066293805087')) {
      cust.phone = '+91 95009 04638';
      cust.whatsapp = '+91 95009 04638';
      cust.jid = '156066293805087@lid';
    }
    if (raw.includes('254562812297404') || (cust.jid && cust.jid.includes('254562812297404'))) {
      cust.phone = '+91 73389 65560';
      cust.whatsapp = '+91 73389 65560';
      cust.jid = '254562812297404@lid';
    }
  });

  // 2. Deduplicate customers by normalized phone / whatsapp (last 10 digits) or JID
  const seenCustomers = new Map();
  const dedupedCustomers = [];

  CRM_STATE.customers.forEach(cust => {
    const clean = (cust.phone || cust.whatsapp || '').replace(/[^0-9]/g, '');
    let normKey = '';
    if (clean.length >= 10) {
      normKey = 'phone_' + clean.slice(-10);
    } else if (clean.length >= 5) {
      normKey = 'phone_' + clean;
    } else if (cust.jid) {
      normKey = 'jid_' + (cust.jid.split('@')[0] || cust.jid).toLowerCase();
    } else {
      normKey = 'id_' + cust.id;
    }

    if (!seenCustomers.has(normKey)) {
      seenCustomers.set(normKey, cust);
      dedupedCustomers.push(cust);
    } else {
      const existing = seenCustomers.get(normKey);

      // Prefer a real name over generic "Customer ..." or "WhatsApp Customer ..."
      if ((!existing.name || existing.name.startsWith('Customer') || existing.name.startsWith('WhatsApp Customer')) &&
        (cust.name && !cust.name.startsWith('Customer') && !cust.name.startsWith('WhatsApp Customer'))) {
        existing.name = cust.name;
        existing.avatar = cust.avatar || existing.avatar;
      }

      // Merge tags
      if (Array.isArray(cust.tags)) {
        if (!Array.isArray(existing.tags)) existing.tags = [];
        cust.tags.forEach(t => {
          if (!existing.tags.includes(t)) existing.tags.push(t);
        });
      }

      // Merge orders / spend
      if (cust.totalOrders) existing.totalOrders = (existing.totalOrders || 0) + (cust.totalOrders || 0);
      if (cust.totalSpend) existing.totalSpend = (existing.totalSpend || 0) + (cust.totalSpend || 0);

      // Merge conversation history into primary customer
      if (CRM_STATE.conversations && CRM_STATE.conversations[cust.id]) {
        if (!CRM_STATE.conversations[existing.id]) CRM_STATE.conversations[existing.id] = [];
        const existingMsgSet = new Set(CRM_STATE.conversations[existing.id].map(m => m.id || `${m.text}_${m.time || m.received_at}`));
        CRM_STATE.conversations[cust.id].forEach(m => {
          const mKey = m.id || `${m.text}_${m.time || m.received_at}`;
          if (!existingMsgSet.has(mKey)) {
            existingMsgSet.add(mKey);
            CRM_STATE.conversations[existing.id].push(m);
          }
        });
        if (cust.id !== existing.id) {
          delete CRM_STATE.conversations[cust.id];
        }
      }

      // Migrate followups, queries, and orders if customerId was deduplicated
      if (cust.id !== existing.id) {
        if (Array.isArray(CRM_STATE.followups)) {
          CRM_STATE.followups.forEach(f => {
            if (f && (f.customerId === cust.id || String(f.customerId) === String(cust.id))) {
              f.customerId = existing.id;
              f.customerName = existing.name || f.customerName;
            }
          });
        }
        if (Array.isArray(CRM_STATE.queries)) {
          CRM_STATE.queries.forEach(q => {
            if (q && (q.customerId === cust.id || String(q.customerId) === String(cust.id))) {
              q.customerId = existing.id;
            }
          });
        }
        if (Array.isArray(CRM_STATE.orders)) {
          CRM_STATE.orders.forEach(o => {
            if (o && (o.customerId === cust.id || String(o.customerId) === String(cust.id))) {
              o.customerId = existing.id;
              o.customerName = existing.name || o.customerName;
            }
          });
        }
        if (typeof ACTIVE_CUSTOMER_ID !== 'undefined' && ACTIVE_CUSTOMER_ID === cust.id) {
          ACTIVE_CUSTOMER_ID = existing.id;
        }
      }
    }
  });
  CRM_STATE.customers = dedupedCustomers;

  // 3. Deduplicate queries: exactly ONE active query per customer
  const seenQueryCustomers = new Set();
  const dedupedQueries = [];

  CRM_STATE.queries.forEach(q => {
    const custExists = CRM_STATE.customers.some(c => c.id === q.customerId);
    if (!custExists) return;

    if (!seenQueryCustomers.has(q.customerId)) {
      seenQueryCustomers.add(q.customerId);
      dedupedQueries.push(q);
    }
  });
  CRM_STATE.queries = dedupedQueries;

  // 4. Ensure all catalog products have valid, non-broken, beautiful garment images and clean descriptions
  if (Array.isArray(CRM_STATE.products)) {
    CRM_STATE.products.forEach(p => {
      if (!p.image || p.image.includes('photo-1518831959646-742c3a14ebf7') || p.image.includes('photo-1583846783977-d2b0993d4265') || p.image.includes('No Image') || p.image.includes('No%20Image')) {
        p.image = getSmartProductImage(p);
      }
      if (p.description && (p.description.includes('xdsgt') || p.description.includes('ytfdw') || /^[a-z]{12,}$/i.test(p.description.trim()))) {
        p.description = '';
      }
    });
  }

  saveCRMState();
}



// Robust two-way synchronization and non-destructive merge of catalog products
function mergeCatalogProductsWithDB(dbRawProducts) {
  if (!Array.isArray(dbRawProducts)) return;

  const mappedDb = dbRawProducts.map(p => ({
    id: p.id,
    sku: p.sku,
    name: p.name,
    category: p.category,
    subcategory: p.subcategory || '',
    size: p.size,
    color: p.color,
    fabric: p.fabric || '',
    specifications: (() => {
      if (!p.specifications) return [];
      if (Array.isArray(p.specifications)) return p.specifications;
      try { return JSON.parse(p.specifications); } catch (e) { return []; }
    })(),
    customAttributes: (() => {
      if (!p.custom_attributes && !p.customAttributes) return {};
      const ca = p.custom_attributes || p.customAttributes;
      if (typeof ca === 'object') return ca;
      try { return JSON.parse(ca); } catch (e) { return {}; }
    })(),
    price: parseFloat(p.price) || 0,
    mrp: parseFloat(p.mrp) || parseFloat(p.price) || 0,
    physicalStock: parseInt(p.physical_stock ?? p.physicalStock) || 0,
    reservedStock: parseInt(p.reserved_stock ?? p.reservedStock) || 0,
    image: p.image || getSmartProductImage(p),
    description: p.description || '',
    custom_caption: p.custom_caption || p.customCaption || '',
    customCaption: p.custom_caption || p.customCaption || '',
    accountId: p.account_id || p.accountId || 'account_1'
  }));

  const localProducts = Array.isArray(CRM_STATE.products) ? [...CRM_STATE.products] : [];

  // Merge DB products: if a matching local product exists, merge non-empty fields/specs
  const merged = mappedDb.map(dbP => {
    const localMatch = localProducts.find(lp => lp && (lp.sku === dbP.sku || (lp.id && String(lp.id) === String(dbP.id))));
    if (localMatch) {
      const bestImg = (dbP.image && !dbP.image.includes('photo-1583846783977-d2b0993d4265') && !dbP.image.includes('photo-1518831959646-742c3a14ebf7'))
        ? dbP.image
        : (localMatch.image || getSmartProductImage(dbP));
      return {
        ...localMatch,
        ...dbP,
        image: bestImg,
        customAttributes: (dbP.customAttributes && Object.keys(dbP.customAttributes).length > 0) ? dbP.customAttributes : (localMatch.customAttributes || {}),
        specifications: (dbP.specifications && dbP.specifications.length > 0) ? dbP.specifications : (localMatch.specifications || [])
      };
    }
    return dbP;
  });

  CRM_STATE.products = merged;
  saveCRMState();
}

// =========================================================================
// UNIVERSAL STALE CACHE PURGER: Guarantees 100% data consistency across all browsers
// =========================================================================
(function purgeLegacyStaleCaches() {
  const CURRENT_SYNC_VERSION = 'GRM_CRM_V3_LIVE_SYNC';
  try {
    if (typeof localStorage !== 'undefined' && localStorage.getItem('GRM_SYNC_VERSION') !== CURRENT_SYNC_VERSION) {
      localStorage.removeItem('GRM_CRM_STATE_V2_5');
      localStorage.removeItem('GRM_CRM_STATE_V2');
      localStorage.removeItem('GRM_CRM_STATE');
      localStorage.removeItem('CRM_ROLE_PERMISSIONS');
      localStorage.removeItem('GRM_NOTIFICATIONS');
      const keysToRemove = [];
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (k && (k.startsWith('GRM_TRACKED_PRODUCTS_') || k.startsWith('GRM_CRM_MOCK_') || k.startsWith('GRM_CACHE_'))) {
          keysToRemove.push(k);
        }
      }
      keysToRemove.forEach(k => localStorage.removeItem(k));
      localStorage.setItem('GRM_SYNC_VERSION', CURRENT_SYNC_VERSION);
    }
  } catch (e) {}
})();

// Cross-tab live broadcast channel for instant multi-tab sync
if (typeof window !== 'undefined' && 'BroadcastChannel' in window) {
  try {
    const crmSyncChannel = new BroadcastChannel('grm_crm_live_channel');
    crmSyncChannel.onmessage = (event) => {
      if (event && event.data && event.data.type === 'DATA_MUTATED') {
        if (event.data.mutation === 'NEW_OUTBOUND_MESSAGE' && event.data.payload) {
          try {
            const d = event.data.payload;
            const msgObj = d.message || {};
            const cId = d.customer_id;
            const targetCust = (window.CRM_STATE && Array.isArray(window.CRM_STATE.customers))
              ? window.CRM_STATE.customers.find(c => c && (String(c.id) === String(cId) || (d.phone && c.phone && c.phone.replace(/\D/g, '').slice(-10) === d.phone.replace(/\D/g, '').slice(-10))))
              : null;
            if (targetCust && window.CRM_STATE) {
              if (!window.CRM_STATE.conversations) window.CRM_STATE.conversations = {};
              if (!window.CRM_STATE.conversations[targetCust.id]) window.CRM_STATE.conversations[targetCust.id] = [];
              const exists = window.CRM_STATE.conversations[targetCust.id].some(m => (msgObj.id && String(m.id) === String(msgObj.id)) || (m.sender === 'staff' && m.text === msgObj.text && m.time === msgObj.time));
              if (!exists) {
                window.CRM_STATE.conversations[targetCust.id].push(msgObj);
                targetCust.last_message = msgObj.text || 'Message';
                targetCust.last_message_time = msgObj.time || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                if (typeof renderChatConversation === 'function') renderChatConversation();
                if (typeof renderCustomerList === 'function') renderCustomerList();
                if (typeof updateStats === 'function') updateStats();
              }
            }
          } catch (e) {
            console.warn('[BroadcastChannel NEW_OUTBOUND_MESSAGE error]', e);
          }
        }
        if (typeof syncLiveCRMData === 'function') {
          syncLiveCRMData(true);
        }
      }
    };
    window.broadcastCRMMutation = function (mutationType = 'UPDATE', extraPayload = null) {
      try {
        crmSyncChannel.postMessage({ type: 'DATA_MUTATED', mutation: mutationType, payload: extraPayload, time: Date.now() });
      } catch (e) {}
    };
  } catch (e) {}
}

/**
 * Applies authoritative database state from MySQL directly into CRM_STATE.
 * Eliminates phantom records, zombie queries, and cross-browser desynchronization.
 */
function applyAuthoritativeDatabaseState(data) {
  if (!data || typeof data !== 'object') return;

  // 1. Products & Inventory
  if (data.products && Array.isArray(data.products)) {
    if (typeof mergeCatalogProductsWithDB === 'function') {
      mergeCatalogProductsWithDB(data.products);
    } else {
      CRM_STATE.products = data.products;
    }
  }

  // 2. Taxonomy & Catalog Attributes (MySQL is the single source of truth)
  if (Array.isArray(data.categories)) {
    CRM_STATE.categories = data.categories;
  }
  if (Array.isArray(data.subcategories)) {
    CRM_STATE.subcategories = data.subcategories;
  }
  if (data.attributes && typeof data.attributes === 'object') {
    CRM_STATE.attributes = data.attributes;
    if (CRM_STATE.attributes && CRM_STATE.attributes.custom) {
      Object.keys(CRM_STATE.attributes.custom).forEach(key => {
        if (!key || key.startsWith('{') || key.startsWith('[') || key.includes('dashboard') || key.includes('bulk-assign') || key.includes('inbox') || key.includes('view') || key.length > 50) {
          delete CRM_STATE.attributes.custom[key];
        }
      });
    }
  }

  // 3. Customers (Direct authoritative MySQL sync - strictly replaces stale lists while preserving live chat customers)
  if (Array.isArray(data.customers)) {
    const dbCusts = data.customers.map(c => ({
      id: c.id,
      code: c.code || '',
      name: c.name || 'Customer',
      phone: c.phone || '',
      whatsapp: c.whatsapp || c.phone || '',
      assignedTo: c.assigned_to || c.assignedTo || 'UNASSIGNED',
      assigned_to: c.assigned_to || c.assignedTo || 'UNASSIGNED',
      accountId: c.account_id || c.accountId || 'account_1',
      account_id: c.account_id || c.accountId || 'account_1',
      customerType: c.customer_type || c.customerType || 'Live WhatsApp Lead',
      address: c.address || '',
      altAddress: c.alt_address || c.altAddress || '',
      alt_address: c.alt_address || c.altAddress || '',
      altPhone: c.alt_phone || c.altPhone || '',
      alt_phone: c.alt_phone || c.altPhone || '',
      email: c.email || '',
      gender: c.gender || '',
      age: c.age || '',
      notes: c.notes || '',
      tags: Array.isArray(c.tags) ? c.tags : (typeof c.tags === 'string' ? (JSON.parse(c.tags || '[]') || []) : []),
      totalOrders: parseInt(c.total_orders || c.totalOrders || 0),
      totalSpend: parseFloat(c.total_spend || c.totalSpend || 0),
      isDND: Boolean(c.is_dnd || c.isDND),
      dndReason: c.dnd_reason || '',
      dndNotes: c.dnd_notes || '',
      dndMarkedBy: c.dnd_marked_by || '',
      dndTimestamp: c.dnd_timestamp || '',
      createdAt: c.created_at || '',
      avatar: (c.name ? c.name.slice(0, 2) : 'CU').toUpperCase(),
      automationHistory: Array.isArray(c.automationHistory) ? c.automationHistory : [],
      adminNotes: Array.isArray(c.adminNotes) ? c.adminNotes : [],
      lastMessage: c.lastMessage || c.last_message || '',
      lastMessageAt: c.lastMessageAt || c.last_message_at || '',
      unreadCount: parseInt(c.unreadCount || c.unread_count || 0)
    }));

    const custMap = new Map();
    const phoneMap = new Map();

    function addOrMergeCustomer(cust) {
      if (!cust) return;
      const cleanP = String(cust.phone || cust.whatsapp || '').replace(/\D/g, '');
      const p10 = cleanP.length >= 7 ? cleanP.slice(-10) : '';

      const existing = (p10 ? phoneMap.get(p10) : null) || custMap.get(String(cust.id));
      if (existing) {
        // Upgrade generic name to genuine contact name
        const exName = existing.name || '';
        const curName = cust.name || '';
        if ((!exName || exName.startsWith('Customer') || exName.startsWith('WhatsApp Customer')) && curName && !curName.startsWith('Customer') && !curName.startsWith('WhatsApp Customer')) {
          existing.name = curName;
          existing.avatar = (curName.slice(0, 2) || 'CU').toUpperCase();
        }
        if ((!existing.phone || existing.phone.length < 10) && cust.phone && cust.phone.length >= 10) {
          existing.phone = cust.phone;
          existing.whatsapp = cust.phone;
        }
        if ((!existing.assignedTo || existing.assignedTo === 'UNASSIGNED') && cust.assignedTo && cust.assignedTo !== 'UNASSIGNED') {
          existing.assignedTo = cust.assignedTo;
          existing.assigned_to = cust.assignedTo;
        }
        if (cust.lastMessageAt && (!existing.lastMessageAt || new Date(cust.lastMessageAt) > new Date(existing.lastMessageAt))) {
          existing.lastMessage = cust.lastMessage;
          existing.lastMessageAt = cust.lastMessageAt;
        }
        existing.unreadCount = Math.max(existing.unreadCount || 0, cust.unreadCount || 0);
        return;
      }

      custMap.set(String(cust.id), cust);
      if (p10) phoneMap.set(p10, cust);
    }

    dbCusts.forEach(addOrMergeCustomer);
    (CRM_STATE.customers || []).forEach(ec => {
      if (ec && ec.id) {
        const hasConv = CRM_STATE.conversations && Array.isArray(CRM_STATE.conversations[ec.id]) && CRM_STATE.conversations[ec.id].length > 0;
        if (hasConv || ec.lastMessage || (typeof ACTIVE_CUSTOMER_ID !== 'undefined' && String(ACTIVE_CUSTOMER_ID) === String(ec.id))) {
          addOrMergeCustomer(ec);
        }
      }
    });

    // Resilient Synthesis: Guarantee any customer with conversation threads is NEVER dropped on refresh
    const convSource = (data.conversations && typeof data.conversations === 'object') ? data.conversations : (CRM_STATE.conversations || {});
    for (const [cid, msgs] of Object.entries(convSource)) {
      if (cid && Array.isArray(msgs) && msgs.length > 0) {
        const lastM = msgs[msgs.length - 1];
        const cleanP = String(lastM.sender_phone || cid).replace(/\D/g, '');
        const clean10 = cleanP.slice(-10);
        if (clean10 && phoneMap.has(clean10)) continue;
        if (custMap.has(String(cid))) continue;

        const sName = lastM.sender_name || (clean10 ? ('Customer (' + clean10.slice(-4) + ')') : 'WhatsApp Customer');
        const pFormatted = clean10 ? ('+91 ' + clean10.slice(0, 5) + ' ' + clean10.slice(5)) : '';
        addOrMergeCustomer({
          id: cid,
          code: 'CUST-' + (clean10 || cid),
          name: sName,
          phone: pFormatted,
          whatsapp: pFormatted,
          assignedTo: 'UNASSIGNED',
          assigned_to: 'UNASSIGNED',
          accountId: lastM.account_id || 'account_1',
          account_id: lastM.account_id || 'account_1',
          customerType: 'Live WhatsApp Lead',
          address: '',
          altAddress: '',
          altPhone: '',
          email: '',
          tags: ['Live Lead'],
          totalOrders: 0,
          totalSpend: 0,
          isDND: false,
          createdAt: lastM.time || new Date().toISOString(),
          avatar: (sName ? sName.slice(0, 2) : 'CU').toUpperCase(),
          lastMessage: lastM.text || lastM.message_text || '',
          lastMessageAt: lastM.time || '',
          unreadCount: 1
        });
      }
    }
    CRM_STATE.customers = Array.from(custMap.values());
  }

  // 4. Orders (Authoritative MySQL sync)
  if (Array.isArray(data.orders)) {
    CRM_STATE.orders = data.orders.map(o => ({
      id: o.id,
      queryId: o.queryId || o.query_id || '',
      customerId: o.customerId || o.customer_id || '',
      customerName: o.customerName || o.customer_name || 'Customer',
      customerPhone: o.customerPhone || o.customer_phone || '',
      shippingAddress: o.shippingAddress || o.shipping_address || '',
      items: Array.isArray(o.items) ? o.items : (typeof o.items_json === 'string' ? (JSON.parse(o.items_json || '[]') || []) : []),
      grandTotal: parseFloat(o.grandTotal || o.grand_total || 0),
      shippingAmount: parseFloat(o.shippingAmount || o.shipping_amount || o.shippingCharge || o.shipping_charge || 0),
      shippingCharge: parseFloat(o.shippingAmount || o.shipping_amount || o.shippingCharge || o.shipping_charge || 0),
      codAdvance: parseFloat(o.codAdvance || o.cod_advance || o.advancePayment || o.advance_payment || 0),
      advancePayment: parseFloat(o.codAdvance || o.cod_advance || o.advancePayment || o.advance_payment || 0),
      codBalanceDue: parseFloat(o.codBalanceDue || o.cod_balance_due || o.balanceAmount || o.balance_amount || 0),
      balanceAmount: parseFloat(o.codBalanceDue || o.cod_balance_due || o.balanceAmount || o.balance_amount || 0),
      paymentMethod: o.paymentMethod || o.payment_method || 'COD',
      paymentStatus: o.paymentStatus || o.payment_status || 'PENDING',
      upiTransactionId: o.upiTransactionId || o.upi_transaction_id || '',
      paymentScreenshot: o.paymentScreenshot || o.payment_screenshot || '',
      orderStatus: o.orderStatus || o.order_status || 'PLACED',
      staffId: o.staffId || o.staff_id || 'staff_01',
      staffName: o.staffName || o.staff_name || 'Staff',
      createdBy: o.createdBy || o.created_by || 'Staff',
      trackingNumber: o.trackingNumber || o.tracking_number || '',
      courierName: o.courierName || o.courier_name || '',
      createdAt: o.createdAt || o.created_at || ''
    }));
  }

  // 5. Customer Enquiries & Leads (Authoritative MySQL sync - strictly replaces stale lists)
  if (Array.isArray(data.queries)) {
    CRM_STATE.queries = data.queries.map(q => ({
      id: q.id,
      customerId: q.customerId || q.customer_id || '',
      customer_id: q.customerId || q.customer_id || '',
      assignedTo: q.assignedTo || q.assigned_to || 'UNASSIGNED',
      assigned_to: q.assignedTo || q.assigned_to || 'UNASSIGNED',
      accountId: q.account_id || q.accountId || q.account_slot || 'account_1',
      account_id: q.account_id || q.accountId || q.account_slot || 'account_1',
      status: q.status || 'NEW',
      priority: q.priority || 'NORMAL',
      queryText: q.queryText || q.query_text || '',
      statusNotes: q.statusNotes !== undefined ? q.statusNotes : (q.status_notes || ''),
      isPaymentPending: Boolean(q.isPaymentPending || q.is_payment_pending),
      paymentAmount: parseFloat(q.paymentAmount || q.payment_amount || 0),
      shippingAmount: parseFloat(q.shippingAmount || q.shipping_amount || 0),
      paymentMode: q.paymentMode || q.payment_mode || 'UPI',
      advancePayment: parseFloat(q.advancePayment || q.advance_payment || 0),
      paymentDueDate: q.paymentDueDate || q.payment_due_date || '',
      paymentNotes: q.paymentNotes || q.payment_notes || '',
      quotedItems: q.quotedItems || q.quoted_items || '',
      callbackDate: q.callbackDate || q.callback_date || '',
      callbackTime: q.callbackTime || q.callback_time || '11:00 AM',
      statusHistory: Array.isArray(q.statusHistory) ? q.statusHistory : (typeof q.status_history === 'string' ? (JSON.parse(q.status_history || '[]') || []) : []),
      createdAt: q.createdAt || q.created_at || ''
    }));
  }

  // Ensure all active customers have a corresponding query representation in CRM_STATE.queries
  if (!Array.isArray(CRM_STATE.queries)) CRM_STATE.queries = [];
  const existingQCustIds = new Set(CRM_STATE.queries.map(q => String(q.customerId || q.customer_id)));
  const existingQPhones10 = new Set(
    CRM_STATE.queries
      .map(q => String(q.customerPhone || q.customer_phone || '').replace(/\D/g, '').slice(-10))
      .filter(p => p.length >= 7)
  );
  (CRM_STATE.customers || []).forEach(c => {
    if (!c) return;
    const clean10 = (c.phone || c.whatsapp || '').replace(/\D/g, '').slice(-10);
    if (!existingQCustIds.has(String(c.id)) && (!clean10 || !existingQPhones10.has(clean10))) {
      CRM_STATE.queries.push({
        id: clean10 ? ('Q-' + clean10) : ('Q-' + c.id),
        customerId: c.id,
        customer_id: c.id,
        customerPhone: c.phone || c.whatsapp || '',
        customer_phone: c.phone || c.whatsapp || '',
        customerName: c.name || 'Customer',
        customer_name: c.name || 'Customer',
        assignedTo: c.assignedTo || c.assigned_to || 'UNASSIGNED',
        assigned_to: c.assignedTo || c.assigned_to || 'UNASSIGNED',
        accountId: c.accountId || c.account_id || 'account_1',
        account_id: c.accountId || c.account_id || 'account_1',
        status: (c.assignedTo && c.assignedTo !== 'UNASSIGNED') ? 'ASSIGNED' : 'NEW',
        priority: 'NORMAL',
        queryText: c.lastMessage || 'Customer WhatsApp Enquiry',
        lastMessage: c.lastMessage || 'Customer WhatsApp Enquiry',
        createdAt: c.createdAt || c.lastMessageAt || ''
      });
      existingQCustIds.add(String(c.id));
      if (clean10) existingQPhones10.add(clean10);
    }
  });

  // Bidirectional Customer Synthesis: Ensure all queries have a corresponding customer in CRM_STATE.customers
  if (!Array.isArray(CRM_STATE.customers)) CRM_STATE.customers = [];
  const existingCustIds = new Set(CRM_STATE.customers.map(c => String(c.id)));
  const existingCustPhones10 = new Set(
    CRM_STATE.customers
      .map(c => (c.phone || c.whatsapp || '').replace(/\D/g, '').slice(-10))
      .filter(p => p.length >= 7)
  );

  (CRM_STATE.queries || []).forEach(q => {
    if (!q) return;
    const qCid = String(q.customerId || q.customer_id || '');
    const qP = String(q.customerPhone || q.customer_phone || qCid).replace(/\D/g, '');
    const qP10 = qP.length >= 7 ? qP.slice(-10) : '';

    const hasCust = (qCid && existingCustIds.has(qCid)) || (qP10 && existingCustPhones10.has(qP10));
    if (!hasCust) {
      const finalCid = qCid || (qP10 ? ('cust_' + qP10) : ('cust_' + (q.id || Date.now())));
      const cName = q.customerName || q.customer_name || 'Customer';
      const cPhone = q.customerPhone || q.customer_phone || (qP10 ? ('+91 ' + qP10) : '');
      const newCust = {
        id: finalCid,
        code: 'CUST-' + (qP10 || finalCid),
        name: cName,
        phone: cPhone,
        whatsapp: cPhone,
        assignedTo: q.assignedTo || q.assigned_to || 'UNASSIGNED',
        assigned_to: q.assignedTo || q.assigned_to || 'UNASSIGNED',
        accountId: q.accountId || q.account_id || 'account_1',
        account_id: q.accountId || q.account_id || 'account_1',
        customerType: 'Live WhatsApp Lead',
        address: '',
        altAddress: '',
        altPhone: '',
        email: '',
        tags: ['Live Lead'],
        totalOrders: 0,
        totalSpend: 0,
        isDND: q.status === 'DND',
        createdAt: q.createdAt || q.created_at || '',
        avatar: (cName ? cName.slice(0, 2) : 'CU').toUpperCase(),
        lastMessage: q.lastMessage || q.queryText || 'Customer Enquiry',
        lastMessageAt: q.createdAt || q.created_at || '',
        unreadCount: q.unreadCount || 0
      };
      CRM_STATE.customers.push(newCust);
      existingCustIds.add(String(finalCid));
      if (qP10) existingCustPhones10.add(qP10);
      if (!q.customerId) q.customerId = finalCid;
      if (!q.customer_id) q.customer_id = finalCid;
    }
  });

  // Reconcile assignedTo bidirectionally between queries and customers in memory
  (CRM_STATE.customers || []).forEach(c => {
    const cP10 = (c.phone || c.whatsapp || '').replace(/\D/g, '').slice(-10);
    const q = (CRM_STATE.queries || []).find(qry => qry.customerId === c.id || (cP10 && String(qry.customerPhone || qry.customer_phone || '').replace(/\D/g, '').slice(-10) === cP10));
    if (q) {
      if (q.assignedTo && q.assignedTo !== 'UNASSIGNED' && (!c.assignedTo || c.assignedTo === 'UNASSIGNED')) {
        c.assignedTo = q.assignedTo;
        c.assigned_to = q.assignedTo;
      } else if (c.assignedTo && c.assignedTo !== 'UNASSIGNED' && (!q.assignedTo || q.assignedTo === 'UNASSIGNED')) {
        q.assignedTo = c.assignedTo;
        q.assigned_to = c.assignedTo;
      }
    }
  });

  // 6. Follow-ups (Authoritative MySQL sync)
  if (Array.isArray(data.followups)) {
    const seenKeys = new Set();
    const cleanList = [];
    data.followups.forEach(fu => {
      if (!fu || !fu.id) return;
      const key = fu.id;
      const custKey = (fu.customerId || '') + '_' + ((fu.isPaymentPending === true || fu.isPaymentPending === 1 || fu.isPaymentPending === '1' || fu.is_payment_pending == 1) ? 'PAY' : 'FU') + '_' + (fu.status || '');
      if (!seenKeys.has(key) && (!fu.customerId || !seenKeys.has(custKey))) {
        seenKeys.add(key);
        if (fu.customerId) seenKeys.add(custKey);
        cleanList.push({
          id: fu.id,
          queryId: fu.queryId || fu.query_id || '',
          customerId: fu.customerId || fu.customer_id || '',
          customerName: fu.customerName || fu.customer_name || 'Customer',
          assignedTo: fu.assignedTo || fu.assigned_to || 'staff_01',
          date: fu.date || fu.date_str || '',
          time: fu.time || fu.time_str || '11:00 AM',
          reason: fu.reason || '',
          status: fu.status || 'PENDING',
          outcome: fu.outcome || 'PENDING',
          priority: fu.priority || 'NORMAL',
          channel: fu.channel || fu.contact_channel || 'WHATSAPP',
          outcomeNotes: fu.outcomeNotes || fu.outcome_notes || '',
          completedAt: fu.completedAt || fu.completed_at || null,
          rescheduledFromId: fu.rescheduledFromId || fu.rescheduled_from_id || null,
          createdAt: fu.createdAt || fu.created_at || '',
          isPaymentPending: (fu.isPaymentPending === true || fu.isPaymentPending === 1 || fu.isPaymentPending === '1' || fu.is_payment_pending == 1),
          paymentAmount: parseFloat(fu.paymentAmount || fu.payment_amount || 0),
          paymentMode: fu.paymentMode || fu.payment_mode || 'UPI',
          paymentDueDate: fu.paymentDueDate || fu.payment_due_date || '',
          paymentNotes: fu.paymentNotes || fu.payment_notes || '',
          quotedItems: fu.quotedItems || fu.quoted_items || ''
        });
      }
    });
    CRM_STATE.followups = cleanList;
  }

  // 7. Staff
  if (Array.isArray(data.staffList)) {
    CRM_STATE.staffList = data.staffList.map(s => ({
      id: s.id,
      name: s.name,
      role: s.role,
      avatar: s.avatar || (s.name ? s.name.split(' ').map(w => w[0]).join('').slice(0, 2).toUpperCase() : 'ST'),
      activeQueries: parseInt(s.active_queries || s.activeQueries || 0),
      converted: parseInt(s.converted || 0),
      dailyQuota: parseInt(s.daily_quota || s.dailyQuota || 70),
      todayHandled: parseInt(s.today_handled || s.todayHandled || 0),
      email: s.email || '',
      phone: s.phone || '',
      specialization: s.specialization || s.role || 'Sales Specialist',
      status: s.status || 'ACTIVE'
    }));
  }

  // 8. Conversations & Message History (Safe merge - NEVER overwrite with array or wipe in-memory threads!)
  if (!CRM_STATE.conversations || typeof CRM_STATE.conversations !== 'object' || Array.isArray(CRM_STATE.conversations)) {
    CRM_STATE.conversations = {};
  }
  if (data.conversations && typeof data.conversations === 'object' && !Array.isArray(data.conversations)) {
    Object.keys(data.conversations).forEach(cid => {
      const incomingMsgs = data.conversations[cid];
      if (Array.isArray(incomingMsgs) && incomingMsgs.length > 0) {
        if (!Array.isArray(CRM_STATE.conversations[cid])) {
          CRM_STATE.conversations[cid] = incomingMsgs;
        } else {
          const existingList = CRM_STATE.conversations[cid];
          const msgMap = new Map();
          existingList.forEach(m => {
            const mid = String(m.message_uid || m.id || '');
            if (mid) msgMap.set(mid, m);
          });
          incomingMsgs.forEach(im => {
            const mid = String(im.message_uid || im.id || '');
            if (mid && msgMap.has(mid)) {
              const target = msgMap.get(mid);
              if (im.media_url && (!target.media_url || target.media_url === '' || target.media_url.startsWith('data:'))) {
                target.media_url = im.media_url;
              }
              if (im.mediaUrl && (!target.mediaUrl || target.mediaUrl === '' || target.mediaUrl.startsWith('data:'))) {
                target.mediaUrl = im.mediaUrl;
              }
              if (im.audio_duration) target.audio_duration = im.audio_duration;
              if (im.duration) target.duration = im.duration;
              if (im.status) target.status = im.status;
            } else if (mid) {
              msgMap.set(mid, im);
            }
          });
          CRM_STATE.conversations[cid] = Array.from(msgMap.values());
        }
      }
    });
  }

  // 8.1 Consolidate Privacy LID conversations, queries & customer profiles
  const activeLidMap = (data.lidMappings && typeof data.lidMappings === 'object') ? data.lidMappings : (CRM_STATE.lidMappings || window.LID_MAPPINGS || {});
  if (data.lidMappings && typeof data.lidMappings === 'object') {
    CRM_STATE.lidMappings = data.lidMappings;
    window.LID_MAPPINGS = Object.assign(window.LID_MAPPINGS || {}, data.lidMappings);
  }

  for (const [lidDig, phoneDig] of Object.entries(activeLidMap)) {
    const cleanLid = String(lidDig).replace(/[^0-9]/g, '');
    const cleanPn = String(phoneDig).replace(/[^0-9]/g, '');
    if (cleanLid.length >= 14 && cleanPn.length >= 10) {
      const pn10 = cleanPn.slice(-10);
      const realCust = (CRM_STATE.customers || []).find(c => {
        const cp = (c.phone || c.whatsapp || '').replace(/[^0-9]/g, '');
        return cp.endsWith(pn10) || (c.id && c.id.endsWith(pn10));
      });
      if (realCust) {
        const realCustId = realCust.id;
        const lid10 = cleanLid.slice(-10);

        // Find and remove placeholder customer
        const phIdx = (CRM_STATE.customers || []).findIndex(c => {
          if (c.id === realCustId) return false;
          const cp = (c.phone || c.whatsapp || '').replace(/[^0-9]/g, '');
          return c.id === ('cust_' + cleanLid) || c.id === ('cust_' + lid10) || cp.includes(cleanLid) || (c.name && c.name.includes(cleanLid.slice(-4)));
        });

        if (phIdx !== -1) {
          const phCust = CRM_STATE.customers[phIdx];
          const phId = phCust.id;

          // Merge conversations
          if (CRM_STATE.conversations) {
            const phMsgs = Array.isArray(CRM_STATE.conversations[phId]) ? CRM_STATE.conversations[phId] : [];
            if (phMsgs.length > 0) {
              if (!Array.isArray(CRM_STATE.conversations[realCustId])) CRM_STATE.conversations[realCustId] = [];
              const existingUids = new Set(CRM_STATE.conversations[realCustId].map(m => m.id || m.message_uid));
              phMsgs.forEach(m => {
                const uid = m.id || m.message_uid;
                if (!existingUids.has(uid)) {
                  m.customer_id = realCustId;
                  CRM_STATE.conversations[realCustId].push(m);
                  existingUids.add(uid);
                }
              });
              CRM_STATE.conversations[realCustId].sort((a, b) => (a.timestamp_epoch || 0) - (b.timestamp_epoch || 0));
            }
            delete CRM_STATE.conversations[phId];
          }

          // Remove placeholder query
          if (Array.isArray(CRM_STATE.queries)) {
            CRM_STATE.queries = CRM_STATE.queries.filter(q => q.customerId !== phId && q.customer_id !== phId);
          }

          // Remove placeholder customer
          CRM_STATE.customers.splice(phIdx, 1);

          // If user currently had placeholder selected, point to real customer
          if (typeof ACTIVE_CUSTOMER_ID !== 'undefined' && ACTIVE_CUSTOMER_ID === phId) {
            ACTIVE_CUSTOMER_ID = realCustId;
            try { localStorage.setItem('GRM_ACTIVE_CUSTOMER_ID', realCustId); } catch(e) {}
            if (typeof selectCustomerChat === 'function') {
              selectCustomerChat(realCustId);
            }
          }
        }
      }
    }
  }

  // 8.2 Purge internal company business lines from CRM_STATE.customers and CRM_STATE.queries
  // Real customer phone numbers (Abi prasath, Pavi Anand, etc.) and staff profiles are strictly preserved!
  const internalBusinessPhones = [];
  const waAccountsList = Array.isArray(CRM_STATE.whatsappLines) ? CRM_STATE.whatsappLines : [];
  waAccountsList.forEach(acc => {
    if (acc && acc.status === 'CONNECTED' && acc.connected_number && acc.connected_number !== 'Awaiting Link') {
      const digits = acc.connected_number.replace(/[^0-9]/g, '');
      if (digits.length >= 10 && (typeof isStaffMobile !== 'function' || !isStaffMobile(digits))) {
        internalBusinessPhones.push(digits.slice(-10));
      }
    }
  });
  if (CRM_STATE?.whatsappAccount?.phoneNumber && CRM_STATE.whatsappAccount.status === 'CONNECTED' && (typeof isStaffMobile !== 'function' || !isStaffMobile(CRM_STATE.whatsappAccount.phoneNumber))) {
    const mainDigits = CRM_STATE.whatsappAccount.phoneNumber.replace(/[^0-9]/g, '');
    if (mainDigits.length >= 10) internalBusinessPhones.push(mainDigits.slice(-10));
  }
  if (Array.isArray(CRM_STATE.customers)) {
    CRM_STATE.customers = CRM_STATE.customers.filter(c => {
      if (!c) return false;
      const cp = (c.phone || c.whatsapp || '').replace(/[^0-9]/g, '');
      const isBiz = internalBusinessPhones.some(bp => cp.endsWith(bp)) ||
                    c.name === 'GRM Garments' ||
                    c.name === 'WhatsApp Business #2' ||
                    c.name === 'Bot (Auto-Reply)' ||
                    (c.id && internalBusinessPhones.some(bp => c.id.includes(bp)));
      return !isBiz;
    });
  }
  if (Array.isArray(CRM_STATE.queries)) {
    CRM_STATE.queries = CRM_STATE.queries.filter(q => {
      if (!q) return false;
      const qp = (q.customerPhone || q.customer_phone || '').replace(/[^0-9]/g, '');
      const qcid = String(q.customerId || q.customer_id || '');
      const isBiz = internalBusinessPhones.some(bp => qp.endsWith(bp) || qcid.includes(bp)) ||
                    (q.customerName || q.customer_name) === 'WhatsApp Business #2' ||
                    (q.customerName || q.customer_name) === 'GRM Garments' ||
                    (q.customerName || q.customer_name) === 'Bot (Auto-Reply)';
      return !isBiz;
    });
  }

  // Ensure active customer is valid and not pointing to internal business line
  if (typeof ACTIVE_CUSTOMER_ID !== 'undefined') {
    const isCurrentActiveBiz = internalBusinessPhones.some(bp => String(ACTIVE_CUSTOMER_ID).includes(bp));
    if (isCurrentActiveBiz || !ACTIVE_CUSTOMER_ID || (CRM_STATE.customers && !CRM_STATE.customers.some(c => c && c.id === ACTIVE_CUSTOMER_ID))) {
      if (CRM_STATE.customers && CRM_STATE.customers.length > 0) {
        ACTIVE_CUSTOMER_ID = CRM_STATE.customers[0].id;
        try { localStorage.setItem('GRM_ACTIVE_CUSTOMER_ID', ACTIVE_CUSTOMER_ID); } catch(e) {}
        if (typeof selectCustomerChat === 'function') {
          setTimeout(() => selectCustomerChat(ACTIVE_CUSTOMER_ID), 50);
        }
      }
    } else if (ACTIVE_CUSTOMER_ID && typeof selectCustomerChat === 'function') {
      setTimeout(() => selectCustomerChat(ACTIVE_CUSTOMER_ID), 50);
    }
  }

  // Persist cleaned conversations to sessionStorage
  if (typeof sessionStorage !== 'undefined' && CRM_STATE.conversations) {
    try {
      sessionStorage.setItem('GRM_INBOX_CONVERSATIONS', JSON.stringify(CRM_STATE.conversations));
    } catch (e) {}
  }

  // 9. DND Records
  if (Array.isArray(data.dndRecords)) {
    CRM_STATE.dndRecords = data.dndRecords;
  }

  // 10. Auto-reply Rules (Direct authoritative assignment)
  if (Array.isArray(data.autoReplyRules)) {
    CRM_STATE.autoReplyRules = data.autoReplyRules;
  }

  // 11. Broadcast Templates
  if (Array.isArray(data.broadcastTemplates)) {
    CRM_STATE.broadcastTemplates = data.broadcastTemplates;
    data.broadcastTemplates.forEach(bt => {
      let varObj = {};
      if (bt.variables_json) {
        try { varObj = typeof bt.variables_json === 'string' ? JSON.parse(bt.variables_json) : bt.variables_json; } catch (e) { }
      }
      if (typeof BROADCAST_PRESETS_DATA !== 'undefined') {
        BROADCAST_PRESETS_DATA[bt.id] = {
          label: bt.name,
          text: bt.body_text,
          category: bt.category,
          image_url: bt.image_url || null,
          variables: varObj
        };
      }
    });
  }

  // 12. Audit Logs
  if (Array.isArray(data.auditLogs)) {
    CRM_STATE.auditLogs = data.auditLogs;
  }

  // 13. Role Permissions
  if (data.rolePermissions && typeof data.rolePermissions === 'object') {
    if (typeof initRolePermissionsState === 'function') initRolePermissionsState();
    Object.keys(data.rolePermissions).forEach(r => {
      if (r && r.trim()) {
        CRM_STATE.rolePermissions[r] = data.rolePermissions[r];
      }
    });
    if (typeof updateStaffRoleSelectDropdowns === 'function') updateStaffRoleSelectDropdowns();
    if (typeof enforceGranularActionPermissions === 'function') enforceGranularActionPermissions();
  }

  // 14. Authoritative WhatsApp Account & Multi-Accounts State Sync from Database
  if (Array.isArray(data.whatsappAccounts) && data.whatsappAccounts.length > 0) {
    const isSocketAlive = Boolean(typeof SOCKET_IO !== 'undefined' && SOCKET_IO && SOCKET_IO.connected);
    const liveFromDb = data.whatsappAccounts.map(a => ({
      id: a.account_slot || a.id,
      name: a.display_name || a.account_name || a.brand_name || 'WhatsApp Line',
      label: a.display_name || a.account_name || a.brand_name || 'WhatsApp Line',
      phone: a.phone_number || a.phone || '',
      status: (a.status || 'DISCONNECTED').toUpperCase(),
      qr_image: a.qr_code || null,
      connected_number: a.phone_number || a.phone || (a.status === 'CONNECTED' ? 'Connected' : 'Awaiting Link')
    }));
    MULTI_ACCOUNTS_STATE = liveFromDb;
    if (!Array.isArray(CRM_STATE.whatsappLines)) {
      CRM_STATE.whatsappLines = [];
    }
    liveFromDb.forEach(dbAcc => {
      let line = CRM_STATE.whatsappLines.find(l => l.id === dbAcc.id);
      if (line) {
        // Guard: If the line is already CONNECTED with an active phone, never demote it to SCAN_QR or DISCONNECTED
        const isCurrentlyLive = line.status === 'CONNECTED' && line.connected_number && line.connected_number !== 'Awaiting Link';
        const isIncomingDemotion = dbAcc.status === 'SCAN_QR' || dbAcc.status === 'DISCONNECTED' || dbAcc.status === 'CONNECTING';
        if (isCurrentlyLive && isIncomingDemotion) {
          return;
        }
        line.status = dbAcc.status;
        line.connected_number = dbAcc.phone || line.connected_number;
        line.qr_image = dbAcc.qr_image;
        line.label = dbAcc.label || line.label;
      } else {
        if (!Array.isArray(CRM_STATE.deletedSlots) || !CRM_STATE.deletedSlots.includes(dbAcc.id)) {
          CRM_STATE.whatsappLines.push({
            id: dbAcc.id,
            label: dbAcc.label || dbAcc.name,
            status: dbAcc.status,
            connected_number: dbAcc.phone || 'Awaiting Link',
            qr_image: dbAcc.qr_image,
            brand_name: dbAcc.label || dbAcc.name
          });
        }
      }
    });

    if (typeof sessionStorage !== 'undefined' && Array.isArray(CRM_STATE.whatsappLines)) {
      try { sessionStorage.setItem('GRM_WHATSAPP_LINES', JSON.stringify(CRM_STATE.whatsappLines)); } catch (e) {}
    }
    // Instant zero-lag UI render for multi-account hub and switcher
    if (typeof renderMultiAccountsHub === 'function') renderMultiAccountsHub();
    if (typeof renderPhoneSwitcherDropdown === 'function') renderPhoneSwitcherDropdown();
    if (typeof renderQuickLineSwitcher === 'function') renderQuickLineSwitcher();
  }

  if (data.whatsappAccount) {
    if (!CRM_STATE.whatsappAccount) CRM_STATE.whatsappAccount = {};
    const incomingStatus = (data.whatsappAccount.status || 'DISCONNECTED').toUpperCase();
    const incomingPhone = data.whatsappAccount.phone_number || '';
    const currentStatus = CRM_STATE.whatsappAccount.status;
    const currentPhone = CRM_STATE.whatsappAccount.phoneNumber;
    const isCurrentlyConnected = currentStatus === 'CONNECTED' && currentPhone && currentPhone !== 'Awaiting Link';

    if (isCurrentlyConnected && (incomingStatus === 'DISCONNECTED' || incomingStatus === 'SCAN_QR' || !incomingPhone || incomingPhone === 'Awaiting Link')) {
      // Guard: Do not allow background sync to demote an already connected account to DISCONNECTED
    } else {
      CRM_STATE.whatsappAccount.status = incomingStatus;
      if (incomingPhone && incomingPhone !== 'Awaiting Link') {
        CRM_STATE.whatsappAccount.phoneNumber = incomingPhone;
      }
    }
    CRM_STATE.whatsappAccount.businessName = data.whatsappAccount.business_name || CRM_STATE.whatsappAccount.businessName;
    if (typeof updateConfiguredPhoneDisplays === 'function') updateConfiguredPhoneDisplays();
  }

  // Auto-select first active customer if none selected
  if (!ACTIVE_CUSTOMER_ID && Array.isArray(CRM_STATE.customers) && CRM_STATE.customers.length > 0) {
    const activeOne = CRM_STATE.customers.find(c => {
      const conv = (CRM_STATE.conversations && typeof CRM_STATE.conversations === 'object') ? CRM_STATE.conversations[c.id] : null;
      return (conv && conv.length > 0) || c.lastMessage || c.last_message;
    });
    if (activeOne) {
      ACTIVE_CUSTOMER_ID = activeOne.id;
    }
  }

  // Update badges & UI for the active view
  if (typeof updateBadgeCounters === 'function') updateBadgeCounters();
  if (typeof updateConfiguredPhoneDisplays === 'function') updateConfiguredPhoneDisplays();

  if (ACTIVE_VIEW === 'inbox') {
    if (typeof renderInbox === 'function') renderInbox();
    if (typeof renderCustomer360Panel === 'function') renderCustomer360Panel();
  } else if (ACTIVE_VIEW === 'dashboard') {
    if (typeof updateDashboardKPIs === 'function') updateDashboardKPIs();
    if (typeof renderDashboard === 'function') renderDashboard();
  } else if (ACTIVE_VIEW === 'catalog') {
    if (typeof populateCatalogCategoryFilters === 'function') populateCatalogCategoryFilters();
    if (typeof populateProductFormCategories === 'function') populateProductFormCategories();
    if (typeof filterCatalogGrid === 'function') filterCatalogGrid();
  } else if (ACTIVE_VIEW === 'orders') {
    if (typeof renderOrdersModule === 'function') renderOrdersModule();
  } else if (ACTIVE_VIEW === 'followups') {
    if (typeof updateFollowupsKPICounters === 'function') updateFollowupsKPICounters();
    if (typeof filterFollowupsCards === 'function') filterFollowupsCards();
    if (typeof updatePaymentPendingKPICounters === 'function') updatePaymentPendingKPICounters();
    if (typeof filterPaymentPendingCards === 'function') filterPaymentPendingCards();
  } else if (ACTIVE_VIEW === 'customers') {
    if (typeof renderCustomersGrid === 'function') renderCustomersGrid();
    if (typeof renderCustomersTable === 'function') renderCustomersTable();
  } else if (ACTIVE_VIEW === 'enquiries') {
    if (typeof renderEnquiriesTable === 'function') renderEnquiriesTable();
  } else if (ACTIVE_VIEW === 'staff') {
    if (typeof renderStaffCards === 'function') renderStaffCards();
    if (typeof renderStaffKPIOverview === 'function') renderStaffKPIOverview();
    if (typeof renderStaffTable === 'function') renderStaffTable();
  }

  // Sync order badges in header without full module rebuild
  const badgeOrders = document.getElementById('badge-orders-count');
  const badgeTotalHeader = document.getElementById('badge-orders-total-count');
  const badgeHistoryTab = document.getElementById('orders-tab-history-badge');
  const badgeSidebarHistory = document.getElementById('nav-sub-orders-history-badge');
  const totalCount = (CRM_STATE?.orders || []).length;
  if (badgeOrders) badgeOrders.innerText = totalCount;
  if (badgeTotalHeader) badgeTotalHeader.innerText = `${totalCount} Order${totalCount === 1 ? '' : 's'}`;
  if (badgeHistoryTab) badgeHistoryTab.innerText = totalCount;
  if (badgeSidebarHistory) badgeSidebarHistory.innerText = totalCount;
}
window.applyAuthoritativeDatabaseState = applyAuthoritativeDatabaseState;

let _lastSyncTimestamp = 0;
let _isSyncing = false;
function syncLiveCRMData(force = false) {
  const now = Date.now();
  if (!force && (now - _lastSyncTimestamp < 2500)) return; // Throttle to max once per 2.5s
  if (_isSyncing) return;
  _isSyncing = true;
  _lastSyncTimestamp = now;

  const activeScope = (typeof ACTIVE_VIEW !== 'undefined' && ACTIVE_VIEW) ? ACTIVE_VIEW : 'dashboard';
  fetch(`api.php?action=get_all&scope=${activeScope}&_t=${now}`, {
    cache: 'no-store',
    headers: { 'Cache-Control': 'no-cache', 'Pragma': 'no-cache' }
  })
    .then(r => r.json())
    .then(res => {
      const data = res.data || res;
      if (data) {
        applyAuthoritativeDatabaseState(data);
      }
    })
    .catch(err => {
      console.warn('[syncLiveCRMData] Network check:', err);
    })
    .finally(() => {
      _isSyncing = false;
    });
}
window.syncLiveCRMData = syncLiveCRMData;

// Universal Visibility & Focus Sync: Alt+Tab safe, delta-only in inbox view
if (typeof document !== 'undefined') {
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') {
      if (typeof ACTIVE_VIEW !== 'undefined' && ACTIVE_VIEW === 'inbox') {
        // In inbox: quietly poll new messages without re-rendering or wiping chat
        if (typeof syncInboundMessagesNow === 'function') syncInboundMessagesNow(false);
        if (typeof ACTIVE_CUSTOMER_ID !== 'undefined' && ACTIVE_CUSTOMER_ID && typeof syncCustomerMessagesFromDB === 'function') {
          syncCustomerMessagesFromDB(ACTIVE_CUSTOMER_ID);
        }
      } else {
        syncLiveCRMData(false);
      }
    }
  });
}
if (typeof window !== 'undefined') {
  window.addEventListener('focus', () => {
    if (typeof ACTIVE_VIEW !== 'undefined' && ACTIVE_VIEW === 'inbox') {
      if (typeof syncInboundMessagesNow === 'function') syncInboundMessagesNow(false);
      if (typeof ACTIVE_CUSTOMER_ID !== 'undefined' && ACTIVE_CUSTOMER_ID && typeof syncCustomerMessagesFromDB === 'function') {
        syncCustomerMessagesFromDB(ACTIVE_CUSTOMER_ID);
      }
    } else {
      syncLiveCRMData(false);
    }
  });
}

// Initialise CRM State from clean schema and sync from MySQL
function initCRMState() {
  CRM_STATE = JSON.parse(JSON.stringify(INITIAL_CRM_DATA));
  if (!Array.isArray(CRM_STATE.customers)) CRM_STATE.customers = [];
  if (!Array.isArray(CRM_STATE.queries)) CRM_STATE.queries = [];
  if (!Array.isArray(CRM_STATE.orders)) CRM_STATE.orders = [];
  if (!Array.isArray(CRM_STATE.followups)) CRM_STATE.followups = [];
  if (!Array.isArray(CRM_STATE.products)) CRM_STATE.products = [];
  if (!Array.isArray(CRM_STATE.staffList)) CRM_STATE.staffList = [];
  if (!Array.isArray(CRM_STATE.categories)) CRM_STATE.categories = [];
  if (!Array.isArray(CRM_STATE.subcategories)) CRM_STATE.subcategories = [];
  if (!Array.isArray(CRM_STATE.autoReplyRules)) CRM_STATE.autoReplyRules = [];
  if (!Array.isArray(CRM_STATE.broadcastTemplates)) CRM_STATE.broadcastTemplates = [];
  if (!CRM_STATE.conversations || typeof CRM_STATE.conversations !== 'object') CRM_STATE.conversations = {};
  if (typeof sessionStorage !== 'undefined') {
    try {
      const cachedConvs = sessionStorage.getItem('GRM_INBOX_CONVERSATIONS');
      if (cachedConvs) {
        const parsed = JSON.parse(cachedConvs);
        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
          CRM_STATE.conversations = parsed;
        }
      }
      const cachedLines = sessionStorage.getItem('GRM_WHATSAPP_LINES') || (typeof localStorage !== 'undefined' ? localStorage.getItem('GRM_WHATSAPP_LINES') : null);
      if (cachedLines) {
        const parsedLines = JSON.parse(cachedLines);
        if (Array.isArray(parsedLines) && parsedLines.length > 0) {
          const cleanLines = parsedLines.filter(a => !isPhantomWhatsAppAccount(a));
          CRM_STATE.whatsappLines = cleanLines;
          MULTI_ACCOUNTS_STATE = cleanLines;
        }
      }
    } catch (e) {}
  }

  // Restore permanently deleted slots from localStorage
  if (typeof localStorage !== 'undefined') {
    try {
      const storedDeleted = localStorage.getItem('GRM_DELETED_SLOTS');
      if (storedDeleted) {
        CRM_STATE.deletedSlots = JSON.parse(storedDeleted);
      }
    } catch (e) {}
  }
  if (!Array.isArray(CRM_STATE.deletedSlots)) {
    CRM_STATE.deletedSlots = [];
  }

  // Sanitize attributes: strictly purge any JSON role permissions matrix accidentally registered as custom garment attributes
  if (CRM_STATE.attributes && CRM_STATE.attributes.custom) {
    Object.keys(CRM_STATE.attributes.custom).forEach(key => {
      if (!key || key.startsWith('{') || key.startsWith('[') || key.includes('dashboard') || key.includes('bulk-assign') || key.includes('inbox') || key.includes('view') || key.length > 50) {
        delete CRM_STATE.attributes.custom[key];
      }
    });
  }
  if (typeof localStorage !== 'undefined') {
    try {
      const storedAttrs = localStorage.getItem('CRM_STATE');
      if (storedAttrs) {
        const parsedState = JSON.parse(storedAttrs);
        if (parsedState && parsedState.attributes && parsedState.attributes.custom) {
          let dirty = false;
          Object.keys(parsedState.attributes.custom).forEach(key => {
            if (!key || key.startsWith('{') || key.startsWith('[') || key.includes('dashboard') || key.includes('bulk-assign') || key.includes('inbox') || key.includes('view') || key.length > 50) {
              delete parsedState.attributes.custom[key];
              dirty = true;
            }
          });
          if (dirty) {
            localStorage.setItem('CRM_STATE', JSON.stringify(parsedState));
          }
        }
      }
    } catch (e) {}
  }

  if (typeof localStorage !== 'undefined') {
    try {
      const savedAcc = localStorage.getItem('GRM_ACTIVE_SEND_ACCOUNT_ID');
      if (savedAcc && !isPhantomWhatsAppAccount({ id: savedAcc })) {
        ACTIVE_SEND_ACCOUNT_ID = savedAcc;
      } else {
        ACTIVE_SEND_ACCOUNT_ID = 'all';
      }
    } catch (e) {
      ACTIVE_SEND_ACCOUNT_ID = 'all';
    }
  } else if (typeof ACTIVE_SEND_ACCOUNT_ID !== 'undefined' && isPhantomWhatsAppAccount({ id: ACTIVE_SEND_ACCOUNT_ID })) {
    ACTIVE_SEND_ACCOUNT_ID = 'all';
  }

  if (!CRM_STATE.whatsappAccount) {
    CRM_STATE.whatsappAccount = JSON.parse(JSON.stringify(INITIAL_CRM_DATA.whatsappAccount));
  }
  if (!CRM_STATE.dailyMessageTarget) {
    CRM_STATE.dailyMessageTarget = JSON.parse(JSON.stringify(INITIAL_CRM_DATA.dailyMessageTarget));
  }
  if (!CRM_STATE.autoReplySettings) {
    CRM_STATE.autoReplySettings = {
      enabled: true,
      cooldownMinutes: 0,
      keywordMatching: true,
      messageTemplate: getDefaultStockAutoReplyTemplate()
    };
  }

  // Load from backend config if available
  fetch('api.php?action=get_config&_t=' + Date.now(), { cache: 'no-store' })
    .then(r => r.json())
    .then(res => {
      if (res.status === 'success' && res.data) {
        if (res.data.phone_number) {
          CRM_STATE.whatsappAccount.phoneNumber = formatPhoneNumberPretty(res.data.phone_number);
          CRM_STATE.whatsappAccount.businessName = res.data.business_name || CRM_STATE.whatsappAccount.businessName;
          CRM_STATE.whatsappAccount.displayName = res.data.display_name || CRM_STATE.whatsappAccount.displayName;
          updateConfiguredPhoneDisplays();
        }
        if (res.data.bridge_url && !res.data.bridge_url.includes('trycloudflare.com')) {
          window.BRIDGE_URL = res.data.bridge_url;
          try { localStorage.setItem('GRM_BRIDGE_URL', res.data.bridge_url); } catch (e) { }
          if (CRM_STATE) {
            if (!CRM_STATE.settings) CRM_STATE.settings = {};
            CRM_STATE.settings.bridgeUrl = res.data.bridge_url;
          }
          if ((!SOCKET_IO || !SOCKET_IO.connected) && res.data.bridge_url !== 'http://localhost:3000') {
            initSocketIO();
            fetchQRBridgeStatus();
          }
        }
      }
    })
    .catch(() => {});

  // Load brand name & tagline from bridge config file with fast 1200ms timeout
  const brandAbort = (typeof AbortController !== 'undefined') ? new AbortController() : null;
  const brandTimer = brandAbort ? setTimeout(() => brandAbort.abort(), 1200) : null;
  fetch(`${getBridgeBaseUrl()}/api/brand/config`, brandAbort ? { signal: brandAbort.signal } : {})
    .then(r => r.json())
    .then(res => {
      if (brandTimer) clearTimeout(brandTimer);
      if (res.status === 'success') {
        if (!CRM_STATE.brandSettings) CRM_STATE.brandSettings = {};
        if (res.brand_name) CRM_STATE.brandSettings.brandName = res.brand_name;
        if (res.brand_tagline) CRM_STATE.brandSettings.brandTagline = res.brand_tagline;
        const brandInput = document.getElementById('cfg-brand-name');
        const taglineInput = document.getElementById('cfg-brand-tagline');
        if (brandInput) brandInput.value = res.brand_name || '';
        if (taglineInput) taglineInput.value = res.brand_tagline || '';
        if (typeof updateBrandPreview === 'function') updateBrandPreview();
      }
    })
    .catch(() => {
      if (brandTimer) clearTimeout(brandTimer);
    });

  // Pull authoritative database state immediately
  syncLiveCRMData(true);

  cleanupAndDeduplicateCRMState();
  if (typeof populateCatalogCategoryFilters === 'function') {
    populateCatalogCategoryFilters();
  }
  updateConfiguredPhoneDisplays();
  updateAutoReplyUI();
  initSocketIO();
  fetchQRBridgeStatus();
  startRealtimeMessageSync();
  startFollowupReminderTicker();
}

function purgeStaticMockData() {
  return;
}

let _saveCRMStateTimer = null;
function saveCRMState(immediate = false) {
  const doSave = () => {
    try {
      localStorage.removeItem('GRM_CRM_STATE_V2_5');
      localStorage.removeItem('GRM_CRM_STATE_V2');
      localStorage.removeItem('GRM_CRM_STATE');

      // Keep recent in-memory conversation threads in sessionStorage for zero-latency instant chat rendering
      if (typeof sessionStorage !== 'undefined' && CRM_STATE && CRM_STATE.conversations && typeof CRM_STATE.conversations === 'object') {
        try {
          const trimmedConvs = {};
          for (const [cid, msgs] of Object.entries(CRM_STATE.conversations)) {
            if (Array.isArray(msgs)) {
              trimmedConvs[cid] = msgs.slice(-500).map(m => {
                if (m && m.media_url && typeof m.media_url === 'string' && m.media_url.startsWith('data:')) {
                  return { ...m, media_url: '' };
                }
                return m;
              });
            }
          }
          sessionStorage.setItem('GRM_INBOX_CONVERSATIONS', JSON.stringify(trimmedConvs));
        } catch (e) {}
      }

      // Keep multi-account lines synchronized in storage for 0ms instant display upon refresh
      if (CRM_STATE && Array.isArray(CRM_STATE.whatsappLines) && CRM_STATE.whatsappLines.length > 0) {
        try {
          const linesJson = JSON.stringify(CRM_STATE.whatsappLines);
          sessionStorage.setItem('GRM_WHATSAPP_LINES', linesJson);
          localStorage.setItem('GRM_WHATSAPP_LINES', linesJson);
        } catch (e) {}
      }

      if (typeof window !== 'undefined' && typeof window.broadcastCRMMutation === 'function') {
        window.broadcastCRMMutation('MUTATION');
      }
    } catch (err) {
      console.warn('LocalStorage save notice:', err);
    }
  };

  updateBadgeCounters();
  updateConfiguredPhoneDisplays();

  if (immediate) {
    if (_saveCRMStateTimer) clearTimeout(_saveCRMStateTimer);
    doSave();
  } else {
    if (_saveCRMStateTimer) clearTimeout(_saveCRMStateTimer);
    _saveCRMStateTimer = setTimeout(doSave, 250);
  }
}
window.saveCRMState = saveCRMState;
window.saveStateToStorage = saveCRMState;

// 5 Connected WhatsApp Business Numbers Engine
function getAvailableWhatsAppAccounts() {
  // Instant 0ms memory fallback from storage before network returns
  if ((!Array.isArray(CRM_STATE?.whatsappLines) || CRM_STATE.whatsappLines.length === 0) && typeof localStorage !== 'undefined') {
    try {
      const stored = localStorage.getItem('GRM_WHATSAPP_LINES') || (typeof sessionStorage !== 'undefined' ? sessionStorage.getItem('GRM_WHATSAPP_LINES') : null);
      if (stored) {
        const parsed = JSON.parse(stored);
        if (Array.isArray(parsed) && parsed.length > 0) {
          const clean = parsed.filter(a => !isPhantomWhatsAppAccount(a));
          if (CRM_STATE) CRM_STATE.whatsappLines = clean;
          MULTI_ACCOUNTS_STATE = clean;
        }
      }
    } catch (e) {}
  }

  const defaultAccounts = [
    {
      id: 'account_1',
      label: 'Primary WhatsApp',
      status: 'DISCONNECTED',
      connected_number: 'Awaiting Link',
      brand_name: 'Primary Line'
    },
    {
      id: 'account_2',
      label: 'WhatsApp Business #2',
      status: 'DISCONNECTED',
      connected_number: 'Awaiting Link',
      brand_name: 'WhatsApp Business #2'
    }
  ];

  const existingMap = new Map();
  if (Array.isArray(CRM_STATE?.whatsappLines)) {
    CRM_STATE.whatsappLines.forEach(acc => {
      if (acc && acc.id) existingMap.set(acc.id, acc);
    });
  }

  let accountsList = defaultAccounts.map(def => {
    const existing = existingMap.get(def.id);
    if (!existing) {
      if (def.id === 'account_1' && CRM_STATE?.whatsappAccount?.phoneNumber && CRM_STATE.whatsappAccount.phoneNumber !== 'Awaiting Link' && CRM_STATE.whatsappAccount.status === 'CONNECTED') {
        return {
          ...def,
          status: 'CONNECTED',
          connected_number: CRM_STATE.whatsappAccount.phoneNumber,
          brand_name: CRM_STATE.whatsappAccount.businessName || def.brand_name
        };
      }
      return JSON.parse(JSON.stringify(def));
    }
    const curStatus = existing.status || def.status || 'DISCONNECTED';
    const finalPhone = curStatus === 'CONNECTED' 
      ? (existing.connected_number && existing.connected_number !== 'Awaiting Link' && existing.connected_number !== 'Scan QR Code' ? existing.connected_number : def.connected_number)
      : (curStatus === 'SCAN_QR' ? 'Scan QR Code' : 'Awaiting Link');

    return {
      ...def,
      ...existing,
      id: def.id,
      label: existing.label || def.label,
      brand_name: existing.brand_name || def.brand_name,
      connected_number: finalPhone,
      status: curStatus,
      qr_image: existing.qr_image || null
    };
  });

  // Append any additional custom account slots (added manually by user)
  if (Array.isArray(CRM_STATE?.whatsappLines)) {
    CRM_STATE.whatsappLines.forEach(acc => {
      if (acc && acc.id && acc.id !== 'account_1') {
        if (!accountsList.some(d => d.id === acc.id)) {
          accountsList.push(JSON.parse(JSON.stringify(acc)));
        }
      }
    });
  }

  // Filter out deleted slots
  if (Array.isArray(CRM_STATE?.deletedSlots)) {
    CRM_STATE.deletedSlots = CRM_STATE.deletedSlots.filter(id => id !== 'account_1');
    if (CRM_STATE.deletedSlots.length > 0) {
      accountsList = accountsList.filter(acc => !CRM_STATE.deletedSlots.includes(acc.id));
    }
  }

  // Merge with live MULTI_ACCOUNTS_STATE if available
  if (Array.isArray(MULTI_ACCOUNTS_STATE) && MULTI_ACCOUNTS_STATE.length > 0) {
    MULTI_ACCOUNTS_STATE.forEach(liveAcc => {
      if (!liveAcc || !liveAcc.id) return;
      const existing = accountsList.find(a => a.id === liveAcc.id);
      if (existing) {
        existing.status = (liveAcc.status || existing.status || 'DISCONNECTED').toUpperCase();
        if (existing.status === 'CONNECTED') {
          existing.connected_number = liveAcc.connected_number || liveAcc.phone || existing.connected_number;
          existing.qr_image = null;
        } else if (existing.status === 'SCAN_QR') {
          existing.connected_number = 'Scan QR Code';
          existing.qr_image = liveAcc.qr_image || liveAcc.qr || existing.qr_image || null;
        } else {
          existing.connected_number = 'Awaiting Link';
          existing.qr_image = null;
        }
        existing.connected_name = liveAcc.connected_name || liveAcc.name || existing.connected_name;
        existing.label = liveAcc.label || liveAcc.name || existing.label;
        if (liveAcc.qr_image || liveAcc.qr) existing.qr_image = liveAcc.qr_image || liveAcc.qr;
      } else {
        if (!Array.isArray(CRM_STATE?.deletedSlots) || !CRM_STATE.deletedSlots.includes(liveAcc.id)) {
          const st = (liveAcc.status || 'DISCONNECTED').toUpperCase();
          accountsList.push({
            id: liveAcc.id,
            label: liveAcc.label || liveAcc.name || `WhatsApp Line (${liveAcc.id})`,
            status: st,
            connected_number: (st === 'CONNECTED' ? (liveAcc.connected_number || liveAcc.phone || 'Connected') : (st === 'SCAN_QR' ? 'Scan QR Code' : 'Awaiting Link')),
            connected_name: liveAcc.connected_name || liveAcc.name || null,
            brand_name: liveAcc.label || liveAcc.name || liveAcc.id,
            qr_image: liveAcc.qr_image || liveAcc.qr || null
          });
        }
      }
    });
  }

  // Filter out any phantom accounts (Lines 3, 4, 5 and account_1795...)
  accountsList = accountsList.filter(acc => !isPhantomWhatsAppAccount(acc));

  return accountsList;
}

function handleHeaderAddNewWhatsAppLine() {
  closePhoneSwitcherDropdown();
  const currentUser = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER) ? CURRENT_USER : null;
  const isSuperAdmin = currentUser ? (currentUser.role === 'admin' || currentUser.id === 'admin' || currentUser.role === 'Super Admin' || (currentUser.title && currentUser.title.includes('Admin Manager'))) : false;
  if (!isSuperAdmin) {
    if (typeof showToast === 'function') {
      showToast('Admin Panel Protected', 'Staff accounts cannot link or modify WhatsApp lines. Please contact Super Admin.', 'lock', 'rose');
    }
    return;
  }
  if (typeof switchView === 'function') {
    switchView('settings');
  }
  setTimeout(() => {
    const hub = document.getElementById('multi-accounts-container');
    if (hub) hub.scrollIntoView({ behavior: 'smooth', block: 'start' });
    addNewWhatsAppAccountSlot();
  }, 250);
}
window.handleHeaderAddNewWhatsAppLine = handleHeaderAddNewWhatsAppLine;

function togglePhoneSwitcherDropdown(event, triggerBtn) {
  if (event) event.stopPropagation();
  if (typeof isCurrentUserStaff === 'function' && isCurrentUserStaff()) {
    return; // Strictly disable opening WhatsApp line switcher / QR dropdown for staff
  }
  const dropdown = document.getElementById('phone-switcher-dropdown');
  const btn = triggerBtn || document.getElementById('header-phone-badge') || document.getElementById('settings-phone-badge');
  const arrow = btn ? btn.querySelector('#phone-dropdown-arrow, .material-symbols-outlined:last-child') : document.getElementById('phone-dropdown-arrow');
  if (!dropdown) return;

  const isHidden = dropdown.classList.contains('hidden');
  if (isHidden) {
    renderPhoneSwitcherDropdown();
    dropdown.classList.remove('hidden');
    if (arrow) arrow.style.transform = 'rotate(180deg)';

    // Dynamic viewport positioning so dropdown is NEVER clipped by any header or overflow container
    if (btn) {
      const rect = btn.getBoundingClientRect();
      const dropWidth = Math.min(320, window.innerWidth - 24);
      dropdown.style.position = 'fixed';
      dropdown.style.top = (rect.bottom + 6) + 'px';
      dropdown.style.width = dropWidth + 'px';
      dropdown.style.maxWidth = 'calc(100vw - 24px)';
      dropdown.style.zIndex = '99999';

      let leftPos = rect.left;
      if (leftPos + dropWidth > window.innerWidth - 12) {
        leftPos = Math.max(12, window.innerWidth - dropWidth - 12);
      }
      dropdown.style.left = leftPos + 'px';
      dropdown.style.right = 'auto';
    }
  } else {
    closePhoneSwitcherDropdown();
  }
}

function closePhoneSwitcherDropdown() {
  const dropdown = document.getElementById('phone-switcher-dropdown');
  const arrow = document.getElementById('phone-dropdown-arrow');
  if (dropdown) dropdown.classList.add('hidden');
  if (arrow) arrow.style.transform = 'rotate(0deg)';
}

function renderPhoneSwitcherDropdown() {
  const listContainer = document.getElementById('phone-dropdown-accounts-list');
  const countBadge = document.getElementById('dropdown-connected-count');
  const addLineFooter = document.getElementById('phone-dropdown-add-line-footer');
  if (!listContainer) return;

  const currentUser = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER) ? CURRENT_USER : ((typeof CRM_AUTH_SESSION !== 'undefined') ? CRM_AUTH_SESSION : null);
  const isSuperAdmin = currentUser ? (currentUser.role === 'admin' || currentUser.id === 'admin' || currentUser.role === 'Super Admin' || (currentUser.title && currentUser.title.includes('Admin Manager'))) : false;

  // STRICT RULE: Staff login time Admin Panel cannot be touched!
  // Hide "+ Scan New WhatsApp Line / QR" footer button completely for staff
  if (addLineFooter) {
    if (isSuperAdmin) {
      addLineFooter.classList.remove('hidden');
      addLineFooter.style.display = '';
    } else {
      addLineFooter.classList.add('hidden');
      addLineFooter.style.display = 'none';
    }
  }

  let accounts = getAvailableWhatsAppAccounts();

  // STRICT RULE: "staff login time Switch WhatsApp Line showbased on admin login mobile no add there only"
  // For Staff Workstation: show ONLY the accounts with active/connected mobile numbers added by Admin!
  if (!isSuperAdmin) {
    accounts = accounts.filter(acc => {
      const phone = (acc.connected_number || acc.phone_number || acc.phone || '').trim();
      const isLive = acc.status === 'CONNECTED';
      const hasRealPhone = phone && phone !== 'Awaiting Link' && phone !== 'Scan QR Code';
      return isLive || hasRealPhone;
    });

    // Fallback to Admin's configured primary line if array is empty
    if (accounts.length === 0 && CRM_STATE?.whatsappAccount?.phoneNumber && CRM_STATE.whatsappAccount.phoneNumber !== 'Awaiting Link') {
      accounts = [{
        id: 'account_1',
        label: CRM_STATE.whatsappAccount.businessName || 'Primary WhatsApp',
        status: CRM_STATE.whatsappAccount.status || 'CONNECTED',
        connected_number: CRM_STATE.whatsappAccount.phoneNumber,
        brand_name: CRM_STATE.whatsappAccount.businessName || 'Primary Line'
      }];
    }

    // If staff has a specific assigned WhatsApp line configured by Admin, filter to it
    const staffId = currentUser?.staff_id || currentUser?.staffId || currentUser?.id || currentUser?.username;
    const staffObj = (CRM_STATE?.staffList || []).find(s => s.id === staffId || s.username === currentUser?.username);
    if (staffObj && staffObj.assignedLine && staffObj.assignedLine !== 'ALL') {
      const assignedFiltered = accounts.filter(a => a.id === staffObj.assignedLine || a.connected_number === staffObj.assignedLine);
      if (assignedFiltered.length > 0) {
        accounts = assignedFiltered;
      }
    }
  }

  const currentPhone = ((CRM_STATE?.whatsappAccount?.phoneNumber && !isStaffMobile(CRM_STATE.whatsappAccount.phoneNumber)) ? CRM_STATE.whatsappAccount.phoneNumber : '').replace(/\s+/g, '');
  const connectedCount = accounts.filter(a => {
    const ph = (a.connected_number || '').replace(/\D/g, '');
    return a.status === 'CONNECTED' || ph.length >= 10;
  }).length;

  if (countBadge) {
    countBadge.innerText = `${connectedCount} / ${accounts.length} Active Line${accounts.length > 1 ? 's' : ''}`;
    countBadge.className = connectedCount > 0 ? "text-[10px] bg-emerald-100 text-emerald-800 font-extrabold px-2 py-0.5 rounded-full" : "text-[10px] bg-amber-100 text-amber-800 font-extrabold px-2 py-0.5 rounded-full";
  }

  if (accounts.length === 0) {
    listContainer.innerHTML = `
      <div class="p-4 text-center text-slate-400">
        <span class="material-symbols-outlined text-[24px] text-slate-300 mb-1">phonelink_off</span>
        <p class="font-bold text-xs text-slate-700">No WhatsApp Lines Available</p>
        <p class="text-[11px] text-slate-400 mt-0.5">Please wait for Super Admin to connect WhatsApp in Admin Panel.</p>
      </div>
    `;
    return;
  }

  const availableAccountIds = accounts.map(a => a.id);
  const totalChats = (CRM_STATE?.customers || []).filter(c => {
    const q = (CRM_STATE?.queries || []).find(qry => qry.customerId === c.id);
    const accId = c.accountId || (q ? q.accountId : 'account_1');
    return availableAccountIds.includes(accId);
  }).length;

  let html = '';

  if (accounts.length > 1) {
    html += `
      <!-- Option: View All Lines (Combined View) -->
      <div onclick="switchActiveWhatsAppLine('all', 'All ${accounts.length} WhatsApp Lines', 'Combined Hub')" class="p-2.5 rounded-xl hover:bg-slate-50 cursor-pointer transition flex items-center justify-between group ${ACTIVE_SEND_ACCOUNT_ID === 'all' ? 'bg-emerald-50/80 border border-emerald-300' : ''}">
        <div class="flex items-center gap-2.5 min-w-0">
          <div class="w-8 h-8 rounded-lg ${ACTIVE_SEND_ACCOUNT_ID === 'all' ? 'bg-brand-dark text-white shadow-sm' : 'bg-slate-100 text-slate-600 group-hover:bg-emerald-100 group-hover:text-emerald-700'} flex items-center justify-center font-bold text-xs shrink-0">
            <span class="material-symbols-outlined text-[18px]">hub</span>
          </div>
          <div class="min-w-0">
            <div class="flex items-center gap-1.5">
              <span class="font-bold text-slate-900 text-xs truncate">All ${accounts.length} WhatsApp Lines</span>
              ${ACTIVE_SEND_ACCOUNT_ID === 'all' ? '<span class="text-[9px] bg-brand-dark text-white px-1.5 py-0.2 rounded font-extrabold">ACTIVE</span>' : ''}
            </div>
            <p class="text-[10px] text-slate-500">View combined queue across all numbers</p>
          </div>
        </div>
        <span class="text-[10px] bg-slate-200 text-slate-800 font-extrabold px-2 py-0.5 rounded-full">${totalChats} Chats</span>
      </div>
    `;
  }

  html += accounts.map((acc, index) => {
    const accCleanPhone = (acc.connected_number || '').replace(/\s+/g, '');
    const isCurrent = (acc.id === ACTIVE_SEND_ACCOUNT_ID) || (accounts.length === 1 && ACTIVE_SEND_ACCOUNT_ID !== 'all');
    const rawCleanDigits = (acc.connected_number || '').replace(/\D/g, '');
    const hasRealPhone = rawCleanDigits.length >= 10;
    const isConn = acc.status === 'CONNECTED' || hasRealPhone;
    const isScanning = !isConn && acc.status === 'SCAN_QR';
    const isScan = isScanning;
    const isStaffNum = (typeof isStaffMobile === 'function') && (isStaffMobile(acc.connected_number) || isStaffMobile(rawCleanDigits));
    const displayPhone = (rawCleanDigits.length >= 7 && !isStaffNum)
      ? formatPhoneNumberPretty(acc.connected_number)
      : (isConn && !isStaffNum ? (acc.connected_number || CRM_STATE?.whatsappAccount?.phoneNumber || 'Awaiting Link') : (isScanning ? 'Scan QR Code' : (acc.connected_number || 'Awaiting Link')));
    const custCount = (CRM_STATE?.customers || []).filter(c => {
      const q = (CRM_STATE?.queries || []).find(qry => qry.customerId === c.id);
      return (c.accountId || (q ? q.accountId : 'account_1')) === acc.id;
    }).length;

    return `
      <div onclick="switchActiveWhatsAppLine('${acc.id}', '${rawCleanDigits.length >= 7 ? acc.connected_number : ''}', '${acc.label || 'Line ' + (index + 1)}')" class="p-2.5 rounded-xl hover:bg-slate-50 cursor-pointer transition flex items-center justify-between group ${isCurrent ? 'bg-emerald-50/80 border border-emerald-300' : ''}">
        <div class="flex items-center gap-2.5 min-w-0">
          <div class="w-8 h-8 rounded-lg ${isCurrent ? 'bg-brand-wa text-white shadow-sm' : (isConn ? 'bg-emerald-100 text-emerald-700' : (isScanning ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-600'))} flex items-center justify-center font-bold text-xs shrink-0">
            <span class="material-symbols-outlined text-[18px]">${isCurrent ? 'check_circle' : (isConn ? 'phone_android' : (isScanning ? 'qr_code_scanner' : 'phonelink_off'))}</span>
          </div>
          <div class="min-w-0">
            <div class="flex items-center gap-1.5">
              <span class="font-bold text-slate-900 text-xs truncate">${acc.label || ('WhatsApp Line #' + (index + 1))}</span>
              ${isCurrent ? '<span class="text-[9px] bg-brand-wa text-white px-1.5 py-0.2 rounded font-extrabold">ACTIVE</span>' : ''}
            </div>
            <p class="font-mono text-[11px] font-bold ${isConn ? 'text-emerald-700' : (isScan ? 'text-amber-700' : 'text-slate-500')}">${displayPhone}</p>
          </div>
        </div>
        <div class="text-right shrink-0 flex flex-col items-end">
          <span class="inline-flex items-center gap-1 text-[10px] font-bold ${isConn ? 'text-emerald-600' : (isScanning ? 'text-amber-600' : 'text-slate-500')}">
            <span class="w-1.5 h-1.5 rounded-full ${isConn ? 'bg-emerald-500' : (isScanning ? 'bg-amber-500 animate-pulse' : 'bg-slate-400')}"></span>
            ${isConn ? 'Connected' : (isScanning ? 'Scan QR' : 'Awaiting Link')}
          </span>
          <span class="text-[9px] text-slate-400 font-semibold">${custCount} Chats</span>
        </div>
      </div>
    `;
  }).join('');

  listContainer.innerHTML = html;
}

// Switch Active WhatsApp Line & Dynamically Filter Chats
function switchActiveWhatsAppLine(accountId, phoneNumber, label) {
  ACTIVE_SEND_ACCOUNT_ID = accountId;
  try {
    localStorage.setItem('GRM_ACTIVE_SEND_ACCOUNT_ID', accountId);
  } catch (e) {}
  if (!CRM_STATE.whatsappAccount) {
    CRM_STATE.whatsappAccount = {};
  }

  const accounts = getAvailableWhatsAppAccounts();
  const selectedAcc = accounts.find(a => a.id === accountId);
  const isConn = (accountId === 'all')
    ? accounts.some(a => a.status === 'CONNECTED')
    : Boolean(selectedAcc && selectedAcc.status === 'CONNECTED');

  if (accountId !== 'all') {
    const cleanDigits = String(phoneNumber || '').replace(/\D/g, '');
    if (cleanDigits.length >= 7) {
      CRM_STATE.whatsappAccount.phoneNumber = phoneNumber;
    } else if (selectedAcc && selectedAcc.connected_number && selectedAcc.connected_number.replace(/\D/g, '').length >= 7) {
      CRM_STATE.whatsappAccount.phoneNumber = selectedAcc.connected_number;
    }
  }
  CRM_STATE.whatsappAccount.status = isConn ? 'CONNECTED' : (selectedAcc ? (selectedAcc.status || 'DISCONNECTED') : 'DISCONNECTED');
  saveCRMState();
  updateConfiguredPhoneDisplays();
  closePhoneSwitcherDropdown();

  // If selected account is not connected, notify user gracefully without disrupting inbox
  if (selectedAcc && selectedAcc.status !== 'CONNECTED' && accountId !== 'all') {
    showToast('Scan QR Code Required', `Line "${selectedAcc.label || label}" is awaiting phone connection. Go to Settings > QR to link phone.`, 'qr_code_scanner', 'amber');
  }

  // If in settings view, refresh multi-accounts hub
  if (ACTIVE_VIEW === 'settings') {
    renderMultiAccountsHub();
  }
  if (typeof renderInboxSettingsView === 'function') {
    renderInboxSettingsView();
  }

  // Auto-switch ACTIVE_CUSTOMER_ID to the first available conversation in this line
  const availableCusts = (CRM_STATE.customers || []).filter(c => {
    if (accountId === 'all') return true;
    const q = (CRM_STATE.queries || []).find(qry => qry.customerId === c.id);
    const cAcc = c.accountId || (q ? q.accountId : 'account_1');
    return cAcc === accountId;
  });

  if (availableCusts.length > 0 && !availableCusts.some(c => c.id === ACTIVE_CUSTOMER_ID)) {
    ACTIVE_CUSTOMER_ID = availableCusts[0].id;
  }

  // Refresh inbox conversation list & header & chat messages & customer 360
  if (ACTIVE_VIEW === 'inbox') {
    renderInbox();
  } else {
    if (typeof renderInboxConversationList === 'function') renderInboxConversationList();
    if (typeof renderChatHeader === 'function') renderChatHeader();
  }

  if (typeof playChime === 'function') playChime('order');
  showToast(
    'WhatsApp Line Switched',
    `Active Line: ${CRM_STATE.whatsappAccount.phoneNumber || label || 'WhatsApp Line'}. Dynamic chats loaded.`,
    'swap_horiz',
    isConn ? 'emerald' : 'amber'
  );
}

