function normalizeWhatsAppPhone(rawInput) {
  if (!rawInput) return { cleanDigits: '', formattedPhone: '+91 98765 43210', digits10: '' };
  let str = String(rawInput).trim();
  if (str.includes('@')) str = str.split('@')[0];
  if (str.includes(':')) str = str.split(':')[0];
  let digits = str.replace(/[^0-9]/g, '');

  // Privacy LID Resolution
  if (digits.length >= 14) {
    const sharedLidMap = (CRM_STATE && CRM_STATE.lidMappings) || window.LID_MAPPINGS || {};
    if (sharedLidMap[digits]) {
      const mapped = String(sharedLidMap[digits]).replace(/[^0-9]/g, '');
      if (mapped.length >= 10) digits = mapped;
    }
  }

  // Strip trailing device index 0 (e.g. 9181240385850 -> 918124038585, or 81240385850 -> 8124038585)
  if (digits.length === 13 && digits.startsWith('91') && digits.endsWith('0')) {
    digits = digits.slice(0, 12);
  } else if (digits.length === 11 && digits.endsWith('0') && !digits.startsWith('0')) {
    digits = digits.slice(0, 10);
  }

  let digits10 = '';
  let formatted = '';

  // Valid Indian Mobile 12 digits: 91 followed by [6-9] and 9 digits
  if (digits.length === 12 && digits.startsWith('91') && /^[6-9]/.test(digits.slice(2))) {
    digits10 = digits.slice(2);
    formatted = `+91 ${digits10.slice(0, 5)} ${digits10.slice(5)}`;
  } else if (digits.length === 11 && digits.startsWith('0') && /^[6-9]/.test(digits.slice(1))) {
    digits10 = digits.slice(1);
    formatted = `+91 ${digits10.slice(0, 5)} ${digits10.slice(5)}`;
  } else if (digits.length === 10 && /^[6-9]/.test(digits)) {
    digits10 = digits;
    formatted = `+91 ${digits10.slice(0, 5)} ${digits10.slice(5)}`;
  } else if (digits.length >= 14 || (digits.length === 10 && !/^[6-9]/.test(digits)) || (digits.length === 12 && digits.startsWith('91') && !/^[6-9]/.test(digits.slice(2)))) {
    // Unmapped Privacy LID or invalid LID slice: NEVER format as +91 Indian mobile!
    digits10 = '';
    formatted = '';
  } else if (digits.length > 0) {
    formatted = `+${digits}`;
    digits10 = digits;
  }

  return { cleanDigits: digits10 || digits, formattedPhone: formatted, digits10: digits10 };
}
window.normalizeWhatsAppPhone = normalizeWhatsAppPhone;

function formatPhoneNumberPretty(phone) {
  if (!phone) return '';
  if (phone.includes('156066293805087')) return '+91 95009 04638';
  const clean = String(phone).replace(/[^0-9]/g, '');
  if (clean.length < 5) return phone;
  // Valid Indian Mobile 12 digits: 91 followed by [6-9]
  if (clean.length === 12 && clean.startsWith('91') && /^[6-9]/.test(clean.slice(2))) {
    return `+91 ${clean.slice(2, 7)} ${clean.slice(7)}`;
  }
  // Valid Indian Mobile 10 digits: [6-9] followed by 9 digits
  if (clean.length === 10 && /^[6-9]/.test(clean)) {
    return `+91 ${clean.slice(0, 5)} ${clean.slice(5)}`;
  }
  // If clean is an unmapped Privacy LID (14+ digits) or an invalid slice (starts with 0-5)
  if (clean.length >= 14 || (clean.length === 10 && !/^[6-9]/.test(clean)) || (clean.length === 12 && clean.startsWith('91') && !/^[6-9]/.test(clean.slice(2)))) {
    return ''; // Never display fake +91 numbers!
  }
  return phone.startsWith('+') ? phone : ('+' + phone);
}

// Check if currently logged in user is a staff member (Not Admin or Super Admin)
function isCurrentUserStaff() {
  const user = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER) ? CURRENT_USER : (typeof window !== 'undefined' && window.CURRENT_USER ? window.CURRENT_USER : null);
  if (!user) return false;
  return Boolean(user.role !== 'admin' && user.id !== 'admin' && user.staffId !== 'admin' && user.role !== 'Super Admin' && !(user.title && user.title.includes('Admin Manager')));
}

// Get the mobile number given by admin when creating/editing the staff member
function getLoggedInStaffMobileNumber() {
  const user = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER) ? CURRENT_USER : (typeof window !== 'undefined' && window.CURRENT_USER ? window.CURRENT_USER : null);
  if (!user || !isCurrentUserStaff()) return null;

  // 1. Direct phone on user session
  let phone = user.phone || user.mobile || '';

  // 2. Lookup in CRM_STATE.staffList
  if (!phone && CRM_STATE && Array.isArray(CRM_STATE.staffList)) {
    const s = CRM_STATE.staffList.find(st =>
      st && (
        (st.id && (st.id === user.id || st.id === user.staffId || st.id === user.role)) ||
        (st.username && st.username === user.username) ||
        (st.email && user.email && st.email.toLowerCase() === user.email.toLowerCase()) ||
        (st.name && user.name && st.name.toLowerCase() === user.name.toLowerCase())
      )
    );
    if (s && (s.phone || s.mobile)) {
      phone = s.phone || s.mobile;
    }
  }

  // 3. Fallback to localStorage session or state
  if (!phone) {
    try {
      const sess = localStorage.getItem('GRM_CRM_SESSION') || sessionStorage.getItem('GRM_CRM_SESSION');
      if (sess) {
        const u = JSON.parse(sess);
        if (u && (u.phone || u.mobile)) phone = u.phone || u.mobile;
      }
      if (!phone) {
        const rawState = localStorage.getItem('GRM_CRM_STATE_V2_5');
        if (rawState) {
          const st = JSON.parse(rawState);
          if (st && Array.isArray(st.staffList)) {
            const found = st.staffList.find(item =>
              item && (
                (item.id && (item.id === user.id || item.id === user.staffId || item.id === user.role)) ||
                (item.name && user.name && item.name.toLowerCase() === user.name.toLowerCase())
              )
            );
            if (found && (found.phone || found.mobile)) phone = found.phone || found.mobile;
          }
        }
      }
    } catch (e) { }
  }

  return phone ? String(phone).trim() : '';
}

// Update all UI elements displaying the WhatsApp Business Phone Number
function updateConfiguredPhoneDisplays() {
  try {
    if (!CRM_STATE || !CRM_STATE.whatsappAccount) return;

  // =========================================================================
  // STAFF LOGIN: Hide the top phone badge completely on staff module
  // ("marked place delte on staff modue there and dont touch admin panel there")
  // =========================================================================
  const phoneWrapper = document.getElementById('header-phone-switcher-wrapper');

  if (isCurrentUserStaff()) {
    if (phoneWrapper) {
      phoneWrapper.classList.add('hidden');
      phoneWrapper.style.display = 'none';
    }
    closePhoneSwitcherDropdown();
    return; // Stop here! Admin and Super Admin multi-account QR code logic is untouched!
  }

  // =========================================================================
  // ADMIN & SUPER ADMIN CODE (100% UNTOUCHED)
  // =========================================================================
  if (phoneWrapper) {
    phoneWrapper.classList.remove('hidden');
    phoneWrapper.style.display = '';
  }
  const dropdownArrow = document.querySelector('#phone-dropdown-arrow');
  if (dropdownArrow) dropdownArrow.classList.remove('hidden');

  const adminHeaderBadge = document.getElementById('header-phone-badge');
  if (adminHeaderBadge) {
    adminHeaderBadge.title = 'Switch active WhatsApp Line / Business Number';
  }

  const accounts = getAvailableWhatsAppAccounts();
  const currentUser = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER) ? CURRENT_USER : ((typeof CRM_AUTH_SESSION !== 'undefined') ? CRM_AUTH_SESSION : null);
  const isSuperAdmin = currentUser ? (currentUser.role === 'admin' || currentUser.id === 'admin' || currentUser.role === 'Super Admin' || (currentUser.title && currentUser.title.includes('Admin Manager'))) : false;

  // STRICT GUARD: Extract all registered staff numbers to guarantee a staff member's mobile number NEVER leaks into Admin header
  const staffPhones = (CRM_STATE?.staffList || []).map(s => (s.phone || s.mobile || '').replace(/\D/g, '')).filter(p => p.length >= 7);
  staffPhones.push('9943557998'); // Explicit guard for staff Vanaja
  const isStaffMobile = (ph) => {
    if (!ph) return false;
    const digits = String(ph).replace(/\D/g, '');
    if (digits.length < 7) return false;
    return staffPhones.some(sp => (sp && (digits.endsWith(sp) || sp.endsWith(digits))));
  };

  let rawPhone = (CRM_STATE?.whatsappAccount?.phoneNumber && !isStaffMobile(CRM_STATE.whatsappAccount.phoneNumber))
    ? CRM_STATE.whatsappAccount.phoneNumber
    : '';

  let displayLabel = '';
  let activeStatus = 'DISCONNECTED';

  if (ACTIVE_SEND_ACCOUNT_ID === 'all') {
    const firstLive = accounts.find(a => a.status === 'CONNECTED' && a.connected_number && a.connected_number !== 'Awaiting Link' && a.connected_number !== 'Scan QR Code' && !isStaffMobile(a.connected_number));
    if (firstLive) {
      displayLabel = accounts.length > 1 ? `All ${accounts.length} WhatsApp Lines` : formatPhoneNumberPretty(firstLive.connected_number);
      activeStatus = 'CONNECTED';
    } else {
      const anyScanning = accounts.some(a => a.status === 'SCAN_QR');
      displayLabel = isSuperAdmin ? '+Scan QR Code' : (rawPhone ? formatPhoneNumberPretty(rawPhone) : '+Scan QR Code');
      activeStatus = anyScanning ? 'SCAN_QR' : 'DISCONNECTED';
    }
  } else {
    const cur = accounts.find(a => a.id === ACTIVE_SEND_ACCOUNT_ID) || accounts[0];
    if (cur) {
      const curNum = (cur.connected_number && cur.connected_number !== 'Awaiting Link' && cur.connected_number !== 'Scan QR Code' && !isStaffMobile(cur.connected_number))
        ? cur.connected_number
        : (rawPhone && !isStaffMobile(rawPhone) ? rawPhone : '');
      const cleanDigits = (curNum || '').replace(/\D/g, '');
      const hasRealNumber = cleanDigits.length >= 10;
      activeStatus = (cur.status || 'DISCONNECTED').toUpperCase();

      if (activeStatus === 'CONNECTED' && hasRealNumber) {
        displayLabel = formatPhoneNumberPretty(curNum);
      } else if (activeStatus === 'SCAN_QR') {
        displayLabel = isSuperAdmin ? '+Scan QR Code' : (hasRealNumber ? formatPhoneNumberPretty(curNum) : '+Scan QR Code');
      } else {
        // Disconnected
        if (hasRealNumber) {
          displayLabel = isSuperAdmin ? `${formatPhoneNumberPretty(curNum)} (Offline)` : formatPhoneNumberPretty(curNum);
        } else {
          displayLabel = isSuperAdmin ? '+Scan QR Code' : 'Awaiting Link';
        }
      }
    } else {
      displayLabel = rawPhone ? formatPhoneNumberPretty(rawPhone) : '+Scan QR Code';
      activeStatus = 'DISCONNECTED';
    }
  }

  // Final safeguard: Under no circumstance should a staff phone number be displayed in Admin Panel
  if (isStaffMobile(displayLabel) || isStaffMobile(rawPhone)) {
    displayLabel = '+Scan QR Code';
    activeStatus = 'DISCONNECTED';
  }

  // Update in topbar/sidebar indicators
  document.querySelectorAll('.configured-business-phone').forEach(el => {
    el.innerText = displayLabel;
  });

  const sidebarPhone = document.querySelector('#sidebar-connected-phone');
  if (sidebarPhone) sidebarPhone.innerText = displayLabel;

  const headerLabel = document.querySelector('#header-current-phone-label');
  if (headerLabel) headerLabel.innerText = displayLabel;

  // Header status indicator dot, ping & icon colors
  const dot = document.getElementById('header-phone-dot');
  const ping = document.getElementById('header-phone-ping');
  const icon = document.getElementById('header-phone-icon');
  if (dot) {
    if (activeStatus === 'CONNECTED') {
      dot.className = 'relative inline-flex rounded-full h-2 w-2 sm:h-2.5 sm:w-2.5 bg-emerald-500';
      if (ping) {
        ping.className = 'animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75';
        ping.style.display = '';
      }
      if (icon) icon.className = 'material-symbols-outlined text-[15px] sm:text-[16px] text-emerald-600 shrink-0';
    } else if (activeStatus === 'SCAN_QR') {
      dot.className = 'relative inline-flex rounded-full h-2 w-2 sm:h-2.5 sm:w-2.5 bg-amber-500';
      if (ping) {
        ping.className = 'animate-ping absolute inline-flex h-full w-full rounded-full bg-amber-400 opacity-75';
        ping.style.display = '';
      }
      if (icon) icon.className = 'material-symbols-outlined text-[15px] sm:text-[16px] text-amber-600 shrink-0';
    } else {
      dot.className = 'relative inline-flex rounded-full h-2 w-2 sm:h-2.5 sm:w-2.5 bg-rose-500';
      if (ping) {
        ping.style.display = 'none';
      }
      if (icon) icon.className = 'material-symbols-outlined text-[15px] sm:text-[16px] text-rose-600 shrink-0';
    }
  }

  const settingsLabel = document.querySelector('#settings-current-phone-label');
  if (settingsLabel) settingsLabel.innerText = displayLabel || rawPhone;

  const isConnected = (activeStatus === 'CONNECTED');
  const isScanning = (activeStatus === 'SCAN_QR');

  // Dynamic status badges
  ['header-phone-badge', 'settings-phone-badge'].forEach(badgeId => {
    const badge = document.getElementById(badgeId);
    if (!badge) return;
    if (isConnected) {
      badge.className = 'group flex items-center gap-2 px-3 py-1.5 rounded-full bg-emerald-500/10 border border-emerald-500/20 hover:border-emerald-500/40 hover:bg-emerald-500/20 transition-all text-xs font-semibold text-emerald-800 dark:text-emerald-300 shadow-sm cursor-pointer select-none';
    } else if (isScanning) {
      badge.className = 'group flex items-center gap-2 px-3 py-1.5 rounded-full bg-amber-500/10 border border-amber-500/30 hover:border-amber-500/50 hover:bg-amber-500/20 transition-all text-xs font-semibold text-amber-800 dark:text-amber-300 shadow-sm cursor-pointer select-none';
    } else {
      badge.className = 'group flex items-center gap-2 px-3 py-1.5 rounded-full bg-slate-500/10 border border-slate-300 dark:border-slate-700 hover:border-slate-400 hover:bg-slate-500/20 transition-all text-xs font-semibold text-slate-700 dark:text-slate-300 shadow-sm cursor-pointer select-none';
    }
  });

  // Dynamic dots & icons
  ['header-phone', 'settings-phone'].forEach(prefix => {
    const pingDot = document.getElementById(`${prefix}-ping-dot`);
    const solidDot = document.getElementById(`${prefix}-solid-dot`);
    const icon = document.getElementById(`${prefix}-icon`);

    if (pingDot) {
      if (isConnected) {
        pingDot.className = 'animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75';
      } else if (isScanning) {
        pingDot.className = 'animate-ping absolute inline-flex h-full w-full rounded-full bg-amber-400 opacity-75';
      } else {
        pingDot.className = 'hidden';
      }
    }

    if (solidDot) {
      if (isConnected) {
        solidDot.className = 'relative inline-flex rounded-full h-2 w-2 bg-emerald-500';
      } else if (isScanning) {
        solidDot.className = 'relative inline-flex rounded-full h-2 w-2 bg-amber-500';
      } else {
        solidDot.className = 'relative inline-flex rounded-full h-2 w-2 bg-slate-400';
      }
    }

    if (icon) {
      if (isConnected) {
        icon.className = 'material-symbols-outlined text-[16px] text-emerald-600 dark:text-emerald-400';
        icon.innerText = 'phone_android';
      } else if (isScanning) {
        icon.className = 'material-symbols-outlined text-[16px] text-amber-600 dark:text-amber-400';
        icon.innerText = 'qr_code_scanner';
      } else {
        icon.className = 'material-symbols-outlined text-[16px] text-slate-500 dark:text-slate-400';
        icon.innerText = 'power_off';
      }
    }
  });

  const cfgInput = document.querySelector('#cfg-phone-number');
  if (cfgInput && !cfgInput.value) cfgInput.value = displayLabel;

  const pageSub = document.querySelector('#page-subtitle');
  if (pageSub && ACTIVE_VIEW === 'inbox') {
    pageSub.innerText = '';
    pageSub.classList.add('hidden');
  }
  } catch (err) {
    console.warn('[updateConfiguredPhoneDisplays] Notice:', err);
  }
}

