// =========================================================================
// AUDIO PLAYBACK CONTROLLER WITH WEB AUDIO API UNIVERSAL DECODER FALLBACK
// =========================================================================
let _crmWebAudioCtx = null;
let _crmActiveWebAudio = null;

async function playWithWebAudioFallback(src, msgId, icon, seek, timeLbl) {
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return false;
    if (!_crmWebAudioCtx) _crmWebAudioCtx = new AudioCtx();
    if (_crmWebAudioCtx.state === 'suspended') await _crmWebAudioCtx.resume();

    // If currently playing this same voice, toggle pause
    if (_crmActiveWebAudio && _crmActiveWebAudio.msgId === msgId && _crmActiveWebAudio.isPlaying) {
      if (_crmActiveWebAudio.source) {
        try { _crmActiveWebAudio.source.stop(); } catch (e) {}
      }
      if (_crmActiveWebAudio.interval) clearInterval(_crmActiveWebAudio.interval);
      _crmActiveWebAudio.isPlaying = false;
      if (icon) icon.innerText = 'play_arrow';
      return true;
    }

    // Stop any previous Web Audio playback
    if (_crmActiveWebAudio && _crmActiveWebAudio.source) {
      try { _crmActiveWebAudio.source.stop(); } catch (e) {}
      if (_crmActiveWebAudio.interval) clearInterval(_crmActiveWebAudio.interval);
      const prevIcon = document.getElementById(`icon-${_crmActiveWebAudio.msgId}`);
      if (prevIcon) prevIcon.innerText = 'play_arrow';
    }

    let arrayBuf = null;
    if (src.startsWith('data:audio/')) {
      const base64Data = src.split(',')[1] || src.replace(/^data:[^;]+;base64,/, '');
      const binaryStr = atob(base64Data);
      const len = binaryStr.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) bytes[i] = binaryStr.charCodeAt(i);
      arrayBuf = bytes.buffer;
    } else {
      const resp = await fetch(src);
      if (!resp.ok) throw new Error('HTTP ' + resp.status);
      arrayBuf = await resp.arrayBuffer();
    }

    const decodedBuffer = await _crmWebAudioCtx.decodeAudioData(arrayBuf);
    const sourceNode = _crmWebAudioCtx.createBufferSource();
    sourceNode.buffer = decodedBuffer;
    sourceNode.connect(_crmWebAudioCtx.destination);

    const dur = decodedBuffer.duration;
    if (seek) seek.max = dur;
    if (icon) icon.innerText = 'pause';

    const startEpoch = _crmWebAudioCtx.currentTime;
    const interval = setInterval(() => {
      if (!_crmWebAudioCtx) return;
      const elapsed = _crmWebAudioCtx.currentTime - startEpoch;
      if (seek) seek.value = elapsed;
      if (timeLbl) timeLbl.innerText = formatAudioTime(elapsed);
      if (elapsed >= dur) {
        clearInterval(interval);
        if (icon) icon.innerText = 'play_arrow';
        if (seek) seek.value = 0;
        if (timeLbl) timeLbl.innerText = formatAudioTime(dur);
        if (_crmActiveWebAudio) _crmActiveWebAudio.isPlaying = false;
      }
    }, 150);

    sourceNode.onended = () => {
      clearInterval(interval);
      if (icon) icon.innerText = 'play_arrow';
      if (seek) seek.value = 0;
      if (timeLbl) timeLbl.innerText = formatAudioTime(dur);
      if (_crmActiveWebAudio) _crmActiveWebAudio.isPlaying = false;
    };

    sourceNode.start(0);
    _crmActiveWebAudio = { source: sourceNode, msgId: msgId, isPlaying: true, interval: interval };
    return true;
  } catch (err) {
    console.warn('[Web Audio Playback Fallback Failed]:', err);
    return false;
  }
}

window.toggleAudioPlay = function (msgId) {
  const audio = document.getElementById(`audio-${msgId}`);
  const icon = document.getElementById(`icon-${msgId}`);
  const seek = document.getElementById(`seek-${msgId}`);
  const timeLbl = document.getElementById(`time-${msgId}`);
  if (!audio) return;

  // If Web Audio fallback is active for this audio
  if (_crmActiveWebAudio && _crmActiveWebAudio.msgId === msgId && _crmActiveWebAudio.isPlaying) {
    if (_crmActiveWebAudio.source) {
      try { _crmActiveWebAudio.source.stop(); } catch (e) {}
    }
    if (_crmActiveWebAudio.interval) clearInterval(_crmActiveWebAudio.interval);
    _crmActiveWebAudio.isPlaying = false;
    if (icon) icon.innerText = 'play_arrow';
    return;
  }

  let src = audio.currentSrc || audio.src || '';
  if (!src || src === '' || src === window.location.href || src.endsWith('/')) {
    const rawAttr = audio.getAttribute('src') || audio.getAttribute('data-fallback-src') || audio.getAttribute('data-src');
    if (rawAttr && rawAttr.trim()) {
      src = (rawAttr.startsWith('http://') || rawAttr.startsWith('https://') || rawAttr.startsWith('data:') || rawAttr.startsWith('blob:'))
        ? rawAttr
        : (window.location.origin + '/' + rawAttr.replace(/^\/+/, ''));
      audio.src = src;
    }
  }

  if (!src || src === '' || src === window.location.href || src.endsWith('/')) {
    playSimulatedVoice(msgId);
    return;
  }

  if (audio.paused) {
    // Pause all other active HTML5 audios and Web Audio instances
    document.querySelectorAll('audio').forEach(a => {
      if (a !== audio) {
        try { a.pause(); } catch (e) {}
        const otherId = a.id.replace('audio-', '');
        const otherIcon = document.getElementById(`icon-${otherId}`);
        if (otherIcon) otherIcon.innerText = 'play_arrow';
      }
    });
    if (_crmActiveWebAudio && _crmActiveWebAudio.source) {
      try { _crmActiveWebAudio.source.stop(); } catch (e) {}
      if (_crmActiveWebAudio.interval) clearInterval(_crmActiveWebAudio.interval);
      _crmActiveWebAudio.isPlaying = false;
    }

    audio.play().then(() => {
      if (icon) icon.innerText = 'pause';
    }).catch(err => {
      console.warn('[Audio Play Fallback with direct Audio object]:', err);
      try {
        const directAudio = new Audio(src);
        directAudio.play().then(() => {
          if (icon) icon.innerText = 'pause';
          directAudio.onended = () => { if (icon) icon.innerText = 'play_arrow'; };
          directAudio.ontimeupdate = () => {
            if (seek && directAudio.duration) { seek.max = directAudio.duration; seek.value = directAudio.currentTime; }
            if (timeLbl) timeLbl.innerText = formatAudioTime(directAudio.currentTime);
          };
        }).catch(async (err2) => {
          console.warn('[Direct Audio Play Failed, Trying Web Audio API]:', err2);
          const webAudioSuccess = await playWithWebAudioFallback(src, msgId, icon, seek, timeLbl);
          if (!webAudioSuccess) {
            playSimulatedVoice(msgId);
          }
        });
      } catch (e3) {
        playWithWebAudioFallback(src, msgId, icon, seek, timeLbl).then(ok => {
          if (!ok) playSimulatedVoice(msgId);
        });
      }
    });
  } else {
    audio.pause();
    if (icon) icon.innerText = 'play_arrow';
  }
};

window.seekAudio = function (msgId, val) {
  const audio = document.getElementById(`audio-${msgId}`);
  if (audio && !isNaN(audio.duration) && audio.duration > 0) {
    audio.currentTime = parseFloat(val);
  }
};

window.updateAudioProgress = function (msgId) {
  const audio = document.getElementById(`audio-${msgId}`);
  const seek = document.getElementById(`seek-${msgId}`);
  const timeLbl = document.getElementById(`time-${msgId}`);
  if (audio && seek) {
    if (audio.duration && !isNaN(audio.duration)) {
      seek.max = audio.duration;
    }
    seek.value = audio.currentTime;
    if (timeLbl) {
      timeLbl.innerText = formatAudioTime(audio.currentTime);
    }
  }
};

window.onAudioEnded = function (msgId) {
  const icon = document.getElementById(`icon-${msgId}`);
  const seek = document.getElementById(`seek-${msgId}`);
  const timeLbl = document.getElementById(`time-${msgId}`);
  const audio = document.getElementById(`audio-${msgId}`);
  if (icon) icon.innerText = 'play_arrow';
  if (seek) seek.value = 0;
  if (timeLbl && audio && audio.duration) timeLbl.innerText = formatAudioTime(audio.duration);
};

window.toggleAudioSpeed = function (msgId) {
  const audio = document.getElementById(`audio-${msgId}`);
  const btn = document.getElementById(`speed-${msgId}`);
  if (!audio || !btn) return;

  const currentRate = audio.playbackRate || 1.0;
  let nextRate = 1.0;
  if (currentRate === 1.0) nextRate = 1.5;
  else if (currentRate === 1.5) nextRate = 2.0;
  else nextRate = 1.0;

  audio.playbackRate = nextRate;
  btn.innerText = `${nextRate.toFixed(1)}x`;
};

function formatAudioTime(seconds) {
  if (isNaN(seconds) || seconds === null || seconds <= 0) return '0:00';
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
}
window.formatAudioTime = formatAudioTime;

window.handleAudioFallback = function (msgId) {
  console.log(`[Audio Element]: Fallback ready for ${msgId}`);
};

// Simulated voice synthesizer chime for previewing when audio payload is simulated
let synthAudioInterval = null;
window.playSimulatedVoice = function (msgId) {
  const icon = document.getElementById(`icon-${msgId}`);
  const seek = document.getElementById(`seek-${msgId}`);
  const timeLbl = document.getElementById(`time-${msgId}`);

  if (icon && icon.innerText === 'pause') {
    if (synthAudioInterval) clearInterval(synthAudioInterval);
    icon.innerText = 'play_arrow';
    return;
  }

  if (icon) icon.innerText = 'pause';
  playChime('inbound');

  let currentSec = 0;
  const maxSec = (seek && parseFloat(seek.max) > 0) ? parseFloat(seek.max) : 10;
  if (seek) seek.max = maxSec;

  if (synthAudioInterval) clearInterval(synthAudioInterval);
  synthAudioInterval = setInterval(() => {
    currentSec += 0.5;
    if (seek) seek.value = currentSec;
    if (timeLbl) timeLbl.innerText = formatAudioTime(currentSec);

    if (currentSec >= maxSec) {
      clearInterval(synthAudioInterval);
      if (icon) icon.innerText = 'play_arrow';
      if (seek) seek.value = 0;
      if (timeLbl) timeLbl.innerText = formatAudioTime(maxSec);
    }
  }, 500);
};

// Update Query Status (Pending, Follow-up, In Progress, Converted, Resolved, DND) with optional Notes
function updateCustomerQueryStatus(queryId, newStatus, notes = '', paymentData = null, callbackSchedule = null) {
  let query = (CRM_STATE.queries || []).find(q => q && (q.id === queryId || q.customerId === queryId));
  const customer = query ? (CRM_STATE.customers || []).find(c => c && (c.id === query.customerId || String(c.id) === String(query.customerId))) : (CRM_STATE.customers || []).find(c => c && (c.id === queryId || String(c.id) === String(queryId)));
  if (!query && !customer) return;

  const oldStatus = query ? query.status : 'NEW';
  const currentUser = typeof getCurrentUser === 'function' ? getCurrentUser() : null;
  const staffName = currentUser ? (currentUser.name || currentUser.username || (ACTIVE_ROLE === 'admin' ? 'Super Admin' : 'Staff')) : (ACTIVE_ROLE === 'admin' ? 'Super Admin' : (CRM_STATE.staffList?.find(s => s.id === ACTIVE_ROLE)?.name || 'Staff'));
  const now = new Date();
  const timeFormatted = now.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }) + ' at ' + now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });

  // If customer didn't have an existing query entry, instantiate one dynamically
  if (!query && customer) {
    const newQId = 'Q-' + now.getFullYear() + '-' + Math.floor(100000 + Math.random() * 900000);
    query = {
      id: newQId,
      customerId: customer.id,
      assignedTo: 'UNASSIGNED',
      status: newStatus,
      priority: 'NORMAL',
      queryText: notes || 'WhatsApp Lead Enquiry',
      statusNotes: notes,
      isPaymentPending: Boolean(paymentData && paymentData.isPaymentPending),
      paymentAmount: paymentData && paymentData.isPaymentPending ? parseFloat(paymentData.paymentAmount || 0) : 0,
      shippingAmount: paymentData && paymentData.isPaymentPending ? parseFloat(paymentData.shippingAmount || 0) : 0,
      paymentMode: paymentData?.paymentMode || 'UPI',
      advancePayment: paymentData && paymentData.isPaymentPending ? parseFloat(paymentData.advancePayment || 0) : 0,
      paymentDueDate: paymentData?.paymentDueDate || '',
      paymentNotes: paymentData?.paymentNotes || '',
      quotedItems: paymentData?.quotedItems || '',
      callback_date: callbackSchedule?.date || '',
      callback_time: callbackSchedule?.time || '11:00 AM',
      callbackDate: callbackSchedule?.date || '',
      callbackTime: callbackSchedule?.time || '11:00 AM',
      statusHistory: [],
      createdAt: now.toISOString()
    };
    if (!Array.isArray(CRM_STATE.queries)) CRM_STATE.queries = [];
    CRM_STATE.queries.unshift(query);
  }

  if (query) {
    query.status = newStatus;
    query.statusLastEditedBy = staffName;
    query.statusLastEditedAt = timeFormatted;
    query.statusPrevious = oldStatus;
    if (notes !== undefined && notes !== null) {
      query.statusNotes = notes;
    }
    if (paymentData && paymentData.isPaymentPending) {
      query.isPaymentPending = true;
      query.paymentAmount = parseFloat(paymentData.paymentAmount || 0);
      query.shippingAmount = parseFloat(paymentData.shippingAmount || 0);
      query.paymentMode = paymentData.paymentMode || 'UPI';
      query.advancePayment = parseFloat(paymentData.advancePayment || 0);
      query.paymentDueDate = paymentData.paymentDueDate || '';
      query.paymentNotes = paymentData.paymentNotes || '';
      query.quotedItems = paymentData.quotedItems || '';
    } else if (paymentData && paymentData.isPaymentPending === false) {
      query.isPaymentPending = false;
      query.is_payment_pending = 0;
      // Retain stored payment pending details in query so staff sets are safely preserved!
    }
    if (callbackSchedule && callbackSchedule.date) {
      query.callback_date = callbackSchedule.date;
      query.callback_time = callbackSchedule.time || '11:00 AM';
      query.callbackDate = callbackSchedule.date;
      query.callbackTime = callbackSchedule.time || '11:00 AM';
    }
    query.statusHistory = query.statusHistory || [];
    const isReschedAction = (oldStatus === 'FOLLOW_UP' && newStatus === 'FOLLOW_UP');
    const existingPendingFu = (CRM_STATE.followups || []).find(f => f && (f.customerId === customer?.id || (query && f.queryId === query.id)) && f.status === 'PENDING');
    query.statusHistory.unshift({
      action: isReschedAction ? 'FOLLOWUP_RESCHEDULED' : (newStatus === 'FOLLOW_UP' ? 'FOLLOWUP_SCHEDULED' : 'STATUS_CHANGED'),
      from: oldStatus,
      to: newStatus,
      by: staffName,
      at: timeFormatted,
      followupDate: (callbackSchedule && callbackSchedule.date) ? callbackSchedule.date : (existingPendingFu ? existingPendingFu.date : (paymentData?.paymentDueDate || '')),
      followupTime: (callbackSchedule && callbackSchedule.time) ? callbackSchedule.time : (existingPendingFu ? existingPendingFu.time : ''),
      assignedTo: existingPendingFu ? existingPendingFu.assignedTo : query.assignedTo,
      notes: notes || query.statusNotes || '',
      isPaymentPending: Boolean(paymentData && paymentData.isPaymentPending),
      paymentAmount: paymentData && paymentData.isPaymentPending ? parseFloat(paymentData.paymentAmount || 0) : (query.isPaymentPending ? query.paymentAmount : 0),
      shippingAmount: paymentData && paymentData.isPaymentPending ? parseFloat(paymentData.shippingAmount || 0) : (query.isPaymentPending ? query.shippingAmount : 0),
      paymentMode: paymentData && paymentData.isPaymentPending ? (paymentData.paymentMode || 'UPI') : (query.isPaymentPending ? query.paymentMode : ''),
      advancePayment: paymentData && paymentData.isPaymentPending ? parseFloat(paymentData.advancePayment || 0) : (query.isPaymentPending ? query.advancePayment : 0),
      paymentDueDate: paymentData && paymentData.isPaymentPending ? (paymentData.paymentDueDate || '') : (query.isPaymentPending ? query.paymentDueDate : ''),
      quotedItems: paymentData && paymentData.isPaymentPending ? (paymentData.quotedItems || '') : (query.isPaymentPending ? query.quotedItems : ''),
      paymentNotes: paymentData && paymentData.isPaymentPending ? (paymentData.paymentNotes || '') : (query.isPaymentPending ? query.paymentNotes : ''),
      timestamp: now.toISOString()
    });

    // Asynchronously update MySQL database
    fetch('api.php?action=assign_query', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        id: query.id,
        assigned_to: query.assignedTo || 'UNASSIGNED',
        status: newStatus,
        notes: notes || query.statusNotes || '',
        user: staffName,
        customer_id: customer ? customer.id : null,
        customer_name: customer ? customer.name : null,
        phone: customer ? customer.phone : null,
        whatsapp: customer ? customer.whatsapp : null,
        reason: notes || (customer ? customer.dndReason : 'Customer not interested in products (Requested DND)'),
        dnd_timestamp: timeFormatted,
        isPaymentPending: query.isPaymentPending,
        paymentAmount: query.paymentAmount,
        shippingAmount: query.shippingAmount,
        paymentMode: query.paymentMode,
        advancePayment: query.advancePayment,
        paymentDueDate: query.paymentDueDate,
        paymentNotes: query.paymentNotes,
        quotedItems: query.quotedItems,
        callbackDate: (callbackSchedule && callbackSchedule.date) || query.callback_date || query.callbackDate || '',
        callbackTime: (callbackSchedule && callbackSchedule.time) || query.callback_time || query.callbackTime || '11:00 AM',
        statusHistory: query.statusHistory
      })
    }).catch(() => { });
  }

  if (customer) {
    if (newStatus === 'DND') {
      customer.isDND = true;
      customer.dndReason = notes || 'Customer not interested in products (Requested DND)';
      customer.dndNotes = notes || '';
      customer.dndTimestamp = timeFormatted;
      customer.dndMarkedBy = staffName;
      if (!Array.isArray(customer.tags)) customer.tags = [];
      if (!customer.tags.includes('DND / Opt-Out')) customer.tags.push('DND / Opt-Out');

      // Sync dedicated in-memory dndRecords collection
      if (!CRM_STATE.dndRecords) CRM_STATE.dndRecords = [];
      const existingDnd = CRM_STATE.dndRecords.find(d => d.customer_id === customer.id && d.status === 'ACTIVE');
      if (existingDnd) {
        existingDnd.notes = notes || '';
        existingDnd.reason = notes || 'Customer not interested in products (Requested DND)';
        existingDnd.marked_by = staffName;
        existingDnd.dnd_timestamp = timeFormatted;
        existingDnd.assigned_to = query ? (query.assignedTo || 'UNASSIGNED') : 'UNASSIGNED';
      } else {
        CRM_STATE.dndRecords.unshift({
          customer_id: customer.id,
          customer_name: customer.name,
          phone: customer.phone,
          whatsapp: customer.whatsapp,
          query_id: query ? query.id : null,
          reason: notes || 'Customer not interested in products (Requested DND)',
          notes: notes || '',
          marked_by: staffName,
          assigned_to: query ? (query.assignedTo || 'UNASSIGNED') : 'UNASSIGNED',
          status: 'ACTIVE',
          dnd_timestamp: timeFormatted
        });
      }

      // Guarantee MySQL dnd_records table persistence
      fetch('api.php?action=save_dnd_record', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          customer_id: customer.id,
          customer_name: customer.name,
          phone: customer.phone,
          whatsapp: customer.whatsapp,
          query_id: query ? query.id : null,
          reason: customer.dndReason,
          notes: customer.dndNotes,
          marked_by: staffName,
          assigned_to: query ? (query.assignedTo || 'UNASSIGNED') : 'UNASSIGNED',
          status: 'ACTIVE',
          dnd_timestamp: timeFormatted
        })
      }).catch(() => { });

      // Dynamically remove from active inbox view by switching active selection if current customer was marked DND
      if (ACTIVE_CUSTOMER_ID === customer.id || String(ACTIVE_CUSTOMER_ID) === String(customer.id)) {
        const remainingNonDnd = (CRM_STATE.customers || []).filter(c => {
          if (!c || c.id === customer.id) return false;
          if (c.name === 'System' || c.name === 'GRM Linked WhatsApp Device' || c.name.startsWith('WhatsApp Linked')) return false;
          const q = (CRM_STATE.queries || []).find(qry => qry.customerId === c.id);
          const isDnd = (c.isDND === true) || (q && q.status === 'DND') || (Array.isArray(c.tags) && c.tags.includes('DND / Opt-Out'));
          if (isDnd) return false;
          const conv = CRM_STATE.conversations[c.id] || [];
          return (conv.length > 0 || q);
        });
        ACTIVE_CUSTOMER_ID = remainingNonDnd.length > 0 ? remainingNonDnd[0].id : null;
        if (CRM_STATE) CRM_STATE.activeCustomerId = ACTIVE_CUSTOMER_ID;
      }
    } else {
      customer.isDND = false;
      if (Array.isArray(customer.tags)) {
        customer.tags = customer.tags.filter(t => t !== 'DND / Opt-Out');
      }
      if (CRM_STATE.dndRecords) {
        const dRec = CRM_STATE.dndRecords.find(d => d.customer_id === customer.id && d.status === 'ACTIVE');
        if (dRec) {
          dRec.status = 'REVOKED';
          dRec.revoked_at = new Date().toISOString();
          dRec.revoked_by = staffName;
        }
      }
    }
  }

  logAudit('STATUS_CHANGE', 'INBOX_PANEL', `Query ${query ? query.id : customer?.id} status changed from ${oldStatus} to ${newStatus} by ${staffName}${notes ? ' (Note: ' + notes + ')' : ''}`);

  // Automatically ensure active follow-up record in CRM_STATE.followups
  if (newStatus === 'FOLLOW_UP' || newStatus === 'PENDING' || (callbackSchedule && callbackSchedule.date)) {
    if (!Array.isArray(CRM_STATE.followups)) CRM_STATE.followups = [];
    let existingFu = CRM_STATE.followups.find(f => f && (f.customerId === customer?.id || (query && f.queryId === query.id)) && f.status === 'PENDING');
    const fuReason = notes || query?.queryText || (newStatus === 'PENDING' ? 'Payment Pending follow-up' : (newStatus === 'FOLLOW_UP' ? 'Customer callback requested' : 'Customer enquiry callback'));
    const isPayPending = (newStatus === 'PENDING') || Boolean(paymentData && paymentData.isPaymentPending);
    const payAmt = isPayPending
      ? (parseFloat(paymentData?.paymentAmount || 0) || query?.paymentAmount || existingFu?.paymentAmount || 0)
      : 0;
    const shippingAmt = isPayPending ? (parseFloat(paymentData?.shippingAmount || 0) || query?.shippingAmount || existingFu?.shippingAmount || 0) : 0;
    const advanceAmt = isPayPending ? (parseFloat(paymentData?.advancePayment || 0) || query?.advancePayment || existingFu?.advancePayment || 0) : 0;
    const payMode = paymentData?.paymentMode || query?.paymentMode || existingFu?.paymentMode || 'UPI';
    const payDue = paymentData?.paymentDueDate || callbackSchedule?.date || existingFu?.paymentDueDate || query?.paymentDueDate || '';
    const payNotes = paymentData?.paymentNotes || notes || existingFu?.paymentNotes || query?.paymentNotes || '';
    const payItems = paymentData?.quotedItems || existingFu?.quotedItems || query?.quotedItems || '';

    if (query) {
      query.isPaymentPending = isPayPending;
      query.paymentAmount = payAmt;
      query.shippingAmount = shippingAmt;
      query.advancePayment = advanceAmt;
      query.paymentMode = payMode;
      query.paymentDueDate = payDue;
      query.paymentNotes = payNotes;
      query.quotedItems = payItems;
    }

    if (!existingFu) {
      const todayStr = now.toISOString().split('T')[0];
      const newFu = {
        id: `FU-${now.getFullYear()}-${Math.floor(100000 + Math.random() * 900000)}`,
        queryId: query ? query.id : 'Q-2026-0000',
        customerId: customer ? customer.id : (query ? query.customerId : 'cust_101'),
        customerName: customer ? customer.name : 'Customer',
        assignedTo: (query && query.assignedTo && query.assignedTo !== 'UNASSIGNED') ? query.assignedTo : (currentUser?.staffId || currentUser?.id || 'staff_01'),
        date: (callbackSchedule && callbackSchedule.date) ? callbackSchedule.date : (payDue || todayStr),
        date_str: (callbackSchedule && callbackSchedule.date) ? callbackSchedule.date : (payDue || todayStr),
        time: (callbackSchedule && callbackSchedule.time) ? callbackSchedule.time : '11:00 AM',
        time_str: (callbackSchedule && callbackSchedule.time) ? callbackSchedule.time : '11:00 AM',
        reason: fuReason,
        status: 'PENDING',
        outcome: 'PENDING',
        priority: query?.priority || 'NORMAL',
        channel: 'WHATSAPP',
        createdAt: now.toISOString(),
        isPaymentPending: isPayPending,
        is_payment_pending: isPayPending ? 1 : 0,
        paymentAmount: payAmt,
        payment_amount: payAmt,
        shippingAmount: shippingAmt,
        shipping_amount: shippingAmt,
        advancePayment: advanceAmt,
        advance_payment: advanceAmt,
        paymentMode: payMode,
        payment_mode: payMode,
        paymentDueDate: payDue,
        payment_due_date: payDue,
        paymentNotes: payNotes,
        payment_notes: payNotes,
        quotedItems: payItems,
        quoted_items: payItems
      };
      CRM_STATE.followups.unshift(newFu);
      fetch('api.php?action=save_followup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newFu)
      }).catch(() => { });
    } else {
      if (notes) existingFu.reason = notes;
      if (query && query.assignedTo && query.assignedTo !== 'UNASSIGNED') {
        existingFu.assignedTo = query.assignedTo;
      } else if (currentUser && (currentUser.staffId || currentUser.id)) {
        existingFu.assignedTo = currentUser.staffId || currentUser.id;
      }
      if (callbackSchedule && callbackSchedule.date) {
        existingFu.date = callbackSchedule.date;
        existingFu.date_str = callbackSchedule.date;
        if (callbackSchedule.time) {
          existingFu.time = callbackSchedule.time;
          existingFu.time_str = callbackSchedule.time;
        }
      }
      existingFu.isPaymentPending = isPayPending;
      existingFu.is_payment_pending = isPayPending ? 1 : 0;
      existingFu.paymentAmount = payAmt;
      existingFu.payment_amount = payAmt;
      existingFu.shippingAmount = shippingAmt;
      existingFu.shipping_amount = shippingAmt;
      existingFu.advancePayment = advanceAmt;
      existingFu.advance_payment = advanceAmt;
      existingFu.paymentMode = payMode;
      existingFu.payment_mode = payMode;
      if (isPayPending) {
        existingFu.paymentDueDate = payDue || '';
        existingFu.payment_due_date = payDue || '';
        existingFu.paymentNotes = payNotes || '';
        existingFu.payment_notes = payNotes || '';
        existingFu.quotedItems = payItems || '';
        existingFu.quoted_items = payItems || '';
      } else {
        existingFu.paymentDueDate = '';
        existingFu.payment_due_date = '';
        existingFu.paymentNotes = '';
        existingFu.payment_notes = '';
        existingFu.quotedItems = '';
        existingFu.quoted_items = '';
      }
      fetch('api.php?action=save_followup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(existingFu)
      }).catch(() => { });
    }
  } else if (newStatus === 'CONVERTED' || newStatus === 'RESOLVED') {
    if (Array.isArray(CRM_STATE.followups)) {
      CRM_STATE.followups.forEach(f => {
        if (f && (f.customerId === customer?.id || (query && f.queryId === query.id)) && f.status === 'PENDING') {
          f.status = 'COMPLETED';
          f.outcome = newStatus === 'CONVERTED' ? 'ORDER_PLACED' : 'RESOLVED';
          if (notes) f.outcomeNotes = notes;
          f.completedAt = now.toISOString();
        }
      });
    }
  }

  saveCRMState();
  renderInbox();
  renderCustomer360Panel();
  if (typeof renderEnquiriesTable === 'function') renderEnquiriesTable();
  if (typeof renderFollowupsCards === 'function') renderFollowupsCards();
  if (typeof filterFollowupsCards === 'function') filterFollowupsCards();
  if (typeof filterPaymentPendingCards === 'function') filterPaymentPendingCards();
  if (typeof updateFollowupsKPICounters === 'function') updateFollowupsKPICounters();
  if (typeof updatePaymentPendingKPICounters === 'function') updatePaymentPendingKPICounters();
  if (typeof renderDndModule === 'function') renderDndModule();
  updateBadgeCounters();

  const label = newStatus === 'DND' ? '🚫 DND / Not Interested' : newStatus.replace('_', ' ');
  showToast(
    newStatus === 'DND' ? 'Customer Marked as DND' : 'Status & Notes Saved',
    notes ? `Status: "${label}" • Note: "${notes.length > 40 ? notes.slice(0, 37) + '...' : notes}"` : `Query status is now set to "${label}".`,
    newStatus === 'DND' ? 'do_not_disturb_on' : (newStatus === 'RESOLVED' || newStatus === 'CONVERTED' ? 'emerald' : (newStatus === 'PENDING' ? 'amber' : 'blue')),
    newStatus === 'DND' ? 'rose' : (newStatus === 'RESOLVED' || newStatus === 'CONVERTED' ? 'emerald' : (newStatus === 'PENDING' ? 'amber' : 'blue'))
  );
  if (typeof playChime === 'function') playChime('inbound');
}

function reactivateCustomerFromDND(customerId) {
  // RBAC Guard: requires dnd.delete permission
  const _raIsSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER &&
    (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!_raIsSuperAdmin && typeof canUserPerformAction === 'function') {
    if (!canUserPerformAction('dnd', 'delete')) {
      if (typeof showToast === 'function') showToast('🔒 Access Denied: You do not have permission to re-activate DND customers.', 'warning');
      return;
    }
  }
  const customer = CRM_STATE.customers.find(c => c.id === customerId);
  if (!customer) return;

  customer.isDND = false;
  if (Array.isArray(customer.tags)) {
    customer.tags = customer.tags.filter(t => t !== 'DND / Opt-Out');
  }

  const query = CRM_STATE.queries.find(q => q.customerId === customerId);
  if (query && query.status === 'DND') {
    query.status = 'IN_PROGRESS';
  }

  if (CRM_STATE.dndRecords) {
    const dRec = CRM_STATE.dndRecords.find(d => (d.customer_id === customer.id || d.customerId === customer.id) && d.status === 'ACTIVE');
    if (dRec) {
      dRec.status = 'REVOKED';
      dRec.revoked_at = new Date().toISOString();
      dRec.revoked_by = CURRENT_USER?.name || 'Admin';
    }
  }

  // Persist reactivation to MySQL backend
  fetch('api.php?action=revoke_dnd', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      customer_id: customer.id,
      query_id: query ? query.id : null,
      user: CURRENT_USER?.name || 'Admin'
    })
  }).catch(() => { });

  logAudit('DND_REACTIVATED', 'DND_MODULE', `Reactivated customer ${customer.name} (${customer.phone}) from DND list.`);
  saveCRMState();
  renderDndModule();
  renderInbox();
  renderCustomer360Panel();
  updateBadgeCounters();

  showToast('Customer Reactivated', `${customer.name} has been restored to active communication.`, 'check_circle', 'emerald');
  if (typeof playChime === 'function') playChime('order');
}

function openStaffAssignForDndCustomer(customerId) {
  // RBAC Guard: requires dnd.edit permission
  const _daIsSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER &&
    (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!_daIsSuperAdmin && typeof canUserPerformAction === 'function') {
    if (!canUserPerformAction('dnd', 'edit')) {
      if (typeof showToast === 'function') showToast('🔒 Access Denied: You do not have permission to assign staff to DND customers.', 'warning');
      return;
    }
  }
  let query = (CRM_STATE?.queries || []).find(q => q.customerId === customerId);
  const customer = (CRM_STATE?.customers || []).find(c => c.id === customerId);
  if (!customer) return;

  if (!query) {
    query = {
      id: 'Q-' + (customer.code || customer.id || Date.now()),
      customerId: customer.id,
      assignedTo: 'UNASSIGNED',
      status: 'DND',
      priority: 'NORMAL',
      queryText: customer.dndReason || customer.dndNotes || 'DND Customer Enquiry',
      statusNotes: customer.dndNotes || customer.dndReason || '',
      unreadCount: 0,
      createdAt: new Date().toISOString()
    };
    if (!Array.isArray(CRM_STATE.queries)) CRM_STATE.queries = [];
    CRM_STATE.queries.unshift(query);
    saveCRMState();
  }

  openStaffAssignModal(query.id);
}
window.openStaffAssignForDndCustomer = openStaffAssignForDndCustomer;

function viewDndCustomerChat(customerId) {
  ACTIVE_CUSTOMER_ID = customerId;
  if (CRM_STATE) CRM_STATE.activeCustomerId = customerId;
  switchView('inbox');
  renderInbox();
  showToast('Viewing DND Chat', 'Customer is on DND. This chat is removed from the active WhatsApp Inbox queue.', 'block', 'rose');
}
window.viewDndCustomerChat = viewDndCustomerChat;

function renderDndModule() {
  // ── RBAC: Check view permission ───────────────────────────────────────────
  const _dndIsSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER &&
    (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  const canDndView = _dndIsSuperAdmin || (typeof canUserPerformAction === 'function' ? canUserPerformAction('dnd', 'view') : true);
  const canDndCreate = _dndIsSuperAdmin || (typeof canUserPerformAction === 'function' ? canUserPerformAction('dnd', 'create') : true);
  const canDndEdit = _dndIsSuperAdmin || (typeof canUserPerformAction === 'function' ? canUserPerformAction('dnd', 'edit') : true);
  const canDndDelete = _dndIsSuperAdmin || (typeof canUserPerformAction === 'function' ? canUserPerformAction('dnd', 'delete') : true);

  // Gate: no view access → render locked panel and exit
  if (!canDndView) {
    const dndContainer = document.getElementById('dnd-module-container') || document.getElementById('dnd-table-body');
    if (dndContainer) {
      dndContainer.innerHTML = `
        <tr><td colspan="7" class="p-10 text-center">
          <div class="inline-flex flex-col items-center gap-3 bg-slate-50 border border-slate-200 rounded-2xl px-10 py-8 shadow-xs max-w-md mx-auto">
            <span class="material-symbols-outlined text-[48px] text-slate-400">lock</span>
            <p class="text-sm font-bold text-slate-700">Access Restricted</p>
            <p class="text-xs text-slate-500 text-center">You do not have permission to view the DND &amp; Opt-Out Customer Hub.<br>Contact your admin to request access.</p>
          </div>
        </td></tr>
      `;
    }
    return;
  }

  const tableBody = document.getElementById('dnd-table-body');
  const countSummary = document.getElementById('dnd-count-summary');
  const kpiTotal = document.getElementById('kpi-dnd-total');
  const badgeDnd = document.getElementById('badge-dnd-count');
  const searchInput = document.getElementById('dnd-search-input');
  const searchVal = (searchInput ? searchInput.value : '').toLowerCase().trim();

  const dndCustomers = (CRM_STATE?.customers || []).filter(c => {
    if (!c) return false;
    const q = (CRM_STATE?.queries || []).find(qry => qry.customerId === c.id);
    const dndRec = (CRM_STATE?.dndRecords || CRM_STATE?.dnd_records || []).find(d => (d.customer_id === c.id || d.customerId === c.id) && d.status === 'ACTIVE');
    return (dndRec !== undefined) || c.isDND === true || (q && q.status === 'DND') || (Array.isArray(c.tags) && c.tags.includes('DND / Opt-Out'));
  });

  const totalDnd = dndCustomers.length;
  if (countSummary) countSummary.innerText = `${totalDnd} DND Customer${totalDnd === 1 ? '' : 's'}`;
  if (kpiTotal) kpiTotal.innerText = totalDnd;
  if (badgeDnd) badgeDnd.innerText = totalDnd;

  let filtered = dndCustomers;
  if (searchVal) {
    filtered = filtered.filter(c => {
      const q = (CRM_STATE?.queries || []).find(qry => qry.customerId === c.id);
      const dndRec = (CRM_STATE?.dndRecords || CRM_STATE?.dnd_records || []).find(d => (d.customer_id === c.id || d.customerId === c.id) && d.status === 'ACTIVE');
      return (c.name && c.name.toLowerCase().includes(searchVal)) ||
        (c.phone && c.phone.includes(searchVal)) ||
        (c.whatsapp && c.whatsapp.includes(searchVal)) ||
        (dndRec && dndRec.reason && dndRec.reason.toLowerCase().includes(searchVal)) ||
        (dndRec && dndRec.notes && dndRec.notes.toLowerCase().includes(searchVal)) ||
        (c.dndReason && c.dndReason.toLowerCase().includes(searchVal)) ||
        (c.dndNotes && c.dndNotes.toLowerCase().includes(searchVal)) ||
        (q && q.statusNotes && q.statusNotes.toLowerCase().includes(searchVal));
    });
  }

  if (!tableBody) return;

  if (filtered.length === 0) {
    tableBody.innerHTML = `
      <tr>
        <td colspan="7" class="p-8 text-center text-slate-400">
          <span class="material-symbols-outlined text-[36px] text-slate-300">verified_user</span>
          <p class="text-xs font-semibold mt-1">No DND customers found</p>
          <p class="text-[11px] text-slate-400">When staff changes a customer's enquiry status to "🚫 DND", their chat is dynamically removed from the WhatsApp inbox and listed here.</p>
        </td>
      </tr>
    `;
    return;
  }

  tableBody.innerHTML = filtered.map(c => {
    const q = (CRM_STATE?.queries || []).find(qry => qry.customerId === c.id);
    const dndRec = (CRM_STATE?.dndRecords || CRM_STATE?.dnd_records || []).find(d => (d.customer_id === c.id || d.customerId === c.id) && d.status === 'ACTIVE');
    const conv = CRM_STATE?.conversations?.[c.id] || [];
    const lastMsg = conv.length > 0 ? conv[conv.length - 1].text : (q ? q.lastMessage : 'No recent messages');
    const dndTime = (dndRec && dndRec.dnd_timestamp) || c.dndTimestamp || (q ? q.statusLastEditedAt || q.createdAt : 'Recent');
    const markedBy = (dndRec && dndRec.marked_by) || c.dndMarkedBy || (q ? q.statusLastEditedBy : 'Super Admin') || 'Super Admin';

    // Notes fetched from dedicated dnd_records table or WhatsApp Inbox why the user was set to DND
    const inboxNotes = (dndRec && dndRec.notes) || c.dndNotes || (q ? q.statusNotes : '') || (q?.statusHistory?.find(h => h.to === 'DND')?.notes) || (c.dndReason && !c.dndReason.includes('(Requested DND)') ? c.dndReason : '');
    const mainReason = (dndRec && dndRec.reason) || c.dndReason || (inboxNotes ? inboxNotes : 'Customer not interested in products (Requested DND)');
    const displayPhone = formatPhoneNumberPretty(c.whatsapp || c.phone);

    // Assigned Staff
    const staffId = (dndRec && dndRec.assigned_to && dndRec.assigned_to !== 'UNASSIGNED') ? dndRec.assigned_to : (q ? q.assignedTo : 'UNASSIGNED');
    const staff = (CRM_STATE?.staffList || []).find(s => s.id === staffId);
    const assignedStaffName = staff ? staff.name : (staffId === 'admin' || staffId === 'Super Admin' ? 'Super Admin' : (staffId && staffId !== 'UNASSIGNED' ? staffId : 'Unassigned'));
    const isUnassigned = (!staffId || staffId === 'UNASSIGNED');

    return `
      <tr class="hover:bg-slate-50 transition border-b border-slate-100">
        <!-- 1. Customer Details -->
        <td class="py-3.5 px-4 font-bold text-slate-900 flex items-center gap-3">
          <div class="w-9 h-9 rounded-xl bg-gradient-to-tr from-rose-700 to-slate-800 text-white font-bold text-xs flex items-center justify-center shrink-0 shadow-xs">
            ${c.avatar || 'CU'}
          </div>
          <div class="min-w-0">
            <p class="font-bold text-slate-900 text-xs truncate">${c.name || 'Customer'}</p>
            <p class="text-[10px] text-slate-400 font-mono">${c.code || c.id}</p>
          </div>
        </td>

        <!-- 2. Phone / WhatsApp -->
        <td class="py-3.5 px-4 font-mono font-bold text-emerald-950 text-xs whitespace-nowrap">
          ${displayPhone}
        </td>

        <!-- 3. Opt-Out Reason & WhatsApp Inbox Notes -->
        <td class="py-3.5 px-4 max-w-sm">
          <div class="space-y-1.5">
            <div>
              <span class="bg-rose-50 text-rose-800 border border-rose-200 text-[10px] font-extrabold px-2 py-0.5 rounded-full inline-flex items-center gap-1 shadow-2xs">
                <span class="material-symbols-outlined text-[12px] text-rose-600">block</span>
                <span>${mainReason}</span>
              </span>
            </div>
            ${inboxNotes ? `
              <div class="p-2 bg-amber-50/90 border border-amber-200/90 rounded-xl text-xs text-amber-950 shadow-2xs">
                <div class="text-[9px] font-extrabold text-amber-800 uppercase tracking-wide flex items-center gap-1 mb-0.5">
                  <span class="material-symbols-outlined text-[13px] text-amber-600">note_alt</span>
                  <span>WhatsApp Inbox Notes:</span>
                </div>
                <p class="font-semibold text-slate-800 italic leading-snug">"${inboxNotes}"</p>
              </div>
            ` : ''}
            <p class="text-[10px] text-slate-400 truncate max-w-xs mt-0.5" title="${lastMsg}">
              <span class="text-slate-500 font-semibold">Last Message:</span> "${lastMsg.length > 35 ? lastMsg.substring(0, 32) + '...' : lastMsg}"
            </p>
          </div>
        </td>

        <!-- 4. Assigned Staff -->
        <td class="py-3.5 px-4 whitespace-nowrap">
          ${isUnassigned ? `
            <span class="bg-amber-50 text-amber-900 border border-amber-200 px-2.5 py-1 rounded-xl text-xs font-bold inline-flex items-center gap-1.5 shadow-2xs">
              <span class="material-symbols-outlined text-[14px] text-amber-600">person_off</span>
              <span>Unassigned</span>
            </span>
          ` : `
            <span class="bg-indigo-50 text-indigo-900 border border-indigo-200 px-2.5 py-1 rounded-xl text-xs font-bold inline-flex items-center gap-1.5 shadow-2xs">
              <span class="material-symbols-outlined text-[14px] text-indigo-600">badge</span>
              <span>${assignedStaffName}</span>
            </span>
          `}
        </td>

        <!-- 5. Marked By Staff -->
        <td class="py-3.5 px-4 text-xs font-semibold text-slate-700 whitespace-nowrap">
          <span class="bg-slate-100 text-slate-700 px-2.5 py-1 rounded-lg border border-slate-200 text-xs">${markedBy}</span>
        </td>

        <!-- 6. Date / Time -->
        <td class="py-3.5 px-4 text-xs text-slate-500 font-medium whitespace-nowrap">
          ${dndTime}
        </td>

        <!-- 7. Actions: Assign (edit), Re-activate (delete), View Chat (view) -->
        <td class="py-3.5 px-4 text-right whitespace-nowrap">
          <div class="flex items-center justify-end gap-1.5 flex-wrap">
            ${canDndEdit ? `
            <button onclick="openStaffAssignForDndCustomer('${c.id}')" class="px-2.5 py-1.5 bg-amber-500 hover:bg-amber-600 text-white rounded-lg text-xs font-bold transition flex items-center gap-1 shadow-xs cursor-pointer active:scale-95" title="Assign this customer to staff member to communicate">
              <span class="material-symbols-outlined text-[14px]">how_to_reg</span>
              <span>Assign</span>
            </button>
            ` : ''}
            ${canDndDelete ? `
            <button onclick="reactivateCustomerFromDND('${c.id}')" class="px-2.5 py-1.5 bg-emerald-50 hover:bg-emerald-100 text-emerald-800 border border-emerald-300 rounded-lg text-xs font-bold transition flex items-center gap-1 shadow-xs cursor-pointer active:scale-95" title="Reactivate customer to allow messages and orders in WhatsApp Inbox">
              <span class="material-symbols-outlined text-[14px]">check_circle</span>
              <span>Re-activate</span>
            </button>
            ` : ''}
            <button onclick="viewDndCustomerChat('${c.id}')" class="px-2 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 border border-slate-300 rounded-lg text-xs font-bold transition flex items-center gap-1 cursor-pointer" title="View conversation history">
              <span class="material-symbols-outlined text-[14px]">chat</span>
            </button>
            ${(!canDndEdit && !canDndDelete) ? '<span class="text-[9px] text-slate-400 font-semibold flex items-center gap-0.5"><span class=\"material-symbols-outlined text-[11px]\">lock</span>View Only</span>' : ''}
          </div>
        </td>
      </tr>
    `;
  }).join('');
}

// Update all sidebar & header badge counters dynamically across all modules
function updateBadgeCounters() {
  if (!CRM_STATE) return;
  

  // 1. Unread count in inbox (Strictly 1 count per person who sent messages!)
  const unreadEl = document.getElementById('badge-total-unread');
  const subtabUnread = document.getElementById('subtab-unread-badge');
  const unreadCustSet = new Set();
  (CRM_STATE.queries || []).forEach(q => {
    if (q.status !== 'DND' && (q.unreadCount || 0) > 0) {
      const clean = String(q.customerPhone || q.customer_phone || q.customerId || q.customer_id || '').replace(/\D/g, '');
      const p10 = clean.length >= 7 ? clean.slice(-10) : (q.customerId || q.id);
      if (p10) unreadCustSet.add(p10);
    }
  });
  (CRM_STATE.customers || []).forEach(c => {
    if (!c.isDND && (c.unreadCount || 0) > 0) {
      const clean = String(c.phone || c.whatsapp || c.id || '').replace(/\D/g, '');
      const p10 = clean.length >= 7 ? clean.slice(-10) : c.id;
      if (p10) unreadCustSet.add(p10);
    }
  });
  const unreadCount = unreadCustSet.size;
  if (unreadEl) {
    unreadEl.innerText = unreadCount > 0 ? unreadCount : '0';
  }
  if (subtabUnread) {
    subtabUnread.innerText = unreadCount > 0 ? unreadCount : '0';
  }
  const headerLiveCount = document.getElementById('header-live-queue-count');
  if (headerLiveCount) {
    headerLiveCount.innerText = unreadCount > 0 ? unreadCount : '0';
  }

  // 2. Unassigned Enquiries
  const unassignedEl = document.getElementById('badge-unassigned-count');
  const bulkUnassignedBadge = document.getElementById('badge-bulk-unassigned');
  if (unassignedEl || bulkUnassignedBadge) {
    const unassignedCount = (CRM_STATE.queries || []).filter(q => (q.assignedTo === 'UNASSIGNED' || !q.assignedTo) && q.status !== 'DND' && q.status !== 'RESOLVED' && q.status !== 'CLOSED').length;
    if (unassignedEl) unassignedEl.innerText = `${unassignedCount} New`;
    if (bulkUnassignedBadge) bulkUnassignedBadge.innerText = `${unassignedCount}`;
  }

  // 3. Followup count
  const followupEl = document.getElementById('badge-followup-count');
  if (followupEl) {
    const dueCount = (CRM_STATE.followups || []).filter(f => f.status === 'PENDING').length;
    followupEl.innerText = `${dueCount} Due`;
  }

  // 4. Orders count
  const ordersEl = document.getElementById('badge-orders-count');
  if (ordersEl) {
    const ordCount = (CRM_STATE.orders || []).length;
    ordersEl.innerText = ordCount;
  }

  // 5. DND count
  const dndEl = document.getElementById('badge-dnd-count');
  const kpiDndEl = document.getElementById('kpi-dnd-total');
  const dndSummaryEl = document.getElementById('dnd-count-summary');
  const dndCustomers = (CRM_STATE.customers || []).filter(c => {
    if (!c) return false;
    const q = (CRM_STATE.queries || []).find(qry => qry.customerId === c.id);
    return c.isDND === true || (q && q.status === 'DND') || (Array.isArray(c.tags) && c.tags.includes('DND / Opt-Out'));
  });
  const dndCount = dndCustomers.length;
  if (dndEl) dndEl.innerText = dndCount;
  if (kpiDndEl) kpiDndEl.innerText = dndCount;
  if (dndSummaryEl) dndSummaryEl.innerText = `${dndCount} DND Customer${dndCount === 1 ? '' : 's'}`;

  // 6. Total Staff count
  const staffEl = document.getElementById('badge-total-staff-count');
  if (staffEl) {
    staffEl.innerText = (CRM_STATE.staffList || []).length;
  }

  // 7. Dynamic Inbox Counter Pills: All, New Leads, Follow-up
  const countAllEl = document.getElementById('count-all');
  const countNewLeadsEl = document.getElementById('count-new-leads');
  const countFollowupEl = document.getElementById('count-followup');

  if (countAllEl || countNewLeadsEl || countFollowupEl) {
    const activeQ = (CRM_STATE.queries || []).filter(q => q.status !== 'DND');
    const fuCustIds = new Set((CRM_STATE.followups || [])
      .filter(f => f && (f.status === 'PENDING' || f.status === 'FOLLOW_UP' || !f.status || f.status === 'OPEN'))
      .map(f => String(f.customerId || '')));

    const isFu = q => {
      const s = String(q.status || '').toUpperCase();
      return s === 'FOLLOW_UP' || s === 'PENDING' || fuCustIds.has(String(q.customerId));
    };

    const isNl = q => {
      const s = String(q.status || '').toUpperCase();
      if (isFu(q)) return false;
      if (s === 'NEW' || s === 'OPEN' || s === 'ASSIGNED') return true;
      const isUn = !q.assignedTo || q.assignedTo === 'UNASSIGNED' || q.assignedTo === 'unassigned';
      if (isUn && s !== 'RESOLVED' && s !== 'CLOSED' && s !== 'CONVERTED') return true;
      return false;
    };

    if (countAllEl && activeQ.length > 0) countAllEl.innerText = activeQ.length;
    if (countNewLeadsEl && activeQ.length > 0) countNewLeadsEl.innerText = activeQ.filter(isNl).length;
    if (countFollowupEl && activeQ.length > 0) countFollowupEl.innerText = activeQ.filter(isFu).length;
  }
}

// Quick Reassign Handling Staff
function quickReassignQueryStaff(queryId, newStaffId) {
  const isSuperAdminAssign = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!isSuperAdminAssign && typeof canUserPerformAction === 'function' && !canUserPerformAction('inbox', 'edit') && !canUserPerformAction('enquiries', 'edit')) {
    if (typeof showToast === 'function') showToast('Permission Denied', 'Reassigning staff requires Edit permission.', 'lock', 'rose');
    return;
  }
  let query = (CRM_STATE.queries || []).find(q => q && (
    q.id === queryId || q.customerId === queryId || q.customer_id === queryId ||
    ('Q-' + q.customerId) === queryId || ('Q-' + q.customer_id) === queryId
  ));
  let customer = query
    ? (CRM_STATE.customers || []).find(c => c && (c.id === query.customerId || c.id === query.customer_id))
    : (CRM_STATE.customers || []).find(c => c && (c.id === queryId || ('Q-' + c.id) === queryId));

  if (!query && customer) {
    query = {
      id: queryId.startsWith('Q-') ? queryId : ('Q-' + customer.id),
      customerId: customer.id,
      assignedTo: newStaffId,
      status: newStaffId === 'UNASSIGNED' ? 'NEW' : 'IN_PROGRESS',
      priority: 'NORMAL',
      queryText: customer.lastMessage || 'Customer Enquiry',
      createdAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    CRM_STATE.queries.unshift(query);
  }
  if (!query) return;

  const staff = CRM_STATE.staffList.find(s => s.id === newStaffId || s.name === newStaffId);
  query.assignedTo = newStaffId;
  if (customer) {
    customer.assignedTo = newStaffId;
  }
  if (query.status === 'NEW' && newStaffId !== 'UNASSIGNED') {
    query.status = 'IN_PROGRESS';
  }

  logAudit('STAFF_ASSIGNMENT', 'INBOX_PANEL', `Query ${query.id} assigned to ${staff ? staff.name : 'Unassigned'}`);

  const qCust = customer || CRM_STATE.customers.find(c => c.id === query.customerId || c.id === query.customer_id);
  // Asynchronously sync query assignment to MySQL Database
  fetch('api.php?action=assign_query', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      id: query.id,
      customer_id: query.customerId,
      phone: qCust ? (qCust.whatsapp || qCust.phone) : '',
      assigned_to: newStaffId,
      status: query.status,
      user: CURRENT_USER?.name || 'Admin'
    })
  }).catch(() => { });

  saveCRMState();
  renderInbox();
  renderCustomer360Panel();
  if (typeof renderEnquiriesTable === 'function') renderEnquiriesTable();

  showToast(
    'Staff Assigned',
    `Handling staff for query ${query.id} set to ${staff ? staff.name : 'Unassigned'}.`,
    'how_to_reg',
    'emerald'
  );
  if (typeof playChime === 'function') playChime('inbound');
}
window.quickReassignQueryStaff = quickReassignQueryStaff;

// Track which customer profile is currently in Edit Mode (locked by default once saved)
const CUSTOMER_EDIT_MODES = new Set();

function toggleCustomerEditMode(customerId, enableEdit = true) {
  const isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (enableEdit && !isSuperAdmin && typeof canUserPerformAction === 'function' && !canUserPerformAction('customers', 'edit')) {
    if (typeof showToast === 'function') showToast('Permission Denied', 'Your assigned role has View Access Only for customer profiles.', 'lock', 'rose');
    return;
  }
  if (enableEdit) {
    CUSTOMER_EDIT_MODES.add(customerId);
  } else {
    CUSTOMER_EDIT_MODES.delete(customerId);
  }
  renderCustomer360Panel();
}

var QUERY_EDIT_MODES = new Set();

function toggleQueryEditMode(queryId, enable) {
  if (enable) {
    QUERY_EDIT_MODES.add(queryId);
  } else {
    QUERY_EDIT_MODES.delete(queryId);
  }
  renderCustomer360Panel();
}
window.toggleQueryEditMode = toggleQueryEditMode;

function getStatusPrettyLabel(st) {
  const t = window.t || ((k, f) => f || k);
  const map = {
    'NEW': `🟢 ${t('status.new', 'New Lead')}`,
    'PENDING': `🟡 ${t('status.pending', 'Payment Pending')}`,
    'FOLLOW_UP': `🔵 ${t('status.follow_up', 'Follow-up Scheduled')}`,
    'IN_PROGRESS': `🟣 ${t('status.in_progress', 'In Progress')}`,
    'ASSIGNED': `🟣 ${t('status.assigned', 'Assigned')}`,
    'RESOLVED': `✅ ${t('status.resolved', 'Resolved / Closed')}`,
    'CONVERTED': `🏆 ${t('status.converted', 'Converted to Sale')}`,
    'DND': `🚫 ${t('status.dnd', 'DND / Not Interested')}`,
    'LOST': `❌ ${t('status.lost', 'Lead Lost')}`,
    'FOLLOWUP_RESCHEDULED': '🗓️ Follow-up Rescheduled'
  };
  return map[st] || st || t('status.new', 'New');
}
window.getStatusPrettyLabel = getStatusPrettyLabel;

function handleQueryStatusSelectChange(selectedStatus, queryId, customerId) {
  const container = document.getElementById('enquiry-dynamic-followup-container');
  const payContainer = document.getElementById('enquiry-payment-pending-wrapper');
  const cbEditRow = document.getElementById('query-callback-edit-row');
  const payToggle = document.getElementById('query-pay-pending-toggle');

  if (selectedStatus === 'FOLLOW_UP') {
    if (container) container.classList.remove('hidden');
    if (payContainer) payContainer.classList.remove('hidden');
    if (cbEditRow) cbEditRow.classList.remove('hidden');
  } else if (selectedStatus === 'PENDING') {
    if (container) container.classList.remove('hidden');
    if (payContainer) payContainer.classList.remove('hidden');
    if (cbEditRow) cbEditRow.classList.remove('hidden');
    // Keep Payment Pending checkbox unchecked by default on status change, preserving stored details
    if (payToggle) {
      payToggle.checked = false;
      handlePayPendingToggle(false);
    }
  } else if (selectedStatus === 'NEW' || selectedStatus === 'IN_PROGRESS') {
    if (container) container.classList.add('hidden');
    if (payContainer) payContainer.classList.remove('hidden');
    if (cbEditRow) cbEditRow.classList.remove('hidden');
  } else {
    if (container) container.classList.add('hidden');
    if (payContainer) payContainer.classList.add('hidden');
    if (cbEditRow) cbEditRow.classList.remove('hidden');
  }
}
function handlePayPendingToggle(checked) {
  const fields = document.getElementById('query-pay-fields');
  const badge = document.getElementById('query-pay-pending-badge');
  if (fields) {
    if (checked) {
      fields.classList.remove('hidden');
    } else {
      fields.classList.add('hidden');
      // PRESERVE VALUES: Do not wipe input fields so stored staff/admin settings remain safe!
    }
  }
  if (badge) {
    if (checked) {
      badge.innerHTML = `<span class="material-symbols-outlined text-[10px] text-amber-700">check_circle</span><span>ACTIVE</span>`;
      badge.className = 'text-[8.5px] font-extrabold px-1.5 py-0.2 rounded-full bg-amber-100 text-amber-900 border border-amber-300 flex items-center gap-0.5';
    } else {
      badge.innerHTML = 'Optional';
      badge.className = 'text-[8.5px] text-slate-400 font-medium';
    }
  }
}
window.handlePayPendingToggle = handlePayPendingToggle;

function handlePayModeChange(val) {
  const advWrapper = document.getElementById('query-pay-advance-wrapper');
  if (advWrapper) {
    if (val === 'COD_ADVANCE') {
      advWrapper.classList.remove('hidden');
      handleDynamicPaymentCalc();
    } else {
      advWrapper.classList.add('hidden');
    }
  }
}
window.handlePayModeChange = handlePayModeChange;

function handleDynamicPaymentCalc() {
  const total = parseFloat(document.getElementById('query-pay-amount-input')?.value || 0) || 0;
  const shipping = parseFloat(document.getElementById('query-pay-shipping-input')?.value || 0) || 0;
  const advance = parseFloat(document.getElementById('query-pay-advance-input')?.value || 0) || 0;
  const grandTotal = total + shipping;
  const balance = Math.max(0, grandTotal - advance);

  const grandEl = document.getElementById('query-pay-grand-total-val') || document.getElementById('query-pay-grand-total');
  if (grandEl) {
    grandEl.innerText = `₹${grandTotal.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  }

  const balEl = document.getElementById('query-pay-balance-val') || document.getElementById('query-pay-balance-text');
  if (balEl) {
    balEl.innerText = `₹${balance.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  }
}
window.handleDynamicPaymentCalc = handleDynamicPaymentCalc;

function handleSaveQueryStatus(queryId) {
  // RBAC Guard: Only users with inbox.edit or enquiries.edit permission can save
  const _isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER &&
    (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!_isSuperAdmin && typeof canUserPerformAction === 'function') {
    const canEdit = canUserPerformAction('inbox', 'edit') || canUserPerformAction('enquiries', 'edit');
    if (!canEdit) {
      if (typeof showToast === 'function') showToast('🔒 View-Only Access: You cannot change enquiry status.', 'warning');
      return;
    }
  }
  const select = document.getElementById('query-status-select');
  if (!select) return;
  const newStatus = select.value;
  const notes = document.getElementById('query-status-notes-input')?.value.trim() || '';

  // Extract Callback Date if present
  const cbDate = document.getElementById('query-callback-date')?.value || new Date().toISOString().split('T')[0];
  const cbTime = '11:00 AM';
  const callbackSchedule = { date: cbDate, time: cbTime };

  // Locate existing query & customer for smart fallbacks
  let query = (CRM_STATE.queries || []).find(q => q && (q.id === queryId || q.customerId === queryId));
  const customerId = query ? query.customerId : queryId;
  const custFu = (CRM_STATE.followups || []).find(f => f && (f.customerId === customerId || (query && f.queryId === query.id)));

  // Extract Payment Pending details from right panel
  const payToggle = document.getElementById('query-pay-pending-toggle');
  const isPayActive = (newStatus === 'PENDING') || Boolean(payToggle && payToggle.checked);

  let paymentData = null;
  if (isPayActive) {
    const totalAmtVal = document.getElementById('query-pay-amount-input')?.value;
    const shippingAmtVal = document.getElementById('query-pay-shipping-input')?.value;
    const advanceAmtVal = document.getElementById('query-pay-advance-input')?.value;

    const totalAmt = (totalAmtVal !== undefined && totalAmtVal !== '')
      ? (parseFloat(totalAmtVal) || 0)
      : (custFu?.paymentAmount || query?.paymentAmount || 0);

    const shippingAmt = (shippingAmtVal !== undefined && shippingAmtVal !== '')
      ? (parseFloat(shippingAmtVal) || 0)
      : (custFu?.shippingAmount || query?.shippingAmount || 0);

    const mode = document.getElementById('query-pay-mode-select')?.value || custFu?.paymentMode || query?.paymentMode || 'UPI';

    const advanceAmt = (advanceAmtVal !== undefined && advanceAmtVal !== '')
      ? (parseFloat(advanceAmtVal) || 0)
      : (custFu?.advancePayment || query?.advancePayment || 0);

    const payDueDate = document.getElementById('query-pay-due-input')?.value || cbDate || custFu?.paymentDueDate || query?.paymentDueDate || '';
    const payNotes = document.getElementById('query-pay-notes-input')?.value?.trim() || custFu?.paymentNotes || query?.paymentNotes || notes || '';
    const quotedItems = document.getElementById('query-pay-items-input')?.value?.trim() || custFu?.quotedItems || query?.quotedItems || '';

    paymentData = {
      isPaymentPending: true,
      paymentAmount: totalAmt,
      shippingAmount: shippingAmt,
      paymentMode: mode,
      advancePayment: (mode === 'COD_ADVANCE') ? advanceAmt : 0,
      paymentDueDate: payDueDate,
      paymentNotes: payNotes,
      quotedItems: quotedItems
    };
  } else {
    paymentData = {
      isPaymentPending: false
    };
  }

  updateCustomerQueryStatus(queryId, newStatus, notes, paymentData, callbackSchedule);
  QUERY_EDIT_MODES.delete(queryId);
  renderCustomer360Panel();

  // Auto-scroll on status change in WhatsApp inbox right panel
  setTimeout(() => {
    const scrollBox = document.getElementById('status-history-scroll-container');
    if (scrollBox) {
      scrollBox.scrollTop = 0;
    }
    const historyWrapper = document.getElementById('status-history-wrapper');
    if (historyWrapper) {
      historyWrapper.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, 60);
}

function handleCancelQueryEdit(queryId) {
  renderCustomer360Panel();
  showToast('Reset', 'Status and remarks reset to saved values', 'undo', 'slate');
}
window.handleCancelQueryEdit = handleCancelQueryEdit;

// Helper to extract clean 10-digit phone number (removing +91, device :0 index, or leading 0)
function extract10Digits(val) {
  if (!val) return '';
  let str = String(val).trim();
  if (str.includes('@')) str = str.split('@')[0];
  if (str.includes(':')) str = str.split(':')[0];
  let digits = str.replace(/[^0-9]/g, '');

  // Strip trailing device index 0 (e.g. 9181240385850 -> 918124038585, or 81240385850 -> 8124038585)
  if (digits.length === 13 && digits.startsWith('91') && digits.endsWith('0')) {
    digits = digits.slice(0, 12);
  } else if (digits.length === 11 && digits.endsWith('0') && !digits.startsWith('0')) {
    digits = digits.slice(0, 10);
  }

  if (digits.length === 12 && digits.startsWith('91')) {
    return digits.slice(2);
  }
  if (digits.length === 11 && digits.startsWith('0')) {
    return digits.slice(1);
  }
  if (digits.length > 10) {
    return digits.slice(-10);
  }
  return digits;
}
window.extract10Digits = extract10Digits;

// Save Customer Details from Right-Side Panel Form
function handleQuickCustomerSave(event, customerId) {
  if (event) event.preventDefault();
  const isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!isSuperAdmin && typeof canUserPerformAction === 'function' && !canUserPerformAction('customers', 'edit')) {
    if (typeof showToast === 'function') showToast('Permission Denied', 'Your assigned role has View Access Only for customer profiles.', 'lock', 'rose');
    return;
  }

  const customer = CRM_STATE.customers.find(c => c.id === customerId);
  if (!customer) return;

  const nameInput = document.getElementById('cust-edit-name');
  const phoneInput = document.getElementById('cust-edit-phone');
  const altPhoneInput = document.getElementById('cust-edit-alt-phone');
  const ageInput = document.getElementById('cust-edit-age');
  const genderInput = document.getElementById('cust-edit-gender');
  const emailInput = document.getElementById('cust-edit-email');
  const addressInput = document.getElementById('cust-edit-address');
  const altAddressInput = document.getElementById('cust-edit-alt-address');
  const notesInput = document.getElementById('cust-edit-notes');

  const newName = nameInput ? nameInput.value.trim() : customer.name;
  const rawPhone = phoneInput ? phoneInput.value.trim() : (customer.whatsapp || customer.phone || '');
  const rawAltPhone = altPhoneInput ? altPhoneInput.value.trim() : (customer.altPhone || customer.alt_phone || '');
  const newAge = ageInput ? ageInput.value.trim() : (customer.age || '');
  const newGender = genderInput ? genderInput.value : (customer.gender || '');
  const newEmail = emailInput ? emailInput.value.trim() : (customer.email || '');
  const newAddress = addressInput ? addressInput.value.trim() : (customer.address || '');
  const newAltAddress = altAddressInput ? altAddressInput.value.trim() : (customer.altAddress || customer.alt_address || '');
  const newNotes = notesInput ? notesInput.value.trim() : (customer.notes || '');

  // Reset any previous validation error styling
  if (phoneInput) phoneInput.classList.remove('border-rose-500', 'ring-2', 'ring-rose-300');
  if (altPhoneInput) altPhoneInput.classList.remove('border-rose-500', 'ring-2', 'ring-rose-300');

  // 1. WhatsApp Phone Validation (Must be numbers only and exactly 10 digits)
  const corePhone = extract10Digits(rawPhone);
  if (!corePhone || corePhone.length !== 10) {
    if (phoneInput) {
      phoneInput.focus();
      phoneInput.classList.add('border-rose-500', 'ring-2', 'ring-rose-300');
    }
    if (typeof showToast === 'function') {
      showToast('Validation Error', 'WhatsApp Phone must be exactly 10 digits (numbers only).', 'error', 'rose');
    } else {
      alert('WhatsApp Phone must be exactly 10 digits (numbers only).');
    }
    return;
  }

  // 2. Alternative Phone Validation (Optional, but if entered must be numbers only and exactly 10 digits)
  let coreAltPhone = '';
  if (rawAltPhone && rawAltPhone.trim() !== '') {
    coreAltPhone = extract10Digits(rawAltPhone);
    if (!coreAltPhone || coreAltPhone.length !== 10) {
      if (altPhoneInput) {
        altPhoneInput.focus();
        altPhoneInput.classList.add('border-rose-500', 'ring-2', 'ring-rose-300');
      }
      if (typeof showToast === 'function') {
        showToast('Validation Error', 'Alternative Number must be exactly 10 digits (numbers only).', 'error', 'rose');
      } else {
        alert('Alternative Number must be exactly 10 digits (numbers only).');
      }
      return;
    }
  }

  const newPhone = formatPhoneNumberPretty(corePhone);
  const newAltPhone = coreAltPhone ? formatPhoneNumberPretty(coreAltPhone) : '';

  customer.name = newName;
  customer.phone = newPhone;
  customer.whatsapp = newPhone;
  customer.altPhone = newAltPhone;
  customer.alt_phone = newAltPhone;
  customer.age = newAge;
  customer.gender = newGender;
  customer.email = newEmail;
  customer.address = newAddress;
  customer.altAddress = newAltAddress;
  customer.alt_address = newAltAddress;
  customer.notes = newNotes;

  // Update avatar initials
  const nameChars = Array.from(newName || 'WA');
  customer.avatar = (nameChars.slice(0, 2).join('')).toUpperCase();

  // Exit edit mode (locks fields)
  CUSTOMER_EDIT_MODES.delete(customerId);

  // Save to CRM state & MySQL backend
  saveCRMState();

  fetch('api.php?action=save_customer', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      id: customer.id,
      name: customer.name,
      phone: customer.phone,
      whatsapp: customer.whatsapp,
      alt_phone: customer.alt_phone,
      altPhone: customer.alt_phone,
      age: customer.age,
      gender: customer.gender,
      email: customer.email,
      address: customer.address,
      alt_address: customer.alt_address,
      altAddress: customer.alt_address,
      notes: customer.notes
    })
  }).catch(() => { });

  logAudit('CUSTOMER_UPDATED', 'CUSTOMER_360', `Updated profile details and notes for customer ${customer.name} (${customer.id})`);

  renderInbox();
  renderChatHeader();
  renderCustomer360Panel();
  if (typeof renderCustomersGrid === 'function') renderCustomersGrid();
  if (typeof renderCustomersTable === 'function') renderCustomersTable();

  showToast('Customer Details Saved', `Profile & mindset notes for "${customer.name}" saved & locked!`, 'check_circle', 'emerald');
  if (typeof playChime === 'function') playChime('order');
}

// Quick 1-Click Customer Mindset Notes Modal / Prompt
function openCustomerQuickNotesModal(customerId) {
  const isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!isSuperAdmin && typeof canUserPerformAction === 'function' && !canUserPerformAction('customers', 'edit')) {
    if (typeof showToast === 'function') showToast('Permission Denied', 'Your assigned role has View Access Only for customer records.', 'lock', 'rose');
    return;
  }
  const customer = CRM_STATE.customers.find(c => c.id === customerId);
  if (!customer) return;

  const currentNotes = customer.notes || '';
  const updatedNotes = prompt(`📝 Update Customer Mindset, Behavioral Records & Notes for "${customer.name}":`, currentNotes);

  if (updatedNotes !== null) {
    customer.notes = updatedNotes.trim();
    saveCRMState();

    fetch('api.php?action=save_customer', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        id: customer.id,
        name: customer.name,
        phone: customer.phone,
        notes: customer.notes
      })
    }).catch(() => { });

    logAudit('CUSTOMER_NOTES', 'CUSTOMER_360', `Updated mindset notes for ${customer.name}: "${customer.notes.substring(0, 30)}..."`);
    renderCustomer360Panel();
    showToast('Customer Notes Updated', 'Mindset notes saved successfully.', 'edit_note', 'amber');
    if (typeof playChime === 'function') playChime('order');
  }
}

// Quick Append Mindset Tag to Customer Record
function appendCustomerMindsetTag(customerId, tagText) {
  const isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!isSuperAdmin && typeof canUserPerformAction === 'function' && !canUserPerformAction('customers', 'edit')) {
    if (typeof showToast === 'function') showToast('Permission Denied', 'Your assigned role has View Access Only for customer records.', 'lock', 'rose');
    return;
  }
  const customer = CRM_STATE.customers.find(c => c.id === customerId);
  if (!customer) return;

  const existing = customer.notes ? customer.notes.trim() : '';
  if (existing.includes(tagText)) {
    showToast('Already Added', `Tag "${tagText}" is already in customer notes.`, 'info', 'blue');
    return;
  }

  customer.notes = existing ? `${existing} | ${tagText}` : tagText;
  saveCRMState();
  renderCustomer360Panel();
  showToast('Mindset Tag Added', `"${tagText}" recorded in customer mindset notes.`, 'psychology', 'amber');
  if (typeof playChime === 'function') playChime('order');
}

