function resetInboxViewFilters() {
  try {
    const curView = (typeof ACTIVE_VIEW !== 'undefined' && ACTIVE_VIEW) ? ACTIVE_VIEW : 'inbox';

    // Visual Feedback: Spin refresh icon on header reset button
    const resetBtn = document.getElementById('header-reset-inbox-btn');
    const resetIcon = resetBtn ? resetBtn.querySelector('.material-symbols-outlined') : null;
    if (resetIcon) resetIcon.classList.add('animate-spin');

    // 1. Reset WhatsApp Inbox View, Search & Filters
    const chatSearch = document.getElementById('chat-search-input');
    if (chatSearch) chatSearch.value = '';
    const searchInput = document.getElementById('inbox-search-input') ||
                        document.querySelector('input[placeholder*="Search customer"]') ||
                        document.querySelector('input[placeholder*="Search SKU"]');
    if (searchInput) searchInput.value = '';

    const catSel = document.getElementById('inbox-cat-select');
    if (catSel) catSel.value = 'all';

    // Reset Line Switcher to "All Lines"
    if (typeof switchActiveWhatsAppLine === 'function') {
      try { switchActiveWhatsAppLine('all', 'All Lines', 'All Numbers'); } catch (e) {}
    } else {
      window.ACTIVE_SEND_ACCOUNT_ID = 'all';
    }

    // Reset Inbox Filter Tabs & Variables
    window.INBOX_SEARCH_QUERY = '';
    window.INBOX_FILTER = 'all';
    window.ACTIVE_INBOX_FILTER = 'all';
    if (typeof setInboxFilter === 'function') {
      setInboxFilter('all');
    }

    // Break DOM cache fingerprints so conversation queue and messages immediately re-render
    window._FORCE_CONV_LIST_RENDER = true;
    const convContainer = document.getElementById('conversation-list-container');
    if (convContainer) convContainer._lastConvListFp = null;

    // Mobile View Handling: Return to conversation queue if viewing a specific customer
    const isMobile = (typeof window !== 'undefined' && window.innerWidth < 768);
    if (isMobile) {
      window.ACTIVE_CUSTOMER_ID = null;
      if (CRM_STATE) CRM_STATE.activeCustomerId = null;
      const leftPanel = document.getElementById('inbox-left-panel');
      if (leftPanel) {
        leftPanel.classList.remove('hidden');
        leftPanel.style.display = '';
      }
      const centerPanel = document.getElementById('chat-center-panel');
      if (centerPanel) {
        centerPanel.classList.add('hidden');
      }
    }

    // 2. Reset Catalog Filters & Search if active or present
    const catSearch = document.getElementById('catalog-search-input');
    if (catSearch) catSearch.value = '';
    window.CATALOG_SEARCH_QUERY = '';
    if (typeof resetChosenProductsFilters === 'function') resetChosenProductsFilters();
    if (typeof renderCatalog === 'function' && curView === 'catalog') renderCatalog();

    // 3. Reset Orders Filters & Search if active or present
    const ordSearch = document.getElementById('orders-search-input');
    if (ordSearch) ordSearch.value = '';
    if (typeof renderOrdersHistoryTable === 'function' && curView === 'orders') renderOrdersHistoryTable();

    // 4. Reset Follow-ups Filters & Search if active or present
    const fuSearch = document.getElementById('followup-search-input');
    if (fuSearch) fuSearch.value = '';
    if (typeof renderFollowupScheduler === 'function' && curView === 'followups') renderFollowupScheduler();

    // 5. Reset Customer Directory & Requirements Search if active or present
    const custSearch = document.getElementById('customer-search-input');
    if (custSearch) custSearch.value = '';
    const custReqSearch = document.getElementById('customer-req-search-input');
    if (custReqSearch) custReqSearch.value = '';
    window.CUSTOMER_REQ_SEARCH_QUERY = '';
    if (typeof renderCustomersGrid === 'function' && curView === 'customers') renderCustomersGrid();
    if (typeof renderCustomerRequirementsTable === 'function' && curView === 'customers') renderCustomerRequirementsTable();

    // 6. Reset DND Search
    const dndSearch = document.getElementById('dnd-search-input');
    if (dndSearch) dndSearch.value = '';
    if (typeof renderDndList === 'function' && curView === 'dnd') renderDndList();

    // 7. Re-sync live authoritative CRM data from server
    if (typeof syncLiveCRMData === 'function') {
      syncLiveCRMData(true);
    }
    if (typeof syncInboundMessagesNow === 'function') {
      syncInboundMessagesNow(true);
    }

    if (typeof renderInbox === 'function' && curView === 'inbox') {
      renderInbox();
    }
    if (typeof updateBadgeCounters === 'function') updateBadgeCounters();

    setTimeout(() => {
      if (resetIcon) resetIcon.classList.remove('animate-spin');
    }, 800);

    if (typeof showToast === 'function') {
      showToast('WhatsApp Inbox Reset', 'Search cleared, filters reset to All Inboxes, and live queue refreshed.', 'refresh', 'emerald');
    }
  } catch (err) {
    console.error('Error resetting view filters:', err);
    const resetBtn = document.getElementById('header-reset-inbox-btn');
    const resetIcon = resetBtn ? resetBtn.querySelector('.material-symbols-outlined') : null;
    if (resetIcon) resetIcon.classList.remove('animate-spin');
  }
}
window.resetInboxViewFilters = resetInboxViewFilters;

// Live WhatsApp Inbox Refresh Controller (Provides visual time confirmation)
async function refreshInboxDataNow(btn) {
  const icon = btn ? btn.querySelector('.material-symbols-outlined') : null;
  const label = document.getElementById('header-refresh-inbox-label');
  if (icon) icon.classList.add('animate-spin');

  try {
    if (typeof syncLiveCRMData === 'function') syncLiveCRMData(true);
    if (typeof syncInboundMessagesNow === 'function') syncInboundMessagesNow(true);
    if (typeof ACTIVE_CUSTOMER_ID !== 'undefined' && ACTIVE_CUSTOMER_ID && typeof syncCustomerMessagesFromDB === 'function') {
      syncCustomerMessagesFromDB(ACTIVE_CUSTOMER_ID);
    }
    window._FORCE_CONV_LIST_RENDER = true;
    if (typeof renderInbox === 'function') renderInbox();
    if (typeof updateBadgeCounters === 'function') updateBadgeCounters();

    const timeStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true });
    if (label) label.innerText = timeStr;
    if (typeof showToast === 'function') {
      showToast('Inbox Refreshed', `Synced latest WhatsApp queue at ${timeStr}`, 'sync', 'emerald');
    }
  } catch (err) {
    console.warn('[refreshInboxDataNow] error:', err);
  } finally {
    setTimeout(() => {
      if (icon) icon.classList.remove('animate-spin');
    }, 600);
  }
}
window.refreshInboxDataNow = refreshInboxDataNow;

