async function refreshCatalogStockFromAPI(btnEl) {
  const icon = (btnEl ? btnEl.querySelector('.material-symbols-outlined') : null) ||
    document.querySelector('#view-catalog button[onclick*="refreshCatalogStockFromAPI"] .material-symbols-outlined') ||
    document.getElementById('btn-refresh-catalog')?.querySelector('.material-symbols-outlined');
  if (icon) icon.classList.add('animate-spin');
  if (btnEl) btnEl.disabled = true;

  try {
    const res = await fetch('api.php?action=get_all');
    if (res.ok) {
      const data = await res.json();
      const payload = data.data || data;
      if (payload.products && Array.isArray(payload.products)) {
        mergeCatalogProductsWithDB(payload.products);
      }
      if (payload.categories && Array.isArray(payload.categories) && payload.categories.length > 0) {
        CRM_STATE.categories = payload.categories;
      }
      if (payload.subcategories && Array.isArray(payload.subcategories) && payload.subcategories.length > 0) {
        CRM_STATE.subcategories = payload.subcategories;
      }
      if (payload.attributes) {
        CRM_STATE.attributes = payload.attributes;
      }
      if (typeof populateCatalogCategoryFilters === 'function') {
        populateCatalogCategoryFilters();
      }
    }
  } catch (err) {
    console.log('Sync completed with current cache');
  } finally {
    filterCatalogGrid();
    updateOrderProductDropdown();
    if (typeof updateCatalogKPICards === 'function') updateCatalogKPICards();
    if (icon) icon.classList.remove('animate-spin');
    if (btnEl) btnEl.disabled = false;
    showToast('Stock Synchronized', 'All garment inventory levels and catalog taxonomy are live.', 'check_circle', 'emerald');
  }
}
window.refreshCatalogStockFromAPI = refreshCatalogStockFromAPI;

// =========================================================================
// 8. WHATSAPP ORDERS ENGINE: ORDER DASHBOARD & ORDER HISTORY (SUBMODULES)
// =========================================================================

var ACTIVE_ORDERS_SUBMODULE = (function () {
  try {
    const rawHash = (typeof window !== 'undefined' && window.location && window.location.hash) ? window.location.hash.replace('#', '').trim().toLowerCase() : '';
    if (rawHash.startsWith('orders/')) {
      const sub = rawHash.split('/')[1];
      if (sub === 'history' || sub === 'dashboard') return sub;
    }
    const stored = (typeof localStorage !== 'undefined') ? localStorage.getItem('GRM_CRM_ACTIVE_ORDERS_SUBMODULE') : null;
    if (stored === 'history' || stored === 'dashboard') return stored;
  } catch (e) { }
  return 'dashboard';
})();
var ACTIVE_ORDER_HISTORY_STATUS_FILTER = 'ALL';

function normalizeOrderStatus(status) {
  if (!status) return 'PLACED';
  const s = String(status).toUpperCase().replace(/\s+/g, '_');
  if (s === 'STOCK_RESERVED' || s === 'NEW' || s === 'PLACED') return 'PLACED';
  if (s === 'PACKED' || s === 'PROCESSING') return 'PACKED';
  if (s === 'SHIPPED' || s === 'IN_TRANSIT') return 'SHIPPED';
  if (s === 'OUT_FOR_DELIVERY' || s === 'OUT_OF_DELIVERY' || s === 'OUTOFDELIVERY') return 'OUT_FOR_DELIVERY';
  if (s === 'DELIVERED' || s === 'COMPLETED') return 'DELIVERED';
  if (s === 'CANCELLED' || s === 'CANCELED') return 'CANCELLED';
  return s;
}

function switchOrdersSubmodule(submodule) {
  const isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  const hasOrdersAccess = isSuperAdmin || (typeof canUserPerformAction === 'function' && (
    canUserPerformAction('orders', 'view') ||
    canUserPerformAction('orders', 'create') ||
    canUserPerformAction('orders', 'edit') ||
    canUserPerformAction('orders', 'delete')
  ));
  if (!hasOrdersAccess) {
    if (typeof showToast === 'function') showToast('Access Restricted', 'Your assigned role does not have permission to access sales orders.', 'lock', 'rose');
    return;
  }
  ACTIVE_ORDERS_SUBMODULE = submodule || 'dashboard';
  try {
    localStorage.setItem('GRM_CRM_ACTIVE_ORDERS_SUBMODULE', ACTIVE_ORDERS_SUBMODULE);
  } catch (e) { }

  // Clear instant-view-shield if present to allow instant view transitions
  const shield = document.getElementById('instant-view-shield');
  if (shield) shield.remove();

  // Auto-close sidebar drawer on small/tablet screens upon navigation
  if (typeof window !== 'undefined' && window.innerWidth < 1024) {
    if (typeof toggleSidebar === 'function') toggleSidebar(false);
  }

  // Ensure orders main view is active if not already
  if (typeof ACTIVE_VIEW === 'undefined' || ACTIVE_VIEW !== 'orders') {
    if (typeof switchView === 'function') {
      switchView('orders', submodule);
      return;
    }
  }

  // Update URL hash cleanly
  try {
    if (typeof window !== 'undefined' && window.history && window.history.replaceState) {
      window.history.replaceState(null, '', '#orders/' + ACTIVE_ORDERS_SUBMODULE);
    }
  } catch (e) { }

  const viewDash = document.getElementById('subview-orders-dashboard');
  const viewHist = document.getElementById('subview-orders-history');

  // Highlight tab buttons in top segmented bar
  const tabDash = document.getElementById('tab-orders-submodule-dashboard');
  const tabHist = document.getElementById('tab-orders-submodule-history');
  if (tabDash && tabHist) {
    if (submodule === 'history') {
      tabHist.className = 'px-4 py-2 rounded-xl font-extrabold text-xs flex items-center gap-2 transition-all shadow-sm bg-white text-emerald-800 border border-slate-200/80 cursor-pointer';
      tabDash.className = 'px-4 py-2 rounded-xl font-bold text-xs flex items-center gap-2 transition-all text-slate-600 hover:text-emerald-800 hover:bg-white/60 cursor-pointer';
    } else {
      tabDash.className = 'px-4 py-2 rounded-xl font-extrabold text-xs flex items-center gap-2 transition-all shadow-sm bg-white text-emerald-800 border border-slate-200/80 cursor-pointer';
      tabHist.className = 'px-4 py-2 rounded-xl font-bold text-xs flex items-center gap-2 transition-all text-slate-600 hover:text-emerald-800 hover:bg-white/60 cursor-pointer';
    }
  }

  // Highlight standalone sidebar items: WhatsApp Dashboard vs WhatsApp Orders
  const navDash = document.getElementById('nav-orders-dashboard');
  const navOrders = document.getElementById('nav-orders');
  if (navDash && navOrders) {
    if (submodule === 'history') {
      navOrders.className = "w-full flex items-center justify-between px-3 py-2.5 rounded-xl transition bg-brand-wa text-white font-semibold shadow-sm";
      navDash.className = "w-full flex items-center justify-between px-3 py-2.5 rounded-xl transition text-slate-300 hover:text-white hover:bg-surface-sidebarActive group";
    } else {
      navDash.className = "w-full flex items-center justify-between px-3 py-2.5 rounded-xl transition bg-brand-wa text-white font-semibold shadow-sm";
      navOrders.className = "w-full flex items-center justify-between px-3 py-2.5 rounded-xl transition text-slate-300 hover:text-white hover:bg-surface-sidebarActive group";
    }
  }

  // Update header text dynamically
  const headerIcon = document.getElementById('orders-hub-icon');
  const headerTitle = document.getElementById('orders-hub-title');
  const headerSubtitle = document.getElementById('orders-hub-subtitle');
  if (submodule === 'history') {
    if (headerIcon) headerIcon.innerText = 'receipt_long';
    if (headerTitle) headerTitle.innerText = "WhatsApp Sales Orders & Management";
    if (headerSubtitle) headerSubtitle.innerText = "";
  } else {
    if (headerIcon) headerIcon.innerText = 'analytics';
    if (headerTitle) headerTitle.innerText = "WhatsApp Sales Dashboard";
    if (headerSubtitle) headerSubtitle.innerText = "";
  }

  if (typeof updatePageHeaderTitle === 'function') updatePageHeaderTitle();

  // Strictly SEPARATED SINGLE SCREENS: Show ONLY the active screen
  if (submodule === 'history') {
    if (viewDash) viewDash.classList.add('hidden');
    if (viewHist) viewHist.classList.remove('hidden');
    populateOrderHistoryStaffFilter();
    renderOrdersHistoryTable();
  } else {
    if (viewHist) viewHist.classList.add('hidden');
    if (viewDash) viewDash.classList.remove('hidden');
    renderOrdersDashboard();
  }
}
window.switchOrdersSubmodule = switchOrdersSubmodule;

function reassignOrderStaff(orderId, newStaffId) {
  const isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!isSuperAdmin && typeof canUserPerformAction === 'function' && !canUserPerformAction('orders', 'edit')) {
    if (typeof showToast === 'function') showToast('Permission Denied', 'Your assigned role does not have permission to reassign order staff.', 'lock', 'rose');
    return;
  }
  const ord = (CRM_STATE?.orders || []).find(o => o.id === orderId);
  if (!ord) return;
  const staffList = [...(CRM_STATE?.staffList || [])];
  if (!staffList.some(s => s.id === 'admin')) {
    staffList.push({ id: 'admin', name: 'Super Admin', role: 'Admin Manager' });
  }
  const staffObj = staffList.find(s => s.id === newStaffId) || { id: newStaffId, name: newStaffId === 'admin' ? 'Super Admin' : 'Staff' };

  const oldStaff = ord.staffName || ord.staff_name || ord.createdBy || 'Staff';
  ord.staffId = newStaffId;
  ord.staff_id = newStaffId;
  ord.staffName = staffObj.name;
  ord.staff_name = staffObj.name;
  ord.createdBy = staffObj.name;
  ord.created_by = staffObj.name;

  // Persist to MySQL database
  fetch('api.php?action=reassign_order_staff', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      id: orderId,
      order_id: orderId,
      staff_id: newStaffId,
      staff_name: staffObj.name,
      user: CURRENT_USER?.name || 'Super Admin'
    })
  }).catch(() => { });

  logAudit('ORDER_REASSIGNED', 'ORDERS', `Order ${orderId} reassigned from ${oldStaff} to ${staffObj.name}`);
  saveCRMState();
  renderOrdersDashboard();
  renderOrdersHistoryTable();
  showToast('Order Reassigned', `Order ${orderId} credited to ${staffObj.name}`, 'support_agent', 'indigo');
}
window.reassignOrderStaff = reassignOrderStaff;

// Date Range Filtering Engine for Orders Module & Exports
function isOrderWithinDateRange(order, fromDateStr, toDateStr) {
  if (!fromDateStr && !toDateStr) return true;
  const dStr = order.createdAt || order.created_at;
  if (!dStr) return true;
  const d = new Date(dStr);
  if (isNaN(d.getTime())) return true;

  if (fromDateStr) {
    const fromDate = new Date(fromDateStr + 'T00:00:00');
    if (d < fromDate) return false;
  }
  if (toDateStr) {
    const toDate = new Date(toDateStr + 'T23:59:59.999');
    if (d > toDate) return false;
  }
  return true;
}
window.isOrderWithinDateRange = isOrderWithinDateRange;

function getOrdersDateFilteredList() {
  const allOrders = CRM_STATE?.orders || [];
  const fromVal = document.getElementById('orders-filter-date-from')?.value || '';
  const toVal = document.getElementById('orders-filter-date-to')?.value || '';
  if (!fromVal && !toVal) return allOrders;
  return allOrders.filter(o => isOrderWithinDateRange(o, fromVal, toVal));
}
window.getOrdersDateFilteredList = getOrdersDateFilteredList;

function onOrdersDateFilterChange() {
  const fromVal = document.getElementById('orders-filter-date-from')?.value || '';
  const toVal = document.getElementById('orders-filter-date-to')?.value || '';
  const clearBtn = document.getElementById('btn-clear-orders-date');
  if (clearBtn) {
    if (fromVal || toVal) {
      clearBtn.classList.remove('hidden');
    } else {
      clearBtn.classList.add('hidden');
    }
  }

  // Update badge in header if date filter active
  const badgeTotalHeader = document.getElementById('badge-orders-total-count');
  const filtered = getOrdersDateFilteredList();
  if (badgeTotalHeader) {
    badgeTotalHeader.innerText = (fromVal || toVal)
      ? filtered.length + ' Filtered Orders'
      : (CRM_STATE?.orders || []).length + ' Orders';
  }

  renderOrdersDashboard();
  renderOrdersHistoryTable();
  if (typeof updateOrdersPipelineUI === 'function') updateOrdersPipelineUI();
}
window.onOrdersDateFilterChange = onOrdersDateFilterChange;

function clearOrdersDateFilter() {
  const fromInput = document.getElementById('orders-filter-date-from');
  const toInput = document.getElementById('orders-filter-date-to');
  const clearBtn = document.getElementById('btn-clear-orders-date');
  if (fromInput) fromInput.value = '';
  if (toInput) toInput.value = '';
  if (clearBtn) clearBtn.classList.add('hidden');

  const badgeTotalHeader = document.getElementById('badge-orders-total-count');
  if (badgeTotalHeader) {
    badgeTotalHeader.innerText = (CRM_STATE?.orders || []).length + ' Orders';
  }

  renderOrdersDashboard();
  renderOrdersHistoryTable();
  if (typeof updateOrdersPipelineUI === 'function') updateOrdersPipelineUI();
  if (typeof showToast === 'function') {
    showToast('Date Filter Reset', 'Showing all orders.', 'event_busy', 'slate');
  }
}
window.clearOrdersDateFilter = clearOrdersDateFilter;

function renderOrdersModule() {
  if (typeof ACTIVE_VIEW !== 'undefined' && ACTIVE_VIEW !== 'orders') return;
  const badgeOrders = document.getElementById('badge-orders-count');
  const badgeTotalHeader = document.getElementById('badge-orders-total-count');
  const badgeHistoryTab = document.getElementById('orders-tab-history-badge');
  const badgeSidebarHistory = document.getElementById('nav-sub-orders-history-badge');
  const totalCount = (CRM_STATE?.orders || []).length;

  if (badgeOrders) badgeOrders.innerText = totalCount;
  if (badgeTotalHeader) badgeTotalHeader.innerText = `${totalCount} Order${totalCount === 1 ? '' : 's'}`;
  if (badgeHistoryTab) badgeHistoryTab.innerText = totalCount;
  if (badgeSidebarHistory) badgeSidebarHistory.innerText = totalCount;

  populateOrderHistoryStaffFilter();
  if (typeof ACTIVE_VIEW !== 'undefined' && ACTIVE_VIEW === 'orders') {
    switchOrdersSubmodule(ACTIVE_ORDERS_SUBMODULE || 'dashboard');
  }
}
window.renderOrdersModule = renderOrdersModule;
window.renderOrdersTable = renderOrdersModule;

function updateOrdersPipelineUI() {
  const orders = (typeof getOrdersDateFilteredList === 'function') ? getOrdersDateFilteredList() : (CRM_STATE?.orders || []);
  const countPlaced = orders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'PLACED').length;
  const countPacked = orders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'PACKED').length;
  const countShipped = orders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'SHIPPED').length;
  const countOutOfDelivery = orders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'OUT_FOR_DELIVERY').length;
  const countDelivered = orders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'DELIVERED').length;

  const pipePlaced = document.getElementById('pipe-ord-placed-count');
  const pipePacked = document.getElementById('pipe-ord-packed-count');
  const pipeShipped = document.getElementById('pipe-ord-shipped-count');
  const pipeOutOfDelivery = document.getElementById('pipe-ord-out-for-delivery-count');
  const pipeDelivered = document.getElementById('pipe-ord-delivered-count');
  if (pipePlaced) pipePlaced.innerText = countPlaced;
  if (pipePacked) pipePacked.innerText = countPacked;
  if (pipeShipped) pipeShipped.innerText = countShipped;
  if (pipeOutOfDelivery) pipeOutOfDelivery.innerText = countOutOfDelivery;
  if (pipeDelivered) pipeDelivered.innerText = countDelivered;
}
window.updateOrdersPipelineUI = updateOrdersPipelineUI;

function renderOrdersDashboard() {
  const orders = (typeof getOrdersDateFilteredList === 'function') ? getOrdersDateFilteredList() : (CRM_STATE?.orders || []);

  // 1. Overall Revenue
  let overallRevenue = 0;
  let paidOnline = 0;
  let codPending = 0;

  orders.forEach(o => {
    const total = parseFloat(o.grandTotal || o.grand_total) || 0;
    overallRevenue += total;
    const isOnline = o.paymentMethod === 'ONLINE_UPI' || o.paymentMethod === 'UPI' || o.payment_method === 'ONLINE_UPI' || o.payment_method === 'UPI';
    if (isOnline) {
      paidOnline += total;
    } else {
      const adv = parseFloat(o.codAdvance || o.cod_advance) || 200;
      paidOnline += Math.min(total, adv);
      codPending += Math.max(0, total - adv);
    }
  });

  const revEl = document.getElementById('dash-ord-overall-revenue');
  const paidEl = document.getElementById('dash-ord-paid-online');
  const codEl = document.getElementById('dash-ord-cod-pending');
  if (revEl) revEl.innerText = `₹${overallRevenue.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  if (paidEl) paidEl.innerText = `₹${paidOnline.toLocaleString('en-IN')} Paid Online`;
  if (codEl) codEl.innerText = `₹${codPending.toLocaleString('en-IN')} COD Due`;

  // 2. Weekly Orders Count & Revenue (Past 7 days)
  const now = new Date();
  const sevenDaysAgo = new Date(now.getTime() - (7 * 24 * 60 * 60 * 1000));
  const weeklyOrders = orders.filter(o => {
    const dStr = o.createdAt || o.created_at;
    if (!dStr) return true;
    const d = new Date(dStr);
    return !isNaN(d.getTime()) ? d >= sevenDaysAgo : true;
  });
  const weeklyCount = weeklyOrders.length;
  const weeklyRevenue = weeklyOrders.reduce((sum, o) => sum + (parseFloat(o.grandTotal || o.grand_total) || 0), 0);

  const weekCountEl = document.getElementById('dash-ord-weekly-count');
  const weekRevEl = document.getElementById('dash-ord-weekly-revenue');
  if (weekCountEl) weekCountEl.innerText = `${weeklyCount} Order${weeklyCount === 1 ? '' : 's'}`;
  if (weekRevEl) weekRevEl.innerText = `₹${weeklyRevenue.toLocaleString('en-IN', { minimumFractionDigits: 2 })}`;

  // 3. Monthly Orders Count & Revenue (Past 30 days)
  const thirtyDaysAgo = new Date(now.getTime() - (30 * 24 * 60 * 60 * 1000));
  const monthlyOrders = orders.filter(o => {
    const dStr = o.createdAt || o.created_at;
    if (!dStr) return true;
    const d = new Date(dStr);
    return !isNaN(d.getTime()) ? d >= thirtyDaysAgo : true;
  });
  const monthlyCount = monthlyOrders.length;
  const monthlyRevenue = monthlyOrders.reduce((sum, o) => sum + (parseFloat(o.grandTotal || o.grand_total) || 0), 0);

  const monthCountEl = document.getElementById('dash-ord-monthly-count');
  const monthRevEl = document.getElementById('dash-ord-monthly-revenue');
  if (monthCountEl) monthCountEl.innerText = `${monthlyCount} Order${monthlyCount === 1 ? '' : 's'}`;
  if (monthRevEl) monthRevEl.innerText = `₹${monthlyRevenue.toLocaleString('en-IN', { minimumFractionDigits: 2 })}`;

  // 4. Average Order Value (AOV)
  const aov = orders.length > 0 ? (overallRevenue / orders.length) : 0;
  const aovEl = document.getElementById('dash-ord-aov');
  const allTimeEl = document.getElementById('dash-ord-all-time-count');
  if (aovEl) aovEl.innerText = `₹${Math.round(aov).toLocaleString('en-IN')}`;
  if (allTimeEl) allTimeEl.innerText = `${orders.length} total volume`;

  // 5. Stage Funnel Counts (Placed, Packed, Shipped, Delivered)
  const countPlaced = orders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'PLACED').length;
  const countPacked = orders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'PACKED').length;
  const countShipped = orders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'SHIPPED').length;
  const countOutOfDelivery = orders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'OUT_FOR_DELIVERY').length;
  const countDelivered = orders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'DELIVERED').length;

  const pipePlaced = document.getElementById('pipe-ord-placed-count');
  const pipePacked = document.getElementById('pipe-ord-packed-count');
  const pipeShipped = document.getElementById('pipe-ord-shipped-count');
  const pipeOutOfDelivery = document.getElementById('pipe-ord-out-for-delivery-count');
  const pipeDelivered = document.getElementById('pipe-ord-delivered-count');
  if (pipePlaced) pipePlaced.innerText = countPlaced;
  if (pipePacked) pipePacked.innerText = countPacked;
  if (pipeShipped) pipeShipped.innerText = countShipped;
  if (pipeOutOfDelivery) pipeOutOfDelivery.innerText = countOutOfDelivery;
  if (pipeDelivered) pipeDelivered.innerText = countDelivered;

  // 6. Staff Breakdown
  renderOrdersStaffBreakdown();
}
window.renderOrdersDashboard = renderOrdersDashboard;

function renderOrdersStaffBreakdown() {
  const tbody = document.getElementById('orders-staff-breakdown-body');
  if (!tbody) return;

  const orders = (typeof getOrdersDateFilteredList === 'function') ? getOrdersDateFilteredList() : (CRM_STATE?.orders || []);
  const totalOrdersCount = orders.length;

  const staffMembers = [...(CRM_STATE?.staffList || [])];
  if (!staffMembers.some(s => s.id === 'admin' || s.name === 'Super Admin')) {
    staffMembers.push({
      id: 'admin',
      name: 'Super Admin',
      role: 'Admin Manager (Full System)',
      avatar: 'SA',
      specialization: 'Central Sales & Operations'
    });
  }

  const staffStats = staffMembers.map(staff => {
    const staffOrders = orders.filter(o => {
      const matchId = o.staffId && (o.staffId === staff.id || o.staff_id === staff.id);
      const matchName = (o.staffName && o.staffName.toLowerCase().includes(staff.name.toLowerCase())) ||
        (o.staff_name && o.staff_name.toLowerCase().includes(staff.name.toLowerCase())) ||
        (o.createdBy && o.createdBy.toLowerCase().includes(staff.name.toLowerCase())) ||
        (o.created_by && o.created_by.toLowerCase().includes(staff.name.toLowerCase()));
      return matchId || matchName;
    });

    const count = staffOrders.length;
    const revenue = staffOrders.reduce((sum, o) => sum + (parseFloat(o.grandTotal || o.grand_total) || 0), 0);
    const placed = staffOrders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'PLACED').length;
    const packed = staffOrders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'PACKED').length;
    const shipped = staffOrders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'SHIPPED').length;
    const outOfDelivery = staffOrders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'OUT_FOR_DELIVERY').length;
    const delivered = staffOrders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'DELIVERED').length;
    const sharePercent = totalOrdersCount > 0 ? Math.round((count / totalOrdersCount) * 100) : 0;

    return { staff, count, revenue, placed, packed, shipped, outOfDelivery, delivered, sharePercent };
  });

  staffStats.sort((a, b) => b.count - a.count);

  if (staffStats.length === 0 || totalOrdersCount === 0) {
    tbody.innerHTML = `
      <tr>
        <td colspan="7" class="py-8 text-center text-slate-400">
          <span class="material-symbols-outlined text-[28px] text-slate-300 block mb-1">people</span>
          <p class="font-bold text-slate-600">No staff order records available</p>
          <p class="text-[11px]">Orders booked by staff will automatically display here.</p>
        </td>
      </tr>
    `;
    return;
  }

  tbody.innerHTML = staffStats.map((item, idx) => {
    const isTop = idx === 0 && item.count > 0;
    const badgeColor = isTop ? 'bg-amber-100 text-amber-900 border-amber-300' : (item.count > 0 ? 'bg-emerald-100 text-emerald-800 border-emerald-200' : 'bg-slate-100 text-slate-600 border-slate-200');
    const badgeText = isTop ? '🏆 Top Performer' : (item.count > 0 ? '⚡ Active Specialist' : 'No Bookings');

    return `
      <tr class="hover:bg-slate-50/80 transition border-b border-slate-100">
        <td class="py-3.5 px-5">
          <div class="flex items-center gap-3">
            <div class="w-9 h-9 rounded-xl bg-gradient-to-br from-emerald-600 to-teal-800 text-white font-extrabold text-xs flex items-center justify-center shadow-xs shrink-0">
              ${item.staff.avatar || item.staff.name.slice(0, 2).toUpperCase()}
            </div>
            <div>
              <div class="font-extrabold text-slate-900 text-xs flex items-center gap-1.5">
                <span>${item.staff.name}</span>
                ${isTop ? '<span class="text-[10px] text-amber-500">★</span>' : ''}
              </div>
              <div class="text-[10px] text-slate-400 font-mono">ID: ${item.staff.id}</div>
            </div>
          </div>
        </td>
        <td class="py-3.5 px-4 text-slate-600 text-xs font-medium">
          <div class="truncate max-w-xs font-medium">${item.staff.role || item.staff.specialization || 'Sales Specialist'}</div>
        </td>
        <td class="py-3.5 px-4 text-center">
          <span class="inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-mono font-black ${item.count > 0 ? 'bg-emerald-50 text-emerald-800 border border-emerald-200' : 'bg-slate-100 text-slate-500'}">
            <span class="material-symbols-outlined text-[14px]">shopping_bag</span>
            <span>${item.count} Order${item.count === 1 ? '' : 's'}</span>
          </span>
        </td>
        <td class="py-3.5 px-4">
          <div class="flex items-center gap-1 flex-wrap text-[10px] font-bold">
            <span class="px-1.5 py-0.5 rounded bg-blue-50 text-blue-800 border border-blue-200" title="Placed">${item.placed} Placed</span>
            <span class="px-1.5 py-0.5 rounded bg-purple-50 text-purple-800 border border-purple-200" title="Packed">${item.packed} Packed</span>
            <span class="px-1.5 py-0.5 rounded bg-amber-50 text-amber-800 border border-amber-200" title="Shipped">${item.shipped} Shipped</span>
            <span class="px-1.5 py-0.5 rounded bg-orange-50 text-orange-800 border border-orange-200" title="Out for Delivery">${item.outOfDelivery} Out for Delivery</span>
            <span class="px-1.5 py-0.5 rounded bg-emerald-50 text-emerald-800 border border-emerald-200" title="Delivered">${item.delivered} Delivered</span>
          </div>
        </td>
        <td class="py-3.5 px-4">
          <div class="font-mono font-black text-slate-900 text-xs">₹${item.revenue.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</div>
          <div class="text-[10px] text-slate-400 font-medium">Avg: ₹${item.count > 0 ? Math.round(item.revenue / item.count).toLocaleString('en-IN') : 0}</div>
        </td>
        <td class="py-3.5 px-4">
          <div class="w-32 space-y-1">
            <div class="flex items-center justify-between text-[10px] font-bold text-slate-600">
              <span>${item.sharePercent}%</span>
              <span>${item.count}/${totalOrdersCount}</span>
            </div>
            <div class="w-full h-1.5 bg-slate-100 rounded-full overflow-hidden">
              <div class="h-full bg-emerald-500 rounded-full" style="width: ${item.sharePercent}%"></div>
            </div>
          </div>
        </td>
        <td class="py-3.5 px-4 text-right">
          <span class="px-2.5 py-1 rounded-full text-[10px] font-extrabold border ${badgeColor} inline-block whitespace-nowrap">
            ${badgeText}
          </span>
        </td>
      </tr>
    `;
  }).join('');
}
window.renderOrdersStaffBreakdown = renderOrdersStaffBreakdown;

function populateOrderHistoryStaffFilter() {
  const select = document.getElementById('order-history-staff-filter');
  if (!select) return;
  const currentVal = select.value;
  const staffMembers = [...(CRM_STATE?.staffList || [])];
  if (!staffMembers.some(s => s.id === 'admin' || s.name === 'Super Admin')) {
    staffMembers.push({ id: 'admin', name: 'Super Admin' });
  }

  select.innerHTML = '<option value="ALL">All Staff Members</option>' + staffMembers.map(s => `
    <option value="${s.name}">${s.name}</option>
  `).join('');
  if (currentVal) select.value = currentVal;
}
window.populateOrderHistoryStaffFilter = populateOrderHistoryStaffFilter;

function setOrderHistoryStatusFilter(status) {
  ACTIVE_ORDER_HISTORY_STATUS_FILTER = status;
  const buttons = ['ALL', 'PLACED', 'PACKED', 'SHIPPED', 'OUT_FOR_DELIVERY', 'DELIVERED'];
  buttons.forEach(b => {
    const btn = document.getElementById(`filter-btn-status-${b}`);
    if (btn) {
      if (b === status) {
        btn.className = "shrink-0 whitespace-nowrap px-3 py-1.5 rounded-lg text-xs font-bold transition bg-emerald-600 text-white cursor-pointer shadow-xs";
      } else {
        btn.className = "shrink-0 whitespace-nowrap px-3 py-1.5 rounded-lg text-xs font-bold transition bg-slate-100 text-slate-700 hover:bg-slate-200 cursor-pointer";
      }
    }
  });
  renderOrdersHistoryTable();
}
window.setOrderHistoryStatusFilter = setOrderHistoryStatusFilter;

function filterOrderHistoryByStatus(status) {
  switchOrdersSubmodule('history');
  setOrderHistoryStatusFilter(status);
}
window.filterOrderHistoryByStatus = filterOrderHistoryByStatus;

function filterOrdersHistoryTable() {
  renderOrdersHistoryTable();
}
window.filterOrdersHistoryTable = filterOrdersHistoryTable;

function renderOrdersHistoryTable() {
  if (typeof updateOrdersPipelineUI === 'function') updateOrdersPipelineUI();
  const tbody = document.getElementById('orders-table-body');
  const mobileContainer = document.getElementById('orders-mobile-cards-container');
  if (!tbody && !mobileContainer) return;

  const canOrderView = (typeof canUserPerformAction === 'function') ? canUserPerformAction('orders', 'view') : true;
  if (!canOrderView) {
    if (tbody) {
      tbody.innerHTML = `
        <tr>
          <td colspan="7" class="py-12 text-center text-slate-400">
            <div class="flex flex-col items-center justify-center gap-2">
              <span class="material-symbols-outlined text-[40px] text-amber-500">lock</span>
              <p class="font-bold text-slate-700 text-sm">Sales Orders View Restricted</p>
              <p class="text-xs text-slate-400 max-w-sm">Your assigned role does not have permission to view sales order records.</p>
            </div>
          </td>
        </tr>
      `;
    }
    if (mobileContainer) {
      mobileContainer.innerHTML = `
        <div class="py-8 px-4 text-center bg-slate-50 border border-slate-200 rounded-2xl">
          <span class="material-symbols-outlined text-amber-500 text-[36px]">lock</span>
          <p class="font-bold text-slate-700 text-sm mt-1">Orders View Restricted</p>
        </div>
      `;
    }
    if (typeof enforceGranularActionPermissions === 'function') enforceGranularActionPermissions();
    return;
  }

  const orders = (typeof getOrdersDateFilteredList === 'function') ? getOrdersDateFilteredList() : (CRM_STATE?.orders || []);
  const searchInput = document.getElementById('order-history-search');
  const searchVal = (searchInput ? searchInput.value : '').toLowerCase().trim();
  const staffFilter = document.getElementById('order-history-staff-filter');
  const staffVal = staffFilter ? staffFilter.value : 'ALL';

  // Update filter counters
  const cAll = orders.length;
  const cPlaced = orders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'PLACED').length;
  const cPacked = orders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'PACKED').length;
  const cShipped = orders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'SHIPPED').length;
  const cOutOfDelivery = orders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'OUT_FOR_DELIVERY').length;
  const cDelivered = orders.filter(o => normalizeOrderStatus(o.orderStatus || o.order_status) === 'DELIVERED').length;

  const elAll = document.getElementById('count-filter-all');
  const elPlaced = document.getElementById('count-filter-placed');
  const elPacked = document.getElementById('count-filter-packed');
  const elShipped = document.getElementById('count-filter-shipped');
  const elOutOfDelivery = document.getElementById('count-filter-out-for-delivery');
  const elDelivered = document.getElementById('count-filter-delivered');
  if (elAll) elAll.innerText = cAll;
  if (elPlaced) elPlaced.innerText = cPlaced;
  if (elPacked) elPacked.innerText = cPacked;
  if (elShipped) elShipped.innerText = cShipped;
  if (elOutOfDelivery) elOutOfDelivery.innerText = cOutOfDelivery;
  if (elDelivered) elDelivered.innerText = cDelivered;

  const elBatchSlips = document.getElementById('batch-slips-count');
  if (elBatchSlips) elBatchSlips.innerText = orders.length;

  const filteredOrders = orders.filter(ord => {
    const status = normalizeOrderStatus(ord.orderStatus || ord.order_status);
    if (ACTIVE_ORDER_HISTORY_STATUS_FILTER !== 'ALL' && status !== ACTIVE_ORDER_HISTORY_STATUS_FILTER) {
      return false;
    }

    if (staffVal !== 'ALL') {
      const matchStaff = (ord.staffName && ord.staffName.toLowerCase().includes(staffVal.toLowerCase())) ||
        (ord.staff_name && ord.staff_name.toLowerCase().includes(staffVal.toLowerCase())) ||
        (ord.createdBy && ord.createdBy.toLowerCase().includes(staffVal.toLowerCase())) ||
        (ord.created_by && ord.created_by.toLowerCase().includes(staffVal.toLowerCase()));
      if (!matchStaff) return false;
    }

    if (searchVal) {
      let itms = ord.items || [];
      if (typeof itms === 'string') {
        try { itms = JSON.parse(itms); } catch(e) { itms = []; }
      }
      if (!Array.isArray(itms) && ord.items_json && typeof ord.items_json === 'string') {
        try { itms = JSON.parse(ord.items_json); } catch(e) { itms = []; }
      }
      const itemNames = (Array.isArray(itms) ? itms : []).map(i => i.name || i.title || '').join(' ');

      const searchTarget = [
        ord.id,
        ord.customerName,
        ord.customerPhone,
        ord.staffName,
        ord.createdBy,
        ord.shippingAddress,
        ord.upiTransactionId,
        itemNames
      ].join(' ').toLowerCase();

      if (!searchTarget.includes(searchVal)) return false;
    }

    return true;
  });

  if (filteredOrders.length === 0) {
    if (tbody) {
      tbody.innerHTML = `
        <tr>
          <td colspan="7" class="py-12 text-center text-slate-400">
            <span class="material-symbols-outlined text-[36px] block mb-2 text-slate-300">receipt_long</span>
            <p class="font-bold text-slate-600">No matching orders found</p>
            <p class="text-xs text-slate-400 mt-0.5">Try adjusting your status filter or search query.</p>
          </td>
        </tr>
      `;
    }
    if (mobileContainer) {
      mobileContainer.innerHTML = `
        <div class="py-10 px-4 text-center text-slate-400 bg-white rounded-2xl border border-slate-200">
          <span class="material-symbols-outlined text-[36px] block mb-2 text-slate-300">receipt_long</span>
          <p class="font-bold text-slate-600">No matching orders found</p>
          <p class="text-xs text-slate-400 mt-0.5">Try adjusting your status filter or search query.</p>
        </div>
      `;
    }
    return;
  }

  // Render Desktop Table Rows
  if (tbody) {
    tbody.innerHTML = filteredOrders.map(ord => {
      let ordItems = ord.items || [];
      if (typeof ordItems === 'string') {
        try { ordItems = JSON.parse(ordItems); } catch(e) { ordItems = []; }
      }
      if (!Array.isArray(ordItems) && ord.items_json && typeof ord.items_json === 'string') {
        try { ordItems = JSON.parse(ord.items_json); } catch(e) { ordItems = []; }
      }
      if (!Array.isArray(ordItems)) ordItems = [];

      const normStatus = normalizeOrderStatus(ord.orderStatus || ord.order_status);
      const isOnline = ord.paymentMethod === 'ONLINE_UPI' || ord.paymentMethod === 'UPI' || ord.payment_method === 'ONLINE_UPI' || ord.payment_method === 'UPI';
      const isCod = ord.paymentMethod === 'COD' || ord.payment_method === 'COD';
      const grandTotal = parseFloat(ord.grandTotal || ord.grand_total) || 0;
      const codAdv = parseFloat(ord.codAdvance || ord.cod_advance) || 200;
      const codDue = ord.codBalanceDue !== undefined ? parseFloat(ord.codBalanceDue) : Math.max(0, grandTotal - codAdv);

      let amountHtml = '';
      if (isCod) {
        amountHtml = `
          <div class="font-mono font-bold text-slate-900 text-xs">₹${grandTotal.toLocaleString('en-IN')}</div>
          <div class="text-[10px] text-amber-800 font-semibold flex items-center gap-1 mt-0.5 flex-wrap">
            <span class="bg-emerald-100 text-emerald-800 px-1 rounded font-bold">₹${codAdv} Adv</span>
            <span>&bull;</span>
            <span class="bg-amber-100 text-amber-900 px-1 rounded font-bold">₹${codDue.toLocaleString('en-IN')} Due</span>
          </div>
        `;
      } else {
        amountHtml = `
          <div class="font-mono font-bold text-emerald-800 text-xs">₹${grandTotal.toLocaleString('en-IN')}</div>
          <div class="text-[10px] text-emerald-600 font-bold mt-0.5 flex items-center gap-1">
            <span class="material-symbols-outlined text-[13px]">check_circle</span>
            <span>100% Paid Online</span>
          </div>
        `;
      }

      const badgeColor = isOnline ? 'bg-emerald-100 text-emerald-800 border-emerald-200' : 'bg-amber-100 text-amber-900 border-amber-300';
      const badgeLabel = isOnline ? '🟢 ONLINE (PAID)' : '🟠 COD (₹200 ADV)';

      const paymentHtml = `
        <div class="space-y-1">
          <div class="flex items-center gap-1.5 flex-wrap">
            <span class="text-[10px] font-extrabold px-2 py-0.5 rounded-full border ${badgeColor}">
              ${badgeLabel}
            </span>
            ${ord.paymentScreenshot ? `
              <button type="button" onclick="if(typeof openOrderReceiptLightbox==='function') openOrderReceiptLightbox('${ord.id}')" class="p-0.5 rounded border border-slate-200 hover:border-emerald-400 bg-white transition group relative cursor-pointer" title="Click to view payment proof">
                <img src="${ord.paymentScreenshot}" alt="Proof" class="w-6 h-6 rounded object-cover">
                <span class="material-symbols-outlined absolute -bottom-1 -right-1 text-[9px] bg-black/70 text-white rounded-full p-0.5">zoom_in</span>
              </button>
            ` : ''}
          </div>
          ${ord.upiTransactionId ? `
            <div class="flex items-center gap-1 text-[10px] font-mono text-slate-600">
              <span class="text-slate-400">UTR:</span>
              <span class="font-bold text-slate-800 bg-slate-100 hover:bg-slate-200 px-1 rounded cursor-pointer" onclick="navigator.clipboard.writeText('${ord.upiTransactionId}'); if(typeof showToast==='function') showToast('Copied', 'UPI UTR copied to clipboard', 'content_copy', 'emerald')" title="Click to copy UTR">${ord.upiTransactionId}</span>
            </div>
          ` : ''}
        </div>
      `;

      let statusBadgeClass = 'bg-blue-100 text-blue-800 border-blue-200';
      let statusIcon = 'receipt';
      let displayStatusLabel = '1. Placed';
      if (normStatus === 'PACKED') {
        statusBadgeClass = 'bg-purple-100 text-purple-800 border-purple-200';
        statusIcon = 'inventory_2';
        displayStatusLabel = '2. Packed';
      } else if (normStatus === 'SHIPPED') {
        statusBadgeClass = 'bg-amber-100 text-amber-900 border-amber-300';
        statusIcon = 'local_shipping';
        displayStatusLabel = '3. Shipped';
      } else if (normStatus === 'OUT_FOR_DELIVERY') {
        statusBadgeClass = 'bg-orange-100 text-orange-900 border-orange-300';
        statusIcon = 'two_wheeler';
        displayStatusLabel = '4. Out for Delivery';
      } else if (normStatus === 'DELIVERED') {
        statusBadgeClass = 'bg-emerald-100 text-emerald-800 border-emerald-200';
        statusIcon = 'verified';
        displayStatusLabel = '5. Delivered';
      } else if (normStatus === 'CANCELLED') {
        statusBadgeClass = 'bg-rose-100 text-rose-800 border-rose-200';
        statusIcon = 'cancel';
        displayStatusLabel = 'Cancelled';
      }

      const staffDisplayName = ord.staffName || ord.staff_name || ord.createdBy || ord.created_by || 'Super Admin';
      const staffAvatar = staffDisplayName.split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase() || 'SA';

      return `
        <tr class="hover:bg-slate-50/80 transition border-b border-slate-100">
          <!-- 1. Order ID & Date -->
          <td class="py-3.5 px-4 font-mono font-bold text-slate-900 whitespace-nowrap">
            <div class="flex items-center gap-1.5">
              <span class="text-xs text-brand-wa font-black">${ord.id}</span>
              <button onclick="navigator.clipboard.writeText('${ord.id}'); if(typeof showToast==='function') showToast('Copied', 'Order ID copied', 'content_copy', 'emerald')" class="text-slate-400 hover:text-slate-600 cursor-pointer" title="Copy Order ID">
                <span class="material-symbols-outlined text-[14px]">content_copy</span>
              </button>
            </div>
            <div class="text-[10px] font-normal text-slate-400 mt-0.5">${ord.createdAt || 'Recent'}</div>
          </td>

          <!-- 2. Customer Details -->
          <td class="py-3.5 px-4">
            <div class="flex items-center gap-2.5">
              <div class="w-8 h-8 rounded-full bg-slate-100 text-slate-700 font-bold text-xs flex items-center justify-center shrink-0 border border-slate-200">
                ${(ord.customerName || 'CU').slice(0, 2).toUpperCase()}
              </div>
              <div>
                <div class="font-extrabold text-slate-900 text-xs">${ord.customerName || 'Customer'}</div>
                <div class="text-[10px] font-mono text-slate-500">${ord.customerPhone || ord.customer_phone || ''}</div>
                ${ord.shippingAddress ? `<div class="text-[10px] text-slate-400 truncate max-w-[200px]" title="${ord.shippingAddress}">📍 ${ord.shippingAddress}</div>` : ''}
              </div>
            </div>
          </td>

          <!-- 3. Which Staff Taken That Order -->
          <td class="py-3 px-4 whitespace-nowrap">
            <div class="flex items-center gap-2.5">
              <div class="w-8 h-8 rounded-xl bg-gradient-to-br from-indigo-700 to-indigo-900 text-white font-black text-xs flex items-center justify-center shrink-0 shadow-2xs">
                ${staffAvatar}
              </div>
              <div>
                <div class="font-extrabold text-slate-900 text-xs">${staffDisplayName}</div>
                <div class="text-[10px] text-indigo-700 font-medium flex items-center gap-1">
                  <span class="w-1.5 h-1.5 rounded-full bg-indigo-500"></span>
                  <span>Booking Specialist</span>
                </div>
              </div>
            </div>
            ${(typeof canUserPerformAction === 'function' && canUserPerformAction('orders', 'edit')) ? `
            <!-- Inline Quick Staff Reassignment Dropdown -->
            <div class="mt-1.5 flex items-center gap-1.5">
              <span class="text-[9px] text-slate-400 font-extrabold uppercase">Credit:</span>
              <select onchange="reassignOrderStaff('${ord.id}', this.value)" class="text-[10px] font-bold bg-indigo-50/80 hover:bg-indigo-100 text-indigo-950 border border-indigo-200/90 rounded-md px-1.5 py-0.5 outline-none cursor-pointer" title="Reassign order credit to another staff specialist">
                ${(() => {
                  const sList = [...(CRM_STATE?.staffList || [])];
                  if (!sList.some(s => s.id === 'admin')) sList.push({ id: 'admin', name: 'Super Admin' });
                  const curId = ord.staffId || ord.staff_id || (staffDisplayName.includes('Admin') ? 'admin' : '');
                  return sList.map(s => `<option value="${s.id}" ${s.id === curId || s.name === staffDisplayName ? 'selected' : ''}>${s.name}</option>`).join('');
                })()}
              </select>
            </div>` : ''}
          </td>

          <!-- 4. Ordered Items -->
          <td class="py-3 px-4 text-slate-700 text-xs min-w-[240px] max-w-md">
            <div class="space-y-1.5">
              ${ordItems.map(i => {
                const matchedProd = (CRM_STATE?.products || []).find(p => p.sku === i.sku || p.name === i.name);
                const fallbackImg = 'https://images.unsplash.com/photo-1596755094514-f87e34085b2c?w=120&auto=format&fit=crop&q=60';
                const imgUrl = i.image || matchedProd?.image || matchedProd?.imageUrl || (matchedProd?.images && matchedProd.images[0]) || fallbackImg;
                const safeImg = (imgUrl || '').replace(/'/g, "\\'");
                const safeName = (i.name || 'Garment Item').replace(/"/g, '&quot;');
                const unitPrice = parseFloat(i.price || matchedProd?.price || 0);
                const qty = parseInt(i.qty || 1);
                const lineTotal = unitPrice * qty;

                return `
                  <div class="flex items-center gap-2.5 p-1.5 bg-slate-50/90 hover:bg-slate-100/90 rounded-xl border border-slate-200/80 transition">
                    <div class="relative shrink-0">
                      <img src="${imgUrl}" alt="${safeName}" class="w-11 h-11 rounded-lg object-cover border border-slate-200 shadow-2xs bg-white cursor-pointer hover:scale-105 transition" onclick="if(typeof openImageLightbox==='function') openImageLightbox('${safeImg}', '${safeName}')" onerror="this.onerror=null; this.src='${fallbackImg}';">
                      <span class="absolute -top-1.5 -right-1.5 bg-emerald-700 text-white font-black text-[9px] px-1.5 py-0.2 rounded-full font-mono shadow-xs">x${qty}</span>
                    </div>
                    <div class="min-w-0 flex-1">
                      <div class="font-extrabold text-slate-900 text-xs truncate" title="${safeName}">${safeName}</div>
                      <div class="flex items-center gap-1.5 text-[10px] text-slate-500 mt-0.5 flex-wrap">
                        <span class="font-mono bg-white px-1.5 py-0.2 rounded border border-slate-200 font-bold text-slate-700">${i.sku || 'SKU'}</span>
                        ${i.size ? `<span class="bg-indigo-50 text-indigo-700 px-1 rounded font-bold">${i.size}</span>` : ''}
                        ${unitPrice > 0 ? `<span class="font-mono font-bold text-emerald-800 ml-auto">₹${lineTotal.toLocaleString('en-IN')}</span>` : ''}
                      </div>
                    </div>
                  </div>
                `;
              }).join('')}
            </div>
          </td>

          <!-- 5. Payment Details -->
          <td class="py-3.5 px-4 whitespace-nowrap">
            ${amountHtml}
            ${paymentHtml}
          </td>

          <!-- 6. Order Status -->
          <td class="py-3.5 px-4 whitespace-nowrap">
            <div class="space-y-1.5">
              <span class="text-[10px] font-extrabold px-2.5 py-1 rounded-full border ${statusBadgeClass} inline-flex items-center gap-1 shadow-2xs">
                <span class="material-symbols-outlined text-[13px]">${statusIcon}</span>
                <span>${displayStatusLabel}</span>
              </span>

              ${(typeof canUserPerformAction === 'function' && canUserPerformAction('orders', 'edit')) ? `
              <div>
                ${(() => {
                  const stageMap = { 'PLACED': 1, 'PACKED': 2, 'SHIPPED': 3, 'OUT_FOR_DELIVERY': 4, 'DELIVERED': 5 };
                  const curStep = stageMap[normStatus] || 1;
                  const stages = [
                    { val: 'PLACED', label: '1. Placed', step: 1 },
                    { val: 'PACKED', label: '2. Packed', step: 2 },
                    { val: 'SHIPPED', label: '3. Shipped', step: 3 },
                    { val: 'OUT_FOR_DELIVERY', label: '4. Out for Delivery', step: 4 },
                    { val: 'DELIVERED', label: '5. Delivered', step: 5 }
                  ];
                  return `
                    <select onchange="handleOrderStatusChange('${ord.id}', this.value, this)" class="text-[10px] font-bold bg-slate-100 hover:bg-slate-200 text-slate-800 border border-slate-300 rounded px-1.5 py-0.5 outline-none cursor-pointer">
                      ${stages.map(s => {
                        const isSelected = (normStatus === s.val);
                        const isDisabled = (s.step < curStep || s.step > curStep + 1);
                        return `<option value="${s.val}" ${isSelected ? 'selected' : ''} ${isDisabled ? 'disabled style="color:#94a3b8;background-color:#f1f5f9;"' : ''}>${s.label}</option>`;
                      }).join('')}
                    </select>
                  `;
                })()}
              </div>
              ` : ''}
              ${(normStatus === 'SHIPPED' || normStatus === 'OUT_FOR_DELIVERY') ? `
                <div class="mt-1 flex items-center gap-1 flex-wrap">
                  <span class="text-[9px] font-bold bg-amber-50 text-amber-900 border border-amber-200 px-1.5 py-0.5 rounded flex items-center gap-1" title="Courier: ${ord.courierName || 'Courier'}">
                    <span class="material-symbols-outlined text-[11px]">local_shipping</span>
                    ${ord.courierName || 'Courier'}: <strong class="font-mono">${ord.trackingNumber || 'N/A'}</strong>
                  </span>
                  ${ord.shippingUrl ? `
                    <a href="${ord.shippingUrl}" target="_blank" class="text-[9px] font-extrabold text-emerald-700 hover:text-emerald-900 hover:underline inline-flex items-center gap-0.5 bg-emerald-50 border border-emerald-200 px-1 py-0.5 rounded cursor-pointer" title="Open live parcel tracking">
                      Track <span class="material-symbols-outlined text-[10px]">open_in_new</span>
                    </a>
                  ` : ''}
                </div>
              ` : ''}
            </div>
          </td>

          <!-- 7. Actions -->
          <td class="py-3.5 px-4 text-right whitespace-nowrap">
            <div class="flex items-center justify-end gap-1.5">
              ${(typeof canUserPerformAction === 'function' && canUserPerformAction('orders', 'edit')) ? `
              <button type="button" onclick="openEditOrderModal('${ord.id}')" class="px-2 py-1 bg-blue-50 hover:bg-blue-100 text-blue-800 rounded-lg text-xs font-bold transition flex items-center gap-1 cursor-pointer border border-blue-300" title="Edit Order Details">
                <span class="material-symbols-outlined text-[14px]">edit</span>
                <span class="text-[11px]">Edit</span>
              </button>
              ` : ''}

              ${(typeof canUserPerformAction === 'function' && canUserPerformAction('orders', 'delete')) ? `
              <button type="button" onclick="confirmDeleteOrder('${ord.id}')" class="px-2 py-1 bg-rose-50 hover:bg-rose-100 text-rose-800 rounded-lg text-xs font-bold transition flex items-center gap-1 cursor-pointer border border-rose-300" title="Delete Order">
                <span class="material-symbols-outlined text-[14px]">delete</span>
                <span class="text-[11px]">Delete</span>
              </button>
              ` : ''}

              ${(typeof canUserPerformAction === 'function' && canUserPerformAction('orders', 'view')) ? `
              <!-- View Packing Slip -->
              <button type="button" onclick="openOrderPackingSlipModal('${ord.id}')" class="px-2 py-1 bg-teal-50 hover:bg-teal-100 text-teal-800 rounded-lg text-xs font-bold transition flex items-center gap-1 cursor-pointer border border-teal-300" title="View &amp; Print Packing Slip">
                <span class="material-symbols-outlined text-[14px]">local_shipping</span>
                <span class="text-[11px]">Slip</span>
              </button>

              <!-- View Invoice -->
              <button type="button" onclick="openOrderInvoiceModal('${ord.id}')" class="px-2 py-1 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-xs font-bold transition flex items-center gap-1 cursor-pointer border border-slate-300" title="View Tax Invoice &amp; Packing Slip">
                <span class="material-symbols-outlined text-[14px]">receipt_long</span>
                <span class="text-[11px]">Invoice</span>
              </button>

              <!-- Chat -->
              <button type="button" onclick="selectCustomerChat('${ord.customerId}'); switchView('inbox');" class="px-2 py-1 bg-emerald-50 hover:bg-emerald-100 text-emerald-800 rounded-lg text-xs font-bold transition flex items-center gap-1 cursor-pointer border border-emerald-300" title="Chat on WhatsApp">
                <span class="material-symbols-outlined text-[14px]">chat</span>
                <span class="hidden sm:inline text-[11px]">Chat</span>
              </button>
              ` : ''}
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  // Render Mobile Cards View (< md)
  if (mobileContainer) {
    mobileContainer.innerHTML = filteredOrders.map(ord => {
      let ordItems = ord.items || [];
      if (typeof ordItems === 'string') {
        try { ordItems = JSON.parse(ordItems); } catch(e) { ordItems = []; }
      }
      if (!Array.isArray(ordItems) && ord.items_json && typeof ord.items_json === 'string') {
        try { ordItems = JSON.parse(ord.items_json); } catch(e) { ordItems = []; }
      }
      if (!Array.isArray(ordItems)) ordItems = [];

      const normStatus = normalizeOrderStatus(ord.orderStatus || ord.order_status);
      const isOnline = ord.paymentMethod === 'ONLINE_UPI' || ord.paymentMethod === 'UPI' || ord.payment_method === 'ONLINE_UPI' || ord.payment_method === 'UPI';
      const isCod = ord.paymentMethod === 'COD' || ord.payment_method === 'COD';
      const grandTotal = parseFloat(ord.grandTotal || ord.grand_total) || 0;
      const codAdv = parseFloat(ord.codAdvance || ord.cod_advance) || 200;
      const codDue = ord.codBalanceDue !== undefined ? parseFloat(ord.codBalanceDue) : Math.max(0, grandTotal - codAdv);

      let statusBadgeClass = 'bg-blue-100 text-blue-800 border-blue-200';
      let statusIcon = 'receipt';
      let displayStatusLabel = '1. Placed';
      if (normStatus === 'PACKED') {
        statusBadgeClass = 'bg-purple-100 text-purple-800 border-purple-200';
        statusIcon = 'inventory_2';
        displayStatusLabel = '2. Packed';
      } else if (normStatus === 'SHIPPED') {
        statusBadgeClass = 'bg-amber-100 text-amber-900 border-amber-300';
        statusIcon = 'local_shipping';
        displayStatusLabel = '3. Shipped';
      } else if (normStatus === 'OUT_FOR_DELIVERY') {
        statusBadgeClass = 'bg-orange-100 text-orange-900 border-orange-300';
        statusIcon = 'two_wheeler';
        displayStatusLabel = '4. Out for Delivery';
      } else if (normStatus === 'DELIVERED') {
        statusBadgeClass = 'bg-emerald-100 text-emerald-800 border-emerald-200';
        statusIcon = 'verified';
        displayStatusLabel = '5. Delivered';
      } else if (normStatus === 'CANCELLED') {
        statusBadgeClass = 'bg-rose-100 text-rose-800 border-rose-200';
        statusIcon = 'cancel';
        displayStatusLabel = 'Cancelled';
      }

      const staffDisplayName = ord.staffName || ord.staff_name || ord.createdBy || ord.created_by || 'Super Admin';
      const staffAvatar = staffDisplayName.split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase() || 'SA';

      const badgeColor = isOnline ? 'bg-emerald-100 text-emerald-800 border-emerald-200' : 'bg-amber-100 text-amber-900 border-amber-300';
      const badgeLabel = isOnline ? '🟢 ONLINE (PAID)' : '🟠 COD (₹200 ADV)';

      const stageMap = { 'PLACED': 1, 'PACKED': 2, 'SHIPPED': 3, 'OUT_FOR_DELIVERY': 4, 'DELIVERED': 5 };
      const curStep = stageMap[normStatus] || 1;
      const stages = [
        { val: 'PLACED', label: '1. Placed', step: 1 },
        { val: 'PACKED', label: '2. Packed', step: 2 },
        { val: 'SHIPPED', label: '3. Shipped', step: 3 },
        { val: 'OUT_FOR_DELIVERY', label: '4. Out for Delivery', step: 4 },
        { val: 'DELIVERED', label: '5. Delivered', step: 5 }
      ];

      return `
        <div class="bg-white rounded-2xl border border-slate-200 p-3.5 shadow-sm space-y-3">
          <!-- Card Header: ID, Date & Status Pill -->
          <div class="flex items-center justify-between gap-2 border-b border-slate-100 pb-2.5">
            <div>
              <div class="flex items-center gap-1.5">
                <span class="text-xs text-brand-wa font-black font-mono">${ord.id}</span>
                <button type="button" onclick="navigator.clipboard.writeText('${ord.id}'); if(typeof showToast==='function') showToast('Copied', 'Order ID copied', 'content_copy', 'emerald')" class="text-slate-400 hover:text-slate-600 p-0.5 cursor-pointer">
                  <span class="material-symbols-outlined text-[13px]">content_copy</span>
                </button>
              </div>
              <div class="text-[10px] text-slate-400 font-normal mt-0.5">${ord.createdAt || 'Recent'}</div>
            </div>
            <span class="text-[10px] font-extrabold px-2.5 py-1 rounded-full border ${statusBadgeClass} inline-flex items-center gap-1 shrink-0">
              <span class="material-symbols-outlined text-[12px]">${statusIcon}</span>
              <span>${displayStatusLabel}</span>
            </span>
          </div>

          <!-- Customer & Staff Row -->
          <div class="grid grid-cols-2 gap-2 bg-slate-50/70 p-2.5 rounded-xl border border-slate-100 text-xs">
            <!-- Customer -->
            <div class="min-w-0">
              <div class="text-[10px] uppercase font-bold text-slate-400">Customer</div>
              <div class="font-extrabold text-slate-900 truncate mt-0.5">${ord.customerName || 'Customer'}</div>
              <div class="text-[10px] font-mono text-slate-500">${ord.customerPhone || ord.customer_phone || ''}</div>
              ${ord.shippingAddress ? `<div class="text-[10px] text-slate-400 truncate mt-0.5" title="${ord.shippingAddress}">📍 ${ord.shippingAddress}</div>` : ''}
            </div>

            <!-- Staff Specialist -->
            <div class="min-w-0 border-l border-slate-200/80 pl-2.5">
              <div class="text-[10px] uppercase font-bold text-slate-400">Staff Taken</div>
              <div class="flex items-center gap-1.5 mt-0.5">
                <div class="w-5 h-5 rounded-md bg-indigo-700 text-white font-bold text-[9px] flex items-center justify-center shrink-0">
                  ${staffAvatar}
                </div>
                <div class="font-bold text-slate-800 text-[11px] truncate">${staffDisplayName}</div>
              </div>
              ${(typeof canUserPerformAction === 'function' && canUserPerformAction('orders', 'edit')) ? `
                <div class="mt-1">
                  <select onchange="reassignOrderStaff('${ord.id}', this.value)" class="text-[9px] font-bold bg-white text-indigo-950 border border-indigo-200 rounded px-1 py-0.5 w-full outline-none cursor-pointer">
                    ${(() => {
                      const sList = [...(CRM_STATE?.staffList || [])];
                      if (!sList.some(s => s.id === 'admin')) sList.push({ id: 'admin', name: 'Super Admin' });
                      const curId = ord.staffId || ord.staff_id || (staffDisplayName.includes('Admin') ? 'admin' : '');
                      return sList.map(s => `<option value="${s.id}" ${s.id === curId || s.name === staffDisplayName ? 'selected' : ''}>${s.name}</option>`).join('');
                    })()}
                  </select>
                </div>
              ` : ''}
            </div>
          </div>

          <!-- Items Ordered Section -->
          <div class="space-y-1.5">
            <div class="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Ordered Items (${ordItems.length})</div>
            ${ordItems.map(i => {
              const matchedProd = (CRM_STATE?.products || []).find(p => p.sku === i.sku || p.name === i.name);
              const fallbackImg = 'https://images.unsplash.com/photo-1596755094514-f87e34085b2c?w=120&auto=format&fit=crop&q=60';
              const imgUrl = i.image || matchedProd?.image || matchedProd?.imageUrl || (matchedProd?.images && matchedProd.images[0]) || fallbackImg;
              const safeImg = (imgUrl || '').replace(/'/g, "\\'");
              const safeName = (i.name || 'Garment Item').replace(/"/g, '&quot;');
              const unitPrice = parseFloat(i.price || matchedProd?.price || 0);
              const qty = parseInt(i.qty || 1);
              const lineTotal = unitPrice * qty;

              return `
                <div class="flex items-center gap-2.5 p-2 bg-slate-50 rounded-xl border border-slate-100">
                  <div class="relative shrink-0">
                    <img src="${imgUrl}" alt="${safeName}" class="w-10 h-10 rounded-lg object-cover border border-slate-200 bg-white cursor-pointer" onclick="if(typeof openImageLightbox==='function') openImageLightbox('${safeImg}', '${safeName}')" onerror="this.onerror=null; this.src='${fallbackImg}';">
                    <span class="absolute -top-1.5 -right-1.5 bg-emerald-700 text-white font-black text-[9px] px-1 py-0.2 rounded-full font-mono">x${qty}</span>
                  </div>
                  <div class="min-w-0 flex-1">
                    <div class="font-extrabold text-slate-900 text-xs truncate">${safeName}</div>
                    <div class="flex items-center gap-1.5 text-[10px] text-slate-500 mt-0.5 flex-wrap">
                      <span class="font-mono bg-white px-1 rounded border border-slate-200 font-bold text-slate-700">${i.sku || 'SKU'}</span>
                      ${i.size ? `<span class="bg-indigo-50 text-indigo-700 px-1 rounded font-bold">${i.size}</span>` : ''}
                      ${unitPrice > 0 ? `<span class="font-mono font-bold text-emerald-800 ml-auto">₹${lineTotal.toLocaleString('en-IN')}</span>` : ''}
                    </div>
                  </div>
                </div>
              `;
            }).join('')}
          </div>

          <!-- Payment & Totals Summary -->
          <div class="bg-slate-50 p-2.5 rounded-xl border border-slate-200/80 flex items-center justify-between gap-2 flex-wrap">
            <div>
              <div class="text-[10px] text-slate-400 font-bold uppercase">Total Amount</div>
              <div class="font-mono font-black text-slate-900 text-sm">₹${grandTotal.toLocaleString('en-IN')}</div>
              ${isCod ? `
                <div class="text-[10px] text-amber-800 font-semibold flex items-center gap-1 mt-0.5">
                  <span class="bg-emerald-100 text-emerald-800 px-1 rounded font-bold">₹${codAdv} Adv</span>
                  <span>&bull;</span>
                  <span class="bg-amber-100 text-amber-900 px-1 rounded font-bold">₹${codDue.toLocaleString('en-IN')} Due</span>
                </div>
              ` : ''}
            </div>

            <div class="flex flex-col items-end gap-1">
              <div class="flex items-center gap-1.5">
                <span class="text-[10px] font-extrabold px-2 py-0.5 rounded-full border ${badgeColor}">
                  ${badgeLabel}
                </span>
                ${ord.paymentScreenshot ? `
                  <button type="button" onclick="if(typeof openOrderReceiptLightbox==='function') openOrderReceiptLightbox('${ord.id}')" class="p-0.5 rounded border border-slate-200 bg-white" title="View receipt">
                    <img src="${ord.paymentScreenshot}" alt="Proof" class="w-6 h-6 rounded object-cover">
                  </button>
                ` : ''}
              </div>
              ${ord.upiTransactionId ? `
                <div class="text-[9px] font-mono text-slate-600">
                  <span class="text-slate-400">UTR:</span>
                  <span class="font-bold bg-white px-1 rounded border border-slate-200 cursor-pointer" onclick="navigator.clipboard.writeText('${ord.upiTransactionId}'); if(typeof showToast==='function') showToast('Copied', 'UPI UTR copied to clipboard', 'content_copy', 'emerald')">${ord.upiTransactionId}</span>
                </div>
              ` : ''}
            </div>
          </div>

          <!-- Status Selector & Tracking (if applicable) -->
          <div class="flex items-center justify-between gap-2 pt-1">
            <div class="flex items-center gap-1.5 flex-1 min-w-0">
              <span class="text-[10px] font-bold text-slate-400 uppercase shrink-0">Stage:</span>
              ${(typeof canUserPerformAction === 'function' && canUserPerformAction('orders', 'edit')) ? `
                <select onchange="handleOrderStatusChange('${ord.id}', this.value, this)" class="text-[11px] font-bold bg-slate-100 text-slate-800 border border-slate-300 rounded-lg px-2 py-1 outline-none w-full cursor-pointer">
                  ${stages.map(s => {
                    const isSelected = (normStatus === s.val);
                    const isDisabled = (s.step < curStep || s.step > curStep + 1);
                    return `<option value="${s.val}" ${isSelected ? 'selected' : ''} ${isDisabled ? 'disabled style="color:#94a3b8;background-color:#f1f5f9;"' : ''}>${s.label}</option>`;
                  }).join('')}
                </select>
              ` : `<span class="text-xs font-bold text-slate-700">${displayStatusLabel}</span>`}
            </div>

            ${(normStatus === 'SHIPPED' || normStatus === 'OUT_FOR_DELIVERY') && ord.shippingUrl ? `
              <a href="${ord.shippingUrl}" target="_blank" class="text-[10px] font-extrabold text-emerald-700 bg-emerald-50 border border-emerald-200 px-2 py-1 rounded-lg shrink-0 flex items-center gap-0.5">
                Track <span class="material-symbols-outlined text-[11px]">open_in_new</span>
              </a>
            ` : ''}
          </div>

          <!-- Action Buttons Bar -->
          <div class="flex items-center gap-1.5 pt-2 border-t border-slate-100 flex-wrap">
            ${(typeof canUserPerformAction === 'function' && canUserPerformAction('orders', 'edit')) ? `
              <button type="button" onclick="openEditOrderModal('${ord.id}')" class="flex-1 min-w-[70px] py-1.5 px-2 bg-blue-50 hover:bg-blue-100 text-blue-800 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1 border border-blue-200 cursor-pointer">
                <span class="material-symbols-outlined text-[15px]">edit</span>
                <span>Edit</span>
              </button>
            ` : ''}

            ${(typeof canUserPerformAction === 'function' && canUserPerformAction('orders', 'delete')) ? `
              <button type="button" onclick="confirmDeleteOrder('${ord.id}')" class="flex-1 min-w-[70px] py-1.5 px-2 bg-rose-50 hover:bg-rose-100 text-rose-800 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1 border border-rose-200 cursor-pointer">
                <span class="material-symbols-outlined text-[15px]">delete</span>
                <span>Delete</span>
              </button>
            ` : ''}

            ${(typeof canUserPerformAction === 'function' && canUserPerformAction('orders', 'view')) ? `
              <button type="button" onclick="openOrderPackingSlipModal('${ord.id}')" class="flex-1 min-w-[65px] py-1.5 px-2 bg-teal-50 hover:bg-teal-100 text-teal-800 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1 border border-teal-200 cursor-pointer">
                <span class="material-symbols-outlined text-[15px]">local_shipping</span>
                <span>Slip</span>
              </button>

              <button type="button" onclick="openOrderInvoiceModal('${ord.id}')" class="flex-1 min-w-[65px] py-1.5 px-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1 border border-slate-200 cursor-pointer">
                <span class="material-symbols-outlined text-[15px]">receipt_long</span>
                <span>Invoice</span>
              </button>

              <button type="button" onclick="selectCustomerChat('${ord.customerId}'); switchView('inbox');" class="flex-1 min-w-[65px] py-1.5 px-2 bg-emerald-50 hover:bg-emerald-100 text-emerald-800 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1 border border-emerald-200 cursor-pointer">
                <span class="material-symbols-outlined text-[15px]">chat</span>
                <span>Chat</span>
              </button>
            ` : ''}
          </div>
        </div>
      `;
    }).join('');
  }
  if (typeof enforceGranularActionPermissions === 'function') {
    enforceGranularActionPermissions();
  }
}
window.renderOrdersHistoryTable = renderOrdersHistoryTable;

function updateOrderStatus(orderId, newStatus) {
  const isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!isSuperAdmin && typeof canUserPerformAction === 'function' && !canUserPerformAction('orders', 'edit')) {
    if (typeof showToast === 'function') showToast('Permission Denied', 'Your assigned role does not have permission to update order status.', 'lock', 'rose');
    return;
  }

  // Strict Validation: Only the 5 standard stages + CANCELLED are permitted
  const validStatuses = ['PLACED', 'PACKED', 'SHIPPED', 'OUT_FOR_DELIVERY', 'DELIVERED', 'CANCELLED'];
  if (!validStatuses.includes(newStatus)) {
    if (typeof showToast === 'function') showToast('Invalid Status', `"${newStatus}" is not a valid order status value.`, 'error', 'rose');
    return;
  }

  const ord = (CRM_STATE?.orders || []).find(o => o.id === orderId);
  if (!ord) return;

  const oldStatus = ord.orderStatus || ord.order_status;
  // Strict isolated update: modify ONLY this specific order's status
  ord.orderStatus = newStatus;
  ord.order_status = newStatus;

  // Sync to MySQL backend
  fetch('api.php?action=update_order_status', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      id: orderId,
      order_id: orderId,
      order_status: newStatus,
      status: newStatus,
      user: CURRENT_USER?.name || 'Super Admin'
    })
  }).catch(() => { });

  logAudit('ORDER_STATUS_UPDATED', 'ORDERS', `Order ${orderId} status changed from ${oldStatus} to ${newStatus}`);
  saveCRMState();
  renderOrdersDashboard();
  renderOrdersHistoryTable();

  const statusLabels = {
    PLACED: '1. Placed',
    PACKED: '2. Packed',
    SHIPPED: '3. Shipped',
    OUT_FOR_DELIVERY: '4. Out for Delivery',
    DELIVERED: '5. Delivered',
    CANCELLED: 'Cancelled'
  };
  const label = statusLabels[newStatus] || newStatus;
  showToast('Order Status Updated', `Order ${orderId} marked as ${label}.`, 'check_circle', 'emerald');
  if (typeof playChime === 'function') playChime('order');
}
window.updateOrderStatus = updateOrderStatus;

let ACTIVE_SHIPPING_DISPATCH_ORDER = null;

/**
 * Intercepts order status change from dropdown.
 * If user selected 'SHIPPED', opens dispatch popup instead of directly saving!
 */
function handleOrderStatusChange(orderId, newStatus, selectEl) {
  const isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!isSuperAdmin && typeof canUserPerformAction === 'function' && !canUserPerformAction('orders', 'edit')) {
    if (typeof showToast === 'function') showToast('Permission Denied', 'Your assigned role does not have permission to change order status.', 'lock', 'rose');
    if (selectEl) selectEl.value = selectEl.getAttribute('data-prev') || selectEl.value;
    return;
  }
  const ord = (CRM_STATE?.orders || []).find(o => o.id === orderId);
  if (!ord) return;

  if (newStatus === 'SHIPPED') {
    // Intercept 3. Shipped to open the Shipping Dispatch Modal for entering Courier & Tracking Details
    openShippingDispatchModal(orderId);
    return;
  }

  // Directly update to whatever status admin selected dynamically
  updateOrderStatus(orderId, newStatus);
}
window.handleOrderStatusChange = handleOrderStatusChange;

/**
 * Opens Shipping Dispatch popup with Courier Name, Tracking ID, and Tracking URL
 */
function openShippingDispatchModal(orderId) {
  const isSuperAdmin = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER && (CURRENT_USER.role === 'admin' || CURRENT_USER.role === 'Super Admin'));
  if (!isSuperAdmin && typeof canUserPerformAction === 'function' && !canUserPerformAction('orders', 'edit')) {
    if (typeof showToast === 'function') showToast('Permission Denied', 'Your assigned role does not have permission to edit shipping or tracking details.', 'lock', 'rose');
    return;
  }
  const ord = (CRM_STATE?.orders || []).find(o => o.id === orderId);
  if (!ord) {
    showToast('Order Not Found', `Cannot find order #${orderId}`, 'error', 'rose');
    return;
  }

  ACTIVE_SHIPPING_DISPATCH_ORDER = ord;

  // Populate Order & Customer Info
  const idEl = document.getElementById('ship-modal-order-id');
  const custEl = document.getElementById('ship-modal-customer-name');
  const phoneEl = document.getElementById('ship-modal-customer-phone');
  const totalEl = document.getElementById('ship-modal-items-total');
  const addrEl = document.getElementById('ship-modal-address');

  if (idEl) idEl.innerText = ord.id;
  if (custEl) custEl.innerText = ord.customerName || 'Customer';
  if (phoneEl) phoneEl.innerText = ord.customerPhone || 'N/A';
  if (totalEl) totalEl.innerText = `₹${(parseFloat(ord.grandTotal) || 0).toLocaleString('en-IN')} (${(ord.items || []).length} items)`;
  if (addrEl) addrEl.innerText = ord.shippingAddress || 'Store Pickup / Direct WhatsApp';

  // Reset and hide custom courier input box
  toggleAddCustomCourierInput(false);

  // Populate inputs with existing or default values
  const courierInput = document.getElementById('ship-courier-name');
  const trackingInput = document.getElementById('ship-tracking-id');
  const urlInput = document.getElementById('ship-tracking-url');
  const waCheck = document.getElementById('ship-send-whatsapp');

  // Load custom couriers from localStorage into dropdown
  try {
    const savedCouriers = JSON.parse(localStorage.getItem('GRM_CUSTOM_COURIERS') || '[]');
    if (Array.isArray(savedCouriers) && courierInput) {
      const existingVals = new Set(Array.from(courierInput.options).map(o => o.value.toLowerCase()));
      savedCouriers.forEach(cName => {
        if (cName && !existingVals.has(cName.toLowerCase())) {
          const opt = document.createElement('option');
          opt.value = cName;
          opt.textContent = cName;
          courierInput.appendChild(opt);
          existingVals.add(cName.toLowerCase());
        }
      });
    }
  } catch (e) {}

  const defaultCourier = ord.courierName || ord.courier_name || 'ST Courier';
  // If order courier is custom and not yet in select, add it dynamically
  if (defaultCourier && courierInput) {
    const exists = Array.from(courierInput.options).some(o => o.value.toLowerCase() === defaultCourier.toLowerCase());
    if (!exists) {
      const opt = document.createElement('option');
      opt.value = defaultCourier;
      opt.textContent = defaultCourier;
      courierInput.appendChild(opt);
    }
  }
  // Tracking number must be empty by default because courier partner provides it
  const defaultTracking = ord.trackingNumber || ord.tracking_number || '';

  if (courierInput) courierInput.value = defaultCourier;
  if (trackingInput) trackingInput.value = defaultTracking;
  if (urlInput) {
    urlInput.value = ord.shippingUrl || ord.shipping_url || (defaultTracking ? generateCourierTrackingURL(defaultCourier, defaultTracking) : '');
  }
  if (waCheck) waCheck.checked = true;

  updateShippingWhatsAppPreview();

  openModal('modal-order-shipping-dispatch');
}
window.openShippingDispatchModal = openShippingDispatchModal;

function setCourierQuickOption(courierName) {
  const courierInput = document.getElementById('ship-courier-name');
  const trackingInput = document.getElementById('ship-tracking-id');
  const urlInput = document.getElementById('ship-tracking-url');

  if (courierInput) courierInput.value = courierName;
  // Tracking number must be provided by courier partner - DO NOT auto-generate fake AWB
  const trkVal = (trackingInput?.value || '').trim();
  if (urlInput) {
    urlInput.value = trkVal ? generateCourierTrackingURL(courierName, trkVal) : '';
  }
  updateShippingWhatsAppPreview();
}
window.setCourierQuickOption = setCourierQuickOption;

function onShippingIdChange() {
  const courierInput = document.getElementById('ship-courier-name');
  const trackingInput = document.getElementById('ship-tracking-id');
  const urlInput = document.getElementById('ship-tracking-url');

  if (courierInput && trackingInput && urlInput) {
    const courier = (courierInput.value || '').trim();
    const trackingId = (trackingInput.value || '').trim();
    if (trackingId) {
      urlInput.value = generateCourierTrackingURL(courier, trackingId);
    } else {
      urlInput.value = '';
    }
  }
  updateShippingWhatsAppPreview();
}
window.onShippingIdChange = onShippingIdChange;

function onShippingCourierChange(courierName) {
  const trackingInput = document.getElementById('ship-tracking-id');
  const urlInput = document.getElementById('ship-tracking-url');
  const trkVal = (trackingInput?.value || '').trim();

  if (urlInput) {
    urlInput.value = trkVal ? generateCourierTrackingURL(courierName, trkVal) : '';
  }
  updateShippingWhatsAppPreview();
}
window.onShippingCourierChange = onShippingCourierChange;

function toggleAddCustomCourierInput(forceState) {
  const box = document.getElementById('add-custom-courier-box');
  const input = document.getElementById('new-courier-name-input');
  if (!box) return;

  const isHidden = box.classList.contains('hidden') || box.style.display === 'none' || window.getComputedStyle(box).display === 'none';
  const shouldShow = (typeof forceState === 'boolean') ? forceState : isHidden;

  if (shouldShow) {
    box.classList.remove('hidden');
    box.style.display = 'block';
    if (input) {
      input.value = '';
      setTimeout(() => {
        input.focus();
        try { box.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); } catch (e) {}
      }, 50);
    }
  } else {
    box.classList.add('hidden');
    box.style.display = 'none';
  }
}
window.toggleAddCustomCourierInput = toggleAddCustomCourierInput;

function addNewCourierPartnerOption() {
  const input = document.getElementById('new-courier-name-input');
  const select = document.getElementById('ship-courier-name');
  if (!input || !select) return;

  const name = input.value.trim();
  if (!name) {
    if (typeof showToast === 'function') {
      showToast('Courier Name Required', 'Please enter a courier partner name.', 'warning', 'amber');
    } else {
      alert('Please enter a courier partner name.');
    }
    input.focus();
    return;
  }

  // Check if already in options
  let exists = false;
  for (let i = 0; i < select.options.length; i++) {
    if (select.options[i].value.toLowerCase() === name.toLowerCase()) {
      select.selectedIndex = i;
      exists = true;
      break;
    }
  }

  if (!exists) {
    const opt = document.createElement('option');
    opt.value = name;
    opt.textContent = name;
    select.appendChild(opt);
    select.value = name;

    // Save custom courier in localStorage
    try {
      const saved = JSON.parse(localStorage.getItem('GRM_CUSTOM_COURIERS') || '[]');
      if (!saved.some(s => s.toLowerCase() === name.toLowerCase())) {
        saved.push(name);
        localStorage.setItem('GRM_CUSTOM_COURIERS', JSON.stringify(saved));
      }
    } catch (e) {}
  }

  // Recalculate tracking URL & preview
  onShippingCourierChange(name);

  // Close input box
  toggleAddCustomCourierInput(false);

  if (typeof showToast === 'function') {
    showToast('Courier Added', `"${name}" added and selected.`, 'success', 'emerald');
  }
}
window.addNewCourierPartnerOption = addNewCourierPartnerOption;

function generateSampleAWB(courier) {
  const cleanCourier = (courier || 'ST').toUpperCase();
  const randNum = Math.floor(10000000 + Math.random() * 90000000);
  if (cleanCourier.includes('DTDC')) return `D${randNum}`;
  if (cleanCourier.includes('DELHIVERY')) return `DEL${randNum}`;
  if (cleanCourier.includes('BLUE')) return `BD${randNum}`;
  if (cleanCourier.includes('ST')) return `STC${randNum}`;
  if (cleanCourier.includes('PROFESSIONAL')) return `TPC${randNum}`;
  if (cleanCourier.includes('POST')) return `EM${randNum}IN`;
  return `TRK-${randNum}`;
}
window.generateSampleAWB = generateSampleAWB;

function generateCourierTrackingURL(courier, trackingId) {
  const c = (courier || '').toLowerCase();
  const id = encodeURIComponent((trackingId || '').trim());
  if (!id) return '';

  if (c.includes('dtdc')) {
    return `https://www.dtdc.in/tracking/shipment-tracking.asp?strCnno=${id}`;
  }
  if (c.includes('delhivery')) {
    return `https://www.delhivery.com/track/package/${id}`;
  }
  if (c.includes('blue')) {
    return `https://www.bluedart.com/tracking?track=${id}`;
  }
  if (c.includes('st') || c.includes('stcourier')) {
    return `https://stcourier.com/track/search?awb=${id}`;
  }
  if (c.includes('professional') || c.includes('tpc')) {
    return `https://www.tpcindia.com/track.aspx?awb=${id}`;
  }
  if (c.includes('post') || c.includes('speed')) {
    return `https://www.indiapost.gov.in/_layouts/15/dpt.cpt.trackconsignment/trackconsignment.aspx?id=${id}`;
  }
  return `https://track.aftership.com/${id}`;
}
window.generateCourierTrackingURL = generateCourierTrackingURL;

