function switchSettingsTab(tab) {
  const tabQr = document.getElementById('settings-tab-qr');
  const tabManual = document.getElementById('settings-tab-manual');
  const btnQr = document.getElementById('tab-btn-qr');
  const btnManual = document.getElementById('tab-btn-manual');

  if (tab === 'qr') {
    if (tabQr) tabQr.classList.remove('hidden');
    if (tabManual) tabManual.classList.add('hidden');
    if (btnQr) btnQr.className = "w-full px-3.5 py-2.5 bg-brand-wa text-white text-xs font-bold rounded-xl shadow-sm flex items-center justify-center gap-2 transition text-center cursor-pointer";
    if (btnManual) btnManual.className = "w-full px-3.5 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-bold rounded-xl transition flex items-center justify-center gap-2 text-center cursor-pointer";
    fetchQRBridgeStatus();
  } else {
    if (tabQr) tabQr.classList.add('hidden');
    if (tabManual) tabManual.classList.remove('hidden');
    if (btnQr) btnQr.className = "w-full px-3.5 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-bold rounded-xl transition flex items-center justify-center gap-2 text-center cursor-pointer";
    if (btnManual) btnManual.className = "w-full px-3.5 py-2.5 bg-brand-wa text-white text-xs font-bold rounded-xl shadow-sm flex items-center justify-center gap-2 transition text-center cursor-pointer";
  }
}

// Updates UI with Bridge Status & QR Code (used by both Socket.IO and REST Polling)
function updateQRBridgeUI(res) {
  if (!res) return;
  const qrImg = document.getElementById('qr-code-image');
  const spinner = document.getElementById('qr-loading-spinner');
  const connectedBox = document.getElementById('qr-connected-box');
  const statusText = document.getElementById('qr-bridge-status-text');
  const phoneDisplay = document.getElementById('qr-connected-phone-display');

  if (res.connection === 'SCAN_QR' && res.qr_image) {
    if (qrImg) {
      qrImg.src = res.qr_image;
      qrImg.classList.remove('hidden');
    }
    if (spinner) spinner.classList.add('hidden');
    if (connectedBox) connectedBox.classList.add('hidden');
    if (statusText) statusText.innerText = 'Bridge Status: Scan QR Code with WhatsApp on Phone';
  } else if (res.connection === 'CONNECTED') {
    if (qrImg) qrImg.classList.add('hidden');
    if (spinner) spinner.classList.add('hidden');
    if (connectedBox) connectedBox.classList.remove('hidden');
    if (phoneDisplay) phoneDisplay.innerText = res.connected_number || CRM_STATE.whatsappAccount.phoneNumber;
    if (statusText) statusText.innerText = `Bridge Status: Connected to ${res.connected_number || CRM_STATE.whatsappAccount.phoneNumber}`;

    if (res.connected_number && CRM_STATE.whatsappAccount.phoneNumber !== res.connected_number) {
      CRM_STATE.whatsappAccount.phoneNumber = res.connected_number;
      saveCRMState();
      updateConfiguredPhoneDisplays();
    }
  } else {
    if (qrImg) qrImg.classList.add('hidden');
    if (spinner) spinner.classList.remove('hidden');
    if (connectedBox) connectedBox.classList.add('hidden');
    if (statusText) statusText.innerText = 'Bridge Status: Initializing WhatsApp Socket...';
  }
}

// Poll Bridge Server on http://localhost:3000/api/qr/status
function fetchQRBridgeStatus(btnEl) {
  const icon = (btnEl ? btnEl.querySelector('.material-symbols-outlined') : null) ||
    document.querySelector('#view-settings button[onclick*="fetchQRBridgeStatus"] .material-symbols-outlined') ||
    document.getElementById('btn-refresh-whatsapp-settings')?.querySelector('.material-symbols-outlined');
  if (icon) icon.classList.add('animate-spin');
  if (btnEl) btnEl.disabled = true;

  const bUrl = getBridgeBaseUrl();
  const isLocalHost = (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1');
  const canDirectFetchBridge = Boolean(bUrl && (isLocalHost || bUrl.startsWith('https://')));

  if (canDirectFetchBridge) {
    const qrAbort = (typeof AbortController !== "undefined") ? new AbortController() : null;
    const qrTimer = qrAbort ? setTimeout(() => qrAbort.abort(), 4000) : null;
    fetch(`${bUrl}/api/qr/status`, qrAbort ? { signal: qrAbort.signal } : {})
      .then(r => {
        if (qrTimer) clearTimeout(qrTimer);
        return r.json();
      })
      .then(res => {
        if (res.status === 'success' && Array.isArray(res.accounts)) {
          applyUpdatedAccountsDelta(res.accounts, true);
          updateQRBridgeUI(res);
          const primary = res.accounts.find(a => a.id === 'account_1') || res.accounts[0];
          if (primary) {
            updateQRBridgeUI({
              connection: primary.status,
              connected_number: primary.connected_number || primary.phone,
              qr_image: primary.qr_image
            });
          }
        }
      })
      .catch((err) => {
        // Direct bridge fetch failed or timed out: Safely retain in-memory status quo without demoting accounts to DISCONNECTED
        console.warn('[fetchQRBridgeStatus] Bridge poll blip or timeout (preserving connected state):', err);
      })
      .finally(() => {
        renderMultiAccountsHub();
        renderQuickLineSwitcher();
        renderPhoneSwitcherDropdown();
        if (icon) icon.classList.remove('animate-spin');
        if (btnEl) {
          btnEl.disabled = false;
          showToast('WhatsApp Lines Refreshed', 'Live multi-account connection status checked.', 'sync', 'emerald');
        }
      });
  } else {
    // Hosted server fallback (e.g. Hostinger / MariaDB) - Fast dedicated accounts query (<5ms)
    fetch('api.php?action=get_whatsapp_accounts')
      .then(r => r.json())
      .then(res => {
        const rawList = res.accounts || res.whatsappAccounts || (res.data && res.data.whatsappAccounts) || [];
        if (Array.isArray(rawList) && rawList.length > 0) {
          const accounts = rawList.map(a => ({
            id: a.account_slot || a.id,
            name: a.display_name || a.account_name || a.name || 'WhatsApp Line',
            label: a.display_name || a.account_name || a.name || 'WhatsApp Line',
            phone: a.phone_number || a.phone || '',
            status: (a.status || 'DISCONNECTED').toUpperCase(),
            qr_image: a.qr_code || a.qr_image || null,
            connected_number: a.phone_number || a.phone || 'Awaiting Link'
          }));
          applyUpdatedAccountsDelta(accounts, false);
          const primary = accounts.find(a => a.id === 'account_1') || accounts[0];
          if (primary) {
            updateQRBridgeUI({
              connection: primary.status,
              connected_number: primary.phone,
              qr_image: primary.qr_image
            });
          }
        }
        if (res.whatsappAccount) {
          CRM_STATE.whatsappAccount = Object.assign(CRM_STATE.whatsappAccount || {}, res.whatsappAccount);
          saveCRMState();
          updateConfiguredPhoneDisplays();
        }
      })
      .catch(() => {
        // Fallback safely to in-memory accounts without secondary network latency
        const accounts = getAvailableWhatsAppAccounts();
        if (accounts.length > 0) {
          applyUpdatedAccountsDelta(accounts, false);
        }
      })
      .finally(() => {
        renderMultiAccountsHub();
        renderQuickLineSwitcher();
        renderPhoneSwitcherDropdown();
        if (icon) icon.classList.remove('animate-spin');
        if (btnEl) {
          btnEl.disabled = false;
          showToast('WhatsApp Lines Refreshed', 'Connected lines synchronized with database.', 'sync', 'emerald');
        }
      });
  }
}
window.fetchQRBridgeStatus = fetchQRBridgeStatus;

function refreshQRCodeBridge() {
  fetch(`${getBridgeBaseUrl()}/api/accounts/refresh_qr`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ accountId: 'account_1' })
  })
    .then(() => {
      showToast('Refreshing QR Code...', 'Generating fresh scan QR code', 'qr_code_scanner', 'emerald');
      setTimeout(fetchQRBridgeStatus, 1200);
    })
    .catch(() => {
      showToast('Bridge Offline', 'Make sure Node.js bridge server is running on port 3000', 'warning', 'rose');
    });
}

