// 6. Handle Staff Onboarding (Sub-item 2: Add Staff)
window.handleCreateNewStaff = handleCreateNewStaff;
function handleCreateNewStaff(event) {
  event.preventDefault();
  if (!canUserPerformAction('staff', 'create')) {
    showToast('Permission Denied', 'Your assigned role does not have permission to create staff.', 'lock', 'rose');
    return;
  }
  const nameEl = document.getElementById('staff-new-name');
  const emailEl = document.getElementById('staff-new-email');
  const phoneEl = document.getElementById('staff-new-phone');
  const roleEl = document.getElementById('staff-new-role');
  const specEl = document.getElementById('staff-new-specialization');
  const statusEl = document.getElementById('staff-new-status');
  const passwordInput = document.getElementById('staff-new-password');

  const name = nameEl ? nameEl.value.trim() : '';
  const email = emailEl ? emailEl.value.trim() : '';
  const phone = phoneEl ? phoneEl.value.trim() : '';
  const role = roleEl ? roleEl.value : 'Sales Specialist';
  const specialization = (specEl && specEl.value.trim()) ? specEl.value.trim() : 'General';
  const status = statusEl ? statusEl.value : 'ACTIVE';
  const password = passwordInput && passwordInput.value.trim() ? passwordInput.value.trim() : 'staff123';

  const assignedLineEl = document.getElementById('staff-new-assigned-line');
  const assignedLine = assignedLineEl ? assignedLineEl.value : 'ALL';

  if (!name || !phone) {
    showToast('Missing Fields', 'Please enter staff name and phone number.', 'warning', 'amber');
    return;
  }

  if (!password) {
    showToast('Password Required', 'Please enter a login password for the staff member.', 'warning', 'amber');
    return;
  }

  if (!Array.isArray(CRM_STATE.staffList)) {
    CRM_STATE.staffList = [];
  }

  // Collect all staff IDs ever used across staffList, orders, queries, and reserved IDs
  const usedIds = new Set(['staff_01', 'staff_02', 'staff_03']);
  (CRM_STATE.staffList || []).forEach(s => { if (s && s.id) usedIds.add(s.id); });
  (CRM_STATE.orders || []).forEach(o => { if (o && o.staffId) usedIds.add(o.staffId); });
  (CRM_STATE.queries || []).forEach(q => {
    if (q && q.assignedTo && q.assignedTo !== 'UNASSIGNED') usedIds.add(q.assignedTo);
    if (q && q.staffId && q.staffId !== 'UNASSIGNED') usedIds.add(q.staffId);
  });

  let nextNum = 1;
  let newStaffId = `staff_${String(nextNum).padStart(2, '0')}`;
  while (usedIds.has(newStaffId)) {
    nextNum++;
    newStaffId = `staff_${String(nextNum).padStart(2, '0')}`;
  }
  const avatarInitials = name.split(' ').map(n => n[0]).filter(Boolean).join('').substring(0, 2).toUpperCase() || 'ST';

  const newStaff = {
    id: newStaffId,
    name: name,
    email: email || `${name.toLowerCase().replace(/[^a-z0-9]/g, '.')}@grmgarments.com`,
    phone: phone,
    role: role,
    specialization: specialization,
    password: password,
    avatar: avatarInitials,
    dailyQuota: 70,
    todayHandled: 0,
    status: status || 'ACTIVE',
    assignedLine: assignedLine,
    permissions: null,
    createdAt: new Date().toISOString()
  };

  CRM_STATE.staffList.push(newStaff);
  saveCRMState();

  // Persist to MySQL database via api.php
  fetch('api.php?action=create_staff', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      id: newStaffId,
      username: newStaffId,
      name: name,
      email: newStaff.email,
      phone: phone,
      password: password,
      role: role,
      specialization: specialization,
      avatar: avatarInitials,
      status: status,
      assignedLine: assignedLine,
      permissions: null
    })
  }).then(r => r.json()).then(res => {
    console.log('[create_staff] Server response:', res);
  }).catch(err => {
    console.warn('[create_staff] Background server sync error:', err);
  });

  logAudit('STAFF_ONBOARDED', 'STAFF_MODULE', `Super Admin onboarded new staff member: ${name} (${newStaffId}, Role: ${role})`);

  if (event.target && typeof event.target.reset === 'function') {
    event.target.reset();
  }

  // Update counters and dropdowns
  const staffCountBadge = document.getElementById('badge-total-staff-count');
  if (staffCountBadge) staffCountBadge.innerText = CRM_STATE.staffList.length;
  const navSubCount = document.getElementById('nav-sub-staff-count');
  if (navSubCount) navSubCount.innerText = CRM_STATE.staffList.length;

  populateAllStaffDropdowns();
  updateStaffRoleSelectDropdowns();
  renderStaffTable();
  if (typeof renderDashboard === 'function') renderDashboard(); // auto-sync staff count

  if (typeof window.switchStaffSubmodule === 'function') window.switchStaffSubmodule('list'); else if (typeof switchStaffSubmodule === 'function') switchStaffSubmodule('list'); else if (typeof switchStaffTab === 'function') switchStaffTab('list');
  if (typeof playChime === 'function') playChime('order');
  showToast('Staff Member Onboarded!', `${name} successfully added to team roster (${newStaffId}).`, 'person_add', 'emerald');
}

// 7. GRANULAR ROLE-BASED ACCESS CONTROL MATRIX ENGINE (Sub-item 3: Role Base)

// Render Permissions Matrix for selected Role
function renderRolePermissionsMatrix(roleName) {
  initRolePermissionsState();
  const definedRoles = Object.keys(CRM_STATE.rolePermissions || {}).filter(r => r && r.trim() && !LEGACY_HARDCODED_DEMO_ROLES.includes(r));
  const targetRole = roleName || (definedRoles.includes(ACTIVE_MATRIX_ROLE) ? ACTIVE_MATRIX_ROLE : (definedRoles.find(r => r !== 'Super Admin') || definedRoles[0] || 'Super Admin'));
  ACTIVE_MATRIX_ROLE = targetRole;

  // 1. Populate Role Selector
  const roleSelect = document.getElementById('role-matrix-role-select');
  if (roleSelect) {
    roleSelect.innerHTML = definedRoles.map(r => `
      <option value="${r}" ${r === targetRole ? 'selected' : ''}>${r}</option>
    `).join('');
  }

  // Sync Role Name Input Field
  const roleInput = document.getElementById('role-input-name');
  if (roleInput) {
    roleInput.value = targetRole || '';
    if (targetRole === 'Super Admin') {
      roleInput.setAttribute('disabled', 'true');
      roleInput.title = 'Super Admin is a permanent system role';
    } else {
      roleInput.removeAttribute('disabled');
      roleInput.title = '';
    }
  }

  // 2. Count staff assigned to this role
  const assignedStaffCount = (CRM_STATE.staffList || []).filter(s => s.role === targetRole).length;
  const countBadge = document.getElementById('role-staff-count-badge');
  if (countBadge) {
    countBadge.innerText = `${assignedStaffCount} Staff Assigned`;
  }

  // 3. Delete role button visibility (hide for protected Super Admin)
  const btnDeleteRole = document.getElementById('btn-delete-role');
  if (btnDeleteRole) {
    const isSystemRole = targetRole === 'Super Admin';
    if (!isSystemRole) btnDeleteRole.classList.remove('hidden');
    else btnDeleteRole.classList.add('hidden');
  }

  // 4. Ensure role has permission entry
  if (!CRM_STATE.rolePermissions[targetRole]) {
    CRM_STATE.rolePermissions[targetRole] = createRoleDefaultPermissions(targetRole, targetRole === 'Super Admin');
  }
  const perms = CRM_STATE.rolePermissions[targetRole];

  // 5. Populate Table Body with all Active Modules
  const tbody = document.getElementById('role-matrix-table-body');
  if (!tbody) return;

  tbody.innerHTML = CRM_MODULE_DEFINITIONS.map((mod, idx) => {
    const modPerm = perms[mod.key] || { view: false, create: false, edit: false, delete: false };
    const isViewOnlyMod = mod.key === 'audit' || Boolean(mod.viewOnly);
    const allChecked = isViewOnlyMod ? Boolean(modPerm.view) : (modPerm.view && modPerm.create && modPerm.edit && modPerm.delete);
    const isSuperAdmin = targetRole === 'Super Admin';

    return `
      <tr class="hover:bg-slate-50/70 transition ${idx % 2 === 0 ? 'bg-white' : 'bg-slate-50/30'}">
        <!-- Module Info -->
        <td class="py-2.5 sm:py-3 px-3 sm:px-4">
          <div class="flex items-center gap-2 sm:gap-2.5">
            <span class="w-6 h-6 sm:w-7 sm:h-7 rounded-lg bg-slate-100 text-slate-700 flex items-center justify-center shrink-0">
              <span class="material-symbols-outlined text-[15px] sm:text-[17px]">${mod.icon}</span>
            </span>
            <div class="min-w-0">
              <span class="font-bold text-slate-900 text-xs block truncate">${mod.name}</span>
              <span class="text-[10px] text-slate-400 block truncate">${mod.desc}</span>
            </div>
          </div>
        </td>

        <!-- View Action Checkbox -->
        <td class="py-2.5 sm:py-3 px-2 sm:px-3 text-center">
          <label class="inline-flex items-center justify-center p-1 rounded-lg hover:bg-sky-50 cursor-pointer">
            <input type="checkbox" id="role-mod-view-${mod.key}" ${modPerm.view ? 'checked' : ''} ${isSuperAdmin ? 'disabled checked' : ''}
              onchange="handleToggleModuleAction('${mod.key}', 'view', this.checked)"
              class="w-4 h-4 text-sky-600 rounded border-slate-300 focus:ring-sky-500 cursor-pointer">
          </label>
        </td>

        <!-- Create Action Checkbox (Removed for Customer 360) -->
        <td class="py-2.5 sm:py-3 px-2 sm:px-3 text-center">
          ${isViewOnlyMod ? `
            <span class="text-xs text-slate-300 font-bold select-none" title="Create action not applicable for this module">—</span>
          ` : `
            <label class="inline-flex items-center justify-center p-1 rounded-lg hover:bg-emerald-50 cursor-pointer">
              <input type="checkbox" id="role-mod-create-${mod.key}" ${modPerm.create ? 'checked' : ''} ${isSuperAdmin ? 'disabled checked' : ''}
                onchange="handleToggleModuleAction('${mod.key}', 'create', this.checked)"
                class="w-4 h-4 text-emerald-600 rounded border-slate-300 focus:ring-emerald-500 cursor-pointer">
            </label>
          `}
        </td>

        <!-- Edit Action Checkbox (Removed for Customer 360) -->
        <td class="py-2.5 sm:py-3 px-2 sm:px-3 text-center">
          ${isViewOnlyMod ? `
            <span class="text-xs text-slate-300 font-bold select-none" title="Edit action not applicable for this module">—</span>
          ` : `
            <label class="inline-flex items-center justify-center p-1 rounded-lg hover:bg-amber-50 cursor-pointer">
              <input type="checkbox" id="role-mod-edit-${mod.key}" ${modPerm.edit ? 'checked' : ''} ${isSuperAdmin ? 'disabled checked' : ''}
                onchange="handleToggleModuleAction('${mod.key}', 'edit', this.checked)"
                class="w-4 h-4 text-amber-600 rounded border-slate-300 focus:ring-amber-500 cursor-pointer">
            </label>
          `}
        </td>

        <!-- Delete Action Checkbox (Removed for Customer 360) -->
        <td class="py-2.5 sm:py-3 px-2 sm:px-3 text-center">
          ${isViewOnlyMod ? `
            <span class="text-xs text-slate-300 font-bold select-none" title="Delete action not applicable for this module">—</span>
          ` : `
            <label class="inline-flex items-center justify-center p-1 rounded-lg hover:bg-rose-50 cursor-pointer">
              <input type="checkbox" id="role-mod-delete-${mod.key}" ${modPerm.delete ? 'checked' : ''} ${isSuperAdmin ? 'disabled checked' : ''}
                onchange="handleToggleModuleAction('${mod.key}', 'delete', this.checked)"
                class="w-4 h-4 text-rose-600 rounded border-slate-300 focus:ring-rose-500 cursor-pointer">
            </label>
          `}
        </td>

        <!-- All Actions (Row Master Toggle) -->
        <td class="py-2.5 sm:py-3 px-3 sm:px-4 text-center">
          <label class="inline-flex items-center justify-center p-1 rounded-lg hover:bg-purple-50 cursor-pointer">
            <input type="checkbox" id="role-mod-all-${mod.key}" ${allChecked ? 'checked' : ''} ${isSuperAdmin ? 'disabled checked' : ''}
              onchange="handleToggleModuleAll('${mod.key}', this.checked)"
              class="w-4 h-4 text-purple-600 rounded border-slate-300 focus:ring-purple-500 cursor-pointer">
          </label>
        </td>
      </tr>
    `;
  }).join('');

  // Update column master header checkboxes
  if (typeof updateRoleMatrixHeaderCheckboxes === "function") {
    updateRoleMatrixHeaderCheckboxes();
  } else if (typeof window.updateRoleMatrixHeaderCheckboxes === "function") {
    window.updateRoleMatrixHeaderCheckboxes();
  }
}
window.renderRolePermissionsMatrix = renderRolePermissionsMatrix;

// 8. Event Handlers for Role Permissions Matrix
window.handleRoleSelectChange = function (newRole) {
  ACTIVE_MATRIX_ROLE = newRole;
  renderRolePermissionsMatrix(newRole);
};

// Update header checkboxes based on the current role's permission matrix
function updateRoleMatrixHeaderCheckboxes() {
  window.updateRoleMatrixHeaderCheckboxes = updateRoleMatrixHeaderCheckboxes;
  const rolePerms = (CRM_STATE.rolePermissions && CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE]) || {};
  const isSuperAdmin = ACTIVE_MATRIX_ROLE === 'Super Admin';
  const totalMods = (CRM_MODULE_DEFINITIONS || []).length;

  ['view', 'create', 'edit', 'delete'].forEach(action => {
    const el = document.getElementById(`role-header-${action}`);
    if (!el) return;

    if (isSuperAdmin) {
      el.checked = true;
      el.disabled = true;
      el.indeterminate = false;
      return;
    }
    el.disabled = false;

    let count = 0;
    let totalEligible = 0;
    CRM_MODULE_DEFINITIONS.forEach(mod => {
      if ((mod.key === 'audit' || mod.viewOnly) && action !== 'view') return;
      totalEligible++;
      if (rolePerms[mod.key] && rolePerms[mod.key][action]) {
        count++;
      }
    });

    if (count === totalEligible && totalEligible > 0) {
      el.checked = true;
      el.indeterminate = false;
    } else if (count > 0) {
      el.checked = false;
      el.indeterminate = true;
    } else {
      el.checked = false;
      el.indeterminate = false;
    }
  });

  const allHeaderEl = document.getElementById('role-header-all');
  if (allHeaderEl) {
    if (isSuperAdmin) {
      allHeaderEl.checked = true;
      allHeaderEl.disabled = true;
      allHeaderEl.indeterminate = false;
      return;
    }
    allHeaderEl.disabled = false;

    let totalCells = 0;
    let checkedCells = 0;
    CRM_MODULE_DEFINITIONS.forEach(mod => {
      const p = rolePerms[mod.key] || {};
      totalCells += 1;
      if (p.view) checkedCells++;
      if (mod.key !== 'customers' && !mod.viewOnly) {
        totalCells += 3;
        if (p.create) checkedCells++;
        if (p.edit) checkedCells++;
        if (p.delete) checkedCells++;
      }
    });

    if (checkedCells === totalCells && totalCells > 0) {
      allHeaderEl.checked = true;
      allHeaderEl.indeterminate = false;
    } else if (checkedCells > 0) {
      allHeaderEl.checked = false;
      allHeaderEl.indeterminate = true;
    } else {
      allHeaderEl.checked = false;
      allHeaderEl.indeterminate = false;
    }
  }
};

// Toggle an action (view, create, edit, delete, or all) across ALL 12 modules
window.handleToggleActionForAllModules = function (action, isChecked) {
  initRolePermissionsState();
  if (ACTIVE_MATRIX_ROLE === 'Super Admin') {
    showToast('Super Admin Locked', 'Super Admin always retains full system access.', 'info', 'purple');
    renderRolePermissionsMatrix(ACTIVE_MATRIX_ROLE);
    return;
  }

  if (!CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE]) {
    CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE] = {};
  }

  const rolePerms = CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE];

  CRM_MODULE_DEFINITIONS.forEach(mod => {
    if (!rolePerms[mod.key]) {
      rolePerms[mod.key] = { view: false, create: false, edit: false, delete: false };
    }

    if (mod.key === 'audit' || mod.viewOnly) {
      if (action === 'all' || action === 'view') {
        rolePerms[mod.key].view = isChecked;
      }
      rolePerms[mod.key].create = false;
      rolePerms[mod.key].edit = false;
      rolePerms[mod.key].delete = false;
      return;
    }

    if (action === 'all') {
      rolePerms[mod.key].view = isChecked;
      rolePerms[mod.key].create = isChecked;
      rolePerms[mod.key].edit = isChecked;
      rolePerms[mod.key].delete = isChecked;
    } else {
      rolePerms[mod.key][action] = isChecked;
      // Operational actions can be set independently for View-Only, Create-Only, Edit-Only, or Delete-Only modes
    }
  });

  saveCRMState();
  renderRolePermissionsMatrix(ACTIVE_MATRIX_ROLE);
  playChime('order');
  showToast(
    'Bulk Action Updated',
    `${isChecked ? 'Granted' : 'Revoked'} ${action.toUpperCase()} across all modules for "${ACTIVE_MATRIX_ROLE}".`,
    'tune',
    'purple'
  );
};

window.handleToggleModuleAction = function (moduleKey, action, isChecked) {
  initRolePermissionsState();
  if (ACTIVE_MATRIX_ROLE === 'Super Admin') return;

  if (!CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE]) {
    CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE] = {};
  }
  if (!CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE][moduleKey]) {
    CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE][moduleKey] = { view: false, create: false, edit: false, delete: false };
  }

  CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE][moduleKey][action] = isChecked;

  // Keep sub-modules of inbox (autoreply, broadcast, enquiries) in sync with inbox permissions
  if (moduleKey === 'inbox') {
    ['autoreply', 'broadcast', 'enquiries'].forEach(subKey => {
      if (!CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE][subKey]) {
        CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE][subKey] = { view: false, create: false, edit: false, delete: false };
      }
      CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE][subKey][action] = isChecked;
    });
  }

  // Update master all checkbox for this module
  const p = CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE][moduleKey];
  const allEl = document.getElementById(`role-mod-all-${moduleKey}`);
  if (allEl) allEl.checked = (p.view && p.create && p.edit && p.delete);

  // Keep column master header checkboxes in sync
  if (typeof updateRoleMatrixHeaderCheckboxes === "function") {
    updateRoleMatrixHeaderCheckboxes();
  } else if (typeof window.updateRoleMatrixHeaderCheckboxes === "function") {
    window.updateRoleMatrixHeaderCheckboxes();
  }

  // Auto-persist permission changes immediately
  try {
    saveCRMState();
    localStorage.setItem('CRM_ROLE_PERMISSIONS', JSON.stringify(CRM_STATE.rolePermissions));
    fetch('api.php?action=save_role_permissions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        role: ACTIVE_MATRIX_ROLE,
        permissions: CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE]
      })
    }).catch(() => { });
    if (typeof enforceGranularActionPermissions === 'function') {
      enforceGranularActionPermissions();
    }
  } catch (e) { }
};

window.handleToggleModuleAll = function (moduleKey, isChecked) {
  initRolePermissionsState();
  if (ACTIVE_MATRIX_ROLE === 'Super Admin') return;

  if (!CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE]) {
    CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE] = {};
  }

  if (moduleKey === 'audit') {
    CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE][moduleKey] = {
      view: isChecked,
      create: false,
      edit: false,
      delete: false
    };
  } else {
    CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE][moduleKey] = {
      view: isChecked,
      create: isChecked,
      edit: isChecked,
      delete: isChecked
    };
  }

  // Keep sub-modules of inbox in sync
  if (moduleKey === 'inbox') {
    ['autoreply', 'broadcast', 'enquiries'].forEach(subKey => {
      CRM_STATE.rolePermissions[ACTIVE_MATRIX_ROLE][subKey] = {
        view: isChecked,
        create: isChecked,
        edit: isChecked,
        delete: isChecked
      };
    });
  }
  renderRolePermissionsMatrix(ACTIVE_MATRIX_ROLE);
};

window.applyRolePreset = function (presetType) {
  initRolePermissionsState();
  const roleInput = document.getElementById('role-input-name');
  const targetRole = (roleInput && roleInput.value.trim()) ? roleInput.value.trim() : ACTIVE_MATRIX_ROLE;

  if (targetRole === 'Super Admin') {
    showToast('Super Admin Locked', 'Super Admin always retains 100% full system access.', 'info', 'purple');
    return;
  }

  const rolePerms = {};

  CRM_MODULE_DEFINITIONS.forEach(mod => {
    if (mod.key === 'audit' || mod.viewOnly) {
      const viewPerm = (presetType === 'all' || presetType === 'view_only' || (presetType === 'sales' && (mod.key === 'audit')));
      rolePerms[mod.key] = { view: viewPerm, create: false, edit: false, delete: false };
    } else if (presetType === 'all') {
      rolePerms[mod.key] = { view: true, create: true, edit: true, delete: true };
    } else if (presetType === 'view_only') {
      rolePerms[mod.key] = { view: true, create: false, edit: false, delete: false };
    } else if (presetType === 'create_only') {
      rolePerms[mod.key] = { view: false, create: true, edit: false, delete: false };
    } else if (presetType === 'edit_only') {
      rolePerms[mod.key] = { view: false, create: false, edit: true, delete: false };
    } else if (presetType === 'delete_only') {
      rolePerms[mod.key] = { view: false, create: false, edit: false, delete: true };
    } else if (presetType === 'sales') {
      const salesAllowed = ['inbox', 'followups', 'catalog', 'orders'];
      const isSalesMod = salesAllowed.includes(mod.key);
      if (mod.key === 'masking') {
        rolePerms[mod.key] = { view: true, create: true, edit: false, delete: false };
      } else {
        rolePerms[mod.key] = {
          view: isSalesMod,
          create: isSalesMod,
          edit: isSalesMod,
          delete: false
        };
      }
    } else if (presetType === 'reset') {
      rolePerms[mod.key] = { view: false, create: false, edit: false, delete: false };
    }
  });

  if (targetRole) {
    CRM_STATE.rolePermissions[targetRole] = rolePerms;
    ACTIVE_MATRIX_ROLE = targetRole;
    renderRolePermissionsMatrix(targetRole);
  } else {
    CRM_MODULE_DEFINITIONS.forEach(mod => {
      const p = rolePerms[mod.key] || {};
      const vEl = document.getElementById(`role-mod-view-${mod.key}`);
      const cEl = document.getElementById(`role-mod-create-${mod.key}`);
      const eEl = document.getElementById(`role-mod-edit-${mod.key}`);
      const dEl = document.getElementById(`role-mod-delete-${mod.key}`);
      const aEl = document.getElementById(`role-mod-all-${mod.key}`);
      if (vEl) vEl.checked = Boolean(p.view);
      if (cEl) cEl.checked = Boolean(p.create);
      if (eEl) eEl.checked = Boolean(p.edit);
      if (dEl) dEl.checked = Boolean(p.delete);
      if (aEl) aEl.checked = (p.view && p.create && p.edit && p.delete);
    });
    if (typeof updateRoleMatrixHeaderCheckboxes === 'function') {
      updateRoleMatrixHeaderCheckboxes();
    }
  }

  showToast('Preset Applied', `Applied ${presetType.toUpperCase()} permissions preset.`, 'tune', 'blue');
};

window.handleSaveRolePermissions = function () {
  if (!canUserPerformAction('staff', 'edit')) {
    showToast('Permission Denied', 'Your assigned role does not have permission to edit roles & permissions.', 'lock', 'rose');
    return;
  }
  initRolePermissionsState();

  const roleInput = document.getElementById('role-input-name');
  const inputVal = roleInput ? roleInput.value.trim() : '';
  const currentRole = inputVal || ACTIVE_MATRIX_ROLE;

  if (!currentRole) {
    alert('Please enter a role name to save.');
    if (roleInput) roleInput.focus();
    return;
  }

  // Collect checked permissions from the matrix table in DOM
  const perms = {};
  CRM_MODULE_DEFINITIONS.forEach(mod => {
    if (currentRole === 'Super Admin') {
      perms[mod.key] = { view: true, create: true, edit: true, delete: true };
      return;
    }
    const vEl = document.getElementById(`role-mod-view-${mod.key}`);
    const cEl = document.getElementById(`role-mod-create-${mod.key}`);
    const eEl = document.getElementById(`role-mod-edit-${mod.key}`);
    const dEl = document.getElementById(`role-mod-delete-${mod.key}`);
    const isViewOnly = mod.key === 'audit' || Boolean(mod.viewOnly);
    perms[mod.key] = {
      view: vEl ? Boolean(vEl.checked) : false,
      create: !isViewOnly && cEl ? Boolean(cEl.checked) : false,
      edit: !isViewOnly && eEl ? Boolean(eEl.checked) : false,
      delete: !isViewOnly && dEl ? Boolean(dEl.checked) : false
    };
  });

  // Keep sub-modules of inbox (autoreply, broadcast, enquiries) in sync
  if (perms['inbox']) {
    ['autoreply', 'broadcast', 'enquiries'].forEach(subKey => {
      perms[subKey] = Object.assign({}, perms['inbox']);
    });
  }

  CRM_STATE.rolePermissions[currentRole] = perms;
  ACTIVE_MATRIX_ROLE = currentRole;
  saveCRMState();

  // Persist to MySQL database
  fetch('api.php?action=save_role_permissions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      role: currentRole,
      permissions: perms
    })
  }).then(r => r.json()).then(res => {
    console.log('Role permissions saved to DB:', res);
  }).catch(() => { });

  logAudit('ROLE_PERMISSIONS_SAVED', 'ROLES', `Saved role & permissions for: "${currentRole}"`);

  // Re-apply live access control to current active user
  if (CURRENT_USER) {
    applyRoleBasedAccessControl(CURRENT_USER);
  }

  updateStaffRoleSelectDropdowns();
  renderRolePermissionsMatrix(currentRole);

  playChime('order');
  showToast(
    'Role & Permissions Saved!',
    `Role "${currentRole}" and its module permissions have been saved successfully.`,
    'verified_user',
    'emerald'
  );
  alert(`Role "${currentRole}" Successfully Saved!\n\nGranular module actions (View, Create, Edit, Delete) for role "${currentRole}" have been saved to MySQL and applied live.`);
};

window.handleCreateNewRolePrompt = function () {
  initRolePermissionsState();
  const roleInput = document.getElementById('role-input-name');
  if (roleInput) {
    roleInput.removeAttribute('disabled');
    roleInput.value = '';
    roleInput.focus();
  }
  ACTIVE_MATRIX_ROLE = '';
  // Default matrix to view_only for quick onboarding
  applyRolePreset('view_only');
  showToast('Create New Role', 'Type the role name in the Role Name input box, adjust module permissions, and click "Save Role".', 'add_circle', 'purple');
};

window.handleDeleteCurrentRole = function () {
  if (ACTIVE_MATRIX_ROLE === 'Super Admin') {
    showToast('Protected Role', 'Super Admin is a protected system role and cannot be deleted.', 'shield', 'amber');
    return;
  }

  const assignedStaff = (CRM_STATE.staffList || []).filter(s => s.role === ACTIVE_MATRIX_ROLE);
  if (assignedStaff.length > 0) {
    showConfirmDialog({
      title: 'Cannot Delete Role',
      subtitle: 'Staff Assigned',
      message: `Cannot delete role "${ACTIVE_MATRIX_ROLE}" because ${assignedStaff.length} staff member(s) are currently assigned to it.`,
      detail: 'Please reassign or edit the assigned staff members to another role first.',
      confirmText: 'Understood',
      cancelText: 'Close',
      icon: 'shield_lock',
      color: 'amber'
    });
    return;
  }

  showConfirmDialog({
    title: 'Delete Role',
    subtitle: 'Access Control Action',
    message: `Are you sure you want to permanently delete role "${ACTIVE_MATRIX_ROLE}"?`,
    detail: 'All permission grants configured for this role will be removed immediately.',
    confirmText: 'Yes, Delete Role',
    cancelText: 'Cancel',
    icon: 'delete_forever',
    color: 'rose',
    onConfirm: () => {
      const deletedRole = ACTIVE_MATRIX_ROLE;
      delete CRM_STATE.rolePermissions[deletedRole];

      // Delete role from MySQL
      fetch('api.php?action=delete_role_permissions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ role: deletedRole })
      }).then(r => r.json()).then(res => {
        console.log('[delete_role_permissions] Server response:', res);
      }).catch(() => { });

      const remainingRoles = Object.keys(CRM_STATE.rolePermissions);
      ACTIVE_MATRIX_ROLE = remainingRoles.find(r => r !== 'Super Admin') || remainingRoles[0] || 'Super Admin';
      saveCRMState();

      updateStaffRoleSelectDropdowns();
      if (ACTIVE_MATRIX_ROLE) {
        renderRolePermissionsMatrix(ACTIVE_MATRIX_ROLE);
      }

      showToast('Role Removed', `Role "${deletedRole}" was successfully deleted.`, 'delete', 'amber');
    }
  });
};

// 9. Synchronize Dynamic Role Select Dropdowns across CRM (Add Staff, Role Matrix, Reassign, Edit Staff)
function updateStaffRoleSelectDropdowns() {
  initRolePermissionsState();
  const allRoles = Object.keys(CRM_STATE.rolePermissions || {}).filter(r => r && r.trim() && !LEGACY_HARDCODED_DEMO_ROLES.includes(r));

  const roleAssignSelect = document.getElementById('role-assign-new-role');
  const staffNewRoleSelect = document.getElementById('staff-new-role');
  const editStaffRoleSelect = document.getElementById('edit-staff-role');
  const roleMatrixSelect = document.getElementById('role-matrix-role-select');
  const staffSelect = document.getElementById('role-assign-staff-select');

  // 1. Role to Assign dropdown: ONLY dynamically created / active roles
  if (roleAssignSelect) {
    if (allRoles.length === 0) {
      roleAssignSelect.innerHTML = '<option value="" disabled selected>No created roles yet — Click + Create New Role</option>';
    } else {
      roleAssignSelect.innerHTML = allRoles.map(r => `<option value="${r}">${r}</option>`).join('');
    }
  }

  // 2. Add Staff primary role dropdown: dynamically populated
  if (staffNewRoleSelect) {
    if (allRoles.length === 0) {
      staffNewRoleSelect.innerHTML = '<option value="" disabled selected>No created roles yet — Click + Create New Role</option>';
    } else {
      staffNewRoleSelect.innerHTML = allRoles.map(r => `<option value="${r}">${r}</option>`).join('');
    }
  }

  // 3. Edit Staff modal role dropdown: dynamically populated
  if (editStaffRoleSelect) {
    if (allRoles.length === 0) {
      editStaffRoleSelect.innerHTML = '<option value="" disabled selected>No created roles yet</option>';
    } else {
      editStaffRoleSelect.innerHTML = allRoles.map(r => `<option value="${r}">${r}</option>`).join('');
    }
  }

  // 4. Role Matrix selector: dynamically populated
  if (roleMatrixSelect) {
    const curVal = roleMatrixSelect.value;
    if (allRoles.length === 0) {
      roleMatrixSelect.innerHTML = '<option value="" disabled selected>No created roles</option>';
    } else {
      roleMatrixSelect.innerHTML = allRoles.map(r => `<option value="${r}" ${r === ACTIVE_MATRIX_ROLE ? 'selected' : ''}>${r}</option>`).join('');
      if (curVal && allRoles.includes(curVal)) {
        roleMatrixSelect.value = curVal;
      }
    }
  }

  // 5. Select staff member dropdown
  if (staffSelect) {
    const staffList = CRM_STATE.staffList || [];
    staffSelect.innerHTML = staffList.map(s => `
      <option value="${s.id}">${s.name} (${s.id}) &bull; Current: ${s.role}</option>
    `).join('');
  }

  populateAllStaffDropdowns();
}

function populateAllStaffDropdowns() {
  const staffList = CRM_STATE.staffList || [];

  // 1. enquiry-filter-staff
  const enquiryFilter = document.getElementById('enquiry-filter-staff');
  if (enquiryFilter) {
    const cur = enquiryFilter.value;
    enquiryFilter.innerHTML = '<option value="ALL">All Staff Members</option><option value="UNASSIGNED">Unassigned Only</option>' +
      staffList.map(s => `<option value="${s.id}">${s.name} (${s.id})</option>`).join('');
    if (cur) enquiryFilter.value = cur;
  }

  // 2. followup-filter-staff
  const followupFilter = document.getElementById('followup-filter-staff');
  if (followupFilter) {
    const cur = followupFilter.value;
    followupFilter.innerHTML = '<option value="ALL">👥 All Staff Members</option>' +
      staffList.map(s => `<option value="${s.id}">${s.name} (${s.id})</option>`).join('') +
      '<option value="admin">Super Admin</option>';
    if (cur) followupFilter.value = cur;
  }

  // 3. pay-pending-filter-staff
  const payFilter = document.getElementById('pay-pending-filter-staff');
  if (payFilter) {
    const cur = payFilter.value;
    payFilter.innerHTML = '<option value="ALL">👥 All Staff Members</option>' +
      staffList.map(s => `<option value="${s.id}">${s.name} (${s.id})</option>`).join('') +
      '<option value="admin">Super Admin</option>';
    if (cur) payFilter.value = cur;
  }

  // 4. sim-assign
  const simAssign = document.getElementById('sim-assign');
  if (simAssign) {
    const cur = simAssign.value;
    simAssign.innerHTML = '<option value="UNASSIGNED" selected>⚡ Unassigned (Goes to Admin Queue)</option>' +
      staffList.map(s => `<option value="${s.id}">Assign to ${s.name} (${s.id})</option>`).join('');
    if (cur) simAssign.value = cur;
  }

  // 5. followup-staff-select
  const fuSelect = document.getElementById('followup-staff-select');
  if (fuSelect) {
    const cur = fuSelect.value;
    fuSelect.innerHTML = staffList.map(s => `<option value="${s.id}">${s.name} (${s.id})</option>`).join('') +
      '<option value="admin">Super Admin</option>';
    if (cur) fuSelect.value = cur;
  }

  // 6. export-staff-filter
  const exportFilter = document.getElementById('export-staff-filter');
  if (exportFilter) {
    const cur = exportFilter.value;
    exportFilter.innerHTML = '<option value="ALL">👥 All Staff Members</option>' +
      staffList.map(s => `<option value="${s.id}">${s.name} (${s.id})</option>`).join('') +
      '<option value="admin">Super Admin</option>';
    if (cur) exportFilter.value = cur;
  }
}

// 11. Quick Role Reassign Action
function handleQuickRoleReassign(event) {
  event.preventDefault();
  const staffId = document.getElementById('role-assign-staff-select').value;
  const newRole = document.getElementById('role-assign-new-role').value;

  const staff = (CRM_STATE.staffList || []).find(s => s.id === staffId);
  if (!staff) return;

  const oldRole = staff.role;
  staff.role = newRole;

  // Persist role update to MySQL
  fetch('api.php?action=update_staff_role', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ staff_id: staffId, role: newRole })
  }).catch(() => { });

  logAudit('STAFF_ROLE_REASSIGNED', 'STAFF_MODULE', `Reassigned role of ${staff.name} from "${oldRole}" to "${newRole}"`);

  saveCRMState();
  updateStaffRoleSelectDropdowns();
  renderStaffTable();
  if (typeof renderDashboard === 'function') renderDashboard(); // auto-sync staff count
  renderRolePermissionsMatrix(newRole);

  playChime('order');
  showToast('Role Updated!', `${staff.name} is now assigned role: "${newRole}".`, 'admin_panel_settings', 'purple');
}

function quickAssignRoleForStaff(staffId) {
  switchStaffSubmodule('roles');
  const staffSelect = document.getElementById('role-assign-staff-select');
  if (staffSelect) {
    staffSelect.value = staffId;
  }
  const staff = (CRM_STATE.staffList || []).find(s => s.id === staffId);
  if (staff && staff.role) {
    ACTIVE_MATRIX_ROLE = staff.role;
    renderRolePermissionsMatrix(staff.role);
  }
}

function handleToggleStaffStatus(staffId) {
  const staff = (CRM_STATE.staffList || []).find(s => s.id === staffId);
  if (!staff) return;

  const newStatus = (staff.status || 'ACTIVE') === 'ACTIVE' ? 'ON_LEAVE' : 'ACTIVE';
  staff.status = newStatus;

  saveCRMState();
  renderStaffTable();
  if (typeof renderDashboard === 'function') renderDashboard(); // auto-sync staff count

  // Sync to MySQL
  fetch('api.php?action=create_staff', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(staff)
  }).catch(() => { });

  showToast('Status Updated', `${staff.name} is now ${newStatus === 'ACTIVE' ? 'Active on-duty' : 'On Leave'}.`, 'badge', 'sky');
}

function handleDeleteStaff(staffId) {
  if (!canUserPerformAction('staff', 'delete')) {
    showToast('Permission Denied', 'Your assigned role does not have permission to delete staff.', 'lock', 'rose');
    return;
  }
  const staff = (CRM_STATE.staffList || []).find(s => s.id === staffId);
  if (!staff) return;

  showConfirmDialog({
    title: 'Remove Staff Member',
    subtitle: 'Staff Directory Action',
    message: `Are you sure you want to remove ${staff.name} (${staffId}) from the staff directory?`,
    detail: 'This will remove the profile from your team roster and reassign any active customer leads.',
    confirmText: 'Yes, Remove Staff',
    cancelText: 'Cancel',
    icon: 'person_remove',
    color: 'rose',
    onConfirm: () => {
      CRM_STATE.staffList = (CRM_STATE.staffList || []).filter(s => s.id !== staffId);
      (CRM_STATE.queries || []).forEach(q => {
        if (q.assignedTo === staffId || q.staffId === staffId) {
          q.assignedTo = 'UNASSIGNED';
          q.staffId = 'UNASSIGNED';
          q.assignedStaffName = 'Unassigned';
        }
      });

      // Sync delete to MySQL
      fetch('api.php?action=delete_staff', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ staff_id: staffId })
      }).catch(() => { });

      logAudit('STAFF_REMOVED', 'STAFF_MODULE', `Removed staff member ${staff.name} (${staffId})`);
      saveCRMState();
      renderStaffTable();
      if (typeof renderDashboard === 'function') renderDashboard(); // auto-sync staff count
      updateStaffRoleSelectDropdowns();

      showToast('Staff Removed', `${staff.name} was removed from the team roster.`, 'delete', 'amber');
    }
  });
}

window.openEditStaffModal = function (staffId) {
  const staff = (CRM_STATE.staffList || []).find(s => s.id === staffId);
  if (!staff) {
    showToast('Staff Not Found', `Could not find staff member record ${staffId}.`, 'error', 'rose');
    return;
  }

  // Ensure role dropdowns have the dynamic roles
  updateStaffRoleSelectDropdowns();

  // Populate Assigned Line dropdown
  if (typeof populateStaffAssignedLineDropdowns === 'function') {
    populateStaffAssignedLineDropdowns();
  }

  const idInput = document.getElementById('edit-staff-id');
  const nameInput = document.getElementById('edit-staff-name');
  const emailInput = document.getElementById('edit-staff-email');
  const phoneInput = document.getElementById('edit-staff-phone');
  const roleSelect = document.getElementById('edit-staff-role');
  const specSelect = document.getElementById('edit-staff-specialization');
  const statusSelect = document.getElementById('edit-staff-status');
  const passInput = document.getElementById('edit-staff-password');
  const subtitle = document.getElementById('edit-staff-modal-subtitle');
  const assignedLineSelect = document.getElementById('edit-staff-assigned-line');

  if (idInput) idInput.value = staff.id;
  if (nameInput) nameInput.value = staff.name || '';
  if (emailInput) emailInput.value = staff.email || '';
  if (phoneInput) phoneInput.value = staff.phone || '';
  if (specSelect) specSelect.value = staff.specialization || 'General';
  if (statusSelect) statusSelect.value = (staff.status || 'ACTIVE').toUpperCase();
  if (passInput) passInput.value = '';
  if (subtitle) subtitle.innerText = `Edit details for ${staff.name} (${staff.id})`;
  if (assignedLineSelect) assignedLineSelect.value = staff.assignedLine || 'ALL';

  if (roleSelect) {
    if (staff.role && !Array.from(roleSelect.options).some(o => o.value === staff.role)) {
      const opt = document.createElement('option');
      opt.value = staff.role;
      opt.textContent = staff.role;
      roleSelect.appendChild(opt);
    }
    roleSelect.value = staff.role || (roleSelect.options[0] ? roleSelect.options[0].value : '');
  }

  openModal('modal-edit-staff');
};

window.handleSaveEditStaff = function (event) {
  event.preventDefault();
  const staffId = document.getElementById('edit-staff-id')?.value;
  const staff = (CRM_STATE.staffList || []).find(s => s.id === staffId);
  if (!staff) {
    showToast('Error', 'Staff member record not found.', 'error', 'rose');
    return;
  }

  const newName = document.getElementById('edit-staff-name')?.value?.trim();
  const newEmail = document.getElementById('edit-staff-email')?.value?.trim();
  const newPhone = document.getElementById('edit-staff-phone')?.value?.trim();
  const newRole = document.getElementById('edit-staff-role')?.value;
  const newSpec = document.getElementById('edit-staff-specialization')?.value;
  const newStatus = document.getElementById('edit-staff-status')?.value;
  const newPass = document.getElementById('edit-staff-password')?.value?.trim();
  const newAssignedLine = document.getElementById('edit-staff-assigned-line')?.value || 'ALL';

  if (!newName || !newPhone) {
    alert('Please enter staff name and phone number.');
    return;
  }

  const oldRole = staff.role;
  const oldName = staff.name;

  staff.name = newName;
  staff.email = newEmail;
  staff.phone = newPhone;
  staff.role = newRole;
  staff.specialization = newSpec;
  staff.status = newStatus;
  staff.assignedLine = newAssignedLine;
  staff.permissions = null;
  staff.avatar = newName.split(' ').map(n => n[0]).filter(Boolean).join('').substring(0, 2).toUpperCase() || 'ST';
  if (newPass) {
    staff.password = newPass;
  }

  // Update in queries if assigned
  (CRM_STATE.queries || []).forEach(q => {
    if (q.assignedTo === staffId || q.staffId === staffId) {
      q.assignedStaffName = newName;
    }
  });

  saveCRMState();

  // Persist to MySQL via update_staff
  fetch('api.php?action=update_staff', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      id: staffId,
      name: newName,
      email: newEmail,
      phone: newPhone,
      role: newRole,
      specialization: newSpec,
      status: newStatus,
      avatar: staff.avatar,
      assignedLine: newAssignedLine,
      permissions: null,
      password: newPass || undefined
    })
  }).then(r => r.json()).then(res => {
    console.log('[update_staff] Server sync response:', res);
  }).catch(err => {
    console.warn('[update_staff] Background server sync error:', err);
  });

  logAudit('STAFF_UPDATED', 'STAFF_MODULE', `Updated staff member ${oldName} (${staffId}) details: Role: ${newRole}, Dept: ${newSpec}`);

  closeModal('modal-edit-staff');
  renderStaffTable();
  populateAllStaffDropdowns();
  updateStaffRoleSelectDropdowns();
  if (typeof renderDashboard === 'function') renderDashboard();

  showToast('Staff Updated!', `Details for ${newName} successfully updated.`, 'check_circle', 'emerald');
};

function handleEditStaffPrompt(staffId) {
  openEditStaffModal(staffId);
}

// 12. Quota View Handlers
function renderStaffQuotaView() {
  const tbody = document.getElementById('staff-quota-table-body');
  if (!tbody) return;

  const staffList = CRM_STATE.staffList || [];
  const target = (CRM_STATE.dailyMessageTarget && CRM_STATE.dailyMessageTarget.expectedPerDay) || 200;
  const allocated = (CRM_STATE.dailyMessageTarget && CRM_STATE.dailyMessageTarget.allocatedPerDay) || 200;

  const expEl = document.getElementById('kpi-quota-expected');
  const allocEl = document.getElementById('kpi-quota-allocated');
  if (expEl) expEl.innerText = `${target} msgs / day`;
  if (allocEl) allocEl.innerText = `${allocated} / ${target} msgs`;

  tbody.innerHTML = staffList.map(s => {
    const q = s.dailyQuota || 70;
    const h = s.todayHandled || 0;
    const pct = q > 0 ? Math.min(100, Math.round((h / q) * 100)) : 0;

    return `
      <tr class="hover:bg-slate-50">
        <td class="py-3 px-4 font-bold text-slate-900">${s.name} (${s.id})</td>
        <td class="py-3 px-4 text-slate-600">${s.role}</td>
        <td class="py-3 px-4">
          <input type="number" id="quota-input-${s.id}" value="${q}" min="0" max="1000"
            class="w-24 p-1.5 bg-slate-50 border border-slate-300 rounded-lg font-mono font-bold text-xs">
        </td>
        <td class="py-3 px-4 font-mono font-bold text-slate-700">${h} msgs</td>
        <td class="py-3 px-4 font-bold ${pct >= 100 ? 'text-rose-600' : 'text-emerald-600'}">${pct}%</td>
        <td class="py-3 px-4 text-right">
          <button type="button" onclick="document.getElementById('quota-input-${s.id}').value = 70"
            class="px-2 py-1 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded text-[10px] font-bold">70</button>
          <button type="button" onclick="document.getElementById('quota-input-${s.id}').value = 100"
            class="px-2 py-1 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded text-[10px] font-bold ml-1">100</button>
        </td>
      </tr>
    `;
  }).join('');
}

function handleSaveDailyAllocations() {
  const staffList = CRM_STATE.staffList || [];
  let totalAllocated = 0;

  staffList.forEach(staff => {
    const input = document.getElementById(`quota-input-${staff.id}`);
    if (input) {
      staff.dailyQuota = parseInt(input.value, 10) || 0;
    }
    totalAllocated += (Number(staff.dailyQuota) || 0);
  });

  if (!CRM_STATE.dailyMessageTarget) {
    CRM_STATE.dailyMessageTarget = { expectedPerDay: 200, allocatedPerDay: totalAllocated, lastResetDate: new Date().toISOString().split('T')[0] };
  } else {
    CRM_STATE.dailyMessageTarget.allocatedPerDay = totalAllocated;
  }

  saveCRMState();
  renderStaffQuotaView();
  renderStaffTable();
  if (typeof renderDashboard === 'function') renderDashboard(); // auto-sync staff count
  playChime('order');
  showToast('Quota Allocations Saved!', `Allocated ${totalAllocated} daily message capacity.`, 'check_circle', 'emerald');
}



// =========================================================================
// 14. UTILITY & MODAL CONTROLLERS (DYNAMIC Z-INDEX STACKING)
// =========================================================================
var TOP_MODAL_BASE_Z_INDEX = 50;
var ACTIVE_MODAL_STACK = [];

function openModal(id) {
  if (id === 'modal-auto-reply-settings') {
    openAutoReplyModal();
    return;
  }
  if (id === 'modal-broadcast-template') {
    openBroadcastModal();
    return;
  }
  let el = document.getElementById(id);
  if (!el) {
    // Phase 3 Lazy Template Mount on-demand
    const tpl = document.getElementById('tpl-' + id);
    if (tpl && tpl.content) {
      document.body.appendChild(tpl.content.cloneNode(true));
      el = document.getElementById(id);
    }
  }
  if (!el) return;

  // Calculate highest z-index among currently open modals
  let highestZ = TOP_MODAL_BASE_Z_INDEX;
  const allModals = document.querySelectorAll('.modal-backdrop, [id^="modal-"]');
  allModals.forEach(m => {
    if (m !== el && !m.classList.contains('hidden')) {
      const z = parseInt(window.getComputedStyle(m).zIndex, 10);
      if (!isNaN(z) && z > highestZ) {
        highestZ = z;
      }
    }
  });

  const targetZ = highestZ + 20;
  el.style.zIndex = targetZ.toString();
  el.classList.remove('hidden');

  const idx = ACTIVE_MODAL_STACK.indexOf(id);
  if (idx !== -1) {
    ACTIVE_MODAL_STACK.splice(idx, 1);
  }
  ACTIVE_MODAL_STACK.push(id);
}

function closeModal(id) {
  if (id === 'modal-auto-reply-settings' || id === 'modal-broadcast-template') {
    switchInboxSubmodule('chats');
    return;
  }
  const el = document.getElementById(id);
  if (el) {
    el.classList.add('hidden');
    el.style.zIndex = '';
  }
  ACTIVE_MODAL_STACK = ACTIVE_MODAL_STACK.filter(m => m !== id);
}

window.openModal = openModal;
window.closeModal = closeModal;

// =========================================================================
// UNIVERSAL CUSTOM ACTION & DELETE CONFIRMATION POPUP SYSTEM
// =========================================================================
let _customConfirmResolve = null;
let _customConfirmCallback = null;
let _customCancelCallback = null;

function showConfirmDialog(options = {}) {
  return new Promise((resolve) => {
    const modal = document.getElementById('modal-custom-confirm');
    if (!modal) {
      const res = window.confirm(options.message || 'Are you sure?');
      if (res && typeof options.onConfirm === 'function') options.onConfirm();
      else if (!res && typeof options.onCancel === 'function') options.onCancel();
      resolve(res);
      return;
    }

    const titleEl = document.getElementById('custom-confirm-title');
    const subEl = document.getElementById('custom-confirm-subtitle');
    const msgEl = document.getElementById('custom-confirm-message');
    const detailEl = document.getElementById('custom-confirm-detail');
    const btnAction = document.getElementById('custom-confirm-btn-action');
    const btnCancel = document.getElementById('custom-confirm-btn-cancel');
    const actionText = document.getElementById('custom-confirm-action-text');
    const actionIcon = document.getElementById('custom-confirm-action-icon');
    const headerEl = document.getElementById('custom-confirm-header');
    const iconBox = document.getElementById('custom-confirm-icon-box');
    const iconEl = document.getElementById('custom-confirm-icon');
    const bannerEl = document.getElementById('custom-confirm-banner');
    const bannerIcon = document.getElementById('custom-confirm-banner-icon');

    const color = options.color || 'rose';
    const title = options.title || (color === 'rose' ? 'Delete Confirmation' : 'Please Confirm');
    const subtitle = options.subtitle || 'Action requires confirmation';
    const message = options.message || 'Are you sure you want to proceed?';
    const detail = options.detail || '';
    const confirmText = options.confirmText || (color === 'rose' ? 'Delete' : 'Confirm');
    const cancelText = options.cancelText || 'Cancel';
    const icon = options.icon || (color === 'rose' ? 'delete' : 'help_outline');

    if (titleEl) titleEl.textContent = title;
    if (subEl) subEl.textContent = subtitle;
    if (msgEl) msgEl.textContent = message;
    if (detailEl) {
      if (detail) {
        detailEl.textContent = detail;
        detailEl.classList.remove('hidden');
      } else {
        detailEl.classList.add('hidden');
      }
    }
    if (actionText) actionText.textContent = confirmText;
    if (btnCancel) btnCancel.textContent = cancelText;
    if (actionIcon) actionIcon.textContent = icon;
    if (iconEl) iconEl.textContent = icon;

    // Theme color adjustments
    if (color === 'rose') {
      if (headerEl) headerEl.className = 'p-4 sm:p-5 text-white flex items-center justify-between bg-gradient-to-r from-rose-900 via-slate-900 to-rose-950';
      if (iconBox) iconBox.className = 'w-10 h-10 rounded-xl bg-rose-600 flex items-center justify-center text-white shadow-md shrink-0';
      if (bannerEl) bannerEl.className = 'p-3.5 bg-rose-50 border border-rose-200/80 rounded-xl text-slate-800 flex items-start gap-3';
      if (bannerIcon) bannerIcon.className = 'material-symbols-outlined text-rose-600 text-[22px] shrink-0 mt-0.5';
      if (btnAction) btnAction.className = 'flex-1 sm:flex-none px-5 py-2.5 bg-rose-600 hover:bg-rose-700 active:scale-95 text-white rounded-xl font-bold shadow-md flex items-center justify-center gap-1.5 transition cursor-pointer text-xs';
    } else if (color === 'amber') {
      if (headerEl) headerEl.className = 'p-4 sm:p-5 text-white flex items-center justify-between bg-gradient-to-r from-amber-900 via-slate-900 to-amber-950';
      if (iconBox) iconBox.className = 'w-10 h-10 rounded-xl bg-amber-600 flex items-center justify-center text-white shadow-md shrink-0';
      if (bannerEl) bannerEl.className = 'p-3.5 bg-amber-50 border border-amber-200/80 rounded-xl text-slate-800 flex items-start gap-3';
      if (bannerIcon) bannerIcon.className = 'material-symbols-outlined text-amber-600 text-[22px] shrink-0 mt-0.5';
      if (btnAction) btnAction.className = 'flex-1 sm:flex-none px-5 py-2.5 bg-amber-600 hover:bg-amber-700 active:scale-95 text-white rounded-xl font-bold shadow-md flex items-center justify-center gap-1.5 transition cursor-pointer text-xs';
    } else if (color === 'emerald') {
      if (headerEl) headerEl.className = 'p-4 sm:p-5 text-white flex items-center justify-between bg-gradient-to-r from-emerald-900 via-slate-900 to-emerald-950';
      if (iconBox) iconBox.className = 'w-10 h-10 rounded-xl bg-emerald-600 flex items-center justify-center text-white shadow-md shrink-0';
      if (bannerEl) bannerEl.className = 'p-3.5 bg-emerald-50 border border-emerald-200/80 rounded-xl text-slate-800 flex items-start gap-3';
      if (bannerIcon) bannerIcon.className = 'material-symbols-outlined text-emerald-600 text-[22px] shrink-0 mt-0.5';
      if (btnAction) btnAction.className = 'flex-1 sm:flex-none px-5 py-2.5 bg-emerald-600 hover:bg-emerald-700 active:scale-95 text-white rounded-xl font-bold shadow-md flex items-center justify-center gap-1.5 transition cursor-pointer text-xs';
    } else {
      if (headerEl) headerEl.className = 'p-4 sm:p-5 text-white flex items-center justify-between bg-gradient-to-r from-slate-900 via-slate-800 to-slate-950';
      if (iconBox) iconBox.className = 'w-10 h-10 rounded-xl bg-blue-600 flex items-center justify-center text-white shadow-md shrink-0';
      if (bannerEl) bannerEl.className = 'p-3.5 bg-blue-50 border border-blue-200/80 rounded-xl text-slate-800 flex items-start gap-3';
      if (bannerIcon) bannerIcon.className = 'material-symbols-outlined text-blue-600 text-[22px] shrink-0 mt-0.5';
      if (btnAction) btnAction.className = 'flex-1 sm:flex-none px-5 py-2.5 bg-blue-600 hover:bg-blue-700 active:scale-95 text-white rounded-xl font-bold shadow-md flex items-center justify-center gap-1.5 transition cursor-pointer text-xs';
    }

    _customConfirmResolve = resolve;
    _customConfirmCallback = options.onConfirm || null;
    _customCancelCallback = options.onCancel || null;

    openModal('modal-custom-confirm');
  });
}

function executeCustomConfirm() {
  closeModal('modal-custom-confirm');
  const cb = _customConfirmCallback;
  const res = _customConfirmResolve;
  _customConfirmResolve = null;
  _customConfirmCallback = null;
  _customCancelCallback = null;

  if (typeof cb === 'function') {
    try { cb(); } catch (e) { console.error('executeCustomConfirm error:', e); }
  }
  if (typeof res === 'function') {
    res(true);
  }
}

function cancelCustomConfirm() {
  closeModal('modal-custom-confirm');
  const cb = _customCancelCallback;
  const res = _customConfirmResolve;
  _customConfirmResolve = null;
  _customConfirmCallback = null;
  _customCancelCallback = null;

  if (typeof cb === 'function') {
    try { cb(); } catch (e) { console.error('cancelCustomConfirm error:', e); }
  }
  if (typeof res === 'function') {
    res(false);
  }
}

window.showConfirmDialog = showConfirmDialog;
window.showDeleteConfirm = showConfirmDialog;
window.executeCustomConfirm = executeCustomConfirm;
window.cancelCustomConfirm = cancelCustomConfirm;

window.logAudit = logAudit;
function logAudit(action, module, details) {
  try {
    const user = (typeof ACTIVE_ROLE !== 'undefined' && ACTIVE_ROLE === 'admin')
      ? 'Super Admin'
      : (((typeof CRM_STATE !== 'undefined' && CRM_STATE && Array.isArray(CRM_STATE.staffList)) ? CRM_STATE.staffList : []).find(s => s && s.id === (typeof ACTIVE_ROLE !== 'undefined' ? ACTIVE_ROLE : ''))?.name || 'Staff');
    const timestamp = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

    if (typeof CRM_STATE !== 'undefined' && CRM_STATE) {
      if (!Array.isArray(CRM_STATE.auditLogs)) {
        CRM_STATE.auditLogs = [];
      }
      CRM_STATE.auditLogs.unshift({ timestamp, user, action, module, details });
    }

    // Asynchronously persist audit log to MySQL Database
    fetch('api.php?action=save_audit_log', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ user, action, module, details, timestamp })
    }).catch(() => { });
  } catch (err) {
    console.warn('[logAudit] Non-fatal logging error:', err);
  }
}

function updateBadgeCounters() {
  if (!CRM_STATE) return;

  const availableAccountIds = getAvailableWhatsAppAccounts().map(a => a.id);
  const uCurr = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER) ? CURRENT_USER : (typeof CRM_AUTH_SESSION !== 'undefined' ? CRM_AUTH_SESSION : null);
  const myQueueIds = [
    ACTIVE_ROLE,
    uCurr?.id,
    uCurr?.staff_id,
    uCurr?.staffId,
    uCurr?.username,
    uCurr?.name
  ].filter(Boolean).map(s => String(s).toLowerCase());

  const isSuperAdmin = uCurr
    ? (uCurr.role === 'admin' || uCurr.id === 'admin' || uCurr.role === 'Super Admin' || (uCurr.title && uCurr.title.includes('Admin Manager')))
    : (ACTIVE_ROLE === 'admin');

  // DND set
  const dndSet = new Set();
  (CRM_STATE.customers || []).forEach(c => {
    if (c.isDND === true || (Array.isArray(c.tags) && c.tags.includes('DND / Opt-Out'))) {
      dndSet.add(String(c.id));
    }
  });

  const convPhoneMap = new Map();
  for (const [key, msgs] of Object.entries(CRM_STATE.conversations || {})) {
    const kDigits = String(key).replace(/\D/g, '');
    if (kDigits.length >= 7) convPhoneMap.set(kDigits.slice(-10), msgs);
  }

  const queryByCustId = new Map();
  const queryByPhone10 = new Map();
  (CRM_STATE.queries || []).forEach(q => {
    if (!q) return;
    if (q.customerId) queryByCustId.set(String(q.customerId), q);
    if (q.customer_id) queryByCustId.set(String(q.customer_id), q);
    const clean = String(q.customerPhone || q.customer_phone || q.customerId || q.customer_id || '').replace(/\D/g, '');
    if (clean.length >= 7) queryByPhone10.set(clean.slice(-10), q);
  });

  const followupCustIds = new Set((CRM_STATE.followups || [])
    .filter(f => f && (f.status === 'PENDING' || f.status === 'FOLLOW_UP' || !f.status || f.status === 'OPEN'))
    .map(f => String(f.customerId || '')));

  const isFollowupQuery = q => {
    const s = String(q?.status || '').toUpperCase();
    return s === 'FOLLOW_UP' || s === 'PENDING' || followupCustIds.has(String(q?.customerId));
  };

  const isNewLeadQuery = q => {
    const s = String(q?.status || '').toUpperCase();
    if (isFollowupQuery(q)) return false;
    if (s === 'NEW' || s === 'OPEN' || s === 'ASSIGNED') return true;
    const isUnassigned = !q?.assignedTo || q.assignedTo === 'UNASSIGNED' || q.assignedTo === 'unassigned';
    if (isUnassigned && s !== 'RESOLVED' && s !== 'CLOSED' && s !== 'CONVERTED') return true;
    return false;
  };

  // STRICT UNIQUE PERSON DEDUPLICATION MAP
  // Exactly 1 entry per unique customer/phone number (1 PERSON = 1 COUNT!)
  const uniquePersonMap = new Map();

  (CRM_STATE.customers || []).forEach(cust => {
    if (!cust || cust.name === 'System' || cust.name === 'GRM Linked WhatsApp Device' || cust.name.startsWith('WhatsApp Linked')) return;
    if (dndSet.has(String(cust.id))) return;

    const custDigits = (cust.phone || cust.whatsapp || '').replace(/\D/g, '');
    const phone10 = custDigits.length >= 7 ? custDigits.slice(-10) : '';
    const personKey = phone10 || String(cust.id);

    const query = (phone10 ? queryByPhone10.get(phone10) : null) || queryByCustId.get(String(cust.id));
    if (query && query.status === 'DND') return;

    const conv = (CRM_STATE.conversations && CRM_STATE.conversations[cust.id]) || (phone10 ? convPhoneMap.get(phone10) : null) || [];
    const custLastMsg = cust.lastMessage || cust.last_message || '';

    // If contact has messages, last message, active query, or is currently selected
    const isActiveCard = (conv.length > 0) || Boolean(custLastMsg) || Boolean(query) || (window.ACTIVE_CUSTOMER_ID && String(cust.id) === String(window.ACTIVE_CUSTOMER_ID));
    if (!isActiveCard) return;

    // Strict Staff Workstation Isolation: When a staff member is logged in, count ONLY chats assigned to them
    if (!isSuperAdmin) {
      const assignedVal = String(query?.assignedTo || query?.assigned_to || cust.assignedTo || cust.assigned_to || '').trim().toLowerCase();
      const s = (CRM_STATE.staffList || []).find(st => st && (st.id === (query?.assignedTo || cust.assignedTo) || st.name === (query?.assignedTo || cust.assignedTo)));
      const sName = String(s?.name || '').toLowerCase();
      const sId = String(s?.id || '').toLowerCase();
      const isAssignedToMe = myQueueIds.includes(assignedVal) || myQueueIds.includes(sName) || myQueueIds.includes(sId);
      if (!isAssignedToMe) return;
    }

    const hasUnread = ((query && (query.unreadCount || 0) > 0) || (cust.unreadCount || 0) > 0 || (conv.length > 0 && conv[conv.length - 1].direction === 'inbound'));

    if (uniquePersonMap.has(personKey)) {
      const ex = uniquePersonMap.get(personKey);
      if (hasUnread) ex.hasUnread = true;
      return;
    }

    const isFu = query ? isFollowupQuery(query) : followupCustIds.has(String(cust.id));
    const isNl = !isFu && (query ? isNewLeadQuery(query) : (!cust.assignedTo || cust.assignedTo === 'UNASSIGNED'));
    const isUnassigned = (!query?.assignedTo || query.assignedTo === 'UNASSIGNED') && (!cust.assignedTo || cust.assignedTo === 'UNASSIGNED');

    uniquePersonMap.set(personKey, {
      customer: cust,
      query: query,
      hasUnread: Boolean(hasUnread),
      isFollowup: isFu,
      isNewLead: isNl,
      isUnassigned: isUnassigned
    });
  });

  // Safety Fallback: Query leads not yet covered by customers
  (CRM_STATE.queries || []).forEach(q => {
    if (!q || q.status === 'DND') return;
    const qCid = String(q.customerId || q.customer_id || '');
    const clean = String(q.customerPhone || q.customer_phone || qCid).replace(/\D/g, '');
    const phone10 = clean.length >= 7 ? clean.slice(-10) : '';
    const personKey = phone10 || qCid;
    if (!personKey || uniquePersonMap.has(personKey)) return;

    if (!isSuperAdmin) {
      const assignedVal = String(q.assignedTo || q.assigned_to || '').trim().toLowerCase();
      const s = (CRM_STATE.staffList || []).find(st => st && (st.id === q.assignedTo || st.name === q.assignedTo));
      const sName = String(s?.name || '').toLowerCase();
      const sId = String(s?.id || '').toLowerCase();
      if (!myQueueIds.includes(assignedVal) && !myQueueIds.includes(sName) && !myQueueIds.includes(sId)) return;
    }

    const isFu = isFollowupQuery(q);
    const isNl = !isFu && isNewLeadQuery(q);
    const isUnassigned = !q.assignedTo || q.assignedTo === 'UNASSIGNED';
    const hasUnread = (q.unreadCount || 0) > 0;

    uniquePersonMap.set(personKey, {
      customer: null,
      query: q,
      hasUnread: Boolean(hasUnread),
      isFollowup: isFu,
      isNewLead: isNl,
      isUnassigned: isUnassigned
    });
  });

  // Unique person aggregations: ONE PERSON SENDING MULTIPLE MESSAGES = 1 COUNT!
  const totalUniqueChats = uniquePersonMap.size;
  let unreadUniqueCustomers = 0;
  let newLeadsCount = 0;
  let followupCount = 0;
  let unassignedCount = 0;

  uniquePersonMap.forEach(p => {
    if (p.hasUnread) unreadUniqueCustomers++;
    if (p.isFollowup) followupCount++;
    else if (p.isNewLead) newLeadsCount++;
    if (p.isUnassigned) unassignedCount++;
  });

  const countAll = document.getElementById('count-all');
  if (countAll) countAll.innerText = totalUniqueChats;

  const countNewLeads = document.getElementById('count-new-leads');
  if (countNewLeads) countNewLeads.innerText = newLeadsCount;

  const countFollowup = document.getElementById('count-followup');
  if (countFollowup) countFollowup.innerText = followupCount;

  // Sidenav WhatsApp Inbox Badge (Strictly 1 count per person who sent messages):
  const bUnread = document.getElementById('badge-total-unread');
  if (bUnread) {
    bUnread.innerText = unreadUniqueCustomers;
  }
  const subtabUnread = document.getElementById('subtab-unread-badge');
  if (subtabUnread) {
    subtabUnread.innerText = unreadUniqueCustomers;
  }
  const headerLiveCount = document.getElementById('header-live-queue-count');
  if (headerLiveCount) {
    headerLiveCount.innerText = unreadUniqueCustomers;
  }

  const countUnassigned = document.getElementById('count-unassigned');
  if (countUnassigned) countUnassigned.innerText = unassignedCount;
  const bulkUnassignedBadge = document.getElementById('badge-bulk-unassigned');
  if (bulkUnassignedBadge) bulkUnassignedBadge.innerText = unassignedCount;

  const countMy = document.getElementById('count-my');
  if (countMy) countMy.innerText = totalUniqueChats;

  const followupEl = document.getElementById('badge-followup-count');
  if (followupEl) {
    const dueCount = (CRM_STATE.followups || []).filter(f => f.status === 'PENDING').length;
    followupEl.innerText = `${dueCount} Due`;
  }

  const ordersEl = document.getElementById('badge-orders-count');
  if (ordersEl) {
    ordersEl.innerText = (CRM_STATE.orders || []).length;
  }

  const staffEl = document.getElementById('badge-total-staff-count');
  if (staffEl) {
    staffEl.innerText = (CRM_STATE.staffList || []).length;
  }

  // DND count update
  const dndEl = document.getElementById('badge-dnd-count');
  const kpiDndEl = document.getElementById('kpi-dnd-total');
  const dndSummaryEl = document.getElementById('dnd-count-summary');
  const dndCustomers = (CRM_STATE.customers || []).filter(c => {
    if (!c) return false;
    const q = (CRM_STATE.queries || []).find(qry => qry.customerId === c.id);
    return c.isDND === true || (q && q.status === 'DND') || (Array.isArray(c.tags) && c.tags.includes('DND / Opt-Out'));
  });
  const dndCount = dndCustomers.length;
  if (dndEl) dndEl.innerText = dndCount;
  if (kpiDndEl) kpiDndEl.innerText = dndCount;
  if (dndSummaryEl) dndSummaryEl.innerText = `${dndCount} DND Customer${dndCount === 1 ? '' : 's'}`;

  // Update Daily Inbound Messages Progress Counter (e.g. 200 msgs target)
  const target = (CRM_STATE.dailyMessageTarget && CRM_STATE.dailyMessageTarget.expectedPerDay) || 200;

  // 100% Dynamic Unique Inbound Users/Contacts Count Calculation
  // 1 user sending messages = 1 count, regardless of how many messages they send
  const uniqueInboundUsersToday = new Set();
  const startOfToday = new Date().setHours(0, 0, 0, 0);

  if (CRM_STATE.conversations && typeof CRM_STATE.conversations === 'object') {
    Object.entries(CRM_STATE.conversations).forEach(([custId, msgs]) => {
      if (Array.isArray(msgs)) {
        const hasCustomerMsgToday = msgs.some(m => {
          if (!m) return false;
          const isInbound = (m.sender === 'customer' || (!m.isBot && m.sender !== 'staff' && !m.is_outbound));
          if (!isInbound) return false;
          return (!m.timestamp || m.timestamp >= startOfToday);
        });
        if (hasCustomerMsgToday) {
          uniqueInboundUsersToday.add(custId);
        }
      }
    });
  }

  // Active customer inquiry conversations visible in the inbox
  const activeQueries = (CRM_STATE.queries || []).filter(q => q && q.status !== 'RESOLVED' && q.status !== 'CLOSED' && q.status !== 'DND');
  activeQueries.forEach(q => {
    if (q && q.customerId) {
      uniqueInboundUsersToday.add(q.customerId);
    }
  });

  const totalReceivedToday = uniqueInboundUsersToday.size;

  // Dynamically synchronize each staff member's todayHandled with active assigned queries (remove hardcoded static numbers)
  if (Array.isArray(CRM_STATE.staffList)) {
    CRM_STATE.staffList.forEach(staff => {
      const staffIdentifiers = [
        staff.id,
        staff.username,
        staff.name,
        staff.phone
      ].filter(Boolean).map(s => String(s).trim().toLowerCase());

      const assignedToThisStaff = activeQueries.filter(q => {
        const qAssigned = String(q.assignedTo || q.assigned_to || (q.staff && q.staff.id) || '').trim().toLowerCase();
        return qAssigned && qAssigned !== 'unassigned' && staffIdentifiers.includes(qAssigned);
      });
      staff.todayHandled = assignedToThisStaff.length;
    });
  }

  // Live update Staff Workstation Banner quota counter if logged in as staff
  const staffBannerQuota = document.getElementById('staff-banner-quota');
  if (staffBannerQuota && typeof CURRENT_USER !== 'undefined' && CURRENT_USER && CURRENT_USER.role !== 'admin' && CURRENT_USER.role !== 'Super Admin') {
    let myCount = 0;
    if (typeof isAssignedToCurrentStaff === 'function') {
      myCount = activeQueries.filter(q => isAssignedToCurrentStaff(q, CURRENT_USER)).length;
    }
    if (myCount === 0 && Array.isArray(CRM_STATE.customers)) {
      myCount = CRM_STATE.customers.filter(c => isAssignedToCurrentStaff(c, CURRENT_USER)).length;
    }
    staffBannerQuota.innerText = `${myCount} msgs`;
  }

  const todayPct = Math.min(100, Math.round((totalReceivedToday / (target || 1)) * 100));

  const inboxTodayEl = document.getElementById('inbox-today-message-count');
  if (inboxTodayEl) {
    inboxTodayEl.innerText = `${totalReceivedToday} msgs`;
  }

  // Update Quota View KPI Counters if visible
  const kpiExpected = document.getElementById('kpi-quota-expected');
  const kpiAllocated = document.getElementById('kpi-quota-allocated');
  const kpiTodayReceived = document.getElementById('kpi-quota-today-received');
  const kpiProgressBar = document.getElementById('kpi-quota-progress-bar');

  if (kpiExpected) kpiExpected.innerText = `${target} msgs / day`;
  if (kpiTodayReceived) kpiTodayReceived.innerText = `${totalReceivedToday} / ${target} msgs (${todayPct}%)`;
  if (kpiProgressBar) kpiProgressBar.style.width = `${todayPct}%`;

  const totalAllocated = (CRM_STATE.staffList || []).reduce((sum, s) => sum + (Number(s.dailyQuota) || 0), 0);
  if (kpiAllocated) kpiAllocated.innerText = `${totalAllocated} / ${target} msgs`;
}
window.updateBadgeCounters = updateBadgeCounters;

