async function startAutomatedBroadcast() {
  const _user = (typeof CURRENT_USER !== 'undefined' && CURRENT_USER) ? CURRENT_USER : null;
  const _isSA = !_user || _user.role === 'admin' || _user.id === 'admin' || _user.role === 'Super Admin';
  if (!_isSA && typeof canUserPerformAction === 'function' && !canUserPerformAction('broadcast', 'create')) {
    if (typeof showToast === 'function') {
      showToast('Permission Denied', 'Your assigned role has View-Only access. Starting automated broadcasts is restricted.', 'lock', 'rose');
    } else {
      alert('Permission Denied: Your assigned role has View-Only access. Starting automated broadcasts is restricted.');
    }
    return;
  }

  if (IS_BROADCASTING_ACTIVE) return;

  const msgInput = document.getElementById('bcast-message-text');
  const rawTemplate = msgInput ? msgInput.value.trim() : '';

  if (!rawTemplate) {
    alert('Please enter or select a message template before starting broadcast.');
    if (msgInput) msgInput.focus();
    return;
  }

  const numbersTextarea = document.getElementById('bcast-target-numbers');
  const rawNumbersText = numbersTextarea ? numbersTextarea.value.trim() : '';
  const parsedPhoneList = rawNumbersText
    ? rawNumbersText.split(/[,\n;]+/).map(s => s.trim()).filter(s => s.replace(/[^0-9]/g, '').length >= 7)
    : [];

  const audienceSelect = document.getElementById('bcast-target-audience');
  const targetVal = audienceSelect ? audienceSelect.value : 'ALL';
  const targetCustomers = getBroadcastTargetCustomers(targetVal);

  // Build recipients list based on parsed numbers
  let recipients = [];
  if (parsedPhoneList.length > 0) {
    parsedPhoneList.forEach(rawPhone => {
      const cleanDigits = rawPhone.replace(/[^0-9]/g, '');
      // Try to find matching customer in state
      const matchedCust = (CRM_STATE.customers || []).find(c => {
        const cDigits = (c.phone || c.whatsapp || '').replace(/[^0-9]/g, '');
        return cDigits && (cDigits === cleanDigits || cDigits.endsWith(cleanDigits) || cleanDigits.endsWith(cDigits));
      });

      if (matchedCust) {
        recipients.push(matchedCust);
      } else {
        // Synthesize recipient
        const defaultAccId = targetVal.startsWith('account_') ? targetVal : 'account_1';
        recipients.push({
          id: 'cust_bcast_' + cleanDigits,
          name: 'Customer',
          phone: rawPhone,
          whatsapp: rawPhone,
          accountId: defaultAccId
        });
      }
    });
  } else {
    recipients = targetCustomers;
  }

  if (recipients.length === 0) {
    alert('No recipient phone numbers found. Please enter or select phone numbers to broadcast.');
    return;
  }

  const delaySelect = document.getElementById('bcast-delay-select');
  const delayInput = document.getElementById('bcast-delay-range');
  let delaySec = 1.5;
  if (delaySelect && delaySelect.value) {
    const ms = parseFloat(delaySelect.value) || 1500;
    delaySec = ms > 50 ? ms / 1000 : ms;
  } else if (delayInput) {
    delaySec = parseFloat(delayInput.value) || 1.5;
  }

  // Get attached photo from upload / URL
  const attachedBroadcastImage = document.getElementById('bcast-image-url')?.value?.trim() || (BROADCAST_ATTACHED_IMAGE_DATA ? BROADCAST_ATTACHED_IMAGE_DATA.src : null);

  if (!confirm(`📢 Confirm Automated WhatsApp Broadcast:\n\n• Target Audience: ${audienceSelect ? audienceSelect.options[audienceSelect.selectedIndex].text : 'Selected Recipients'}\n• Total Target Numbers: ${recipients.length}\n• Safe Anti-Spam Throttle: ${delaySec} sec/message\n\nProceed to start dispatch loop?`)) {
    return;
  }

  // Auto-save the active broadcast template & dynamic variables to MySQL database
  const presetSelect = document.getElementById('bcast-preset-select');
  const currentKey = presetSelect ? presetSelect.value : ('tmpl_' + Date.now());
  const currentLabel = (BROADCAST_PRESETS_DATA[currentKey] && BROADCAST_PRESETS_DATA[currentKey].label)
    ? BROADCAST_PRESETS_DATA[currentKey].label
    : (CURRENT_BROADCAST_TEMPLATE_TITLE || 'Broadcast Template');

  if (!BROADCAST_PRESETS_DATA[currentKey]) {
    BROADCAST_PRESETS_DATA[currentKey] = {};
  }
  BROADCAST_PRESETS_DATA[currentKey].text = rawTemplate;
  BROADCAST_PRESETS_DATA[currentKey].label = currentLabel;
  BROADCAST_PRESETS_DATA[currentKey].variables = { ...BROADCAST_CUSTOM_TAGS };

  try {
    localStorage.setItem('GRM_CUSTOM_BROADCAST_TEMPLATES', JSON.stringify(BROADCAST_PRESETS_DATA));
  } catch (e) { }

  // Save template & dynamic values to MySQL DB!
  fetch('api.php?action=save_broadcast_template', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      id: currentKey,
      name: currentLabel,
      category: BROADCAST_PRESETS_DATA[currentKey]?.category || 'MARKETING',
      body_text: rawTemplate,
      image_url: attachedBroadcastImage || null,
      variables_json: BROADCAST_CUSTOM_TAGS
    })
  }).catch(err => console.warn('Could not auto-save template to DB:', err));

  // Setup UI State for broadcast in progress
  IS_BROADCASTING_ACTIVE = true;
  BROADCAST_CANCEL_FLAG = false;

  const progContainer = document.getElementById('bcast-progress-container');
  const progBar = document.getElementById('bcast-progress-bar');
  const progPct = document.getElementById('bcast-progress-pct');
  const progStatus = document.getElementById('bcast-progress-status');
  const progDetail = document.getElementById('bcast-progress-detail');

  const startBtn = document.getElementById('btn-bcast-start');
  const stopBtn = document.getElementById('btn-bcast-stop');
  const cancelBtn = document.getElementById('btn-bcast-cancel');

  if (progContainer) progContainer.classList.remove('hidden');
  if (startBtn) startBtn.classList.add('hidden');
  if (stopBtn) stopBtn.classList.remove('hidden');
  if (cancelBtn) cancelBtn.disabled = true;

  if (msgInput) msgInput.disabled = true;
  if (numbersTextarea) numbersTextarea.disabled = true;
  if (audienceSelect) audienceSelect.disabled = true;
  if (delayInput) delayInput.disabled = true;

  if (progStatus) progStatus.innerText = `Broadcasting to ${recipients.length} customer phone numbers...`;
  if (progPct) progPct.innerText = '0%';
  if (progBar) progBar.style.width = '0%';
  if (progDetail) progDetail.innerText = `Starting automated dispatch loop (${delaySec}s delay)...`;

  let sentCount = 0;
  let deliveredCount = 0;
  let failedCount = 0;

  for (let i = 0; i < recipients.length; i++) {
    if (BROADCAST_CANCEL_FLAG) {
      if (progStatus) progStatus.innerText = 'Broadcast Stopped by User';
      if (progDetail) progDetail.innerText = `Stopped after sending ${sentCount} of ${recipients.length} messages (${deliveredCount} delivered, ${failedCount} failed).`;
      break;
    }

    const customer = recipients[i];
    const account = (CRM_STATE.whatsappAccounts && CRM_STATE.whatsappAccounts.find(a => a.id === customer.accountId)) || CRM_STATE.whatsappAccount;

    // Personalize message with all system & manual custom tags
    const personalizedText = renderTemplateMessagePersonalized(rawTemplate, customer, account, BROADCAST_CUSTOM_TAGS);

    // Append to customer's conversation history if valid id
    if (customer.id) {
      if (!CRM_STATE.conversations[customer.id]) {
        CRM_STATE.conversations[customer.id] = [];
      }

      const now = new Date();
      const timeStr = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      const newMsg = {
        id: Date.now() + Math.floor(Math.random() * 1000),
        sender: 'staff',
        text: personalizedText,
        time: timeStr,
        timestamp: Date.now(),
        status: 'PENDING',
        isBroadcast: true,
        media_type: attachedBroadcastImage ? 'image' : null,
        media_url: attachedBroadcastImage || null
      };

      CRM_STATE.conversations[customer.id].push(newMsg);

      // Update query summary in list
      const query = (CRM_STATE.queries || []).find(q => q.customerId === customer.id);
      if (query) {
        query.lastMessage = attachedBroadcastImage
          ? `Staff (Broadcast): [Photo] "${personalizedText.length > 30 ? personalizedText.substring(0, 27) + '...' : personalizedText}"`
          : `Staff (Broadcast): "${personalizedText.length > 40 ? personalizedText.substring(0, 37) + '...' : personalizedText}"`;
        query.lastMessageTime = 'Just now';
      }

      // DISPATCH LIVE REAL-TIME OUTBOUND MESSAGE OVER WHATSAPP
      const targetPhone = customer.whatsapp || customer.phone;
      const targetJid = customer.jid || null;
      const targetAccId = customer.accountId || (account && account.id) || 'account_1';

      let isDelivered = false;
      try {
        isDelivered = await dispatchWhatsAppOutbound(targetPhone, personalizedText, newMsg, targetJid, targetAccId, true, attachedBroadcastImage, customer.id);
      } catch (sendErr) {
        console.warn('[Broadcast Send Error for ' + (customer.name || targetPhone) + ']:', sendErr);
      }

      if (isDelivered) {
        deliveredCount++;
        newMsg.status = 'DELIVERED';
      } else {
        failedCount++;
        newMsg.status = 'FAILED';
      }
    }

    sentCount++;
    const pct = Math.round((sentCount / recipients.length) * 100);

    if (progPct) progPct.innerText = `${pct}%`;
    if (progBar) progBar.style.width = `${pct}%`;
    if (progDetail) progDetail.innerText = `Sent: ${sentCount}/${recipients.length} | Delivered: ${deliveredCount}${failedCount > 0 ? ` | Failed: ${failedCount}` : ''}`;

    // Audio chime feedback
    if (typeof playChime === 'function') {
      playChime('order');
    }

    // Refresh active chat stream if this customer is currently being viewed
    if (ACTIVE_CUSTOMER_ID === customer.id && typeof renderChatMessages === 'function') {
      renderChatMessages(customer.id);
    }

    // Anti-spam throttling delay between consecutive messages
    await new Promise(resolve => setTimeout(resolve, delaySec * 1000));
  }

  // Finalize Broadcast State
  IS_BROADCASTING_ACTIVE = false;
  saveCRMState();

  if (typeof renderInboxConversationList === 'function') {
    renderInboxConversationList();
  }
  if (typeof updateBadgeCounters === 'function') {
    updateBadgeCounters();
  }

  logAudit('TEMPLATE_BROADCAST', 'INBOX_BROADCAST', `Dispatched automated broadcast "${rawTemplate.substring(0, 30)}..." to ${sentCount} recipients.`);

  if (startBtn) startBtn.classList.remove('hidden');
  if (stopBtn) stopBtn.classList.add('hidden');
  if (cancelBtn) cancelBtn.disabled = false;
  if (msgInput) msgInput.disabled = false;
  if (numbersTextarea) numbersTextarea.disabled = false;
  if (audienceSelect) audienceSelect.disabled = false;
  if (delayInput) delayInput.disabled = false;

  if (!BROADCAST_CANCEL_FLAG) {
    if (failedCount === 0) {
      if (progStatus) progStatus.innerText = '✅ Broadcast Completed Successfully!';
      if (progDetail) progDetail.innerText = `All ${deliveredCount} messages delivered to recipients\' WhatsApp.`;
      showToast('Broadcast Complete', `All ${deliveredCount} messages delivered!`, 'campaign', 'emerald');
    } else {
      if (progStatus) progStatus.innerText = `⚠️ Broadcast Finished (${deliveredCount} Delivered, ${failedCount} Failed)`;
      if (progDetail) progDetail.innerText = `${deliveredCount} delivered, ${failedCount} failed. Please ensure WhatsApp QR Bridge is connected.`;
      showToast('Broadcast Notice', `${deliveredCount} delivered, ${failedCount} failed to send. Check WhatsApp Bridge.`, 'warning', 'amber');
    }
  } else {
    showToast('Broadcast Stopped', `Broadcast paused after sending ${sentCount} messages (${deliveredCount} delivered, ${failedCount} failed).`, 'stop_circle', 'amber');
  }
}

function stopAutomatedBroadcast() {
  if (IS_BROADCASTING_ACTIVE) {
    BROADCAST_CANCEL_FLAG = true;
    const progStatus = document.getElementById('bcast-progress-status');
    if (progStatus) progStatus.innerText = 'Stopping broadcast...';
    showToast('Broadcast Stopping', 'Finishing current message and pausing automated queue...', 'pause_circle', 'amber');
  }
}

// INITIALIZE APP ON LOAD
function bootstrapCRMApp() {
  initCRMState();
  initAuthSystem();
  if (typeof initBrowserHistoryGuard === 'function') {
    initBrowserHistoryGuard();
  }
  if (typeof updateHeaderBulkRequestsBadge === 'function') {
    updateHeaderBulkRequestsBadge();
    setInterval(updateHeaderBulkRequestsBadge, 15000);
  }
}

if (document.readyState === 'complete' || document.readyState === 'interactive') {
  bootstrapCRMApp();
} else {
  window.addEventListener('DOMContentLoaded', bootstrapCRMApp);
}


// =========================================================================
// QUICK STATUS NOTES & QUERY CALLBACK PRESET HELPERS
// =========================================================================
function setQuickStatusNote(noteText, suggestedStatus) {
  const query = (CRM_STATE.queries || []).find(q => q.customerId === ACTIVE_CUSTOMER_ID || q.id === ACTIVE_CUSTOMER_ID);
  setTimeout(() => {
    const input = document.getElementById('query-status-notes-input');
    if (input) {
      input.disabled = false;
      input.value = noteText;
      input.focus();
      input.dispatchEvent(new Event('input', { bubbles: true }));
      input.classList.add('ring-2', 'ring-amber-400');
      setTimeout(() => input.classList.remove('ring-2', 'ring-amber-400'), 1000);
    }
    if (suggestedStatus) {
      const select = document.getElementById('query-status-select');
      if (select) {
        select.disabled = false;
        select.value = suggestedStatus;
        if (typeof handleQueryStatusSelectChange === 'function') {
          handleQueryStatusSelectChange(suggestedStatus, query?.id, ACTIVE_CUSTOMER_ID);
        }
      }
    }
    showToast('Quick Note Inserted', `Set note: "${noteText}"`, 'sticky_note_2', 'amber');
  }, 40);
}
window.setQuickStatusNote = setQuickStatusNote;

// DYNAMIC INLINE QUICK NOTES HELPERS (NO POPUP / NO MODAL)
function getCustomQuickNotes() {
  try {
    return JSON.parse(localStorage.getItem('GRM_CUSTOM_QUICK_NOTES') || '[]');
  } catch (e) {
    return [];
  }
}
window.getCustomQuickNotes = getCustomQuickNotes;

function showInlineAddQuickNote() {
  const btn = document.getElementById('btn-show-add-quick-note');
  const box = document.getElementById('inline-add-quick-note-box');
  const input = document.getElementById('inline-quick-note-text');
  if (btn) btn.classList.add('hidden');
  if (box) {
    box.classList.remove('hidden');
    box.classList.add('flex');
  }
  if (input) {
    input.value = '';
    setTimeout(() => input.focus(), 50);
  }
}
window.showInlineAddQuickNote = showInlineAddQuickNote;

function hideInlineAddQuickNote() {
  const btn = document.getElementById('btn-show-add-quick-note');
  const box = document.getElementById('inline-add-quick-note-box');
  const input = document.getElementById('inline-quick-note-text');
  if (input) input.value = '';
  if (box) {
    box.classList.add('hidden');
    box.classList.remove('flex');
  }
  if (btn) btn.classList.remove('hidden');
}
window.hideInlineAddQuickNote = hideInlineAddQuickNote;

function saveCustomQuickNote() {
  const input = document.getElementById('inline-quick-note-text');
  const text = (input?.value || '').trim();
  if (!text) {
    showToast('Empty Note', 'Please enter a quick note title or remark', 'warning', 'amber');
    if (input) input.focus();
    return;
  }

  const list = getCustomQuickNotes();
  const exists = list.some(n => {
    const noteText = typeof n === 'string' ? n : (n.text || '');
    return noteText.toLowerCase() === text.toLowerCase();
  });

  if (exists) {
    showToast('Already Exists', 'This quick note is already in your list', 'info', 'blue');
    hideInlineAddQuickNote();
    return;
  }

  const newNote = {
    id: 'qn_' + Date.now(),
    text: text,
    createdAt: new Date().toISOString()
  };
  list.push(newNote);
  localStorage.setItem('GRM_CUSTOM_QUICK_NOTES', JSON.stringify(list));

  hideInlineAddQuickNote();
  renderQuickNotesList();
  setQuickStatusNote(text);
  showToast('Quick Note Added', `"${text}" dynamically added to Quick Notes`, 'check_circle', 'emerald');
}
window.saveCustomQuickNote = saveCustomQuickNote;

function deleteCustomQuickNote(noteId) {
  let list = getCustomQuickNotes();
  list = list.filter(n => {
    if (typeof n === 'string') return n !== noteId;
    return n.id !== noteId && n.text !== noteId;
  });
  localStorage.setItem('GRM_CUSTOM_QUICK_NOTES', JSON.stringify(list));
  renderQuickNotesList();
  showToast('Quick Note Removed', 'Custom quick note removed', 'delete', 'slate');
}
window.deleteCustomQuickNote = deleteCustomQuickNote;

function renderQuickNotesList() {
  const container = document.getElementById('enquiry-quick-notes-list');
  if (!container) return;

  const query = (CRM_STATE.queries || []).find(q => q.customerId === ACTIVE_CUSTOMER_ID || q.id === ACTIVE_CUSTOMER_ID);
  const isQueryEditing = true;

  const defaults = [
    { text: 'Order Complete', status: 'CONVERTED', icon: '📦', color: 'emerald' },
    { text: 'Callback Promise - Customer requested call back', label: 'Callback Promise', status: 'FOLLOW_UP', icon: '📞', color: 'blue' },
    { text: 'Price Quoted / Catalog Shared', label: 'Price Quoted', status: 'IN_PROGRESS', icon: '💬', color: 'purple' },
    { text: 'Payment Pending - Advance requested', label: 'Advance Pending', status: 'PENDING', icon: '💳', color: 'amber' },
    { text: 'Customer Not Interested / Opt-Out', label: 'Not Interested', status: 'DND', icon: '🚫', color: 'rose' }
  ];

  const customNotes = getCustomQuickNotes();

  const defaultHtml = defaults.map(d => {
    const colorClasses = {
      emerald: 'bg-emerald-50 hover:bg-emerald-100 text-emerald-800 border-emerald-300',
      blue: 'bg-blue-50 hover:bg-blue-100 text-blue-800 border-blue-200',
      purple: 'bg-purple-50 hover:bg-purple-100 text-purple-800 border-purple-200',
      amber: 'bg-amber-50 hover:bg-amber-100 text-amber-800 border-amber-300',
      rose: 'bg-rose-50 hover:bg-rose-100 text-rose-800 border-rose-200'
    }[d.color] || 'bg-slate-50 text-slate-800 border-slate-200';

    return `
      <button type="button" ${isQueryEditing ? `onclick="setQuickStatusNote('${d.text.replace(/'/g, "\\'")}', '${d.status}')"` : `disabled`} class="px-2 py-0.5 ${colorClasses} border rounded-lg text-[10px] font-bold transition flex items-center gap-1 ${isQueryEditing ? 'cursor-pointer active:scale-95 shadow-2xs' : 'opacity-60 cursor-not-allowed select-none'}" title="${isQueryEditing ? `Click to set ${d.label || d.text}` : 'Touch Edit Enquiry Status to use'}">
        <span>${d.icon} ${d.label || d.text}</span>
      </button>
    `;
  }).join('');

  const customHtml = customNotes.map(n => {
    const noteText = typeof n === 'string' ? n : (n.text || '');
    const noteId = typeof n === 'string' ? n : (n.id || noteText);
    if (!noteText) return '';
    return `
      <div class="inline-flex items-center gap-1 px-2 py-0.5 bg-amber-50/90 text-amber-900 border border-amber-300 rounded-lg text-[10px] font-bold transition shadow-2xs group max-w-full ${isQueryEditing ? 'hover:bg-amber-100 cursor-pointer active:scale-95' : 'opacity-60 cursor-not-allowed select-none'}" ${isQueryEditing ? `onclick="setQuickStatusNote('${noteText.replace(/'/g, "\\'")}')"` : ''} title="${isQueryEditing ? `Click to insert '${noteText}'` : 'Touch Edit Enquiry Status to use'}">
        <span class="truncate max-w-[170px]" title="${noteText}">📌 ${noteText}</span>
        ${isQueryEditing ? `
          <button type="button" onclick="event.stopPropagation(); deleteCustomQuickNote('${noteId}')" class="text-amber-400 hover:text-rose-600 rounded p-0.5 hover:bg-rose-50 flex items-center transition shrink-0" title="Delete quick note">
            <span class="material-symbols-outlined text-[10px]">close</span>
          </button>
        ` : ''}
      </div>
    `;
  }).join('');

  container.innerHTML = defaultHtml + customHtml;

  // Sync add button visibility based on edit mode
  const addBtn = document.getElementById('btn-show-add-quick-note');
  const addBox = document.getElementById('inline-add-quick-note-box');
  if (addBtn) addBtn.classList.toggle('hidden', !isQueryEditing);
  if (!isQueryEditing && addBox) {
    addBox.classList.add('hidden');
    addBox.classList.remove('flex');
  }
}
window.renderQuickNotesList = renderQuickNotesList;

function setQueryQuickDate(daysAhead) {
  const target = new Date();
  target.setDate(target.getDate() + daysAhead);
  const year = target.getFullYear();
  const month = String(target.getMonth() + 1).padStart(2, '0');
  const day = String(target.getDate()).padStart(2, '0');
  const dateInput = document.getElementById('query-callback-date');
  if (dateInput) {
    dateInput.value = `${year}-${month}-${day}`;
  }
}
window.setQueryQuickDate = setQueryQuickDate;

function setQueryQuickTime(preset) {
  const hourEl = document.getElementById('query-callback-hour');
  const minEl = document.getElementById('query-callback-min');
  const ampmEl = document.getElementById('query-callback-ampm');
  if (!hourEl || !minEl || !ampmEl) return;

  const now = new Date();
  if (preset === 'NOW') {
    let h = now.getHours();
    let m = Math.ceil(now.getMinutes() / 5) * 5;
    if (m >= 60) { h = (h + 1) % 24; m = 0; }
    ampmEl.value = h >= 12 ? 'PM' : 'AM';
    let h12 = h % 12 || 12;
    hourEl.value = String(h12).padStart(2, '0');
    minEl.value = String(m).padStart(2, '0');
  } else if (preset === 'PLUS_1H') {
    let h = (now.getHours() + 1) % 24;
    let m = Math.ceil(now.getMinutes() / 5) * 5;
    if (m >= 60) { h = (h + 1) % 24; m = 0; }
    ampmEl.value = h >= 12 ? 'PM' : 'AM';
    let h12 = h % 12 || 12;
    hourEl.value = String(h12).padStart(2, '0');
    minEl.value = String(m).padStart(2, '0');
  } else if (preset === '10AM') {
    hourEl.value = '10';
    minEl.value = '00';
    ampmEl.value = 'AM';
  } else if (preset === '5PM') {
    hourEl.value = '05';
    minEl.value = '00';
    ampmEl.value = 'PM';
  }
}
window.setQueryQuickTime = setQueryQuickTime;

